-- ── 20260901000800: dedup the payment ledger by event type ──────────────────────────────────────
-- Dedup the payment ledger by EVENT TYPE as well as provider transaction id.
--
-- append_payment_event absorbs each webhook with `insert … on conflict (<key>) do nothing`, so the
-- conflict target IS the idempotency rule. It shipped as (payment_id, provider_event_id) — no event
-- type. Peach reuses ONE transaction id across the Pending and the Successful notification for a
-- payment, so the Successful collided with the already-stored Pending and was silently discarded:
--
--   * the ledger never credited the money — v_paid stayed 0, so the booking was never confirmed;
--   * nothing raised, so reconcile.ts returned `confirmed: true` for a payment the database had just
--     thrown away: success was REPORTED while nothing was recorded;
--   * the booking stayed payment_pending, and run_booking_maintenance expired it and released the
--     seat on the 30-minute timer — with the customer's money taken.
--
-- Verified on the live schema before writing this: the constraint was
--   payment_events_payment_id_provider_event_id_key UNIQUE (payment_id, provider_event_id)
-- and a real booking (BMT66C2B86F5E2C9) carried three stored `pending` events, one of which reused
-- the checkout id as its provider_event_id — i.e. the collision space is real, not theoretical.
--
-- Adding `type` PRESERVES genuine idempotency: a provider retrying the same Successful with the same
-- transaction id still lands exactly once (same type + same id). It only stops two DIFFERENT events
-- being mistaken for each other. The new key is strictly weaker than the old one, so every existing
-- row satisfies it and the constraint swap cannot fail on live data.
--
-- NULL provider_event_id (our own 'intent' rows) is unaffected: NULLs never collide in either key.

alter table payment_events drop constraint if exists payment_events_payment_id_provider_event_id_key;
-- Idempotent (catch-up.sql re-runs this file): drop-then-add, the same pattern 20260830000000 uses.
alter table payment_events drop constraint if exists payment_events_payment_id_provider_event_id_type_key;
alter table payment_events add constraint payment_events_payment_id_provider_event_id_type_key
  unique (payment_id, provider_event_id, type);

comment on constraint payment_events_payment_id_provider_event_id_type_key on payment_events is
  'Webhook idempotency. Includes `type` because Peach reuses one transaction id across its Pending '
  'and Successful notifications — keying on the id alone discarded the Successful and left the '
  'customer charged with an unconfirmed, then auto-expired, booking.';

-- Verbatim from 20260805000000 with ONE change: the on-conflict target now carries `type`.
-- Signature is byte-identical, so the execute grants pinned in 20260814000000 survive the replace;
-- they are re-issued below anyway (see the definer-grant-leak history).
create or replace function append_payment_event(
  p_payment_id uuid,
  p_type text,
  p_provider_event_id text,
  p_amount_minor bigint,
  p_occurred_at timestamptz,
  p_payload jsonb
)
returns payments
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payment payments;
  v_paid bigint;
  v_refunded bigint;
  v_failed boolean;
  v_state payment_state;
  v_booking_status booking_status;
  v_occ_id uuid;
  v_needed bigint;
  v_cap bigint;
  v_used_conf bigint;
  v_used_hold bigint;
  v_oversold boolean := false;
begin
  select * into v_payment from payments where id = p_payment_id for update;
  if not found then
    raise exception 'payment_not_found';
  end if;

  insert into payment_events (payment_id, type, provider_event_id, amount_minor, occurred_at, payload)
  values (
    p_payment_id, p_type, p_provider_event_id, coalesce(p_amount_minor, 0),
    coalesce(p_occurred_at, now()), coalesce(p_payload, '{}'::jsonb)
  )
  on conflict (payment_id, provider_event_id, type) do nothing;

  select
    coalesce(sum(amount_minor) filter (where type in ('paid', 'captured')), 0),
    coalesce(sum(amount_minor) filter (where type = 'refunded'), 0),
    bool_or(type = 'failed')
  into v_paid, v_refunded, v_failed
  from payment_events
  where payment_id = p_payment_id;

  if v_paid > 0 and v_refunded >= v_paid then
    v_state := 'refunded';
  elsif v_paid > 0 and v_refunded > 0 then
    v_state := 'partially_refunded';
  -- amount_minor > 0: a zero-amount payment must never read as fully paid (0 >= 0) -- the 'failed'
  -- branch below has to win for it.
  elsif v_payment.amount_minor > 0 and v_paid >= v_payment.amount_minor then
    v_state := 'paid';
  elsif v_paid > 0 then
    v_state := 'pending'; -- underpaid: do not confirm
  elsif coalesce(v_failed, false) then
    v_state := 'failed';
  else
    v_state := 'pending';
  end if;

  update payments
  set status = v_state, paid_minor = v_paid, refunded_minor = v_refunded, updated_at = now()
  where id = p_payment_id
  returning * into v_payment;

  update bookings set payment_state = v_state, updated_at = now() where id = v_payment.booking_id;

  if v_state = 'paid' then
    select status into v_booking_status from bookings where id = v_payment.booking_id;

    if v_booking_status in ('draft', 'held', 'payment_pending') then
      -- Re-validate capacity per occurrence, excluding this booking's own items/holds.
      for v_occ_id in
        select distinct session_occurrence_id from booking_items where booking_id = v_payment.booking_id
      loop
        perform 1 from session_occurrences where id = v_occ_id for update;
        select coalesce(sum(quantity), 0) into v_needed
        from booking_items where booking_id = v_payment.booking_id and session_occurrence_id = v_occ_id;
        select capacity into v_cap from session_occurrences where id = v_occ_id;
        select coalesce(sum(bi.quantity), 0) into v_used_conf
        from booking_items bi join bookings b on b.id = bi.booking_id
        where bi.session_occurrence_id = v_occ_id
          and b.status in ('confirmed', 'completed')
          and b.id <> v_payment.booking_id;
        select coalesce(sum(h.quantity), 0) into v_used_hold
        from booking_holds h
        where h.session_occurrence_id = v_occ_id
          and h.status = 'active' and h.expires_at > now()
          and (h.booking_id is null or h.booking_id <> v_payment.booking_id);
        if v_needed > v_cap - v_used_conf - v_used_hold then
          v_oversold := true;
        end if;
      end loop;

      if v_oversold then
        update bookings set status = 'refund_pending', updated_at = now() where id = v_payment.booking_id;
      else
        update bookings set status = 'confirmed', updated_at = now() where id = v_payment.booking_id;
        update booking_holds set status = 'consumed'
        where booking_id = v_payment.booking_id and status = 'active';
      end if;
    elsif v_booking_status not in ('confirmed', 'completed') then
      -- Money captured on an expired/cancelled booking: must be refunded, not confirmed.
      update bookings set status = 'refund_pending', updated_at = now() where id = v_payment.booking_id;
    end if;
  elsif v_state = 'refunded' then
    update bookings set status = 'refunded', updated_at = now()
    where id = v_payment.booking_id and status <> 'cancelled';
    update booking_holds set status = 'released'
    where booking_id = v_payment.booking_id and status = 'active';
  end if;

  return v_payment;
end;
$$;

revoke execute on function append_payment_event(uuid, text, text, bigint, timestamptz, jsonb) from public, anon, authenticated;
grant execute on function append_payment_event(uuid, text, text, bigint, timestamptz, jsonb) to service_role;


-- ── 20260901000900: lock operators + revoke payment delete ──────────────────────────────────────
-- Close two privilege holes on the money path. Both were VERIFIED against production before writing
-- this, and the first was proven end-to-end with nothing but the public anon key:
--
--   GET /rest/v1/operators?select=name,contact_email,phone,payout_details   →   200
--   [{"name":"Belle Mare Tours","contact_email":null,"phone":"…","payout_details":{}}]
--
-- 1) OPERATORS WAS WORLD-READABLE. `anon` holds a table SELECT grant and the `operators_read` policy
--    was `using (true)`, so every anonymous visitor could read the operator row — including
--    payout_details, contact_email and phone. Nothing sensitive was exposed on the day this shipped
--    (payout_details was '{}', contact_email null, the phone already public on the site), so this is
--    a LATENT leak, not an active one: the moment the owner enters real payout/bank details in
--    /admin they become world-readable to anyone holding the key that ships in the client bundle.
--
--    Fix: revoke the anon grant outright, and drop the permissive read policy so the remaining
--    `operators_staff` policy (is_staff()) governs. That also closes the quieter half of the hole —
--    any signed-in CUSTOMER could read the same columns.
--
--    Why `authenticated` keeps its table grant: src/lib/admin/activity-write.ts:170 reads
--    operators.id through the BROWSER client (i.e. as the staff user, not service_role) when creating
--    an activity. Revoking the grant would break admin. RLS now carries the restriction instead —
--    staff pass is_staff(), everyone else matches no policy and sees zero rows.
--
--    The public catalogue is unaffected: it is served by security-definer functions, which run as the
--    owner and never consult these grants.
--
-- 2) A STAFF JWT COULD DELETE PAYMENTS — AND THE LEDGER WITH THEM. `authenticated` held DELETE on
--    payments, `payments_staff` is `for all using (is_staff())`, and payment_events → payments is
--    ON DELETE CASCADE. So one staff account could erase a payment and silently take every
--    payment_event with it: the audit trail of who paid what. (Verified by privilege + policy + the
--    'c' confdeltype, NOT by executing it — proving it would have destroyed a real payment record.)
--
--    Fix: revoke DELETE from authenticated. Refunds and cancellations already go through
--    security-definer RPCs (api_mark_refunded, api_cancel_booking), none of which DELETE a payment —
--    the ledger is append-only by design and nothing in the app deletes from it.
--
-- service_role is untouched throughout: the webhook, the reconcile sweep and the cron all run as
-- service_role and must keep working.

-- ── 1) operators ────────────────────────────────────────────────────────────────────────────────
revoke select on operators from anon;

-- Idempotent: dropping the permissive policy leaves `operators_staff` (for all using is_staff()) as
-- the only policy, so a non-staff session matches nothing and reads zero rows.
drop policy if exists operators_read on operators;

comment on table operators is
  'Operator record. NOT publicly readable: payout_details/contact_email/phone live here. anon has no '
  'grant; authenticated keeps the grant only because the admin UI reads operators.id through the '
  'browser client, and is_staff() in the operators_staff policy is what actually gates the rows.';

-- ── 2) payments ─────────────────────────────────────────────────────────────────────────────────
-- The ledger is append-only. Nothing in the app deletes a payment; the only thing this grant enabled
-- was destroying the audit trail via the ON DELETE CASCADE to payment_events.
revoke delete on payments from authenticated;

comment on column payments.paid_minor is
  'Ledger credit in EUR minor units. The payments row is APPEND-ONLY: DELETE is revoked from '
  'authenticated because payment_events cascades from it, so deleting a payment would erase the '
  'record of what the customer paid.';


-- 20260902000000_money_path_recovery_fixes
--
-- A declined card used to disable the money-recovery machinery, permanently and silently.
--
-- `bookings.payment_state` is a BOOKING-level column, but append_payment_event wrote it from
-- whichever payment ROW the event touched, and the per-row reducer LATCHES to 'failed'
-- (`bool_or(type = 'failed')` over the row's whole event stream — only a later credit on the SAME
-- row can outrank it). That statement is the only writer of the column anywhere in the schema
-- (verified: every `set payment_state =` in supabase/migrations is that one line), so nothing ever
-- reset it. One declined transaction therefore stamped the booking 'failed' for good, and both
-- recovery paths key off exactly that column:
--
--   * api_pending_payment_checkouts -- the webhook-less safety net the cron sweeps before expiry --
--     enumerates `b.payment_state = 'pending'`. A customer who retried after a decline was excluded
--     from it forever, so if their successful retry's webhook was lost and they closed the tab
--     before /payments/sync ran, nothing would ever re-query Peach. Money taken, never confirmed.
--   * run_booking_maintenance expires `b.payment_state = 'pending'`. A declined-then-abandoned
--     booking was never expired, never emitted booking_expired, and kept a live "Pay now" affordance
--     indefinitely -- including after the departure had run.
--
-- The same latch also forked the payment row: api_create_payment looked for a reusable row
-- `and status <> 'failed'`, so after a decline it skipped the row and inserted a new one. Both
-- anti-double-charge mechanisms -- the still-fresh `existingCheckoutId` reuse and the
-- `checkout_claimed_until` single-flight lease -- are COLUMNS ON that skipped row, so the booking
-- could hold two independently payable Peach sessions at once (peach.ts deliberately treats only
-- 100.396.101 as a closed session, so the first stays payable after a decline). Nothing downstream
-- would have caught the overpayment: the reducer is per-row, so two rows each reaching
-- `v_paid >= amount_minor` both read a clean 'paid' and no one sums across them.
--
-- Each fix re-applies its function's WINNING body verbatim with ONE change, because a migration that
-- re-applies a stale body silently reverts an earlier fix ([[gytm-migration-revert-drift]]):
--   1. append_payment_event  (20260901000800) -- booking projection rolls up across the booking's rows
--   2. api_create_payment    (20260830000000) -- reuse the payment row even when it is 'failed'
--   3. run_booking_maintenance      (20260830000000) -- expire 'failed' as well as 'pending'
--   4. api_pending_payment_checkouts (20260805000000) -- sweep 'failed' as well as 'pending'
--
-- Two further money-path defects from the same sweep, unrelated to the decline latch:
--   1b. append_payment_event also refuses to CONFIRM onto a departure that has been called off. Its
--       confirm branch re-validated capacity but never looked at session_occurrences.status, so a
--       payment settling after api_weather_cancel_occurrence confirmed the guest onto a trip that is
--       not running -- and, because the weather fan-out only stamps bookings that were already
--       confirmed+paid and refuses to re-run on an already-cancelled occurrence, that guest could
--       never be stamped `disruption` afterwards either. Without the stamp there is no 24h bypass,
--       so they were charged, told "confirmed", and locked out of both the refund and the free
--       reschedule. Now routed to refund_pending, the same answer an oversold confirm already gives.
--   5.  api_book (20260901000300) -- the airport and hotel-to-hotel fare overrides get the replay
--       guard every other post-create mutation in that function already has.
--
-- (3) and (4) are safe without (1): both already carry their own money guards at the PAYMENTS level
-- -- run_booking_maintenance refuses any booking with a row that is paid/partially_refunded/refunded,
-- has paid_minor > 0, or is flagged settlement_review_at; api_pending_payment_checkouts skips a
-- payment that already has a 'paid'/'refunded' event. The payment_state predicate was never the
-- thing keeping money safe, only the thing keeping coverage narrow.
--
-- Re-run supabase/catch-up.sql after applying (idempotent).

-- ---------------------------------------------------------------------------
-- 1. append_payment_event -- verbatim from 20260901000800 with ONE change: the `update bookings set
--    payment_state = ...` line becomes a roll-up across every payment row of the booking.
--    Signature is byte-identical, so the pinned execute grants survive the replace; re-issued below
--    anyway (see the definer-grant-leak history).
-- ---------------------------------------------------------------------------
create or replace function append_payment_event(
  p_payment_id uuid,
  p_type text,
  p_provider_event_id text,
  p_amount_minor bigint,
  p_occurred_at timestamptz,
  p_payload jsonb
)
returns payments
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payment payments;
  v_paid bigint;
  v_refunded bigint;
  v_failed boolean;
  v_state payment_state;
  v_booking_state payment_state;
  v_booking_status booking_status;
  v_occ_id uuid;
  v_needed bigint;
  v_cap bigint;
  v_used_conf bigint;
  v_used_hold bigint;
  v_oversold boolean := false;
  v_called_off boolean := false;
begin
  select * into v_payment from payments where id = p_payment_id for update;
  if not found then
    raise exception 'payment_not_found';
  end if;

  insert into payment_events (payment_id, type, provider_event_id, amount_minor, occurred_at, payload)
  values (
    p_payment_id, p_type, p_provider_event_id, coalesce(p_amount_minor, 0),
    coalesce(p_occurred_at, now()), coalesce(p_payload, '{}'::jsonb)
  )
  on conflict (payment_id, provider_event_id, type) do nothing;

  select
    coalesce(sum(amount_minor) filter (where type in ('paid', 'captured')), 0),
    coalesce(sum(amount_minor) filter (where type = 'refunded'), 0),
    bool_or(type = 'failed')
  into v_paid, v_refunded, v_failed
  from payment_events
  where payment_id = p_payment_id;

  if v_paid > 0 and v_refunded >= v_paid then
    v_state := 'refunded';
  elsif v_paid > 0 and v_refunded > 0 then
    v_state := 'partially_refunded';
  -- amount_minor > 0: a zero-amount payment must never read as fully paid (0 >= 0) -- the 'failed'
  -- branch below has to win for it.
  elsif v_payment.amount_minor > 0 and v_paid >= v_payment.amount_minor then
    v_state := 'paid';
  elsif v_paid > 0 then
    v_state := 'pending'; -- underpaid: do not confirm
  elsif coalesce(v_failed, false) then
    v_state := 'failed';
  else
    v_state := 'pending';
  end if;

  update payments
  set status = v_state, paid_minor = v_paid, refunded_minor = v_refunded, updated_at = now()
  where id = p_payment_id
  returning * into v_payment;

  -- BOOKING-level projection, rolled up across every payment row of this booking -- best row wins,
  -- and 'failed' only when EVERY row failed. Written from the single touched row it was a latch: one
  -- declined attempt stamped the booking 'failed' forever (nothing else writes this column), which
  -- silently removed it from api_pending_payment_checkouts and run_booking_maintenance. Ranking
  -- rather than re-summing the ledger keeps this a pure widening: a booking with one payment row --
  -- every booking that never hit the fork -- projects exactly what it projected before.
  -- Ordered paid > partially_refunded > refunded > pending > failed: with two rows after a double
  -- charge, one refunded and one not, money is still held and 'paid' is the honest answer.
  select case min(
           case pay.status
             when 'paid' then 1
             when 'partially_refunded' then 2
             when 'refunded' then 3
             when 'pending' then 4
             when 'failed' then 5
           end
         )
         when 1 then 'paid'
         when 2 then 'partially_refunded'
         when 3 then 'refunded'
         when 5 then 'failed'
         else 'pending'
         end::payment_state
    into v_booking_state
    from payments pay
   where pay.booking_id = v_payment.booking_id;

  update bookings set payment_state = coalesce(v_booking_state, v_state), updated_at = now()
  where id = v_payment.booking_id;

  -- Confirmation stays driven by THIS row reaching 'paid' (v_state), never by the roll-up: a row
  -- that just captured the full amount is what licenses confirming, and reusing the roll-up here
  -- would re-run the capacity re-check on every later event of an already-paid booking.
  if v_state = 'paid' then
    select status into v_booking_status from bookings where id = v_payment.booking_id;

    if v_booking_status in ('draft', 'held', 'payment_pending') then
      -- Re-validate capacity per occurrence, excluding this booking's own items/holds.
      for v_occ_id in
        select distinct session_occurrence_id from booking_items where booking_id = v_payment.booking_id
      loop
        perform 1 from session_occurrences where id = v_occ_id for update;
        select coalesce(sum(quantity), 0) into v_needed
        from booking_items where booking_id = v_payment.booking_id and session_occurrence_id = v_occ_id;
        select capacity into v_cap from session_occurrences where id = v_occ_id;
        select coalesce(sum(bi.quantity), 0) into v_used_conf
        from booking_items bi join bookings b on b.id = bi.booking_id
        where bi.session_occurrence_id = v_occ_id
          and b.status in ('confirmed', 'completed')
          and b.id <> v_payment.booking_id;
        select coalesce(sum(h.quantity), 0) into v_used_hold
        from booking_holds h
        where h.session_occurrence_id = v_occ_id
          and h.status = 'active' and h.expires_at > now()
          and (h.booking_id is null or h.booking_id <> v_payment.booking_id);
        if v_needed > v_cap - v_used_conf - v_used_hold then
          v_oversold := true;
        end if;
      end loop;

      -- Was the departure called off while this payment was in flight?
      --
      -- Confirming here would tell the guest they are booked onto a trip that is not running. Worse,
      -- they could never be put right afterwards: api_weather_cancel_occurrence stamps only bookings
      -- that were ALREADY confirmed+paid when it ran, and it refuses to re-run on an occurrence it
      -- has already cancelled — so this booking would never receive a `disruption` stamp, and that
      -- stamp is the ONLY thing that opens the 24h bypass in api_cancel_booking and
      -- api_reschedule_booking (via booking_awaiting_choice). Charged, told "confirmed", and locked
      -- out of both the refund and the free reschedule /refunds promises.
      --
      -- Route the money back instead — the same answer this function already gives when the seats
      -- turn out to be gone (oversold) or the booking is no longer live. refund_pending frees the
      -- capacity immediately and fires enqueue_booking_notification's refund_pending branch, so the
      -- owner gets a work item and the guest is told.
      select exists (
        select 1
          from booking_items bi
          join session_occurrences so on so.id = bi.session_occurrence_id
         where bi.booking_id = v_payment.booking_id
           and so.status = 'cancelled'
      ) into v_called_off;

      if v_oversold or v_called_off then
        update bookings set status = 'refund_pending', updated_at = now() where id = v_payment.booking_id;
      else
        update bookings set status = 'confirmed', updated_at = now() where id = v_payment.booking_id;
        update booking_holds set status = 'consumed'
        where booking_id = v_payment.booking_id and status = 'active';
      end if;
    elsif v_booking_status not in ('confirmed', 'completed') then
      -- Money captured on an expired/cancelled booking: must be refunded, not confirmed.
      update bookings set status = 'refund_pending', updated_at = now() where id = v_payment.booking_id;
    end if;
  elsif v_state = 'refunded' then
    update bookings set status = 'refunded', updated_at = now()
    where id = v_payment.booking_id and status <> 'cancelled';
    update booking_holds set status = 'released'
    where booking_id = v_payment.booking_id and status = 'active';
  end if;

  return v_payment;
end;
$$;

revoke execute on function append_payment_event(uuid, text, text, bigint, timestamptz, jsonb) from public, anon, authenticated;
grant execute on function append_payment_event(uuid, text, text, bigint, timestamptz, jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- 2. api_create_payment -- verbatim from 20260830000000 with ONE change: the reusable-row lookup no
--    longer excludes `status = 'failed'`.
--
--    Excluding it forked the row and took the double-charge guards with it. Reusing a failed row is
--    safe and is what the surrounding machinery already assumes: a booking that actually holds money
--    is rejected above by the booking_not_payable guard (payment_state in paid/partially_refunded/
--    refunded, which after fix 1 is a true booking-level roll-up), and the caller still verifies the
--    returned session with the provider before reusing it. A retry that succeeds on the reused row
--    outranks the latched 'failed' — the reducer's `v_paid >= amount_minor` branch precedes it.
-- ---------------------------------------------------------------------------
create or replace function api_create_payment(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking bookings;
  v_payment payments;
  v_rate numeric;
  v_src text;
  v_at timestamptz;
  v_charged bigint;
begin
  -- FOR UPDATE: every concurrent create-payment call for one booking serialises on this row for the
  -- rest of the transaction. That closes two races at once: two callers both inserting a payments row
  -- below, and — via the checkout lease — two callers both getting a green light to mint a Peach
  -- session. Peach's nonce is unique per REQUEST (it never dedupes), so without this lease two tabs
  -- or a retry could create two independently payable sessions for the same booking.
  -- (It also makes the charge pin race-free: one caller pins, the loser re-reads the pinned row.)
  select * into v_booking from bookings where ref = p ->> 'bookingRef' for update;
  if not found then
    raise exception 'booking_not_found';
  end if;
  if v_booking.status in ('confirmed', 'completed', 'cancelled', 'expired', 'refund_pending', 'refunded', 'failed')
     or v_booking.payment_state in ('paid', 'partially_refunded', 'refunded') then
    raise exception 'booking_not_payable' using detail = v_booking.status::text;
  end if;
  if not (is_staff() or (auth.uid() is not null and v_booking.user_id = auth.uid())) then
    raise exception 'forbidden';
  end if;

  -- No `and status <> 'failed'`: that skipped the row a declined attempt had latched to 'failed' and
  -- minted a SECOND payments row, orphaning the checkout-reuse window and the single-flight lease
  -- (both columns on the skipped row) and leaving two independently payable Peach sessions.
  select * into v_payment from payments
  where booking_id = v_booking.id
  order by created_at desc
  limit 1;

  if not found then
    -- Scoped to THIS booking: an unscoped key lookup let a caller echo another payment's key and
    -- receive that payment's id/amount back.
    select * into v_payment from payments
    where idempotency_key = p ->> 'idempotencyKey' and booking_id = v_booking.id;
  end if;

  if not found then
    insert into payments (booking_id, idempotency_key, amount_minor)
    values (v_booking.id, p ->> 'idempotencyKey', v_booking.total_minor)
    returning * into v_payment;
    insert into payment_events (payment_id, type, amount_minor)
    values (v_payment.id, 'intent', v_booking.total_minor);
  end if;

  -- ── Pin the charge (once per payment row) ────────────────────────────────────────────────────
  -- The EUR ledger total converted to WHOLE MUR RUPEES at the server-controlled rate. Derived here,
  -- in SQL, from fx_rates — NEVER from caller input (this function is granted to authenticated; a
  -- caller-supplied rate would let a booking owner pin their own MUR 0.05 charge). First-write-wins:
  -- every later call — every re-minted checkout session, the pay page, reconcile — reads THIS figure,
  -- so a moved FX rate between sessions can never make the charge and the expected settlement drift.
  if v_payment.charged_amount_minor is null and v_payment.amount_minor > 0 then
    select r.rate, r.source, r.fetched_at into v_rate, v_src, v_at
      from fx_rates r where r.base = 'EUR' and r.quote = 'MUR';
    -- Band-clamped on READ as well as write: an inverted or foreign payload that somehow reached the
    -- table (0.0185 would bill MUR 1.85 for a EUR 100 booking — and, because settled == charged,
    -- CONFIRM it) falls back to the floor instead of being trusted.
    if v_rate is null or v_rate < 40 or v_rate > 70 then
      v_rate := 53.00; -- cold-start floor; see the fx_rates seed comment (kept below mid on purpose)
      v_src := 'fallback';
      v_at := now();
    end if;
    -- Whole rupees: kills every sub-unit disagreement between what we send Peach and what Peach
    -- reports back. Costs at most MUR 0.50 (~EUR 0.01) per booking.
    v_charged := (round(v_payment.amount_minor * v_rate / 100.0) * 100)::bigint;
    update payments
       set charged_amount_minor = v_charged,
           charged_currency = 'MUR',
           charged_fx_rate = v_rate,
           charged_fx_source = v_src,
           charged_fx_at = v_at,
           updated_at = now()
     where id = v_payment.id and charged_amount_minor is null
     returning * into v_payment;
    if not found then
      -- Another transaction pinned first (or a legacy row already carried a charge): read the truth.
      select * into v_payment from payments where id = v_payment.id;
    end if;
  end if;

  -- Checkout lease (single-flight): exactly one caller may be out creating a Peach session at any
  -- moment. Order matters — reuse beats pending beats claim:
  --   1. a still-fresh recorded checkout        -> hand the SAME session back (reuse; no Peach call);
  --   2. someone else holds an unexpired lease  -> checkoutPending (caller retries shortly);
  --   3. otherwise                              -> stamp the lease and let THIS caller call Peach.
  -- api_record_payment_checkout clears the lease when the session id is recorded; a Peach failure
  -- releases it via api_release_checkout_claim, and the 90-second expiry is the crash backstop.
  --
  -- Freshness is measured from checkout_created_at (when the session was MINTED), never from
  -- updated_at: the reconcile sweep touches updated_at on every pass, which used to re-arm this
  -- window forever and trap the customer on a dead session. The caller still verifies liveness with
  -- the provider before actually reusing what this returns.
  if v_payment.provider_checkout_id is not null
     and coalesce(v_payment.checkout_created_at, v_payment.updated_at) > now() - interval '25 minutes' then
    return jsonb_build_object(
      'paymentId', v_payment.id, 'amountMinor', v_payment.amount_minor,
      'bookingRef', v_booking.ref, 'customerEmail', v_booking.customer_email,
      'existingCheckoutId', v_payment.provider_checkout_id,
      'chargedAmountMinor', v_payment.charged_amount_minor,
      'chargedCurrency', v_payment.charged_currency,
      'chargedFxRate', v_payment.charged_fx_rate
    );
  end if;

  if v_payment.checkout_claimed_until is not null and v_payment.checkout_claimed_until > now() then
    return jsonb_build_object(
      'paymentId', v_payment.id, 'amountMinor', v_payment.amount_minor,
      'bookingRef', v_booking.ref, 'customerEmail', v_booking.customer_email,
      'existingCheckoutId', null,
      'checkoutPending', true,
      'chargedAmountMinor', v_payment.charged_amount_minor,
      'chargedCurrency', v_payment.charged_currency,
      'chargedFxRate', v_payment.charged_fx_rate
    );
  end if;

  update payments set checkout_claimed_until = now() + interval '90 seconds'
  where id = v_payment.id;

  return jsonb_build_object(
    'paymentId', v_payment.id, 'amountMinor', v_payment.amount_minor,
    'bookingRef', v_booking.ref, 'customerEmail', v_booking.customer_email,
    'existingCheckoutId', null,
    'chargedAmountMinor', v_payment.charged_amount_minor,
    'chargedCurrency', v_payment.charged_currency,
    'chargedFxRate', v_payment.charged_fx_rate
  );
end;
$$;

revoke execute on function api_create_payment(jsonb) from public, anon;
grant execute on function api_create_payment(jsonb) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 3. run_booking_maintenance -- verbatim from 20260830000000 with ONE change: the expiry predicate
--    accepts 'failed' as well as 'pending'.
--
--    The money guard is the `not exists` over PAYMENTS below, not this column: a booking with any row
--    that is paid/partially_refunded/refunded, carries paid_minor > 0, or is flagged for settlement
--    review is still never expired. Excluding 'failed' only meant a declined-then-abandoned booking
--    was never released at all.
-- ---------------------------------------------------------------------------
create or replace function run_booking_maintenance(p jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_grace interval := make_interval(
    mins => least(greatest(coalesce((p ->> 'graceMinutes')::int, 30), 1), 1440)
  );
  v_holds int;
  v_bookings int;
begin
  v_holds := expire_holds();

  with stale as (
    update bookings b
       set status = 'expired', updated_at = now()
     where b.status in ('draft', 'held', 'payment_pending')
       and b.payment_state in ('pending', 'failed')
       and b.created_at < now() - v_grace
       and not exists (
         select 1 from payments pay
         where pay.booking_id = b.id
           and (pay.status in ('paid', 'partially_refunded', 'refunded')
                or pay.paid_minor > 0
                or pay.settlement_review_at is not null)
       )
    returning b.id
  ), audited as (
    insert into audit_logs (actor_id, actor_role, action, entity_type, entity_id, summary)
    select null, 'system', 'auto_expire_booking', 'booking', s.id,
           'payment_pending past grace, no settled payment'
    from stale s
    returning 1
  )
  select count(*) into v_bookings from stale;

  -- Release any active holds still attached to the just-expired bookings.
  update booking_holds h
     set status = 'released'
    from bookings b
   where h.booking_id = b.id and b.status = 'expired' and h.status = 'active';

  return jsonb_build_object('holdsExpired', v_holds, 'bookingsExpired', v_bookings);
end;
$$;

revoke execute on function run_booking_maintenance(jsonb) from public, anon, authenticated;
grant execute on function run_booking_maintenance(jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- 4. api_pending_payment_checkouts -- verbatim from 20260805000000 with ONE change: the enumeration
--    predicate accepts 'failed' as well as 'pending'.
--
--    This is the sweep that re-queries Peach when a webhook never arrives. Excluding 'failed' made it
--    skip exactly the customers most likely to need it: the ones retrying after a decline.
--    The `not exists` over payment_events below still keeps an already-settled payment out.
-- ---------------------------------------------------------------------------
create or replace function api_pending_payment_checkouts(p jsonb)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object('ref', t.ref, 'paymentId', t.payment_id, 'checkoutId', t.provider_checkout_id)
      order by t.created_at desc
    ),
    '[]'::jsonb
  )
  from (
    -- latest payment per booking (a re-pay opens a fresh checkout the sweep must query), then the
    -- most-recent stuck bookings up to the batch cap. The two orderings need separate query levels:
    -- distinct-on requires its leading sort be (b.id, pay.created_at), so recency + limit wrap it.
    -- LATERAL over (current, previous) checkout ids: a customer can complete a checkout minted
    -- before a re-pay overwrote the pointer (Peach sessions stay completable ~30 min) -- sweeping
    -- both ids means that capture is ingested instead of stranded.
    select c.ref, c.payment_id, v.checkout_id as provider_checkout_id, c.created_at
    from (
      select distinct on (b.id)
             b.id, b.ref, b.created_at, pay.id as payment_id, pay.provider_checkout_id, pay.prev_provider_checkout_id
        from bookings b
        join payments pay on pay.booking_id = b.id
       where b.status = 'payment_pending'
         and b.payment_state in ('pending', 'failed')
         and b.created_at > now() - make_interval(
               mins => least(greatest(coalesce((p ->> 'graceMinutes')::int, 240), 1), 10080)
             )
         and pay.provider_checkout_id is not null
         and not exists (
               select 1 from payment_events pe
                where pe.payment_id = pay.id and pe.type in ('paid', 'refunded')
             )
       order by b.id, pay.created_at desc
    ) c
    cross join lateral (values (c.provider_checkout_id), (c.prev_provider_checkout_id)) as v(checkout_id)
    where v.checkout_id is not null
    -- recency-ordered batch, capped (default 100, hard ceiling 1000) to bound Peach API calls per run
    order by c.created_at desc
    limit least(greatest(coalesce((p ->> 'limit')::int, 100), 1), 1000)
  ) t;
$$;

revoke execute on function api_pending_payment_checkouts(jsonb) from public, anon, authenticated;
grant execute on function api_pending_payment_checkouts(jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- Repair the rows the latch already stranded: a booking still in flight whose projection reads
-- 'failed' while none of its payment rows actually holds money. Recomputed with the same ranking the
-- function now uses, so it is idempotent and a no-op once the code above is live.
-- ---------------------------------------------------------------------------
update bookings b
   set payment_state = 'pending', updated_at = now()
 where b.payment_state = 'failed'
   and b.status in ('draft', 'held', 'payment_pending')
   and exists (select 1 from payments pay where pay.booking_id = b.id and pay.status <> 'failed')
   and not exists (
     select 1 from payments pay
     where pay.booking_id = b.id
       and (pay.status in ('paid', 'partially_refunded', 'refunded') or pay.paid_minor > 0)
   );


-- ---------------------------------------------------------------------------
-- 5. api_book -- verbatim from 20260901000300 with ONE change, applied to BOTH fare-override blocks
--    (airport and hotel-to-hotel, which are byte-identical): the override is skipped once the booking
--    has a payment row.
--
--    Every other post-create mutation here is already replay-safe, because create_booking returns the
--    EXISTING row on an idempotency-key replay -- the child-seat extra is guarded `and child_seats = 0`,
--    the transport add-on `and transport_minor = 0`, the itinerary `and custom_itinerary is null`.
--    The transfer fare branches were the exception: they re-wrote total_minor, operator_payout_minor
--    and the line item unconditionally, so a replayed POST re-priced a live booking underneath a
--    pinned MUR charge and an already-minted Peach session.
-- ---------------------------------------------------------------------------
create or replace function api_book(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_occ uuid := (p ->> 'occurrenceId')::uuid;
  v_key text := p ->> 'idempotencyKey';
  v_expected_slug text := nullif(p ->> 'expectedSlug', '');
  v_total_qty bigint := 0;
  v_items jsonb := '[]'::jsonb;
  v_mode text := 'per_person';
  v_is_private boolean := false;
  v_suv boolean := coalesce((p ->> 'suv')::boolean, false);
  v_hold_id uuid := nullif(p ->> 'holdId', '')::uuid;
  v_want_qty int;
  v_reused boolean := false;
  v_child int;
  v_child_extra bigint;
  v_hold booking_holds;
  v_booking bookings;
  r record;
  v_activity_region text;
  v_pickup_available boolean := false;
  v_pickup_lat double precision;
  v_pickup_lng double precision;
  v_pickup_region text;
  v_transport bigint;
  v_is_airport boolean := false;
  v_is_hotel boolean := false;
  v_dropoff_zone text;
  v_trip_type text;
  v_trip_direction text;
  v_ret_pct int;
  v_fare bigint;
  v_hotel_pickup_region text;
  v_hotel_dropoff_region text;
  v_band text;
  v_actor uuid;
begin
  if v_occ is null or v_key is null then
    raise exception 'invalid_request';
  end if;

  if v_expected_slug is not null and not exists (
    select 1 from session_occurrences so
    join activity_options o on o.id = so.activity_option_id
    join activities a on a.id = o.activity_id
    where so.id = v_occ and a.slug = v_expected_slug
  ) then
    raise exception 'occurrence_activity_mismatch';
  end if;

  for r in select key, (value::text)::bigint as q from jsonb_each(p -> 'party') loop
    if r.q < 0 or r.q > 1000000 then raise exception 'invalid_party'; end if;
    if r.q > 0 then
      v_total_qty := v_total_qty + r.q;
      v_items := v_items || jsonb_build_object('price_label', r.key, 'quantity', r.q);
    end if;
  end loop;
  if v_total_qty <= 0 or v_total_qty > 1000000 then raise exception 'invalid_party'; end if;

  select a.pricing_mode,
         coalesce(a.region, region_from_coords(a.lat, a.lng)),
         coalesce(a.pickup_available, false),
         coalesce(a.is_airport_transfer, false),
         coalesce(a.is_hotel_transfer, false),
         (o.private_base_minor is not null)
    into v_mode, v_activity_region, v_pickup_available, v_is_airport, v_is_hotel, v_is_private
  from session_occurrences so
  join activity_options o on o.id = so.activity_option_id
  join activities a on a.id = o.activity_id
  where so.id = v_occ;
  v_mode := coalesce(v_mode, 'per_person');
  v_want_qty := case when v_mode in ('vehicle', 'vehicle_custom')
                       or coalesce(v_is_private, false) then 1 else v_total_qty::int end;

  -- Actor identity, resolved BEFORE the hold-reuse gate so ownership can bind reuse. api_book is
  -- service-role-only, so auth.uid() is null; the JWKS-verified caller id arrives as p.actorUserId
  -- (trustworthy BECAUSE only the server can execute this function). auth.uid() stays first as
  -- belt-and-suspenders.
  v_actor := coalesce(auth.uid(), nullif(p ->> 'actorUserId', '')::uuid);

  if v_hold_id is not null then
    -- FOR UPDATE: two concurrent api_book calls quoting the same holdId must serialise here, or both
    -- read booking_id IS NULL and both proceed (create_booking's own lock cannot save the second one
    -- on its own — it re-checks under the lock, but only because of the guard added alongside this).
    -- Ownership: an OWNED hold (created_by set) is only reusable by its owner; an ownerless hold
    -- (guest checkout, or created before sign-in) stays reusable by whoever holds the unguessable id,
    -- which keeps the guest → sign-in-mid-checkout flow working.
    select * into v_hold from booking_holds
    where id = v_hold_id and status = 'active' and expires_at > now() and booking_id is null
      and session_occurrence_id = v_occ and quantity = v_want_qty
      and (created_by is null or created_by = v_actor)
    for update;
    if found then v_reused := true; end if;
  end if;
  if not v_reused then
    v_hold := create_hold(v_occ, v_want_qty, v_key || ':book');
  end if;

  v_booking := create_booking(
    v_key, v_hold.id, p ->> 'customerName', p ->> 'customerEmail', p ->> 'customerPhone',
    coalesce((p ->> 'source')::booking_source, 'web'), v_items, v_suv
  );

  -- F23 (replay-disclosure guard): create_booking returns the existing row on an idempotency-key
  -- replay, and api_book runs SECURITY DEFINER, so RLS does not filter the returned DTO. Refuse to
  -- echo a booking the caller can't prove they own:
  --   * an authenticated user replaying someone else's OWNED booking -> forbidden;
  --   * ANY caller replaying an UNOWNED (guest) booking whose supplied email doesn't match -> forbidden.
  --     A stolen/guessed key alone (authenticated OR anonymous) would otherwise hand back the original
  --     guest's PII / let an authed caller adopt the row. A legitimate retry resends the same email and
  --     passes; a fresh create trivially passes (just inserted with this caller's email).
  if (v_booking.user_id is not null and v_booking.user_id is distinct from v_actor)
     or (v_booking.user_id is null
         and lower(coalesce(v_booking.customer_email, '')) <> lower(coalesce(p ->> 'customerEmail', '')))
  then
    raise exception 'forbidden';
  end if;
  if v_actor is not null then
    update bookings set user_id = v_actor where id = v_booking.id and user_id is null;
  end if;

  -- Ownership for the FALLBACK hold: when no reusable holdId was supplied, api_book mints its own
  -- hold above via create_hold, which runs under service_role here (server-only RPC) and so wrote
  -- created_by = auth.uid() = NULL. Stamp the actor onto it so the customer's owner-scoped hold
  -- status/release endpoints work. A REUSED hold already carries its owner (created_by not null),
  -- so the guard leaves it alone; a guest booking (v_actor null) leaves the hold ownerless as before.
  if v_actor is not null then
    update booking_holds set created_by = v_actor where id = v_hold.id and created_by is null;
  end if;

  -- The language the guest booked in. Email and PDFs render later, often from a cron worker with no
  -- request context, so the locale must be stored rather than inferred at send time. Unconditional: by
  -- this point the F23 guard above has already verified the caller may act on this booking, so re-
  -- asserting the same value on an idempotent replay is harmless. Absent/empty collapses to 'en' (never
  -- SQL NULL, never a failed enum cast), so an older client that sends no locale still books cleanly.
  update bookings
  set locale = coalesce(nullif(p ->> 'locale', ''), 'en')::content_locale
  where id = v_booking.id;

  if p ? 'itinerary'
     and jsonb_typeof(p -> 'itinerary') = 'array'
     and jsonb_array_length(p -> 'itinerary') > 0
     and jsonb_array_length(p -> 'itinerary') <= 30
  then
    update bookings set custom_itinerary = p -> 'itinerary'
    where id = v_booking.id and custom_itinerary is null;
  end if;

  if nullif(btrim(p ->> 'pickupLocation'), '') is not null then
    update bookings set pickup_location = left(btrim(p ->> 'pickupLocation'), 200)
    where id = v_booking.id and pickup_location is null;
  end if;

  -- Drop-off is its OWN field (never merged into pickup_location). pickup_pending records "pickup to be
  -- arranged" — distinct from "no pickup" — and is set on the just-created row only.
  if nullif(btrim(p ->> 'dropoffLocation'), '') is not null then
    update bookings set dropoff_location = left(btrim(p ->> 'dropoffLocation'), 200)
    where id = v_booking.id and dropoff_location is null;
  end if;

  if coalesce((p ->> 'pickupPending')::boolean, false) then
    update bookings set pickup_pending = true
    where id = v_booking.id and pickup_pending = false;
  end if;

  -- Airport transfer (server-authoritative, zero-trust): the destination ZONE comes from the hotel
  -- SLUG via airport_transfer_hotels — never a client-sent zone. When the guest's hotel isn't listed
  -- (no dropoffSlug), classify the zone from the supplied AREA instead (Zone 2 = the near-airport
  -- south-east areas), still never trusting a client price. The whole fare is the zone × vehicle matrix
  -- (vehicle derived from party size + the ≤4 SUV upgrade); a return trip is two legs minus the
  -- configured discount. We OVERRIDE the booking total + payout + the single line item so the receipt's
  -- item == total. Mirrors airportTransferQuoteMinor() in pricing.ts.
  if v_is_airport then
    v_trip_direction := case
      when (p ->> 'tripDirection') in ('arrival', 'departure', 'return') then p ->> 'tripDirection'
      when (p ->> 'tripType') = 'return' then 'return'
      else 'arrival'
    end;
    v_trip_type := case when v_trip_direction = 'return' then 'return' else 'one_way' end;
    if nullif(p ->> 'dropoffSlug', '') is not null then
      select zone into v_dropoff_zone from airport_transfer_hotels
        where slug = nullif(p ->> 'dropoffSlug', '');
    end if;
    if v_dropoff_zone is null then
      v_dropoff_zone := airport_transfer_area_zone(p ->> 'dropoffArea');
    end if;
    v_fare := airport_transfer_fare_minor(v_dropoff_zone, v_total_qty::int, v_suv);
    if v_trip_type = 'return' then
      select coalesce(return_discount_pct, 0) into v_ret_pct from airport_transfer_config limit 1;
      v_fare := round(v_fare::numeric * 2 * (100 - coalesce(v_ret_pct, 0)) / 100)::bigint;
    end if;
    -- Replay guard, matching the pattern every other post-create mutation in this function already
    -- uses (`and custom_itinerary is null`, `and pickup_location is null`, `and pickup_pending = false`).
    -- create_booking returns the EXISTING row on an idempotency-key replay, so unguarded this silently
    -- re-prices a booking that has already started paying -- moving total_minor out from under the MUR
    -- charge pinned on its payment row and a Peach session already minted for the old amount.
    if v_fare > 0 and not exists (select 1 from payments pay where pay.booking_id = v_booking.id) then
      update bookings
        set total_minor = v_fare, operator_payout_minor = v_fare
        where id = v_booking.id;
      update booking_items
        set unit_amount_minor = v_fare, subtotal_minor = v_fare
        where booking_id = v_booking.id;
    end if;
    update bookings set
        trip_type = v_trip_type,
        trip_direction = v_trip_direction,
        flight_number = left(nullif(btrim(p ->> 'flightNumber'), ''), 40),
        arrival_time = left(nullif(btrim(p ->> 'arrivalTime'), ''), 40),
        return_date = nullif(p ->> 'returnDate', '')::date,
        return_time = left(nullif(btrim(p ->> 'returnTime'), ''), 40),
        departure_flight_number = left(nullif(btrim(p ->> 'departureFlightNumber'), ''), 40),
        room_or_cabin = left(nullif(btrim(p ->> 'roomOrCabin'), ''), 60),
        luggage_details = left(nullif(btrim(p ->> 'luggageDetails'), ''), 300),
        child_seat_age = nullif(p ->> 'childSeatAge', '')::int,
        traveller_gender = left(nullif(btrim(p ->> 'travellerGender'), ''), 20),
        traveller_company = left(nullif(btrim(p ->> 'travellerCompany'), ''), 120),
        traveller_country = left(nullif(btrim(p ->> 'travellerCountry'), ''), 80),
        special_notes = left(nullif(btrim(p ->> 'specialNotes'), ''), 600)
      where id = v_booking.id;
  end if;

  -- Hotel-to-hotel transfer (server-authoritative, zero-trust): derive BOTH endpoints' regions from the
  -- hotel SLUGS via airport_transfer_hotels (or area_region() for a free-text end), reject a same-hotel
  -- trip, classify the distance band (region_distance_band), and price band × vehicle (× return discount).
  -- OVERRIDE the booking total + payout + line item. Mirrors hotelTransferQuoteMinor() in pricing.ts.
  if v_is_hotel then
    if nullif(p ->> 'pickupSlug', '') is not null
       and nullif(p ->> 'pickupSlug', '') = nullif(p ->> 'dropoffSlug', '') then
      raise exception 'same_hotel';
    end if;
    v_trip_type := case when (p ->> 'tripType') = 'return' then 'return' else 'one_way' end;
    v_hotel_pickup_region := hotel_end_region(
      p ->> 'pickupSlug',
      nullif(p ->> 'pickupLat', '')::double precision,
      nullif(p ->> 'pickupLng', '')::double precision,
      p ->> 'pickupArea');
    v_hotel_dropoff_region := hotel_end_region(
      p ->> 'dropoffSlug',
      nullif(p ->> 'dropoffLat', '')::double precision,
      nullif(p ->> 'dropoffLng', '')::double precision,
      p ->> 'dropoffArea');
    v_band := region_distance_band(v_hotel_pickup_region, v_hotel_dropoff_region);
    v_fare := hotel_transfer_fare_minor(v_band, v_total_qty::int, v_suv);
    if v_trip_type = 'return' then
      select coalesce(return_discount_pct, 0) into v_ret_pct from hotel_transfer_config limit 1;
      v_fare := round(v_fare::numeric * 2 * (100 - coalesce(v_ret_pct, 0)) / 100)::bigint;
    end if;
    -- Replay guard, matching the pattern every other post-create mutation in this function already
    -- uses (`and custom_itinerary is null`, `and pickup_location is null`, `and pickup_pending = false`).
    -- create_booking returns the EXISTING row on an idempotency-key replay, so unguarded this silently
    -- re-prices a booking that has already started paying -- moving total_minor out from under the MUR
    -- charge pinned on its payment row and a Peach session already minted for the old amount.
    if v_fare > 0 and not exists (select 1 from payments pay where pay.booking_id = v_booking.id) then
      update bookings
        set total_minor = v_fare, operator_payout_minor = v_fare
        where id = v_booking.id;
      update booking_items
        set unit_amount_minor = v_fare, subtotal_minor = v_fare
        where booking_id = v_booking.id;
    end if;
    update bookings set
        trip_type = v_trip_type,
        arrival_time = left(nullif(btrim(p ->> 'arrivalTime'), ''), 40),
        pickup_hotel_slug = left(nullif(btrim(p ->> 'pickupSlug'), ''), 120),
        pickup_region = v_hotel_pickup_region,
        return_date = nullif(p ->> 'returnDate', '')::date,
        return_time = left(nullif(btrim(p ->> 'returnTime'), ''), 40),
        room_or_cabin = left(nullif(btrim(p ->> 'roomOrCabin'), ''), 60),
        luggage_details = left(nullif(btrim(p ->> 'luggageDetails'), ''), 300),
        special_notes = left(nullif(btrim(p ->> 'specialNotes'), ''), 600)
      where id = v_booking.id;
  end if;

  v_child := least(greatest(coalesce(nullif(p ->> 'childSeats', '')::int, 0), 0), v_total_qty::int);
  if v_child > 0 then
    v_child_extra := greatest(0, v_child - 1) * 600;
    update bookings
    set child_seats = v_child,
        total_minor = total_minor + v_child_extra,
        operator_payout_minor = operator_payout_minor + v_child_extra
    where id = v_booking.id and child_seats = 0;
  end if;

  -- Region-based transport add-on (per_person / per_group with pickup_available): a fee that scales with
  -- how far the pickup is from the activity's boarding region. The server RE-DERIVES the region from the
  -- pickup coordinates and looks up the fare here — it never trusts a client-sent price. Round-trip rule:
  -- drop-off doesn't change the fare, so it isn't read. Mirrors transportFare() in pricing.ts.
  if v_mode in ('per_person', 'per_group') and v_pickup_available
     and nullif(p ->> 'pickupLat', '') is not null
     and nullif(p ->> 'pickupLng', '') is not null
  then
    v_pickup_lat := (p ->> 'pickupLat')::double precision;
    v_pickup_lng := (p ->> 'pickupLng')::double precision;
    v_pickup_region := region_from_coords(v_pickup_lat, v_pickup_lng);
    if v_pickup_region is not null and v_activity_region is not null then
      v_transport := transport_fare_minor(v_pickup_region, v_activity_region, v_total_qty::int, v_suv);
      if v_transport > 0 then
        update bookings
        set transport_minor = v_transport,
            total_minor = total_minor + v_transport,
            operator_payout_minor = operator_payout_minor + v_transport,
            pickup_region = v_pickup_region,
            pickup_lat = v_pickup_lat,
            pickup_lng = v_pickup_lng
        where id = v_booking.id and transport_minor = 0;
      end if;
    end if;
  end if;

  return booking_json(v_booking.id);
end;
$$;

revoke execute on function api_book(jsonb) from public, anon, authenticated;
grant execute on function api_book(jsonb) to service_role;


-- 20260903000000_book_replay_no_orphan_hold
--
-- api_book: don't mint a hold when replaying a booking that already exists.
--
-- Found by the money-path sweep (the last of the four split-verdict findings, run down by hand).
-- One refuter called it unreachable because create_hold is idempotent on its key -- true, but it
-- misses that on the FIRST call create_hold is never reached at all: the supplied hold is reused, so
-- no hold ever carries the `<key>:book` idempotency key. The replay is therefore the first call to
-- create_hold, and it mints.
--
-- Sequence:
--   1. POST /api/v1/bookings with holdId H and idempotency key K. H is active and unclaimed, so the
--      reuse SELECT matches, v_reused = true, create_hold is NOT called. create_booking claims H.
--   2. The response is lost; the client retries with the SAME K and the SAME holdId (the documented
--      replay path).
--   3. The reuse SELECT now requires `booking_id is null` and H is claimed -> no match, v_reused
--      false -> create_hold mints a NEW hold under key K||':book'.
--   4. create_booking sees K, returns the existing booking, and never touches that new hold.
--
-- The orphan is active and counted by used_capacity until it expires. On a departure with little left
-- create_hold raises insufficient_capacity in step 3, so the retry FAILS and the caller is told the
-- booking did not happen -- when it did. Self-limiting at one orphan (a further replay finds it by
-- key), which is still enough to block the last vehicle on a private transfer.
--
-- Verbatim re-application of the winning api_book body (20260902000000) with that one guard added --
-- a stale re-apply silently reverts an earlier fix ([[gytm-migration-revert-drift]]).
--
-- Re-run supabase/catch-up.sql after applying (idempotent).

create or replace function api_book(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_occ uuid := (p ->> 'occurrenceId')::uuid;
  v_key text := p ->> 'idempotencyKey';
  v_expected_slug text := nullif(p ->> 'expectedSlug', '');
  v_total_qty bigint := 0;
  v_items jsonb := '[]'::jsonb;
  v_mode text := 'per_person';
  v_is_private boolean := false;
  v_suv boolean := coalesce((p ->> 'suv')::boolean, false);
  v_hold_id uuid := nullif(p ->> 'holdId', '')::uuid;
  v_want_qty int;
  v_reused boolean := false;
  v_child int;
  v_child_extra bigint;
  v_hold booking_holds;
  v_booking bookings;
  r record;
  v_activity_region text;
  v_pickup_available boolean := false;
  v_pickup_lat double precision;
  v_pickup_lng double precision;
  v_pickup_region text;
  v_transport bigint;
  v_is_airport boolean := false;
  v_is_hotel boolean := false;
  v_dropoff_zone text;
  v_trip_type text;
  v_trip_direction text;
  v_ret_pct int;
  v_fare bigint;
  v_hotel_pickup_region text;
  v_hotel_dropoff_region text;
  v_band text;
  v_actor uuid;
begin
  if v_occ is null or v_key is null then
    raise exception 'invalid_request';
  end if;

  if v_expected_slug is not null and not exists (
    select 1 from session_occurrences so
    join activity_options o on o.id = so.activity_option_id
    join activities a on a.id = o.activity_id
    where so.id = v_occ and a.slug = v_expected_slug
  ) then
    raise exception 'occurrence_activity_mismatch';
  end if;

  for r in select key, (value::text)::bigint as q from jsonb_each(p -> 'party') loop
    if r.q < 0 or r.q > 1000000 then raise exception 'invalid_party'; end if;
    if r.q > 0 then
      v_total_qty := v_total_qty + r.q;
      v_items := v_items || jsonb_build_object('price_label', r.key, 'quantity', r.q);
    end if;
  end loop;
  if v_total_qty <= 0 or v_total_qty > 1000000 then raise exception 'invalid_party'; end if;

  select a.pricing_mode,
         coalesce(a.region, region_from_coords(a.lat, a.lng)),
         coalesce(a.pickup_available, false),
         coalesce(a.is_airport_transfer, false),
         coalesce(a.is_hotel_transfer, false),
         (o.private_base_minor is not null)
    into v_mode, v_activity_region, v_pickup_available, v_is_airport, v_is_hotel, v_is_private
  from session_occurrences so
  join activity_options o on o.id = so.activity_option_id
  join activities a on a.id = o.activity_id
  where so.id = v_occ;
  v_mode := coalesce(v_mode, 'per_person');
  v_want_qty := case when v_mode in ('vehicle', 'vehicle_custom')
                       or coalesce(v_is_private, false) then 1 else v_total_qty::int end;

  -- Actor identity, resolved BEFORE the hold-reuse gate so ownership can bind reuse. api_book is
  -- service-role-only, so auth.uid() is null; the JWKS-verified caller id arrives as p.actorUserId
  -- (trustworthy BECAUSE only the server can execute this function). auth.uid() stays first as
  -- belt-and-suspenders.
  v_actor := coalesce(auth.uid(), nullif(p ->> 'actorUserId', '')::uuid);

  if v_hold_id is not null then
    -- FOR UPDATE: two concurrent api_book calls quoting the same holdId must serialise here, or both
    -- read booking_id IS NULL and both proceed (create_booking's own lock cannot save the second one
    -- on its own — it re-checks under the lock, but only because of the guard added alongside this).
    -- Ownership: an OWNED hold (created_by set) is only reusable by its owner; an ownerless hold
    -- (guest checkout, or created before sign-in) stays reusable by whoever holds the unguessable id,
    -- which keeps the guest → sign-in-mid-checkout flow working.
    select * into v_hold from booking_holds
    where id = v_hold_id and status = 'active' and expires_at > now() and booking_id is null
      and session_occurrence_id = v_occ and quantity = v_want_qty
      and (created_by is null or created_by = v_actor)
    for update;
    if found then v_reused := true; end if;
  end if;
  -- A REPLAY whose booking already exists must not mint a hold.
  --
  -- create_booking's idempotency check runs before it ever looks at p_hold_id, so on a replay it
  -- returns the existing booking and never attaches whatever hold we passed. The original hold is by
  -- then consumed (booking_id set), so the reuse SELECT above cannot match it and v_reused is false --
  -- and create_hold would mint a fresh one that nothing ever claims. It then sits ACTIVE, counted by
  -- used_capacity, for its whole TTL. Worse, on a nearly-full departure create_hold raises
  -- insufficient_capacity, so a legitimate retry of a booking that ALREADY SUCCEEDED fails instead of
  -- returning it -- the caller is told the booking failed when it did not.
  -- (Only ever one orphan: a second replay finds it by idempotency key. One is enough to sell out a
  -- last vehicle.)
  if not v_reused and not exists (select 1 from bookings where idempotency_key = v_key) then
    v_hold := create_hold(v_occ, v_want_qty, v_key || ':book');
  end if;

  v_booking := create_booking(
    v_key, v_hold.id, p ->> 'customerName', p ->> 'customerEmail', p ->> 'customerPhone',
    coalesce((p ->> 'source')::booking_source, 'web'), v_items, v_suv
  );

  -- F23 (replay-disclosure guard): create_booking returns the existing row on an idempotency-key
  -- replay, and api_book runs SECURITY DEFINER, so RLS does not filter the returned DTO. Refuse to
  -- echo a booking the caller can't prove they own:
  --   * an authenticated user replaying someone else's OWNED booking -> forbidden;
  --   * ANY caller replaying an UNOWNED (guest) booking whose supplied email doesn't match -> forbidden.
  --     A stolen/guessed key alone (authenticated OR anonymous) would otherwise hand back the original
  --     guest's PII / let an authed caller adopt the row. A legitimate retry resends the same email and
  --     passes; a fresh create trivially passes (just inserted with this caller's email).
  if (v_booking.user_id is not null and v_booking.user_id is distinct from v_actor)
     or (v_booking.user_id is null
         and lower(coalesce(v_booking.customer_email, '')) <> lower(coalesce(p ->> 'customerEmail', '')))
  then
    raise exception 'forbidden';
  end if;
  if v_actor is not null then
    update bookings set user_id = v_actor where id = v_booking.id and user_id is null;
  end if;

  -- Ownership for the FALLBACK hold: when no reusable holdId was supplied, api_book mints its own
  -- hold above via create_hold, which runs under service_role here (server-only RPC) and so wrote
  -- created_by = auth.uid() = NULL. Stamp the actor onto it so the customer's owner-scoped hold
  -- status/release endpoints work. A REUSED hold already carries its owner (created_by not null),
  -- so the guard leaves it alone; a guest booking (v_actor null) leaves the hold ownerless as before.
  if v_actor is not null then
    update booking_holds set created_by = v_actor where id = v_hold.id and created_by is null;
  end if;

  -- The language the guest booked in. Email and PDFs render later, often from a cron worker with no
  -- request context, so the locale must be stored rather than inferred at send time. Unconditional: by
  -- this point the F23 guard above has already verified the caller may act on this booking, so re-
  -- asserting the same value on an idempotent replay is harmless. Absent/empty collapses to 'en' (never
  -- SQL NULL, never a failed enum cast), so an older client that sends no locale still books cleanly.
  update bookings
  set locale = coalesce(nullif(p ->> 'locale', ''), 'en')::content_locale
  where id = v_booking.id;

  if p ? 'itinerary'
     and jsonb_typeof(p -> 'itinerary') = 'array'
     and jsonb_array_length(p -> 'itinerary') > 0
     and jsonb_array_length(p -> 'itinerary') <= 30
  then
    update bookings set custom_itinerary = p -> 'itinerary'
    where id = v_booking.id and custom_itinerary is null;
  end if;

  if nullif(btrim(p ->> 'pickupLocation'), '') is not null then
    update bookings set pickup_location = left(btrim(p ->> 'pickupLocation'), 200)
    where id = v_booking.id and pickup_location is null;
  end if;

  -- Drop-off is its OWN field (never merged into pickup_location). pickup_pending records "pickup to be
  -- arranged" — distinct from "no pickup" — and is set on the just-created row only.
  if nullif(btrim(p ->> 'dropoffLocation'), '') is not null then
    update bookings set dropoff_location = left(btrim(p ->> 'dropoffLocation'), 200)
    where id = v_booking.id and dropoff_location is null;
  end if;

  if coalesce((p ->> 'pickupPending')::boolean, false) then
    update bookings set pickup_pending = true
    where id = v_booking.id and pickup_pending = false;
  end if;

  -- Airport transfer (server-authoritative, zero-trust): the destination ZONE comes from the hotel
  -- SLUG via airport_transfer_hotels — never a client-sent zone. When the guest's hotel isn't listed
  -- (no dropoffSlug), classify the zone from the supplied AREA instead (Zone 2 = the near-airport
  -- south-east areas), still never trusting a client price. The whole fare is the zone × vehicle matrix
  -- (vehicle derived from party size + the ≤4 SUV upgrade); a return trip is two legs minus the
  -- configured discount. We OVERRIDE the booking total + payout + the single line item so the receipt's
  -- item == total. Mirrors airportTransferQuoteMinor() in pricing.ts.
  if v_is_airport then
    v_trip_direction := case
      when (p ->> 'tripDirection') in ('arrival', 'departure', 'return') then p ->> 'tripDirection'
      when (p ->> 'tripType') = 'return' then 'return'
      else 'arrival'
    end;
    v_trip_type := case when v_trip_direction = 'return' then 'return' else 'one_way' end;
    if nullif(p ->> 'dropoffSlug', '') is not null then
      select zone into v_dropoff_zone from airport_transfer_hotels
        where slug = nullif(p ->> 'dropoffSlug', '');
    end if;
    if v_dropoff_zone is null then
      v_dropoff_zone := airport_transfer_area_zone(p ->> 'dropoffArea');
    end if;
    v_fare := airport_transfer_fare_minor(v_dropoff_zone, v_total_qty::int, v_suv);
    if v_trip_type = 'return' then
      select coalesce(return_discount_pct, 0) into v_ret_pct from airport_transfer_config limit 1;
      v_fare := round(v_fare::numeric * 2 * (100 - coalesce(v_ret_pct, 0)) / 100)::bigint;
    end if;
    -- Replay guard, matching the pattern every other post-create mutation in this function already
    -- uses (`and custom_itinerary is null`, `and pickup_location is null`, `and pickup_pending = false`).
    -- create_booking returns the EXISTING row on an idempotency-key replay, so unguarded this silently
    -- re-prices a booking that has already started paying -- moving total_minor out from under the MUR
    -- charge pinned on its payment row and a Peach session already minted for the old amount.
    if v_fare > 0 and not exists (select 1 from payments pay where pay.booking_id = v_booking.id) then
      update bookings
        set total_minor = v_fare, operator_payout_minor = v_fare
        where id = v_booking.id;
      update booking_items
        set unit_amount_minor = v_fare, subtotal_minor = v_fare
        where booking_id = v_booking.id;
    end if;
    update bookings set
        trip_type = v_trip_type,
        trip_direction = v_trip_direction,
        flight_number = left(nullif(btrim(p ->> 'flightNumber'), ''), 40),
        arrival_time = left(nullif(btrim(p ->> 'arrivalTime'), ''), 40),
        return_date = nullif(p ->> 'returnDate', '')::date,
        return_time = left(nullif(btrim(p ->> 'returnTime'), ''), 40),
        departure_flight_number = left(nullif(btrim(p ->> 'departureFlightNumber'), ''), 40),
        room_or_cabin = left(nullif(btrim(p ->> 'roomOrCabin'), ''), 60),
        luggage_details = left(nullif(btrim(p ->> 'luggageDetails'), ''), 300),
        child_seat_age = nullif(p ->> 'childSeatAge', '')::int,
        traveller_gender = left(nullif(btrim(p ->> 'travellerGender'), ''), 20),
        traveller_company = left(nullif(btrim(p ->> 'travellerCompany'), ''), 120),
        traveller_country = left(nullif(btrim(p ->> 'travellerCountry'), ''), 80),
        special_notes = left(nullif(btrim(p ->> 'specialNotes'), ''), 600)
      where id = v_booking.id;
  end if;

  -- Hotel-to-hotel transfer (server-authoritative, zero-trust): derive BOTH endpoints' regions from the
  -- hotel SLUGS via airport_transfer_hotels (or area_region() for a free-text end), reject a same-hotel
  -- trip, classify the distance band (region_distance_band), and price band × vehicle (× return discount).
  -- OVERRIDE the booking total + payout + line item. Mirrors hotelTransferQuoteMinor() in pricing.ts.
  if v_is_hotel then
    if nullif(p ->> 'pickupSlug', '') is not null
       and nullif(p ->> 'pickupSlug', '') = nullif(p ->> 'dropoffSlug', '') then
      raise exception 'same_hotel';
    end if;
    v_trip_type := case when (p ->> 'tripType') = 'return' then 'return' else 'one_way' end;
    v_hotel_pickup_region := hotel_end_region(
      p ->> 'pickupSlug',
      nullif(p ->> 'pickupLat', '')::double precision,
      nullif(p ->> 'pickupLng', '')::double precision,
      p ->> 'pickupArea');
    v_hotel_dropoff_region := hotel_end_region(
      p ->> 'dropoffSlug',
      nullif(p ->> 'dropoffLat', '')::double precision,
      nullif(p ->> 'dropoffLng', '')::double precision,
      p ->> 'dropoffArea');
    v_band := region_distance_band(v_hotel_pickup_region, v_hotel_dropoff_region);
    v_fare := hotel_transfer_fare_minor(v_band, v_total_qty::int, v_suv);
    if v_trip_type = 'return' then
      select coalesce(return_discount_pct, 0) into v_ret_pct from hotel_transfer_config limit 1;
      v_fare := round(v_fare::numeric * 2 * (100 - coalesce(v_ret_pct, 0)) / 100)::bigint;
    end if;
    -- Replay guard, matching the pattern every other post-create mutation in this function already
    -- uses (`and custom_itinerary is null`, `and pickup_location is null`, `and pickup_pending = false`).
    -- create_booking returns the EXISTING row on an idempotency-key replay, so unguarded this silently
    -- re-prices a booking that has already started paying -- moving total_minor out from under the MUR
    -- charge pinned on its payment row and a Peach session already minted for the old amount.
    if v_fare > 0 and not exists (select 1 from payments pay where pay.booking_id = v_booking.id) then
      update bookings
        set total_minor = v_fare, operator_payout_minor = v_fare
        where id = v_booking.id;
      update booking_items
        set unit_amount_minor = v_fare, subtotal_minor = v_fare
        where booking_id = v_booking.id;
    end if;
    update bookings set
        trip_type = v_trip_type,
        arrival_time = left(nullif(btrim(p ->> 'arrivalTime'), ''), 40),
        pickup_hotel_slug = left(nullif(btrim(p ->> 'pickupSlug'), ''), 120),
        pickup_region = v_hotel_pickup_region,
        return_date = nullif(p ->> 'returnDate', '')::date,
        return_time = left(nullif(btrim(p ->> 'returnTime'), ''), 40),
        room_or_cabin = left(nullif(btrim(p ->> 'roomOrCabin'), ''), 60),
        luggage_details = left(nullif(btrim(p ->> 'luggageDetails'), ''), 300),
        special_notes = left(nullif(btrim(p ->> 'specialNotes'), ''), 600)
      where id = v_booking.id;
  end if;

  v_child := least(greatest(coalesce(nullif(p ->> 'childSeats', '')::int, 0), 0), v_total_qty::int);
  if v_child > 0 then
    v_child_extra := greatest(0, v_child - 1) * 600;
    update bookings
    set child_seats = v_child,
        total_minor = total_minor + v_child_extra,
        operator_payout_minor = operator_payout_minor + v_child_extra
    where id = v_booking.id and child_seats = 0;
  end if;

  -- Region-based transport add-on (per_person / per_group with pickup_available): a fee that scales with
  -- how far the pickup is from the activity's boarding region. The server RE-DERIVES the region from the
  -- pickup coordinates and looks up the fare here — it never trusts a client-sent price. Round-trip rule:
  -- drop-off doesn't change the fare, so it isn't read. Mirrors transportFare() in pricing.ts.
  if v_mode in ('per_person', 'per_group') and v_pickup_available
     and nullif(p ->> 'pickupLat', '') is not null
     and nullif(p ->> 'pickupLng', '') is not null
  then
    v_pickup_lat := (p ->> 'pickupLat')::double precision;
    v_pickup_lng := (p ->> 'pickupLng')::double precision;
    v_pickup_region := region_from_coords(v_pickup_lat, v_pickup_lng);
    if v_pickup_region is not null and v_activity_region is not null then
      v_transport := transport_fare_minor(v_pickup_region, v_activity_region, v_total_qty::int, v_suv);
      if v_transport > 0 then
        update bookings
        set transport_minor = v_transport,
            total_minor = total_minor + v_transport,
            operator_payout_minor = operator_payout_minor + v_transport,
            pickup_region = v_pickup_region,
            pickup_lat = v_pickup_lat,
            pickup_lng = v_pickup_lng
        where id = v_booking.id and transport_minor = 0;
      end if;
    end if;
  end if;

  return booking_json(v_booking.id);
end;
$$;

revoke execute on function api_book(jsonb) from public, anon, authenticated;
grant execute on function api_book(jsonb) to service_role;

-- ===========================================================================
-- 20260904000000_activity_map_coords: real map points for every published activity + summary
-- exposure. The planner map's "Our activities" layer was pinning from fallbacks (first itinerary
-- stop, else a Places text search of the title) because 42/43 activities had lat/lng NULL — pins
-- piled into the sea. Curated departure/meeting points per slug (guarded: `lat is null`, so admin
-- fine-tunes are never overwritten), and api_search_activities now returns 'region'/'lat'/'lng' per
-- summary so the layer builds from ONE RPC instead of ~42 sequential detail lookups. Mirror of the
-- migration; the function body is the 20260901000600 definition with only those fields added.
-- ===========================================================================
update activities as a
set lat = v.lat, lng = v.lng
from (
  values
    -- East — Trou d'Eau Douce jetty area (Ile aux Cerfs departures, fanned ~50–150 m so
    -- same-jetty pills don't stack into one point at island zoom)
    ('catamaran-cruise-ile-aux-cerfs', -20.2436, 57.7872),
    ('catapseed-5-islands', -20.2452, 57.7887),
    ('private-full-day-5-islands-tour-ile-aux-cerfs-with-lunch', -20.2444, 57.7879),
    ('private-full-day-catamaran-ile-aux-cerfs', -20.2428, 57.7868),
    ('private-full-day-cataspeed-ile-aux-cerfs', -20.2460, 57.7891),
    ('private-full-day-speed-boat-ile-aux-cerf-with-lunch', -20.2420, 57.7862),
    ('the-blue-cruise-ile-aux-cerfs-5-islands-visit', -20.2468, 57.7895),
    ('speed-boat-ile-aux-cerfs', -20.2412, 57.7856),
    ('seaplane', -20.2385, 57.7905),
    -- East — Belle Mare beach
    ('skydive', -20.1875, 57.7710),
    ('horse-back-riding-on-the-beach', -20.1932, 57.7738),
    ('underwater-sea-walk-excursion', -20.1905, 57.7726),
    -- North — Grand Baie / Sunset Boulevard departures
    ('catamaran-cruise-3-northern-island-adventure', -20.0104, 57.5789),
    ('catamaran-sunset-cruise', -20.0086, 57.5800),
    ('private-full-day-3-northern-island-speed-boat-with-lunch-bbq', -20.0072, 57.5814),
    ('private-full-day-3-northern-islands-adventure', -20.0060, 57.5824),
    ('flat-island-gabriel-island-and-the-gunners-coin-by-speedboat-exclusive-basis-only', -20.0050, 57.5834),
    ('scubadiving', -20.0095, 57.5760),
    -- North — coast + inland bases
    ('blue-safari-submarine-subscooter', -20.0310, 57.5530), -- Trou aux Biches coastal road
    ('helicotour', -20.0553, 57.5449),                       -- Triolet base
    ('visit-to-ambre-island-by-kayak', -20.0560, 57.6800),   -- St Antoine, Poudre d'Or
    ('north-beaches-tour', -20.0269, 57.5586),               -- Mont Choisy public beach
    ('north-tour', -20.1063, 57.5726),                       -- SSR Botanical Garden, Pamplemousses
    ('port-louis-city-tour', -20.1601, 57.4977),             -- Caudan Waterfront
    ('private-shopping-tour', -20.2247, 57.4930),            -- Bagatelle Mall
    -- West — Tamarin bay + Black River harbour
    ('western-cruise-catamaran', -20.3624, 57.3662),
    ('private-full-day-western-cruise-catamaran', -20.3615, 57.3670),
    ('deep-sea-fishing', -20.3600, 57.3655),
    ('swimming-with-dolphins', -20.3258, 57.3703),
    ('private-swimming-with-dolphins-only', -20.3247, 57.3712),
    ('encountering-the-whales-and-swim-with-dolphins-excursion', -20.3268, 57.3695),
    ('swimming-with-dolphins-benitier-island-speedboat-all-inclusive', -20.3240, 57.3720),
    ('private-full-day-dolphin-swimming-ile-aux-benitiers-with-lunch', -20.4266, 57.3629), -- La Gaulette
    ('casela-world-of-adventures', -20.2895, 57.4010),
    -- Centre / South
    ('hiking-at-the-tamarind-falls-7-cascade', -20.2926, 57.4888), -- Henrietta trailhead
    ('black-river-gorges-hiking', -20.4050, 57.4665),              -- Pétrin info centre
    ('hiking-le-morne', -20.4425, 57.3140),                        -- Le Morne trailhead
    ('la-vallee-des-couleurs-nature-park-2', -20.4700, 57.5520),   -- Chamouny
    ('tea-tasting-tour', -20.4400, 57.5210),                       -- Bois Chéri tea factory
    ('south-tour-mauritius', -20.5255, 57.5290),                   -- Gris Gris, Souillac
    ('private-south-east-tour', -20.4074, 57.7003)                 -- Mahébourg waterfront
) as v(slug, lat, lng)
where a.slug = v.slug
  and a.lat is null
  and a.lng is null;

-- ---------------------------------------------------------------------------
-- api_search_activities: the 20260901000600 locale-aware definition, with 'region'/'lat'/'lng'
-- added to each summary (see header). Everything else is unchanged — copied verbatim, per the
-- "a later migration must never silently revert an earlier one" rule.
-- ---------------------------------------------------------------------------
create or replace function api_search_activities(p jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public
as $$
  with filtered as (
    select a.*,
      case
        when a.pricing_mode = 'vehicle'
          then (select sedan_minor from sightseeing_pricing limit 1)
        else coalesce(
          (
            -- Per-OPTION front price, then the cheapest across options: a banded option fronts its
            -- adult (max) tier; a plain option its cheapest non-free tier. Aggregating across the whole
            -- ACTIVITY made any age band inflate the headline to the priciest option's adult rate.
            select min(case when opt.banded then opt.max_amt else coalesce(opt.min_paid, opt.min_amt) end)
            from (
              select bool_or(pr.min_age is not null or pr.max_age is not null) as banded,
                     max(pr.amount_minor) as max_amt,
                     min(pr.amount_minor) filter (where pr.amount_minor > 0) as min_paid,
                     min(pr.amount_minor) as min_amt
              from activity_option_prices pr
              join activity_options o on o.id = pr.activity_option_id
              where o.activity_id = a.id
              group by pr.activity_option_id
            ) opt
          ),
          (
            select min(o.private_base_minor)
            from activity_options o
            where o.activity_id = a.id and o.private_base_minor is not null
          )
        )
      end as from_price_minor,
      t.title as translated_title,
      t.summary as translated_summary
    from activities a
    left join activity_translations t
      on t.activity_id = a.id
     and t.locale = coalesce(nullif(p ->> 'locale', ''), 'en')::content_locale
    -- Second, UNCONDITIONAL join to the French row, used only by the `q` predicate below. `t` above
    -- is locale-parameterized (it resolves to whichever locale was requested, defaulting to 'en' —
    -- which is usually NULL, since English content lives in the base `activities` columns, not an
    -- 'en' overlay row), so it cannot be relied on to hold French text for an English session. tf
    -- always holds the French overlay regardless of the requested locale, which is what lets the
    -- free-text search match French independently of the locale parameter. Same unique-key join
    -- (activity_id, locale), so it cannot fan out rows either.
    left join activity_translations tf
      on tf.activity_id = a.id
     and tf.locale = 'fr'::content_locale
    where a.status = 'published'
      and coalesce(a.is_custom_planner, false) = false
      and (p ->> 'category' is null or a.category::text = p ->> 'category')
      and (p ->> 'type' is null or a.type::text = p ->> 'type')
      and (p ->> 'region' is null or a.region = p ->> 'region')
      and (
        p ->> 'q' is null
        or a.title ilike '%' || (p ->> 'q') || '%'
        or coalesce(a.summary, '') ilike '%' || (p ->> 'q') || '%'
        or coalesce(tf.title, '') ilike '%' || (p ->> 'q') || '%'
        or coalesce(tf.summary, '') ilike '%' || (p ->> 'q') || '%'
      )
      and (p ->> 'durationMin' is null or coalesce(a.duration_minutes, 0) >= (p ->> 'durationMin')::int)
      and (p ->> 'durationMax' is null or coalesce(a.duration_minutes, 0) <= (p ->> 'durationMax')::int)
      and (p ->> 'minRating' is null or coalesce(a.rating_avg, 0) >= (p ->> 'minRating')::numeric)
  ),
  priced as (
    select * from filtered
    where (p ->> 'priceMin' is null or from_price_minor >= (p ->> 'priceMin')::numeric * 100)
      and (p ->> 'priceMax' is null or from_price_minor <= (p ->> 'priceMax')::numeric * 100)
  ),
  paged as (
    select * from priced
    order by sort, rating_count desc, title
    limit coalesce((p ->> 'pageSize')::int, 20)
    offset (coalesce((p ->> 'page')::int, 1) - 1) * coalesce((p ->> 'pageSize')::int, 20)
  )
  select jsonb_build_object(
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', x.id, 'slug', x.slug, 'type', x.type,
        'title', coalesce(x.translated_title, x.title),
        'summary', coalesce(x.translated_summary, x.summary),
        'category', x.category, 'location', x.location, 'durationMinutes', x.duration_minutes,
        'region', x.region, 'lat', x.lat, 'lng', x.lng,
        'ratingAvg', x.rating_avg, 'ratingCount', x.rating_count, 'pricingMode', x.pricing_mode,
        'minAdvanceDays', coalesce(x.min_advance_days, 1),
        'fromPriceEur', x.from_price_minor::float / 100,
        'fromPriceMaxGuests', case when x.pricing_mode = 'vehicle' then null else (
          select pr.max_guests
          from activity_option_prices pr
          join activity_options o on o.id = pr.activity_option_id
          where o.activity_id = x.id
          order by pr.amount_minor asc nulls last
          limit 1
        ) end,
        'fromPriceIncluded', case
          when x.pricing_mode = 'vehicle'
            or exists (
              select 1 from activity_option_prices pr
              join activity_options o on o.id = pr.activity_option_id
              where o.activity_id = x.id
            ) then null
          else (
            select o.private_included
            from activity_options o
            where o.activity_id = x.id and o.private_base_minor is not null
            order by o.private_base_minor asc
            limit 1
          )
        end,
        'heroImage', (
          select jsonb_build_object('id', img.id, 'url', img.url, 'alt', img.alt, 'position', img.position)
          from activity_images img where img.activity_id = x.id order by img.position limit 1
        ),
        'images', coalesce((
          select jsonb_agg(
            jsonb_build_object('id', img.id, 'url', img.url, 'alt', img.alt, 'position', img.position)
            order by img.position
          )
          from activity_images img where img.activity_id = x.id
        ), '[]'::jsonb)
      ))
      from paged x
    ), '[]'::jsonb),
    'total', (select count(*)::int from priced),
    'page', coalesce((p ->> 'page')::int, 1),
    'pageSize', coalesce((p ->> 'pageSize')::int, 20)
  );
$$;

-- ============================================================================================
-- 20260905000000_activity_supplement.sql
-- ============================================================================================

-- 20260905000000_activity_supplement
--
-- A per-activity optional SUPPLEMENT the owner can name and price himself -- the first one being the
-- lobster lunch upgrade on the Ile aux Cerfs day trips.
--
-- WHY a real pair of columns rather than an `activities.extra` key: `extra` is presentational only
-- (20260901000700 says so on the column comment) and, worse, it is MERGED with the French overlay
-- (`a.extra || coalesce(t.extra, '{}')`) -- so a translated `extra` could shadow a PRICE. Money never
-- comes out of a free-form bag that content editing can reach.
--
-- Shape, mirroring the child-seat add-on (20260617180000) exactly:
--   * activities.supplement_name  -- blank/NULL = this activity has no supplement (the feature is off)
--   * activities.supplement_minor -- the PER-PERSON price in minor units; the only price that exists
--   * activity_translations.supplement_name -- the FR label, per-field coalesce like title/summary
--   * bookings.supplement_qty / supplement_minor / supplement_name -- what was actually bought
--
-- The booking columns SNAPSHOT the name and the charged total. The owner will re-price the lobster
-- next season, and an invoice reprinted after that must still show what the guest actually paid for.
-- (Child seats got this wrong -- their €6 is a literal in the function body and in pricing.ts, so an
-- old receipt silently re-prices itself. Not repeating that.)
--
-- The client sends only the QUANTITY. The unit price is read here, from the activity behind the
-- occurrence -- never from the payload ([[the five rules]] #1).
--
-- Re-run supabase/catch-up.sql after applying (idempotent).

alter table activities add column if not exists supplement_name text;
alter table activities add column if not exists supplement_minor int;
alter table activity_translations add column if not exists supplement_name text;

alter table bookings add column if not exists supplement_qty int not null default 0;
alter table bookings add column if not exists supplement_minor int not null default 0;
alter table bookings add column if not exists supplement_name text;

-- `add constraint if not exists` does not exist in Postgres, and catch-up.sql is re-run after every
-- deploy, so each check is guarded by name.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'activities_supplement_minor_nonneg') then
    alter table activities add constraint activities_supplement_minor_nonneg
      check (supplement_minor is null or supplement_minor >= 0);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'bookings_supplement_qty_nonneg') then
    alter table bookings add constraint bookings_supplement_qty_nonneg
      check (supplement_qty >= 0);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'bookings_supplement_minor_nonneg') then
    alter table bookings add constraint bookings_supplement_minor_nonneg
      check (supplement_minor >= 0);
  end if;
end $$;

comment on column activities.supplement_name is
  'Optional per-activity supplement the guest can add per person (e.g. "Lobster lunch"). Blank or '
  'NULL switches the whole feature off for this activity. Owner-editable in /admin.';
comment on column activities.supplement_minor is
  'Per-PERSON price of activities.supplement_name, in minor units. Server-authoritative: api_book '
  'reads it here and the client only ever sends a quantity.';
comment on column bookings.supplement_name is
  'Snapshot of the supplement label at booking time, so a reprinted invoice keeps showing what the '
  'guest bought after the owner renames or re-prices it.';
comment on column bookings.supplement_minor is
  'TOTAL charged for the supplement on this booking (unit x qty), already inside total_minor.';

-- ---------------------------------------------------------------------------
-- api_get_activity -- the 20260901000700 body VERBATIM, plus supplementName / supplementEur.
-- The NAME falls back per-field to the French overlay exactly like title/summary/meetingPoint; the
-- PRICE and the on/off gate come only from the English (operational) columns.
-- STAYS `security invoker` -- definer-grants-lockdown.test.ts depends on it.
-- ---------------------------------------------------------------------------
create or replace function api_get_activity(p jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public
as $$
  select jsonb_build_object(
    'id', a.id, 'slug', a.slug, 'type', a.type, 'title', coalesce(t.title, a.title),
    'summary', coalesce(t.summary, a.summary),
    'description', coalesce(t.description, a.description), 'category', a.category, 'location', a.location,
    'durationMinutes', a.duration_minutes, 'meetingPoint', coalesce(t.meeting_point, a.meeting_point),
    'pickupAvailable', a.pickup_available, 'pricingMode', a.pricing_mode,
    'minAdvanceDays', coalesce(a.min_advance_days, 1),
    'isAirportTransfer', coalesce(a.is_airport_transfer, false),
    'isHotelTransfer', coalesce(a.is_hotel_transfer, false),
    'airportFares', case when coalesce(a.is_airport_transfer, false) then (
      select jsonb_object_agg(f.zone, jsonb_build_object(
        'sedanMinor', f.sedan_minor, 'suvMinor', f.suv_minor, 'familyMinor', f.family_minor,
        'vanMinor', f.van_minor, 'coasterMinor', f.coaster_minor
      )) from airport_transfer_fare f
    ) else null end,
    'hotelTransferFares', case when coalesce(a.is_hotel_transfer, false) then (
      select jsonb_object_agg(f.band, jsonb_build_object(
        'sedanMinor', f.sedan_minor, 'suvMinor', f.suv_minor, 'familyMinor', f.family_minor,
        'vanMinor', f.van_minor, 'coasterMinor', f.coaster_minor
      )) from hotel_transfer_fare f
    ) else null end,
    'returnDiscountPct', case
      when coalesce(a.is_airport_transfer, false) then (select return_discount_pct from airport_transfer_config limit 1)
      when coalesce(a.is_hotel_transfer, false) then (select return_discount_pct from hotel_transfer_config limit 1)
      else null end,
    'region', coalesce(a.region, region_from_coords(a.lat, a.lng)),
    'lat', a.lat, 'lng', a.lng,
    'transportBands', case
      when a.pricing_mode in ('per_person', 'per_group') and coalesce(a.pickup_available, false) then (
        select jsonb_object_agg(t.band, jsonb_build_object(
          'sedanMinor', t.sedan_minor, 'suvMinor', t.suv_minor, 'familyMinor', t.family_minor,
          'vanMinor', t.van_minor, 'coasterMinor', t.coaster_minor
        )) from transport_band_pricing t
      ) else null end,
    'regionDistances', case
      when (a.pricing_mode in ('per_person', 'per_group') and coalesce(a.pickup_available, false))
        or coalesce(a.is_hotel_transfer, false) then (
        select jsonb_object_agg(d.region_a || '|' || d.region_b, d.band) from region_zone_distance d
      ) else null end,
    'languages', to_jsonb(a.languages),
    'inclusions', to_jsonb(coalesce(nullif(t.inclusions, '{}'), a.inclusions)),
    'exclusions', to_jsonb(coalesce(nullif(t.exclusions, '{}'), a.exclusions)),
    'highlights', to_jsonb(coalesce(nullif(t.highlights, '{}'), a.highlights)), 'cancellationPolicy', a.cancellation_policy,
    'seoTitle', coalesce(t.seo_title, a.seo_title), 'seoDescription', coalesce(t.seo_description, a.seo_description),
    'extra', a.extra || coalesce(t.extra, '{}'::jsonb),
    'supplementName', case
      when nullif(btrim(coalesce(a.supplement_name, '')), '') is null then null
      else coalesce(
        nullif(btrim(coalesce(t.supplement_name, '')), ''),
        btrim(a.supplement_name)
      ) end,
    'supplementEur', case
      when nullif(btrim(coalesce(a.supplement_name, '')), '') is null then null
      else coalesce(a.supplement_minor, 0)::float / 100 end,
    'ratingAvg', a.rating_avg, 'ratingCount', a.rating_count,
    'fromPriceEur', case
      when a.pricing_mode = 'vehicle'
        then (select sedan_minor from sightseeing_pricing limit 1)::float / 100
      else (
        -- Per-OPTION front price, then min across options (mirrors api_search_activities).
        select min(case when opt.banded then opt.max_amt else coalesce(opt.min_paid, opt.min_amt) end)::float / 100
        from (
          select bool_or(pr.min_age is not null or pr.max_age is not null) as banded,
                 max(pr.amount_minor) as max_amt,
                 min(pr.amount_minor) filter (where pr.amount_minor > 0) as min_paid,
                 min(pr.amount_minor) as min_amt
          from activity_option_prices pr
          join activity_options o on o.id = pr.activity_option_id
          where o.activity_id = a.id
          group by pr.activity_option_id
        ) opt
      )
    end,
    'vehiclePricing', case when a.pricing_mode = 'vehicle' then (
      select jsonb_build_object(
        'sedanEur', sedan_minor::float / 100,
        'suvEur', suv_minor::float / 100,
        'familyEur', family_minor::float / 100,
        'vanEur', van_minor::float / 100,
        'coasterEur', coaster_minor::float / 100,
        'maxParty', 25
      ) from sightseeing_pricing limit 1
    ) else null end,
    'heroImage', (
      select jsonb_build_object('id', img.id, 'url', img.url, 'alt', img.alt, 'position', img.position)
      from activity_images img where img.activity_id = a.id order by img.position limit 1
    ),
    'images', coalesce((
      select jsonb_agg(jsonb_build_object('id', i.id, 'url', i.url, 'alt', i.alt, 'position', i.position) order by i.position)
      from activity_images i where i.activity_id = a.id
    ), '[]'::jsonb),
    'options', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', o.id, 'name', o.name, 'description', o.description, 'durationMinutes', o.duration_minutes, 'startWindow', o.start_window,
        'privateBaseEur', o.private_base_minor::float / 100,
        'privateIncluded', o.private_included,
        'privateExtraEur', o.private_extra_minor::float / 100,
        'privateMaxGuests', o.private_max_guests,
        'prices', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', pr.id, 'label', pr.label, 'amountEur', pr.amount_minor::float / 100, 'maxGuests', pr.max_guests, 'minAge', pr.min_age, 'maxAge', pr.max_age
          ) order by pr.position)
          from activity_option_prices pr where pr.activity_option_id = o.id
        ), '[]'::jsonb)
      ) order by o.position)
      from activity_options o where o.activity_id = a.id
    ), '[]'::jsonb),
    'translations', coalesce((
      select jsonb_object_agg(t.locale, jsonb_build_object('title', t.title, 'summary', t.summary, 'description', t.description))
      from activity_translations t where t.activity_id = a.id
    ), '{}'::jsonb),
    'reviews', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', rv.id, 'author', rv.author, 'rating', rv.rating, 'text', rv.text, 'createdAt', rv.created_at
      ) order by rv.created_at desc)
      from reviews rv where rv.activity_id = a.id
    ), '[]'::jsonb)
  )
  from activities a
  left join activity_translations t
    on t.activity_id = a.id
   and t.locale = coalesce(nullif(p ->> 'locale', ''), 'en')::content_locale
  where a.slug = p ->> 'slug';
$$;
grant execute on function api_get_activity(jsonb) to anon, authenticated, service_role;

-- ---------------------------------------------------------------------------
-- booking_json -- the 20260819000000 body VERBATIM, plus the three supplement fields.
-- They are scalars on the booking, NOT booking_items rows: an extra item row would inflate
-- partySize (sum of pax) and unitsNeeded (sum of quantity), and unitsNeeded is what the reschedule
-- date-picker checks capacity against. Same reason child seats and transport are scalars.
-- STAYS `security invoker`.
-- ---------------------------------------------------------------------------
create or replace function booking_json(p_booking_id uuid)
returns jsonb
language sql
stable
security invoker
set search_path = public
as $$
  select jsonb_build_object(
    'id', b.id, 'ref', b.ref, 'status', b.status, 'paymentState', b.payment_state,
    'customerName', b.customer_name, 'customerEmail', b.customer_email,
    'totalEur', b.total_minor::float / 100, 'currency', b.currency, 'source', b.source,
    'createdAt', b.created_at,
    'customItinerary', b.custom_itinerary,
    'pickupLocation', b.pickup_location,
    'dropoffLocation', b.dropoff_location,
    'pickupPending', b.pickup_pending,
    'pickupHotelSlug', b.pickup_hotel_slug,
    'childSeats', b.child_seats,
    'transportEur', b.transport_minor::float / 100,
    'supplementName', b.supplement_name,
    'supplementQty', b.supplement_qty,
    'supplementEur', b.supplement_minor::float / 100,
    'pickupRegion', b.pickup_region,
    'tripType', b.trip_type,
    'tripDirection', b.trip_direction,
    'flightNumber', b.flight_number,
    'arrivalTime', b.arrival_time,
    'returnDate', b.return_date,
    'returnTime', b.return_time,
    'departureFlightNumber', b.departure_flight_number,
    'roomOrCabin', b.room_or_cabin,
    'luggageDetails', b.luggage_details,
    'childSeatAge', b.child_seat_age,
    'travellerGender', b.traveller_gender,
    'travellerCompany', b.traveller_company,
    'travellerCountry', b.traveller_country,
    'specialNotes', b.special_notes,
    'disruption', b.disruption,
    'partySize', coalesce((
      select sum(coalesce(bi.pax, bi.quantity))
        from booking_items bi where bi.booking_id = b.id
    ), 0),
    -- The BOOKING-UNIT count, the unit seatsLeft is denominated in. For a per-person option it equals
    -- partySize; for a vehicle/private one it is 1 (one van / one trip, any group size). The date
    -- picker must filter on THIS, not partySize, or a 6-guest transfer is offered nothing.
    'unitsNeeded', coalesce((
      select sum(bi.quantity)
        from booking_items bi where bi.booking_id = b.id
    ), 0),
    'activityOptionId', (
      select bi.activity_option_id
        from booking_items bi where bi.booking_id = b.id order by bi.id limit 1
    ),
    'activitySlug', (
      select a.slug
        from booking_items bi
        join activity_options ao on ao.id = bi.activity_option_id
        join activities a on a.id = ao.activity_id
       where bi.booking_id = b.id
       order by bi.id limit 1
    ),
    'cancellable', (
      b.status = 'confirmed' and b.payment_state = 'paid'
      and (
        booking_awaiting_choice(b.disruption)
        or coalesce((
          select min(so.starts_at)
            from booking_items bi
            join session_occurrences so on so.id = bi.session_occurrence_id
           where bi.booking_id = b.id
        ), 'epoch'::timestamptz) > now() + interval '24 hours'
      )
    ),
    'reschedulable', (
      b.status = 'confirmed' and b.payment_state = 'paid'
      and (
        booking_awaiting_choice(b.disruption)
        or coalesce((
          select min(so.starts_at)
            from booking_items bi
            join session_occurrences so on so.id = bi.session_occurrence_id
           where bi.booking_id = b.id
        ), 'epoch'::timestamptz) > now() + interval '24 hours'
      )
    ),
    'serviceDate', (
      select min(so.starts_at)
        from booking_items bi
        join session_occurrences so on so.id = bi.session_occurrence_id
       where bi.booking_id = b.id
    ),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'priceLabel', bi.price_label, 'quantity', bi.quantity, 'pax', bi.pax,
        'unitAmountEur', bi.unit_amount_minor::float / 100, 'subtotalEur', bi.subtotal_minor::float / 100,
        'occurrenceId', bi.session_occurrence_id
      ))
      from booking_items bi where bi.booking_id = b.id
    ), '[]'::jsonb)
  )
  from bookings b where b.id = p_booking_id;
$$;

-- ---------------------------------------------------------------------------
-- api_book -- the 20260903000000 body VERBATIM, plus the supplement charge.
--
-- Placed immediately after the child-seat block, which means AFTER the airport / hotel transfer
-- blocks. Those two OVERWRITE total_minor with the fare, so anything added before them is silently
-- erased. Additive add-ons belong at the end, and this is the end.
--
-- Server-authoritative: the unit price comes from activities.supplement_minor, read in the same
-- SELECT that already resolves the activity behind the occurrence. The payload contributes only
-- `supplementQty`, clamped to the head count.
--
-- Replay guard `and supplement_qty = 0`, matching child_seats / transport_minor: create_booking
-- returns the EXISTING row on an idempotency-key replay, so an unguarded update would charge the
-- supplement a second time onto a booking that may already have a Peach session minted for the old
-- amount ([[gytm-drift-gate-double-charge]]).
--
-- A configured-but-free supplement (price 0) still records the guest's request and adds nothing --
-- the kitchen needs the head count either way.
-- ---------------------------------------------------------------------------
create or replace function api_book(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_occ uuid := (p ->> 'occurrenceId')::uuid;
  v_key text := p ->> 'idempotencyKey';
  v_expected_slug text := nullif(p ->> 'expectedSlug', '');
  v_total_qty bigint := 0;
  v_items jsonb := '[]'::jsonb;
  v_mode text := 'per_person';
  v_is_private boolean := false;
  v_suv boolean := coalesce((p ->> 'suv')::boolean, false);
  v_hold_id uuid := nullif(p ->> 'holdId', '')::uuid;
  v_want_qty int;
  v_reused boolean := false;
  v_child int;
  v_child_extra bigint;
  v_supp_qty int;
  v_supp_extra bigint;
  v_supp_name text;
  v_supp_unit int;
  v_hold booking_holds;
  v_booking bookings;
  r record;
  v_activity_region text;
  v_pickup_available boolean := false;
  v_pickup_lat double precision;
  v_pickup_lng double precision;
  v_pickup_region text;
  v_transport bigint;
  v_is_airport boolean := false;
  v_is_hotel boolean := false;
  v_dropoff_zone text;
  v_trip_type text;
  v_trip_direction text;
  v_ret_pct int;
  v_fare bigint;
  v_hotel_pickup_region text;
  v_hotel_dropoff_region text;
  v_band text;
  v_actor uuid;
begin
  if v_occ is null or v_key is null then
    raise exception 'invalid_request';
  end if;

  if v_expected_slug is not null and not exists (
    select 1 from session_occurrences so
    join activity_options o on o.id = so.activity_option_id
    join activities a on a.id = o.activity_id
    where so.id = v_occ and a.slug = v_expected_slug
  ) then
    raise exception 'occurrence_activity_mismatch';
  end if;

  for r in select key, (value::text)::bigint as q from jsonb_each(p -> 'party') loop
    if r.q < 0 or r.q > 1000000 then raise exception 'invalid_party'; end if;
    if r.q > 0 then
      v_total_qty := v_total_qty + r.q;
      v_items := v_items || jsonb_build_object('price_label', r.key, 'quantity', r.q);
    end if;
  end loop;
  if v_total_qty <= 0 or v_total_qty > 1000000 then raise exception 'invalid_party'; end if;

  select a.pricing_mode,
         coalesce(a.region, region_from_coords(a.lat, a.lng)),
         coalesce(a.pickup_available, false),
         coalesce(a.is_airport_transfer, false),
         coalesce(a.is_hotel_transfer, false),
         (o.private_base_minor is not null),
         nullif(btrim(coalesce(a.supplement_name, '')), ''),
         coalesce(a.supplement_minor, 0)
    into v_mode, v_activity_region, v_pickup_available, v_is_airport, v_is_hotel, v_is_private,
         v_supp_name, v_supp_unit
  from session_occurrences so
  join activity_options o on o.id = so.activity_option_id
  join activities a on a.id = o.activity_id
  where so.id = v_occ;
  v_mode := coalesce(v_mode, 'per_person');
  v_want_qty := case when v_mode in ('vehicle', 'vehicle_custom')
                       or coalesce(v_is_private, false) then 1 else v_total_qty::int end;

  -- Actor identity, resolved BEFORE the hold-reuse gate so ownership can bind reuse. api_book is
  -- service-role-only, so auth.uid() is null; the JWKS-verified caller id arrives as p.actorUserId
  -- (trustworthy BECAUSE only the server can execute this function). auth.uid() stays first as
  -- belt-and-suspenders.
  v_actor := coalesce(auth.uid(), nullif(p ->> 'actorUserId', '')::uuid);

  if v_hold_id is not null then
    -- FOR UPDATE: two concurrent api_book calls quoting the same holdId must serialise here, or both
    -- read booking_id IS NULL and both proceed (create_booking's own lock cannot save the second one
    -- on its own — it re-checks under the lock, but only because of the guard added alongside this).
    -- Ownership: an OWNED hold (created_by set) is only reusable by its owner; an ownerless hold
    -- (guest checkout, or created before sign-in) stays reusable by whoever holds the unguessable id,
    -- which keeps the guest → sign-in-mid-checkout flow working.
    select * into v_hold from booking_holds
    where id = v_hold_id and status = 'active' and expires_at > now() and booking_id is null
      and session_occurrence_id = v_occ and quantity = v_want_qty
      and (created_by is null or created_by = v_actor)
    for update;
    if found then v_reused := true; end if;
  end if;
  -- A REPLAY whose booking already exists must not mint a hold.
  --
  -- create_booking's idempotency check runs before it ever looks at p_hold_id, so on a replay it
  -- returns the existing booking and never attaches whatever hold we passed. The original hold is by
  -- then consumed (booking_id set), so the reuse SELECT above cannot match it and v_reused is false --
  -- and create_hold would mint a fresh one that nothing ever claims. It then sits ACTIVE, counted by
  -- used_capacity, for its whole TTL. Worse, on a nearly-full departure create_hold raises
  -- insufficient_capacity, so a legitimate retry of a booking that ALREADY SUCCEEDED fails instead of
  -- returning it -- the caller is told the booking failed when it did not.
  -- (Only ever one orphan: a second replay finds it by idempotency key. One is enough to sell out a
  -- last vehicle.)
  if not v_reused and not exists (select 1 from bookings where idempotency_key = v_key) then
    v_hold := create_hold(v_occ, v_want_qty, v_key || ':book');
  end if;

  v_booking := create_booking(
    v_key, v_hold.id, p ->> 'customerName', p ->> 'customerEmail', p ->> 'customerPhone',
    coalesce((p ->> 'source')::booking_source, 'web'), v_items, v_suv
  );

  -- F23 (replay-disclosure guard): create_booking returns the existing row on an idempotency-key
  -- replay, and api_book runs SECURITY DEFINER, so RLS does not filter the returned DTO. Refuse to
  -- echo a booking the caller can't prove they own:
  --   * an authenticated user replaying someone else's OWNED booking -> forbidden;
  --   * ANY caller replaying an UNOWNED (guest) booking whose supplied email doesn't match -> forbidden.
  --     A stolen/guessed key alone (authenticated OR anonymous) would otherwise hand back the original
  --     guest's PII / let an authed caller adopt the row. A legitimate retry resends the same email and
  --     passes; a fresh create trivially passes (just inserted with this caller's email).
  if (v_booking.user_id is not null and v_booking.user_id is distinct from v_actor)
     or (v_booking.user_id is null
         and lower(coalesce(v_booking.customer_email, '')) <> lower(coalesce(p ->> 'customerEmail', '')))
  then
    raise exception 'forbidden';
  end if;
  if v_actor is not null then
    update bookings set user_id = v_actor where id = v_booking.id and user_id is null;
  end if;

  -- Ownership for the FALLBACK hold: when no reusable holdId was supplied, api_book mints its own
  -- hold above via create_hold, which runs under service_role here (server-only RPC) and so wrote
  -- created_by = auth.uid() = NULL. Stamp the actor onto it so the customer's owner-scoped hold
  -- status/release endpoints work. A REUSED hold already carries its owner (created_by not null),
  -- so the guard leaves it alone; a guest booking (v_actor null) leaves the hold ownerless as before.
  if v_actor is not null then
    update booking_holds set created_by = v_actor where id = v_hold.id and created_by is null;
  end if;

  -- The language the guest booked in. Email and PDFs render later, often from a cron worker with no
  -- request context, so the locale must be stored rather than inferred at send time. Unconditional: by
  -- this point the F23 guard above has already verified the caller may act on this booking, so re-
  -- asserting the same value on an idempotent replay is harmless. Absent/empty collapses to 'en' (never
  -- SQL NULL, never a failed enum cast), so an older client that sends no locale still books cleanly.
  update bookings
  set locale = coalesce(nullif(p ->> 'locale', ''), 'en')::content_locale
  where id = v_booking.id;

  if p ? 'itinerary'
     and jsonb_typeof(p -> 'itinerary') = 'array'
     and jsonb_array_length(p -> 'itinerary') > 0
     and jsonb_array_length(p -> 'itinerary') <= 30
  then
    update bookings set custom_itinerary = p -> 'itinerary'
    where id = v_booking.id and custom_itinerary is null;
  end if;

  if nullif(btrim(p ->> 'pickupLocation'), '') is not null then
    update bookings set pickup_location = left(btrim(p ->> 'pickupLocation'), 200)
    where id = v_booking.id and pickup_location is null;
  end if;

  -- Drop-off is its OWN field (never merged into pickup_location). pickup_pending records "pickup to be
  -- arranged" — distinct from "no pickup" — and is set on the just-created row only.
  if nullif(btrim(p ->> 'dropoffLocation'), '') is not null then
    update bookings set dropoff_location = left(btrim(p ->> 'dropoffLocation'), 200)
    where id = v_booking.id and dropoff_location is null;
  end if;

  if coalesce((p ->> 'pickupPending')::boolean, false) then
    update bookings set pickup_pending = true
    where id = v_booking.id and pickup_pending = false;
  end if;

  -- Airport transfer (server-authoritative, zero-trust): the destination ZONE comes from the hotel
  -- SLUG via airport_transfer_hotels — never a client-sent zone. When the guest's hotel isn't listed
  -- (no dropoffSlug), classify the zone from the supplied AREA instead (Zone 2 = the near-airport
  -- south-east areas), still never trusting a client price. The whole fare is the zone × vehicle matrix
  -- (vehicle derived from party size + the ≤4 SUV upgrade); a return trip is two legs minus the
  -- configured discount. We OVERRIDE the booking total + payout + the single line item so the receipt's
  -- item == total. Mirrors airportTransferQuoteMinor() in pricing.ts.
  if v_is_airport then
    v_trip_direction := case
      when (p ->> 'tripDirection') in ('arrival', 'departure', 'return') then p ->> 'tripDirection'
      when (p ->> 'tripType') = 'return' then 'return'
      else 'arrival'
    end;
    v_trip_type := case when v_trip_direction = 'return' then 'return' else 'one_way' end;
    if nullif(p ->> 'dropoffSlug', '') is not null then
      select zone into v_dropoff_zone from airport_transfer_hotels
        where slug = nullif(p ->> 'dropoffSlug', '');
    end if;
    if v_dropoff_zone is null then
      v_dropoff_zone := airport_transfer_area_zone(p ->> 'dropoffArea');
    end if;
    v_fare := airport_transfer_fare_minor(v_dropoff_zone, v_total_qty::int, v_suv);
    if v_trip_type = 'return' then
      select coalesce(return_discount_pct, 0) into v_ret_pct from airport_transfer_config limit 1;
      v_fare := round(v_fare::numeric * 2 * (100 - coalesce(v_ret_pct, 0)) / 100)::bigint;
    end if;
    -- Replay guard, matching the pattern every other post-create mutation in this function already
    -- uses (`and custom_itinerary is null`, `and pickup_location is null`, `and pickup_pending = false`).
    -- create_booking returns the EXISTING row on an idempotency-key replay, so unguarded this silently
    -- re-prices a booking that has already started paying -- moving total_minor out from under the MUR
    -- charge pinned on its payment row and a Peach session already minted for the old amount.
    if v_fare > 0 and not exists (select 1 from payments pay where pay.booking_id = v_booking.id) then
      update bookings
        set total_minor = v_fare, operator_payout_minor = v_fare
        where id = v_booking.id;
      update booking_items
        set unit_amount_minor = v_fare, subtotal_minor = v_fare
        where booking_id = v_booking.id;
    end if;
    update bookings set
        trip_type = v_trip_type,
        trip_direction = v_trip_direction,
        flight_number = left(nullif(btrim(p ->> 'flightNumber'), ''), 40),
        arrival_time = left(nullif(btrim(p ->> 'arrivalTime'), ''), 40),
        return_date = nullif(p ->> 'returnDate', '')::date,
        return_time = left(nullif(btrim(p ->> 'returnTime'), ''), 40),
        departure_flight_number = left(nullif(btrim(p ->> 'departureFlightNumber'), ''), 40),
        room_or_cabin = left(nullif(btrim(p ->> 'roomOrCabin'), ''), 60),
        luggage_details = left(nullif(btrim(p ->> 'luggageDetails'), ''), 300),
        child_seat_age = nullif(p ->> 'childSeatAge', '')::int,
        traveller_gender = left(nullif(btrim(p ->> 'travellerGender'), ''), 20),
        traveller_company = left(nullif(btrim(p ->> 'travellerCompany'), ''), 120),
        traveller_country = left(nullif(btrim(p ->> 'travellerCountry'), ''), 80),
        special_notes = left(nullif(btrim(p ->> 'specialNotes'), ''), 600)
      where id = v_booking.id;
  end if;

  -- Hotel-to-hotel transfer (server-authoritative, zero-trust): derive BOTH endpoints' regions from the
  -- hotel SLUGS via airport_transfer_hotels (or area_region() for a free-text end), reject a same-hotel
  -- trip, classify the distance band (region_distance_band), and price band × vehicle (× return discount).
  -- OVERRIDE the booking total + payout + line item. Mirrors hotelTransferQuoteMinor() in pricing.ts.
  if v_is_hotel then
    if nullif(p ->> 'pickupSlug', '') is not null
       and nullif(p ->> 'pickupSlug', '') = nullif(p ->> 'dropoffSlug', '') then
      raise exception 'same_hotel';
    end if;
    v_trip_type := case when (p ->> 'tripType') = 'return' then 'return' else 'one_way' end;
    v_hotel_pickup_region := hotel_end_region(
      p ->> 'pickupSlug',
      nullif(p ->> 'pickupLat', '')::double precision,
      nullif(p ->> 'pickupLng', '')::double precision,
      p ->> 'pickupArea');
    v_hotel_dropoff_region := hotel_end_region(
      p ->> 'dropoffSlug',
      nullif(p ->> 'dropoffLat', '')::double precision,
      nullif(p ->> 'dropoffLng', '')::double precision,
      p ->> 'dropoffArea');
    v_band := region_distance_band(v_hotel_pickup_region, v_hotel_dropoff_region);
    v_fare := hotel_transfer_fare_minor(v_band, v_total_qty::int, v_suv);
    if v_trip_type = 'return' then
      select coalesce(return_discount_pct, 0) into v_ret_pct from hotel_transfer_config limit 1;
      v_fare := round(v_fare::numeric * 2 * (100 - coalesce(v_ret_pct, 0)) / 100)::bigint;
    end if;
    -- Replay guard, matching the pattern every other post-create mutation in this function already
    -- uses (`and custom_itinerary is null`, `and pickup_location is null`, `and pickup_pending = false`).
    -- create_booking returns the EXISTING row on an idempotency-key replay, so unguarded this silently
    -- re-prices a booking that has already started paying -- moving total_minor out from under the MUR
    -- charge pinned on its payment row and a Peach session already minted for the old amount.
    if v_fare > 0 and not exists (select 1 from payments pay where pay.booking_id = v_booking.id) then
      update bookings
        set total_minor = v_fare, operator_payout_minor = v_fare
        where id = v_booking.id;
      update booking_items
        set unit_amount_minor = v_fare, subtotal_minor = v_fare
        where booking_id = v_booking.id;
    end if;
    update bookings set
        trip_type = v_trip_type,
        arrival_time = left(nullif(btrim(p ->> 'arrivalTime'), ''), 40),
        pickup_hotel_slug = left(nullif(btrim(p ->> 'pickupSlug'), ''), 120),
        pickup_region = v_hotel_pickup_region,
        return_date = nullif(p ->> 'returnDate', '')::date,
        return_time = left(nullif(btrim(p ->> 'returnTime'), ''), 40),
        room_or_cabin = left(nullif(btrim(p ->> 'roomOrCabin'), ''), 60),
        luggage_details = left(nullif(btrim(p ->> 'luggageDetails'), ''), 300),
        special_notes = left(nullif(btrim(p ->> 'specialNotes'), ''), 600)
      where id = v_booking.id;
  end if;

  v_child := least(greatest(coalesce(nullif(p ->> 'childSeats', '')::int, 0), 0), v_total_qty::int);
  if v_child > 0 then
    v_child_extra := greatest(0, v_child - 1) * 600;
    update bookings
    set child_seats = v_child,
        total_minor = total_minor + v_child_extra,
        operator_payout_minor = operator_payout_minor + v_child_extra
    where id = v_booking.id and child_seats = 0;
  end if;

  -- Per-activity supplement (e.g. the lobster lunch upgrade). Priced PER PERSON from
  -- activities.supplement_minor, read above; the payload supplies only the count, clamped to the head
  -- count. A blank supplement_name means the activity has none, so nothing is charged whatever the
  -- client sends. See the header for why this sits after the transfer overrides.
  v_supp_qty := least(greatest(coalesce(nullif(p ->> 'supplementQty', '')::int, 0), 0), v_total_qty::int);
  if v_supp_qty > 0 and v_supp_name is not null then
    v_supp_extra := coalesce(v_supp_unit, 0)::bigint * v_supp_qty;
    update bookings
    set supplement_qty = v_supp_qty,
        supplement_name = v_supp_name,
        supplement_minor = v_supp_extra,
        total_minor = total_minor + v_supp_extra,
        operator_payout_minor = operator_payout_minor + v_supp_extra
    where id = v_booking.id and supplement_qty = 0;
  end if;

  -- Region-based transport add-on (per_person / per_group with pickup_available): a fee that scales with
  -- how far the pickup is from the activity's boarding region. The server RE-DERIVES the region from the
  -- pickup coordinates and looks up the fare here — it never trusts a client-sent price. Round-trip rule:
  -- drop-off doesn't change the fare, so it isn't read. Mirrors transportFare() in pricing.ts.
  if v_mode in ('per_person', 'per_group') and v_pickup_available
     and nullif(p ->> 'pickupLat', '') is not null
     and nullif(p ->> 'pickupLng', '') is not null
  then
    v_pickup_lat := (p ->> 'pickupLat')::double precision;
    v_pickup_lng := (p ->> 'pickupLng')::double precision;
    v_pickup_region := region_from_coords(v_pickup_lat, v_pickup_lng);
    if v_pickup_region is not null and v_activity_region is not null then
      v_transport := transport_fare_minor(v_pickup_region, v_activity_region, v_total_qty::int, v_suv);
      if v_transport > 0 then
        update bookings
        set transport_minor = v_transport,
            total_minor = total_minor + v_transport,
            operator_payout_minor = operator_payout_minor + v_transport,
            pickup_region = v_pickup_region,
            pickup_lat = v_pickup_lat,
            pickup_lng = v_pickup_lng
        where id = v_booking.id and transport_minor = 0;
      end if;
    end if;
  end if;

  return booking_json(v_booking.id);
end;
$$;

revoke execute on function api_book(jsonb) from public, anon, authenticated;
grant execute on function api_book(jsonb) to service_role;


-- ── 20260906000000: reject out-of-Mauritius activity coordinates ────────────────────────────────
-- Refuse an activity coordinate that cannot be in Mauritius.
--
-- On 2026-08-03 the activities map looked comprehensively broken — pins piled into the sea, nothing
-- near where the tours actually run. The cause was ONE row: private-luxury-speedboat-5-island had
-- lng = 57779735 instead of 57.779735. A single missing decimal point.
--
-- One value seven million degrees off the map is enough to wreck the auto-fit that decides the map's
-- centre and zoom, so all 43 correctly-placed activities got squashed into a corner. One keystroke,
-- every pin wrong, and NOTHING complained: not the admin form, not the database, not a test. The map
-- just looked broken and no error was ever raised.
--
-- A bounds check is the cheapest possible guard: the save fails loudly instead of silently poisoning
-- every other pin. Latitude was fine in that incident, but it is constrained too — the same slip on
-- the other field is equally possible.
--
-- NULL is allowed on purpose: custom-road-trip has no fixed location and must not be forced to invent
-- one. The map should skip an activity without coordinates, not pin it at a made-up point.
--
-- Bounds cover the main island with margin (it spans roughly -20.52..-19.98 lat, 57.31..57.80 lng).
-- Rodrigues (~-19.7, 63.4) is deliberately OUTSIDE: no activity runs there, so a hit that far east is
-- a typo, not a location. If Rodrigues tours are ever added, widen maxLat to -19.6 and maxLng to 63.5
-- HERE and in scripts/geocode-activities.mjs, which enforces the same window before it writes.

alter table activities drop constraint if exists activities_lat_in_mauritius;
alter table activities add constraint activities_lat_in_mauritius
  check (lat is null or (lat >= -20.6 and lat <= -19.9));

alter table activities drop constraint if exists activities_lng_in_mauritius;
alter table activities add constraint activities_lng_in_mauritius
  check (lng is null or (lng >= 57.2 and lng <= 57.9));

comment on column activities.lat is
  'Latitude of where the activity actually happens; NULL means no fixed location (the map skips it, '
  'it is never pinned at a fallback point). Bounds-checked to Mauritius — a mistyped coordinate used '
  'to break the auto-fit for EVERY other pin on the map without raising anything.';
comment on column activities.lng is
  'Longitude; see activities.lat. The 2026-08-03 incident was lng 57779735 instead of 57.779735.';


-- ── 20260907000000: website enquiry alerts ──────────────────────────────────────────────────────
-- Website enquiry alerts.
--
-- The floating "WhatsApp us" button became a real enquiry FORM (ContactFloat), so a visitor's question
-- now lands in `leads` instead of in the owner's phone. Two gaps had to close for that to be an
-- improvement rather than a regression:
--
--   1. `leads` could not hold what the form collects. The single 200-char `contact` blob has to carry
--      email + phone already, and truncating a customer's actual question mid-sentence is not an
--      option — so the free text, the page they asked from, and the optional trip fields get real
--      columns. `contact` keeps being written exactly as before, so ContactForm, InquiryWidget and
--      the admin list all keep working untouched.
--
--   2. A lead notified NOBODY. Rows sat in /admin/leads until somebody thought to look — the same
--      hole owner booking alerts closed in 20260804000000. Every new lead now enqueues ONE owner
--      email on the existing outbox rails (drained every 2 minutes by the cron worker), using the
--      literal recipient sentinel 'owner' so the drain resolves the real address from
--      OWNER_NOTIFY_EMAIL at send time and no personal contact detail is stored in the DB.

alter table leads add column if not exists message text;
alter table leads add column if not exists page_url text;
alter table leads add column if not exists preferred_date date;
alter table leads add column if not exists party_size int;

-- Mirrors the form's own 1..99 bound. Every pre-existing row is null, so this validates instantly.
alter table leads drop constraint if exists leads_party_size_range;
alter table leads
  add constraint leads_party_size_range
  check (party_size is null or party_size between 1 and 99);

-- Re-applies the 20260617120500 body VERBATIM (per-IP hourly cap intact — the endpoint is public and
-- unauthenticated) with the four new fields threaded through insert + return. Empty strings are
-- normalised to null so an untouched optional input never stores '' and renders as a blank row in the
-- owner's email.
create or replace function api_capture_lead(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_lead leads;
  v_ip text := nullif(p ->> 'ip', '');
  v_recent int;
  v_max_per_hour constant int := 8;
begin
  if v_ip is not null then
    select count(*) into v_recent
    from leads
    where ip = v_ip and created_at > now() - interval '1 hour';
    if v_recent >= v_max_per_hour then
      raise exception 'rate_limited' using detail = format('ip %s', v_ip);
    end if;
  end if;

  insert into leads (
    name, contact, interest_activity_id, source, ip,
    message, page_url, preferred_date, party_size
  )
  values (
    p ->> 'name', p ->> 'contact',
    nullif(p ->> 'interestActivityId', '')::uuid,
    coalesce(p ->> 'source', 'web'),
    v_ip,
    nullif(p ->> 'message', ''),
    nullif(p ->> 'pageUrl', ''),
    nullif(p ->> 'preferredDate', '')::date,
    nullif(p ->> 'partySize', '')::int
  )
  returning * into v_lead;
  return jsonb_build_object(
    'id', v_lead.id, 'name', v_lead.name, 'contact', v_lead.contact,
    'interestActivityId', v_lead.interest_activity_id, 'status', v_lead.status,
    'source', v_lead.source, 'createdAt', v_lead.created_at
  );
end;
$$;

-- Re-assert the 20260807000000 lockdown. CREATE OR REPLACE preserves privileges, but this file is
-- also appended to catch-up.sql AFTER that lockdown runs, so stating it here keeps the grant correct
-- no matter which of the two paths applied it (same convention as every api_book redefinition).
revoke execute on function api_capture_lead(jsonb) from public, anon, authenticated;
grant execute on function api_capture_lead(jsonb) to service_role;

-- The payload carries EVERYTHING the email needs, so the drain's enrich step is pure and synchronous
-- (no DB round-trip, hence no failure mode that could strand the row) — the same shape
-- enqueue_review_invites / owner_date_changed already rely on. The activity title is resolved here,
-- at insert time, because that is the one fact the lead row itself doesn't carry.
create or replace function enqueue_lead_notification()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_title text;
begin
  if new.interest_activity_id is not null then
    select a.title into v_title from activities a where a.id = new.interest_activity_id;
  end if;

  -- No booking_id: this is an ad-hoc notification, and the column is nullable for exactly that case.
  insert into notification_outbox (channel, recipient, template, payload, idempotency_key)
  values (
    'email', 'owner', 'owner_new_lead',
    jsonb_build_object(
      'leadId', new.id,
      'name', new.name,
      'contact', new.contact,
      'message', new.message,
      'pageUrl', new.page_url,
      'activityTitle', v_title,
      'preferredDate', new.preferred_date,
      'partySize', new.party_size,
      'source', new.source
    ),
    'owner_new_lead:' || new.id
  )
  on conflict (idempotency_key) do nothing;
  return new;
end;
$$;

drop trigger if exists leads_notify_owner on leads;
create trigger leads_notify_owner
after insert on leads
for each row execute function enqueue_lead_notification();

-- 20260908000000_multi_supplements_trip_capacity
--
-- Two owner asks, one schema pass (they share the same rewritten function bodies):
--
-- 1) MULTIPLE optional supplements per activity. The single supplement pair
--    (activities.supplement_name / supplement_minor, 20260905000000) becomes a real child table,
--    `activity_supplements`, so the Ile aux Cerfs trips can sell the lobster lunch AND snorkel gear
--    AND anything else the owner dreams up — each named and priced by him, each per person. What a
--    guest actually bought is snapshot per supplement into `booking_supplements` (name + unit + qty
--    + total at booking time), for the same reason the old scalars were snapshots: a reprinted
--    invoice must show what was paid, not today's menu.
--
--    Money stays in REAL columns ([[gytm-activity-supplement]]): the French label rides as a
--    `name_fr` column on the supplement row itself (per-field coalesce in api_get_activity), never
--    through `extra`, which the FR overlay merges over. The client still only ever sends WHICH
--    supplement (by id) and HOW MANY heads; the unit price is read here, from the row.
--
--    The legacy columns (activities.supplement_name/supplement_minor,
--    activity_translations.supplement_name, bookings.supplement_qty/minor/name) are FROZEN, not
--    dropped: the live seed dump and old booking rows reference them, and this site is live. Their
--    data is migrated into the new tables below; nothing writes or reads them after this.
--
-- 2) Trips/day × guests/trip capacity, for EVERY activity. The availability screen's one number
--    hid two facts the owner actually manages: how many trips can run per day, and how many guests
--    one trip can take. The storage model keeps `daily_capacity` as the POOL in the units it always
--    had (guests for shared per_person/per_group options, trips for private options, vehicles for
--    vehicle mode) — so used_capacity / create_hold / reschedule need NO changes — and adds ONE new
--    fact: `guests_per_trip` (activities default + activity_options override). For a shared option
--    the pool the admin UI writes is trips × guests_per_trip, and create_booking now refuses a
--    single booking bigger than guests_per_trip (the widget caps its party selector from the same
--    number). A private option's "guests per trip" IS private_max_guests (already enforced); a
--    vehicle's is the bracket cap (25). NULL guests_per_trip = no per-booking cap — exactly the old
--    behaviour, so existing activities change nothing until the owner edits the two numbers.
--
-- Re-applied winning bodies (verbatim + delta, per the revert-drift rule):
--   set_daily_capacity_atomic (20260801000000) + guestsPerTrip paths (incl. private_max_guests)
--   create_booking            (20260812000000)  + guests-per-trip guard on the shared branch
--   api_book                  (20260905000000)  + booking_supplements charge loop replaces the scalars
--   booking_json              (20260905000000)  + 'supplements' array replaces the three scalars
--   api_get_activity          (20260905000000)  + 'supplements' array + per-option 'guestsPerTrip'
--
-- Idempotent throughout (this file is appended verbatim to supabase/catch-up.sql).

-- ---------------------------------------------------------------------------
-- 1a) activity_supplements — the owner's per-activity upgrade menu.
-- ---------------------------------------------------------------------------
create table if not exists activity_supplements (
  id uuid primary key default gen_random_uuid(),
  activity_id uuid not null references activities (id) on delete cascade,
  name text not null check (btrim(name) <> ''),
  -- French label, per-field coalesce like activity_translations.title. The ENGLISH name alone
  -- decides the supplement exists; the price is never translated.
  name_fr text,
  -- Per-PERSON price in minor units. Server-authoritative: api_book reads it here and the client
  -- only ever sends an id + a head count.
  price_minor int not null default 0 check (price_minor >= 0),
  position int not null default 0,
  created_at timestamptz not null default now()
);
create index if not exists activity_supplements_activity_idx
  on activity_supplements (activity_id, position, id);

alter table activity_supplements enable row level security;

-- Public reads the published catalogue's supplements (the booking widget prices locally from them);
-- staff manage. Mirrors activity_option_prices exactly.
drop policy if exists activity_supplements_read on activity_supplements;
create policy activity_supplements_read on activity_supplements for select using (
  exists (select 1 from activities a where a.id = activity_id and (a.status = 'published' or is_staff()))
);
drop policy if exists activity_supplements_staff on activity_supplements;
create policy activity_supplements_staff on activity_supplements for all
  using (is_staff()) with check (is_staff());

grant select on activity_supplements to anon, authenticated, service_role;
grant insert, update, delete on activity_supplements to authenticated, service_role;

-- Migrate the single-supplement columns into the table (once — an activity that already has rows is
-- left alone, so re-running never duplicates). The FR label comes along from activity_translations.
insert into activity_supplements (activity_id, name, name_fr, price_minor, position)
select a.id,
       btrim(a.supplement_name),
       nullif(btrim(coalesce(t.supplement_name, '')), ''),
       coalesce(a.supplement_minor, 0),
       0
from activities a
left join activity_translations t on t.activity_id = a.id and t.locale = 'fr'
where nullif(btrim(coalesce(a.supplement_name, '')), '') is not null
  and not exists (select 1 from activity_supplements s where s.activity_id = a.id);

comment on column activities.supplement_name is
  'FROZEN legacy (20260908000000): the single supplement moved to activity_supplements. Kept only '
  'because the live catalogue dump/seed reference the column; nothing writes or reads it.';
comment on column activities.supplement_minor is
  'FROZEN legacy (20260908000000): see activities.supplement_name.';
comment on column activity_translations.supplement_name is
  'FROZEN legacy (20260908000000): the FR label moved to activity_supplements.name_fr.';

-- ---------------------------------------------------------------------------
-- 1b) booking_supplements — what a booking actually bought, snapshot per supplement.
-- ---------------------------------------------------------------------------
create table if not exists booking_supplements (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references bookings (id) on delete cascade,
  -- SET NULL: the owner deleting a supplement from the menu must never break an old booking's
  -- receipt — the name/unit/total below are the snapshot that survives.
  supplement_id uuid references activity_supplements (id) on delete set null,
  name text not null,
  qty int not null check (qty > 0),
  unit_minor int not null check (unit_minor >= 0),
  total_minor int not null check (total_minor >= 0),
  -- The MENU position at booking time, so every reader (booking_json → invoice / alert /
  -- confirmation) lists the supplements in one stable order. Ordering by id would be ordering by
  -- gen_random_uuid() — i.e. random per booking.
  position int not null default 0
);
create index if not exists booking_supplements_booking_idx on booking_supplements (booking_id);
-- One row per supplement per booking (api_book aggregates payload duplicates before inserting;
-- this backstops it). Partial: legacy backfilled rows carry no supplement_id.
create unique index if not exists booking_supplements_booking_supplement_key
  on booking_supplements (booking_id, supplement_id) where supplement_id is not null;

alter table booking_supplements enable row level security;

-- Owner-or-staff read, exactly like booking_items; writes only via the definer RPC below.
drop policy if exists booking_supplements_select on booking_supplements;
create policy booking_supplements_select on booking_supplements for select using (
  exists (select 1 from bookings b where b.id = booking_id and (b.user_id = auth.uid() or is_staff()))
);
drop policy if exists booking_supplements_staff on booking_supplements;
create policy booking_supplements_staff on booking_supplements for all
  using (is_staff()) with check (is_staff());

grant select on booking_supplements to authenticated, service_role;
grant insert, update, delete on booking_supplements to service_role;

-- Backfill the old scalar snapshots (unit price recovered as total/qty — exact, because api_book
-- always wrote total = unit × qty). Once: a booking that already has rows is left alone.
insert into booking_supplements (booking_id, name, qty, unit_minor, total_minor)
select b.id, b.supplement_name, b.supplement_qty,
       (b.supplement_minor / b.supplement_qty)::int, b.supplement_minor
from bookings b
where b.supplement_qty > 0 and b.supplement_name is not null
  and not exists (select 1 from booking_supplements bs where bs.booking_id = b.id);

comment on column bookings.supplement_name is
  'FROZEN legacy (20260908000000): supplements snapshot per row in booking_supplements now. '
  'Backfilled there; nothing writes or reads these three columns.';

-- ---------------------------------------------------------------------------
-- 2) guests_per_trip — how many guests ONE trip (one booking) can take.
--    activities.guests_per_trip is the default; activity_options.guests_per_trip overrides it.
--    NULL = uncapped (the pre-migration behaviour). Only meaningful for shared per_person /
--    per_group options: a private option's cap is private_max_guests, a vehicle's is the bracket.
-- ---------------------------------------------------------------------------
alter table activities
  add column if not exists guests_per_trip int
    check (guests_per_trip is null or guests_per_trip >= 1);
alter table activity_options
  add column if not exists guests_per_trip int
    check (guests_per_trip is null or guests_per_trip >= 1);

comment on column activities.guests_per_trip is
  'Max guests ONE booking may hold on a shared option (the "guests per trip" half of the '
  'availability screen; daily_capacity stays the whole day''s guest pool = trips x this). NULL = '
  'no per-booking cap. Options may override via activity_options.guests_per_trip.';
comment on column activity_options.guests_per_trip is
  'Per-option override of activities.guests_per_trip (shared options only — a private option''s '
  'cap is private_max_guests). NULL = inherit the activity''s number.';

-- ---------------------------------------------------------------------------
-- 3) set_daily_capacity_atomic — the 20260801000000 body VERBATIM, plus guestsPerTrip:
--    * activity path: `guestsPerTrip` (when the key is present) writes activities.guests_per_trip;
--    * option path:   for a SHARED option it writes activity_options.guests_per_trip; for a PRIVATE
--      option it writes private_max_guests (validated against private_included, so the pricing
--      constraint can never be tripped into a 500);
--    * option path now allows a guests-only update (capacity omitted) — the availability screen
--      edits the two numbers of a single-private-option activity through two different rows;
--    * inherit clears guests_per_trip along with daily_capacity (back to the activity's numbers).
-- ---------------------------------------------------------------------------
create or replace function set_daily_capacity_atomic(p jsonb)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_activity_id uuid := nullif(p ->> 'activityId', '')::uuid;
  v_capacity int := (p ->> 'capacity')::int;
  v_option_id uuid := nullif(p ->> 'optionId', '')::uuid;
  v_inherit boolean := coalesce((p ->> 'inherit')::boolean, false);
  v_has_gpt boolean := p ? 'guestsPerTrip';
  v_gpt int := nullif(p ->> 'guestsPerTrip', '')::int;
  v_activity_capacity int;
  v_private_base int;
  v_private_included int;
begin
  if not is_staff() then
    raise exception 'forbidden';
  end if;
  if v_activity_id is null then
    raise exception 'invalid_request';
  end if;
  if v_has_gpt and v_gpt is not null and v_gpt < 1 then
    raise exception 'invalid_request';
  end if;
  if v_option_id is not null and v_inherit then
    -- Clear the option's overrides; its future occurrences fall back to the activity numbers.
    update activity_options set daily_capacity = null, guests_per_trip = null
     where id = v_option_id and activity_id = v_activity_id;
    if not found then
      raise exception 'invalid_request';
    end if;
    select daily_capacity into v_activity_capacity from activities where id = v_activity_id;
    if v_activity_capacity is not null then
      update session_occurrences so
         set capacity = v_activity_capacity
       where so.activity_option_id = v_option_id
         and so.starts_at >= now();
    end if;
  elsif v_option_id is not null then
    -- Option-scoped: capacity and/or guests-per-trip for THIS option only.
    if v_capacity is null and not v_has_gpt then
      raise exception 'invalid_request';
    end if;
    if v_capacity is not null and v_capacity < 0 then
      raise exception 'invalid_request';
    end if;
    if v_has_gpt then
      select private_base_minor, private_included into v_private_base, v_private_included
        from activity_options where id = v_option_id and activity_id = v_activity_id;
      if not found then
        raise exception 'invalid_request';
      end if;
      if v_private_base is not null then
        -- Private option: "guests per trip" IS private_max_guests. It must stay a number (the
        -- completeness constraint requires one) and cover at least the base's included heads.
        if v_gpt is null or v_gpt < coalesce(v_private_included, 1) then
          raise exception 'invalid_request'
            using detail = format('private guests/trip must be >= %s', coalesce(v_private_included, 1));
        end if;
        update activity_options set private_max_guests = v_gpt
         where id = v_option_id and activity_id = v_activity_id;
      else
        update activity_options set guests_per_trip = v_gpt
         where id = v_option_id and activity_id = v_activity_id;
      end if;
    end if;
    if v_capacity is not null then
      update activity_options set daily_capacity = v_capacity
       where id = v_option_id and activity_id = v_activity_id;
      if not found then
        raise exception 'invalid_request';
      end if;
      update session_occurrences so
         set capacity = v_capacity
       where so.activity_option_id = v_option_id
         and so.starts_at >= now();
    end if;
  else
    if v_capacity is null or v_capacity < 0 then
      raise exception 'invalid_request';
    end if;
    if v_has_gpt then
      update activities set daily_capacity = v_capacity, guests_per_trip = v_gpt
        where id = v_activity_id;
    else
      update activities set daily_capacity = v_capacity where id = v_activity_id;
    end if;
    update session_occurrences so
       set capacity = v_capacity
      from activity_options o
     where so.activity_option_id = o.id
       and o.activity_id = v_activity_id
       and o.daily_capacity is null
       and so.starts_at >= now();
  end if;
  perform materialize_availability(jsonb_build_object('activityId', v_activity_id::text));
end;
$$;
revoke execute on function set_daily_capacity_atomic(jsonb) from public;
grant execute on function set_daily_capacity_atomic(jsonb) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 4) create_booking — the 20260812000000 body VERBATIM, plus the guests-per-trip guard on the
--    shared (per_person / per_group) branch: one booking may not exceed
--    coalesce(option.guests_per_trip, activity.guests_per_trip). Private/vehicle branches keep
--    their own caps (private_max_guests / the bracket) and are untouched.
-- ---------------------------------------------------------------------------
create or replace function create_booking(
  p_idempotency_key text,
  p_hold_id uuid,
  p_customer_name text,
  p_customer_email text,
  p_customer_phone text,
  p_source booking_source,
  p_items jsonb,
  p_suv boolean default false
)
returns bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_existing bookings;
  v_hold booking_holds;
  v_occ session_occurrences;
  v_option_id uuid;
  v_mode text := 'per_person';
  v_trip_cap int;
  v_booking bookings;
  v_item jsonb;
  v_label text;
  v_qty int;
  v_unit bigint;
  v_max int;
  v_total bigint := 0;
  v_qty_total int := 0;
  v_agg jsonb := '{}'::jsonb;
  v_vehicle text;
  v_sedan bigint;
  v_suv_price bigint;
  v_family bigint;
  v_van bigint;
  v_coaster bigint;
  v_pl_standard bigint;
  v_pl_suv bigint;
  v_pl_six bigint;
  v_pl_van bigint;
  v_pl_coach bigint;
  v_pl_max int;
  v_pb bigint;
  v_pi int;
  v_pe bigint;
  v_pm int;
  v_opt_name text;
begin
  select * into v_existing from bookings where idempotency_key = p_idempotency_key;
  if found then
    return v_existing;
  end if;

  select * into v_hold from booking_holds where id = p_hold_id for update;
  if not found then
    raise exception 'hold_not_found';
  end if;
  if v_hold.status <> 'active' or v_hold.expires_at <= now() then
    raise exception 'hold_not_active';
  end if;
  -- Re-checked HERE, under the FOR UPDATE taken above: attaching to a booking does not change the
  -- hold's status, so the active check alone would let a second booking (different idempotency key)
  -- adopt a hold that booking A already consumed — two payable bookings sharing one capacity unit.
  -- The idempotency-replay path returned earlier, so any booking_id at this point is a conflict.
  if v_hold.booking_id is not null then
    raise exception 'hold_already_used';
  end if;

  select * into v_occ from session_occurrences where id = v_hold.session_occurrence_id for update;
  if v_occ.status <> 'open' then
    raise exception 'occurrence_not_bookable' using detail = v_occ.status::text;
  end if;
  v_option_id := v_occ.activity_option_id;

  -- Pricing mode + the per-booking guest cap for shared options (option override, else the
  -- activity default; NULL = uncapped, the pre-20260908 behaviour).
  select a.pricing_mode, coalesce(o.guests_per_trip, a.guests_per_trip)
    into v_mode, v_trip_cap
  from activity_options o
  join activities a on a.id = o.activity_id
  where o.id = v_option_id;
  v_mode := coalesce(v_mode, 'per_person');

  select private_base_minor, private_included, private_extra_minor, private_max_guests, name
    into v_pb, v_pi, v_pe, v_pm, v_opt_name
  from activity_options
  where id = v_option_id;

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_label := v_item ->> 'price_label';
    v_qty := (v_item ->> 'quantity')::int;
    if v_label is null or v_qty is null or v_qty <= 0 then
      raise exception 'invalid_item';
    end if;
    v_qty_total := v_qty_total + v_qty;
    v_agg := jsonb_set(v_agg, array[v_label], to_jsonb(coalesce((v_agg ->> v_label)::int, 0) + v_qty));
  end loop;
  if v_qty_total <= 0 then
    raise exception 'invalid_item';
  end if;

  if v_pb is not null then
    -- Private option (option-level flag): a flat base covers the first v_pi guests, v_pe per extra
    -- head. Counted like a vehicle: ONE capacity unit per booking (the pool is trips/day), with the
    -- real headcount recorded in pax on the single line item below.
    if v_qty_total < 1 or v_qty_total > v_pm then
      raise exception 'exceeds_max_guests' using detail = format('private: %s > %s', v_qty_total, v_pm);
    end if;
    v_total := v_pb + v_pe * greatest(0, v_qty_total - v_pi);
    v_vehicle := coalesce(nullif(v_opt_name, ''), 'Private');
    if v_hold.quantity <> 1 then
      raise exception 'items_quantity_mismatch' using detail = format('private hold %s', v_hold.quantity);
    end if;
  elsif v_mode = 'vehicle' then
    -- One flat price for the bracket that fits P = v_qty_total (people on board). (Unchanged.)
    if v_qty_total < 1 or v_qty_total > 25 then
      raise exception 'exceeds_vehicle_capacity' using detail = v_qty_total::text;
    end if;
    select sedan_minor, suv_minor, family_minor, van_minor, coaster_minor
      into v_sedan, v_suv_price, v_family, v_van, v_coaster
      from sightseeing_pricing limit 1;
    if v_sedan is null then
      raise exception 'sightseeing_pricing_unset';
    end if;
    if v_qty_total <= 4 then
      if p_suv then
        v_total := v_suv_price;
        v_vehicle := 'SUV';
      else
        v_total := v_sedan;
        v_vehicle := 'Sedan';
      end if;
    elsif v_qty_total <= 6 then
      v_total := v_family;
      v_vehicle := 'Family car';
    elsif v_qty_total <= 14 then
      v_total := v_van;
      v_vehicle := 'Van';
    else
      v_total := v_coaster;
      v_vehicle := 'Coaster';
    end if;
    if v_hold.quantity <> 1 then
      raise exception 'items_quantity_mismatch' using detail = format('vehicle hold %s', v_hold.quantity);
    end if;
  elsif v_mode = 'vehicle_custom' then
    -- Parallel planner path: same bracket shape, the planner's own prices/names + cap.
    select standard_minor, suv_minor, six_minor, van_minor, coach_minor, max_party
      into v_pl_standard, v_pl_suv, v_pl_six, v_pl_van, v_pl_coach, v_pl_max
      from planner_pricing limit 1;
    if v_pl_standard is null then
      raise exception 'planner_pricing_unset';
    end if;
    if v_qty_total < 1 or v_qty_total > v_pl_max then
      raise exception 'exceeds_vehicle_capacity' using detail = v_qty_total::text;
    end if;
    if v_qty_total <= 4 then
      if p_suv then
        v_total := v_pl_suv;
        v_vehicle := 'SUV';
      else
        v_total := v_pl_standard;
        v_vehicle := 'Standard car';
      end if;
    elsif v_qty_total <= 6 then
      v_total := v_pl_six;
      v_vehicle := '6-seater';
    elsif v_qty_total <= 14 then
      v_total := v_pl_van;
      v_vehicle := 'Van';
    else
      v_total := v_pl_coach;
      v_vehicle := 'Coach';
    end if;
    if v_hold.quantity <> 1 then
      raise exception 'items_quantity_mismatch' using detail = format('vehicle hold %s', v_hold.quantity);
    end if;
  else
    -- Per-person / per-group: one booking may not exceed the option's guests-per-trip (the boat
    -- only seats so many, however big the day's pool is). NULL = uncapped, as before 20260908.
    if v_trip_cap is not null and v_qty_total > v_trip_cap then
      raise exception 'exceeds_max_guests' using detail = format('trip: %s > %s', v_qty_total, v_trip_cap);
    end if;
    -- Price each aggregated tier from the DB. (Unchanged.)
    for v_label, v_qty in select key, (value::text)::int from jsonb_each(v_agg) loop
      select amount_minor, max_guests into v_unit, v_max
      from activity_option_prices
      where activity_option_id = v_option_id and label = v_label;
      if not found then
        raise exception 'unknown_price_tier' using detail = v_label;
      end if;
      if v_mode = 'per_group' and v_max is not null then
        v_total := v_total + (v_unit * ceil(v_qty::numeric / v_max)::int);
      else
        if v_max is not null and v_qty > v_max then
          raise exception 'exceeds_max_guests' using detail = format('%s: %s > %s', v_label, v_qty, v_max);
        end if;
        v_total := v_total + (v_unit * v_qty);
      end if;
    end loop;
    if v_qty_total <> v_hold.quantity then
      raise exception 'items_quantity_mismatch'
        using detail = format('items %s, hold %s', v_qty_total, v_hold.quantity);
    end if;
  end if;

  -- A EUR 0 booking must never exist: an all-free party (infants only) would otherwise mint a
  -- zero-amount payment that flips 'paid' on any event. The client blocks free-only parties;
  -- enforce it zero-trust here too.
  if v_total <= 0 then
    raise exception 'zero_total';
  end if;

  insert into bookings (
    idempotency_key, customer_name, customer_email, customer_phone, source,
    status, total_minor, operator_payout_minor, agency_commission_minor
  )
  values (
    p_idempotency_key, p_customer_name, p_customer_email, p_customer_phone,
    coalesce(p_source, 'web'), 'payment_pending', v_total, v_total, 0
  )
  returning * into v_booking;

  if v_pb is not null or v_mode in ('vehicle', 'vehicle_custom') then
    insert into booking_items (
      booking_id, session_occurrence_id, activity_option_id, price_label,
      quantity, unit_amount_minor, subtotal_minor, pax
    )
    values (
      v_booking.id, v_hold.session_occurrence_id, v_option_id, v_vehicle,
      1, v_total, v_total, v_qty_total
    );
  else
    for v_label, v_qty in select key, (value::text)::int from jsonb_each(v_agg) loop
      select amount_minor, max_guests into v_unit, v_max
      from activity_option_prices
      where activity_option_id = v_option_id and label = v_label;
      insert into booking_items (
        booking_id, session_occurrence_id, activity_option_id, price_label,
        quantity, unit_amount_minor, subtotal_minor
      )
      values (
        v_booking.id, v_hold.session_occurrence_id, v_option_id, v_label, v_qty, v_unit,
        case
          when v_mode = 'per_group' and v_max is not null then v_unit * ceil(v_qty::numeric / v_max)::int
          else v_unit * v_qty
        end
      );
    end loop;
  end if;

  -- Conditional attach, belt-and-braces with the guard above: if anything ever attaches this hold
  -- between our check and here, refuse rather than silently overwrite the other booking's claim.
  update booking_holds set booking_id = v_booking.id where id = v_hold.id and booking_id is null;
  if not found then
    raise exception 'hold_already_used';
  end if;
  return v_booking;
end;
$$;

revoke execute on function create_booking(text, uuid, text, text, text, booking_source, jsonb, boolean)
  from public, anon, authenticated;
grant execute on function create_booking(text, uuid, text, text, text, booking_source, jsonb, boolean)
  to service_role;

-- ---------------------------------------------------------------------------
-- 5) api_book — the 20260905000000 body VERBATIM, with the single-supplement charge replaced by
--    the booking_supplements loop. The payload's `supplements` is [{id, qty}] only: each id must
--    belong to the activity behind the occurrence (zero-trust — an unknown or foreign id is simply
--    ignored), duplicates are aggregated, each qty is clamped to the head count, and the unit price
--    comes from the supplement row. Replay guards, both required: rows already written (the normal
--    replay) OR a payment exists (a mutated replay must never re-price a booking mid-payment).
-- ---------------------------------------------------------------------------
create or replace function api_book(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_occ uuid := (p ->> 'occurrenceId')::uuid;
  v_key text := p ->> 'idempotencyKey';
  v_expected_slug text := nullif(p ->> 'expectedSlug', '');
  v_total_qty bigint := 0;
  v_items jsonb := '[]'::jsonb;
  v_mode text := 'per_person';
  v_is_private boolean := false;
  v_suv boolean := coalesce((p ->> 'suv')::boolean, false);
  v_hold_id uuid := nullif(p ->> 'holdId', '')::uuid;
  v_want_qty int;
  v_reused boolean := false;
  v_child int;
  v_child_extra bigint;
  v_supp_total bigint := 0;
  v_activity_id uuid;
  v_hold booking_holds;
  v_booking bookings;
  r record;
  v_activity_region text;
  v_pickup_available boolean := false;
  v_pickup_lat double precision;
  v_pickup_lng double precision;
  v_pickup_region text;
  v_transport bigint;
  v_is_airport boolean := false;
  v_is_hotel boolean := false;
  v_dropoff_zone text;
  v_trip_type text;
  v_trip_direction text;
  v_ret_pct int;
  v_fare bigint;
  v_hotel_pickup_region text;
  v_hotel_dropoff_region text;
  v_band text;
  v_actor uuid;
begin
  if v_occ is null or v_key is null then
    raise exception 'invalid_request';
  end if;

  if v_expected_slug is not null and not exists (
    select 1 from session_occurrences so
    join activity_options o on o.id = so.activity_option_id
    join activities a on a.id = o.activity_id
    where so.id = v_occ and a.slug = v_expected_slug
  ) then
    raise exception 'occurrence_activity_mismatch';
  end if;

  for r in select key, (value::text)::bigint as q from jsonb_each(p -> 'party') loop
    if r.q < 0 or r.q > 1000000 then raise exception 'invalid_party'; end if;
    if r.q > 0 then
      v_total_qty := v_total_qty + r.q;
      v_items := v_items || jsonb_build_object('price_label', r.key, 'quantity', r.q);
    end if;
  end loop;
  if v_total_qty <= 0 or v_total_qty > 1000000 then raise exception 'invalid_party'; end if;

  select a.pricing_mode,
         coalesce(a.region, region_from_coords(a.lat, a.lng)),
         coalesce(a.pickup_available, false),
         coalesce(a.is_airport_transfer, false),
         coalesce(a.is_hotel_transfer, false),
         (o.private_base_minor is not null),
         a.id
    into v_mode, v_activity_region, v_pickup_available, v_is_airport, v_is_hotel, v_is_private,
         v_activity_id
  from session_occurrences so
  join activity_options o on o.id = so.activity_option_id
  join activities a on a.id = o.activity_id
  where so.id = v_occ;
  v_mode := coalesce(v_mode, 'per_person');
  v_want_qty := case when v_mode in ('vehicle', 'vehicle_custom')
                       or coalesce(v_is_private, false) then 1 else v_total_qty::int end;

  -- Actor identity, resolved BEFORE the hold-reuse gate so ownership can bind reuse. api_book is
  -- service-role-only, so auth.uid() is null; the JWKS-verified caller id arrives as p.actorUserId
  -- (trustworthy BECAUSE only the server can execute this function). auth.uid() stays first as
  -- belt-and-suspenders.
  v_actor := coalesce(auth.uid(), nullif(p ->> 'actorUserId', '')::uuid);

  if v_hold_id is not null then
    -- FOR UPDATE: two concurrent api_book calls quoting the same holdId must serialise here, or both
    -- read booking_id IS NULL and both proceed (create_booking's own lock cannot save the second one
    -- on its own — it re-checks under the lock, but only because of the guard added alongside this).
    -- Ownership: an OWNED hold (created_by set) is only reusable by its owner; an ownerless hold
    -- (guest checkout, or created before sign-in) stays reusable by whoever holds the unguessable id,
    -- which keeps the guest → sign-in-mid-checkout flow working.
    select * into v_hold from booking_holds
    where id = v_hold_id and status = 'active' and expires_at > now() and booking_id is null
      and session_occurrence_id = v_occ and quantity = v_want_qty
      and (created_by is null or created_by = v_actor)
    for update;
    if found then v_reused := true; end if;
  end if;
  -- A REPLAY whose booking already exists must not mint a hold.
  --
  -- create_booking's idempotency check runs before it ever looks at p_hold_id, so on a replay it
  -- returns the existing booking and never attaches whatever hold we passed. The original hold is by
  -- then consumed (booking_id set), so the reuse SELECT above cannot match it and v_reused is false --
  -- and create_hold would mint a fresh one that nothing ever claims. It then sits ACTIVE, counted by
  -- used_capacity, for its whole TTL. Worse, on a nearly-full departure create_hold raises
  -- insufficient_capacity, so a legitimate retry of a booking that ALREADY SUCCEEDED fails instead of
  -- returning it -- the caller is told the booking failed when it did not.
  -- (Only ever one orphan: a second replay finds it by idempotency key. One is enough to sell out a
  -- last vehicle.)
  if not v_reused and not exists (select 1 from bookings where idempotency_key = v_key) then
    v_hold := create_hold(v_occ, v_want_qty, v_key || ':book');
  end if;

  v_booking := create_booking(
    v_key, v_hold.id, p ->> 'customerName', p ->> 'customerEmail', p ->> 'customerPhone',
    coalesce((p ->> 'source')::booking_source, 'web'), v_items, v_suv
  );

  -- F23 (replay-disclosure guard): create_booking returns the existing row on an idempotency-key
  -- replay, and api_book runs SECURITY DEFINER, so RLS does not filter the returned DTO. Refuse to
  -- echo a booking the caller can't prove they own:
  --   * an authenticated user replaying someone else's OWNED booking -> forbidden;
  --   * ANY caller replaying an UNOWNED (guest) booking whose supplied email doesn't match -> forbidden.
  --     A stolen/guessed key alone (authenticated OR anonymous) would otherwise hand back the original
  --     guest's PII / let an authed caller adopt the row. A legitimate retry resends the same email and
  --     passes; a fresh create trivially passes (just inserted with this caller's email).
  if (v_booking.user_id is not null and v_booking.user_id is distinct from v_actor)
     or (v_booking.user_id is null
         and lower(coalesce(v_booking.customer_email, '')) <> lower(coalesce(p ->> 'customerEmail', '')))
  then
    raise exception 'forbidden';
  end if;
  if v_actor is not null then
    update bookings set user_id = v_actor where id = v_booking.id and user_id is null;
  end if;

  -- Ownership for the FALLBACK hold: when no reusable holdId was supplied, api_book mints its own
  -- hold above via create_hold, which runs under service_role here (server-only RPC) and so wrote
  -- created_by = auth.uid() = NULL. Stamp the actor onto it so the customer's owner-scoped hold
  -- status/release endpoints work. A REUSED hold already carries its owner (created_by not null),
  -- so the guard leaves it alone; a guest booking (v_actor null) leaves the hold ownerless as before.
  if v_actor is not null then
    update booking_holds set created_by = v_actor where id = v_hold.id and created_by is null;
  end if;

  -- The language the guest booked in. Email and PDFs render later, often from a cron worker with no
  -- request context, so the locale must be stored rather than inferred at send time. Unconditional: by
  -- this point the F23 guard above has already verified the caller may act on this booking, so re-
  -- asserting the same value on an idempotent replay is harmless. Absent/empty collapses to 'en' (never
  -- SQL NULL, never a failed enum cast), so an older client that sends no locale still books cleanly.
  update bookings
  set locale = coalesce(nullif(p ->> 'locale', ''), 'en')::content_locale
  where id = v_booking.id;

  if p ? 'itinerary'
     and jsonb_typeof(p -> 'itinerary') = 'array'
     and jsonb_array_length(p -> 'itinerary') > 0
     and jsonb_array_length(p -> 'itinerary') <= 30
  then
    update bookings set custom_itinerary = p -> 'itinerary'
    where id = v_booking.id and custom_itinerary is null;
  end if;

  if nullif(btrim(p ->> 'pickupLocation'), '') is not null then
    update bookings set pickup_location = left(btrim(p ->> 'pickupLocation'), 200)
    where id = v_booking.id and pickup_location is null;
  end if;

  -- Drop-off is its OWN field (never merged into pickup_location). pickup_pending records "pickup to be
  -- arranged" — distinct from "no pickup" — and is set on the just-created row only.
  if nullif(btrim(p ->> 'dropoffLocation'), '') is not null then
    update bookings set dropoff_location = left(btrim(p ->> 'dropoffLocation'), 200)
    where id = v_booking.id and dropoff_location is null;
  end if;

  if coalesce((p ->> 'pickupPending')::boolean, false) then
    update bookings set pickup_pending = true
    where id = v_booking.id and pickup_pending = false;
  end if;

  -- Airport transfer (server-authoritative, zero-trust): the destination ZONE comes from the hotel
  -- SLUG via airport_transfer_hotels — never a client-sent zone. When the guest's hotel isn't listed
  -- (no dropoffSlug), classify the zone from the supplied AREA instead (Zone 2 = the near-airport
  -- south-east areas), still never trusting a client price. The whole fare is the zone × vehicle matrix
  -- (vehicle derived from party size + the ≤4 SUV upgrade); a return trip is two legs minus the
  -- configured discount. We OVERRIDE the booking total + payout + the single line item so the receipt's
  -- item == total. Mirrors airportTransferQuoteMinor() in pricing.ts.
  if v_is_airport then
    v_trip_direction := case
      when (p ->> 'tripDirection') in ('arrival', 'departure', 'return') then p ->> 'tripDirection'
      when (p ->> 'tripType') = 'return' then 'return'
      else 'arrival'
    end;
    v_trip_type := case when v_trip_direction = 'return' then 'return' else 'one_way' end;
    if nullif(p ->> 'dropoffSlug', '') is not null then
      select zone into v_dropoff_zone from airport_transfer_hotels
        where slug = nullif(p ->> 'dropoffSlug', '');
    end if;
    if v_dropoff_zone is null then
      v_dropoff_zone := airport_transfer_area_zone(p ->> 'dropoffArea');
    end if;
    v_fare := airport_transfer_fare_minor(v_dropoff_zone, v_total_qty::int, v_suv);
    if v_trip_type = 'return' then
      select coalesce(return_discount_pct, 0) into v_ret_pct from airport_transfer_config limit 1;
      v_fare := round(v_fare::numeric * 2 * (100 - coalesce(v_ret_pct, 0)) / 100)::bigint;
    end if;
    -- Replay guard, matching the pattern every other post-create mutation in this function already
    -- uses (`and custom_itinerary is null`, `and pickup_location is null`, `and pickup_pending = false`).
    -- create_booking returns the EXISTING row on an idempotency-key replay, so unguarded this silently
    -- re-prices a booking that has already started paying -- moving total_minor out from under the MUR
    -- charge pinned on its payment row and a Peach session already minted for the old amount.
    if v_fare > 0 and not exists (select 1 from payments pay where pay.booking_id = v_booking.id) then
      update bookings
        set total_minor = v_fare, operator_payout_minor = v_fare
        where id = v_booking.id;
      update booking_items
        set unit_amount_minor = v_fare, subtotal_minor = v_fare
        where booking_id = v_booking.id;
    end if;
    update bookings set
        trip_type = v_trip_type,
        trip_direction = v_trip_direction,
        flight_number = left(nullif(btrim(p ->> 'flightNumber'), ''), 40),
        arrival_time = left(nullif(btrim(p ->> 'arrivalTime'), ''), 40),
        return_date = nullif(p ->> 'returnDate', '')::date,
        return_time = left(nullif(btrim(p ->> 'returnTime'), ''), 40),
        departure_flight_number = left(nullif(btrim(p ->> 'departureFlightNumber'), ''), 40),
        room_or_cabin = left(nullif(btrim(p ->> 'roomOrCabin'), ''), 60),
        luggage_details = left(nullif(btrim(p ->> 'luggageDetails'), ''), 300),
        child_seat_age = nullif(p ->> 'childSeatAge', '')::int,
        traveller_gender = left(nullif(btrim(p ->> 'travellerGender'), ''), 20),
        traveller_company = left(nullif(btrim(p ->> 'travellerCompany'), ''), 120),
        traveller_country = left(nullif(btrim(p ->> 'travellerCountry'), ''), 80),
        special_notes = left(nullif(btrim(p ->> 'specialNotes'), ''), 600)
      where id = v_booking.id;
  end if;

  -- Hotel-to-hotel transfer (server-authoritative, zero-trust): derive BOTH endpoints' regions from the
  -- hotel SLUGS via airport_transfer_hotels (or area_region() for a free-text end), reject a same-hotel
  -- trip, classify the distance band (region_distance_band), and price band × vehicle (× return discount).
  -- OVERRIDE the booking total + payout + line item. Mirrors hotelTransferQuoteMinor() in pricing.ts.
  if v_is_hotel then
    if nullif(p ->> 'pickupSlug', '') is not null
       and nullif(p ->> 'pickupSlug', '') = nullif(p ->> 'dropoffSlug', '') then
      raise exception 'same_hotel';
    end if;
    v_trip_type := case when (p ->> 'tripType') = 'return' then 'return' else 'one_way' end;
    v_hotel_pickup_region := hotel_end_region(
      p ->> 'pickupSlug',
      nullif(p ->> 'pickupLat', '')::double precision,
      nullif(p ->> 'pickupLng', '')::double precision,
      p ->> 'pickupArea');
    v_hotel_dropoff_region := hotel_end_region(
      p ->> 'dropoffSlug',
      nullif(p ->> 'dropoffLat', '')::double precision,
      nullif(p ->> 'dropoffLng', '')::double precision,
      p ->> 'dropoffArea');
    v_band := region_distance_band(v_hotel_pickup_region, v_hotel_dropoff_region);
    v_fare := hotel_transfer_fare_minor(v_band, v_total_qty::int, v_suv);
    if v_trip_type = 'return' then
      select coalesce(return_discount_pct, 0) into v_ret_pct from hotel_transfer_config limit 1;
      v_fare := round(v_fare::numeric * 2 * (100 - coalesce(v_ret_pct, 0)) / 100)::bigint;
    end if;
    -- Replay guard, matching the pattern every other post-create mutation in this function already
    -- uses (`and custom_itinerary is null`, `and pickup_location is null`, `and pickup_pending = false`).
    -- create_booking returns the EXISTING row on an idempotency-key replay, so unguarded this silently
    -- re-prices a booking that has already started paying -- moving total_minor out from under the MUR
    -- charge pinned on its payment row and a Peach session already minted for the old amount.
    if v_fare > 0 and not exists (select 1 from payments pay where pay.booking_id = v_booking.id) then
      update bookings
        set total_minor = v_fare, operator_payout_minor = v_fare
        where id = v_booking.id;
      update booking_items
        set unit_amount_minor = v_fare, subtotal_minor = v_fare
        where booking_id = v_booking.id;
    end if;
    update bookings set
        trip_type = v_trip_type,
        arrival_time = left(nullif(btrim(p ->> 'arrivalTime'), ''), 40),
        pickup_hotel_slug = left(nullif(btrim(p ->> 'pickupSlug'), ''), 120),
        pickup_region = v_hotel_pickup_region,
        return_date = nullif(p ->> 'returnDate', '')::date,
        return_time = left(nullif(btrim(p ->> 'returnTime'), ''), 40),
        room_or_cabin = left(nullif(btrim(p ->> 'roomOrCabin'), ''), 60),
        luggage_details = left(nullif(btrim(p ->> 'luggageDetails'), ''), 300),
        special_notes = left(nullif(btrim(p ->> 'specialNotes'), ''), 600)
      where id = v_booking.id;
  end if;

  v_child := least(greatest(coalesce(nullif(p ->> 'childSeats', '')::int, 0), 0), v_total_qty::int);
  if v_child > 0 then
    v_child_extra := greatest(0, v_child - 1) * 600;
    update bookings
    set child_seats = v_child,
        total_minor = total_minor + v_child_extra,
        operator_payout_minor = operator_payout_minor + v_child_extra
    where id = v_booking.id and child_seats = 0;
  end if;

  -- Per-activity supplements (e.g. the lobster lunch upgrade), MANY per activity since 20260908.
  -- Priced PER PERSON from each activity_supplements row, resolved by id AND scoped to the activity
  -- behind the occurrence — an unknown or foreign id simply doesn't join and charges nothing.
  -- Duplicate ids in the payload aggregate; every count clamps to the head count. Replay guards:
  -- rows already snapshot (the normal replay) or a payment already exists (a mutated replay must
  -- never re-price a booking mid-payment — [[gytm-drift-gate-double-charge]]). A configured-but-free
  -- supplement (price 0) still records the guest's request — the kitchen needs the head count.
  -- Sits after the transfer overrides for the same reason the child seats do: those OVERWRITE
  -- total_minor, so additive add-ons belong at the end.
  if p ? 'supplements'
     and jsonb_typeof(p -> 'supplements') = 'array'
     and jsonb_array_length(p -> 'supplements') between 1 and 20
     and not exists (select 1 from booking_supplements bs where bs.booking_id = v_booking.id)
     and not exists (select 1 from payments pay where pay.booking_id = v_booking.id)
  then
    for r in
      select s.id, s.name, s.price_minor, s.position,
             least(
               sum(least(greatest(coalesce(nullif(e ->> 'qty', '')::int, 0), 0), v_total_qty::int)),
               v_total_qty
             )::int as q
      from jsonb_array_elements(p -> 'supplements') e
      join activity_supplements s
        on s.id = nullif(e ->> 'id', '')::uuid
       and s.activity_id = v_activity_id
      group by s.id, s.name, s.price_minor, s.position
      order by s.position, s.id
    loop
      if r.q > 0 then
        insert into booking_supplements (booking_id, supplement_id, name, qty, unit_minor, total_minor, position)
        values (v_booking.id, r.id, r.name, r.q, r.price_minor, r.price_minor::bigint * r.q, r.position)
        on conflict (booking_id, supplement_id) where supplement_id is not null do nothing;
        v_supp_total := v_supp_total + r.price_minor::bigint * r.q;
      end if;
    end loop;
    if v_supp_total > 0 then
      update bookings
      set total_minor = total_minor + v_supp_total,
          operator_payout_minor = operator_payout_minor + v_supp_total
      where id = v_booking.id;
    end if;
  end if;

  -- Region-based transport add-on (per_person / per_group with pickup_available): a fee that scales with
  -- how far the pickup is from the activity's boarding region. The server RE-DERIVES the region from the
  -- pickup coordinates and looks up the fare here — it never trusts a client-sent price. Round-trip rule:
  -- drop-off doesn't change the fare, so it isn't read. Mirrors transportFare() in pricing.ts.
  if v_mode in ('per_person', 'per_group') and v_pickup_available
     and nullif(p ->> 'pickupLat', '') is not null
     and nullif(p ->> 'pickupLng', '') is not null
  then
    v_pickup_lat := (p ->> 'pickupLat')::double precision;
    v_pickup_lng := (p ->> 'pickupLng')::double precision;
    v_pickup_region := region_from_coords(v_pickup_lat, v_pickup_lng);
    if v_pickup_region is not null and v_activity_region is not null then
      v_transport := transport_fare_minor(v_pickup_region, v_activity_region, v_total_qty::int, v_suv);
      if v_transport > 0 then
        update bookings
        set transport_minor = v_transport,
            total_minor = total_minor + v_transport,
            operator_payout_minor = operator_payout_minor + v_transport,
            pickup_region = v_pickup_region,
            pickup_lat = v_pickup_lat,
            pickup_lng = v_pickup_lng
        where id = v_booking.id and transport_minor = 0;
      end if;
    end if;
  end if;

  return booking_json(v_booking.id);
end;
$$;

revoke execute on function api_book(jsonb) from public, anon, authenticated;
grant execute on function api_book(jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- 6) booking_json — the 20260905000000 body VERBATIM, with the three supplement scalars replaced by
--    the 'supplements' array (one entry per bought supplement, from the booking's own snapshot
--    rows). Old bookings were backfilled into booking_supplements above, so every reader sees one
--    shape. STAYS `security invoker`.
-- ---------------------------------------------------------------------------
create or replace function booking_json(p_booking_id uuid)
returns jsonb
language sql
stable
security invoker
set search_path = public
as $$
  select jsonb_build_object(
    'id', b.id, 'ref', b.ref, 'status', b.status, 'paymentState', b.payment_state,
    'customerName', b.customer_name, 'customerEmail', b.customer_email,
    'totalEur', b.total_minor::float / 100, 'currency', b.currency, 'source', b.source,
    'createdAt', b.created_at,
    'customItinerary', b.custom_itinerary,
    'pickupLocation', b.pickup_location,
    'dropoffLocation', b.dropoff_location,
    'pickupPending', b.pickup_pending,
    'pickupHotelSlug', b.pickup_hotel_slug,
    'childSeats', b.child_seats,
    'transportEur', b.transport_minor::float / 100,
    'supplements', coalesce((
      select jsonb_agg(jsonb_build_object(
        'name', bs.name, 'qty', bs.qty,
        'unitEur', bs.unit_minor::float / 100, 'totalEur', bs.total_minor::float / 100
      ) order by bs.position, bs.name)
      from booking_supplements bs where bs.booking_id = b.id
    ), '[]'::jsonb),
    'pickupRegion', b.pickup_region,
    'tripType', b.trip_type,
    'tripDirection', b.trip_direction,
    'flightNumber', b.flight_number,
    'arrivalTime', b.arrival_time,
    'returnDate', b.return_date,
    'returnTime', b.return_time,
    'departureFlightNumber', b.departure_flight_number,
    'roomOrCabin', b.room_or_cabin,
    'luggageDetails', b.luggage_details,
    'childSeatAge', b.child_seat_age,
    'travellerGender', b.traveller_gender,
    'travellerCompany', b.traveller_company,
    'travellerCountry', b.traveller_country,
    'specialNotes', b.special_notes,
    'disruption', b.disruption,
    'partySize', coalesce((
      select sum(coalesce(bi.pax, bi.quantity))
        from booking_items bi where bi.booking_id = b.id
    ), 0),
    -- The BOOKING-UNIT count, the unit seatsLeft is denominated in. For a per-person option it equals
    -- partySize; for a vehicle/private one it is 1 (one van / one trip, any group size). The date
    -- picker must filter on THIS, not partySize, or a 6-guest transfer is offered nothing.
    'unitsNeeded', coalesce((
      select sum(bi.quantity)
        from booking_items bi where bi.booking_id = b.id
    ), 0),
    'activityOptionId', (
      select bi.activity_option_id
        from booking_items bi where bi.booking_id = b.id order by bi.id limit 1
    ),
    'activitySlug', (
      select a.slug
        from booking_items bi
        join activity_options ao on ao.id = bi.activity_option_id
        join activities a on a.id = ao.activity_id
       where bi.booking_id = b.id
       order by bi.id limit 1
    ),
    'cancellable', (
      b.status = 'confirmed' and b.payment_state = 'paid'
      and (
        booking_awaiting_choice(b.disruption)
        or coalesce((
          select min(so.starts_at)
            from booking_items bi
            join session_occurrences so on so.id = bi.session_occurrence_id
           where bi.booking_id = b.id
        ), 'epoch'::timestamptz) > now() + interval '24 hours'
      )
    ),
    'reschedulable', (
      b.status = 'confirmed' and b.payment_state = 'paid'
      and (
        booking_awaiting_choice(b.disruption)
        or coalesce((
          select min(so.starts_at)
            from booking_items bi
            join session_occurrences so on so.id = bi.session_occurrence_id
           where bi.booking_id = b.id
        ), 'epoch'::timestamptz) > now() + interval '24 hours'
      )
    ),
    'serviceDate', (
      select min(so.starts_at)
        from booking_items bi
        join session_occurrences so on so.id = bi.session_occurrence_id
       where bi.booking_id = b.id
    ),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'priceLabel', bi.price_label, 'quantity', bi.quantity, 'pax', bi.pax,
        'unitAmountEur', bi.unit_amount_minor::float / 100, 'subtotalEur', bi.subtotal_minor::float / 100,
        'occurrenceId', bi.session_occurrence_id
      ))
      from booking_items bi where bi.booking_id = b.id
    ), '[]'::jsonb)
  )
  from bookings b where b.id = p_booking_id;
$$;

-- ---------------------------------------------------------------------------
-- 7) api_get_activity — the 20260905000000 body VERBATIM, with:
--    * 'supplementName'/'supplementEur' replaced by the 'supplements' array (id + locale-resolved
--      name + per-person price), so the widget renders one picker row per supplement;
--    * each option carrying 'guestsPerTrip' (option override, else the activity default) so the
--      party selector caps itself at what one trip can take.
--    STAYS `security invoker` — definer-grants-lockdown.test.ts depends on it.
-- ---------------------------------------------------------------------------
create or replace function api_get_activity(p jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public
as $$
  select jsonb_build_object(
    'id', a.id, 'slug', a.slug, 'type', a.type, 'title', coalesce(t.title, a.title),
    'summary', coalesce(t.summary, a.summary),
    'description', coalesce(t.description, a.description), 'category', a.category, 'location', a.location,
    'durationMinutes', a.duration_minutes, 'meetingPoint', coalesce(t.meeting_point, a.meeting_point),
    'pickupAvailable', a.pickup_available, 'pricingMode', a.pricing_mode,
    'minAdvanceDays', coalesce(a.min_advance_days, 1),
    'isAirportTransfer', coalesce(a.is_airport_transfer, false),
    'isHotelTransfer', coalesce(a.is_hotel_transfer, false),
    'airportFares', case when coalesce(a.is_airport_transfer, false) then (
      select jsonb_object_agg(f.zone, jsonb_build_object(
        'sedanMinor', f.sedan_minor, 'suvMinor', f.suv_minor, 'familyMinor', f.family_minor,
        'vanMinor', f.van_minor, 'coasterMinor', f.coaster_minor
      )) from airport_transfer_fare f
    ) else null end,
    'hotelTransferFares', case when coalesce(a.is_hotel_transfer, false) then (
      select jsonb_object_agg(f.band, jsonb_build_object(
        'sedanMinor', f.sedan_minor, 'suvMinor', f.suv_minor, 'familyMinor', f.family_minor,
        'vanMinor', f.van_minor, 'coasterMinor', f.coaster_minor
      )) from hotel_transfer_fare f
    ) else null end,
    'returnDiscountPct', case
      when coalesce(a.is_airport_transfer, false) then (select return_discount_pct from airport_transfer_config limit 1)
      when coalesce(a.is_hotel_transfer, false) then (select return_discount_pct from hotel_transfer_config limit 1)
      else null end,
    'region', coalesce(a.region, region_from_coords(a.lat, a.lng)),
    'lat', a.lat, 'lng', a.lng,
    'transportBands', case
      when a.pricing_mode in ('per_person', 'per_group') and coalesce(a.pickup_available, false) then (
        select jsonb_object_agg(t.band, jsonb_build_object(
          'sedanMinor', t.sedan_minor, 'suvMinor', t.suv_minor, 'familyMinor', t.family_minor,
          'vanMinor', t.van_minor, 'coasterMinor', t.coaster_minor
        )) from transport_band_pricing t
      ) else null end,
    'regionDistances', case
      when (a.pricing_mode in ('per_person', 'per_group') and coalesce(a.pickup_available, false))
        or coalesce(a.is_hotel_transfer, false) then (
        select jsonb_object_agg(d.region_a || '|' || d.region_b, d.band) from region_zone_distance d
      ) else null end,
    'languages', to_jsonb(a.languages),
    'inclusions', to_jsonb(coalesce(nullif(t.inclusions, '{}'), a.inclusions)),
    'exclusions', to_jsonb(coalesce(nullif(t.exclusions, '{}'), a.exclusions)),
    'highlights', to_jsonb(coalesce(nullif(t.highlights, '{}'), a.highlights)), 'cancellationPolicy', a.cancellation_policy,
    'seoTitle', coalesce(t.seo_title, a.seo_title), 'seoDescription', coalesce(t.seo_description, a.seo_description),
    'extra', a.extra || coalesce(t.extra, '{}'::jsonb),
    'supplements', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', s.id,
        'name', case
          when coalesce(nullif(p ->> 'locale', ''), 'en') = 'fr'
            then coalesce(nullif(btrim(coalesce(s.name_fr, '')), ''), s.name)
          else s.name end,
        'priceEur', s.price_minor::float / 100
      ) order by s.position, s.id)
      from activity_supplements s where s.activity_id = a.id
    ), '[]'::jsonb),
    'ratingAvg', a.rating_avg, 'ratingCount', a.rating_count,
    'fromPriceEur', case
      when a.pricing_mode = 'vehicle'
        then (select sedan_minor from sightseeing_pricing limit 1)::float / 100
      else (
        -- Per-OPTION front price, then min across options (mirrors api_search_activities).
        select min(case when opt.banded then opt.max_amt else coalesce(opt.min_paid, opt.min_amt) end)::float / 100
        from (
          select bool_or(pr.min_age is not null or pr.max_age is not null) as banded,
                 max(pr.amount_minor) as max_amt,
                 min(pr.amount_minor) filter (where pr.amount_minor > 0) as min_paid,
                 min(pr.amount_minor) as min_amt
          from activity_option_prices pr
          join activity_options o on o.id = pr.activity_option_id
          where o.activity_id = a.id
          group by pr.activity_option_id
        ) opt
      )
    end,
    'vehiclePricing', case when a.pricing_mode = 'vehicle' then (
      select jsonb_build_object(
        'sedanEur', sedan_minor::float / 100,
        'suvEur', suv_minor::float / 100,
        'familyEur', family_minor::float / 100,
        'vanEur', van_minor::float / 100,
        'coasterEur', coaster_minor::float / 100,
        'maxParty', 25
      ) from sightseeing_pricing limit 1
    ) else null end,
    'heroImage', (
      select jsonb_build_object('id', img.id, 'url', img.url, 'alt', img.alt, 'position', img.position)
      from activity_images img where img.activity_id = a.id order by img.position limit 1
    ),
    'images', coalesce((
      select jsonb_agg(jsonb_build_object('id', i.id, 'url', i.url, 'alt', i.alt, 'position', i.position) order by i.position)
      from activity_images i where i.activity_id = a.id
    ), '[]'::jsonb),
    'options', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', o.id, 'name', o.name, 'description', o.description, 'durationMinutes', o.duration_minutes, 'startWindow', o.start_window,
        'privateBaseEur', o.private_base_minor::float / 100,
        'privateIncluded', o.private_included,
        'privateExtraEur', o.private_extra_minor::float / 100,
        'privateMaxGuests', o.private_max_guests,
        'guestsPerTrip', coalesce(o.guests_per_trip, a.guests_per_trip),
        'prices', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', pr.id, 'label', pr.label, 'amountEur', pr.amount_minor::float / 100, 'maxGuests', pr.max_guests, 'minAge', pr.min_age, 'maxAge', pr.max_age
          ) order by pr.position)
          from activity_option_prices pr where pr.activity_option_id = o.id
        ), '[]'::jsonb)
      ) order by o.position)
      from activity_options o where o.activity_id = a.id
    ), '[]'::jsonb),
    'translations', coalesce((
      select jsonb_object_agg(t.locale, jsonb_build_object('title', t.title, 'summary', t.summary, 'description', t.description))
      from activity_translations t where t.activity_id = a.id
    ), '{}'::jsonb),
    'reviews', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', rv.id, 'author', rv.author, 'rating', rv.rating, 'text', rv.text, 'createdAt', rv.created_at
      ) order by rv.created_at desc)
      from reviews rv where rv.activity_id = a.id
    ), '[]'::jsonb)
  )
  from activities a
  left join activity_translations t
    on t.activity_id = a.id
   and t.locale = coalesce(nullif(p ->> 'locale', ''), 'en')::content_locale
  where a.slug = p ->> 'slug';
$$;
grant execute on function api_get_activity(jsonb) to anon, authenticated, service_role;

-- 20260909000000_quotes
--
-- Staff-drafted QUOTES: an itemised offer the owner builds in /admin/quotes, emails to a guest with
-- a signed public link, and that the guest pays through the EXISTING Peach checkout — so it lands in
-- the ledger and fires the confirmation + VAT invoice like any other booking. Schema only here; the
-- conversion RPC, the token, the pages and the email land in the tasks that follow.
--
-- Three tables, and the reason each exists:
--
-- 1) `quotes` — the draft itself, plus the public-link material. Only the SHA-256 HASH of the link
--    token is stored (`token_hash`); the raw token exists solely in the emailed URL, so a database
--    read (or a leaked backup) cannot mint a working link. `booking_id` is UNIQUE and set at
--    conversion, which is the schema-level half of "one quote can never mint two payable bookings"
--    (the other half is the guard inside api_convert_quote).
--
-- 2) `quote_items` — the lines. A CATALOGUE line names a real occurrence + option, so the money path
--    can re-price it from the catalogue at conversion; a CUSTOM (or, later, RENTAL) line is free text
--    carrying its own date/time, because it has no occurrence at all. `quote_item_shape` makes that
--    an invariant rather than a convention.
--
-- 3) `booking_custom_items` — the durable home for a priced booking line that has NO
--    session_occurrence. Deliberately NOT booking_items: that table's NOT NULL occurrence + option
--    are load-bearing for capacity, the day sheet and the voucher, and relaxing them would force
--    every existing reader to handle a null occurrence — on the money path. A separate table leaves
--    all of them untouched.
--
-- Conversion happens at PAY, never at send, so an unaccepted quote never holds capacity.
--
-- Part 2 (rentals) and Part 3 (calendar union) have their landing ground here on purpose:
-- `kind = 'rental'` + `rental_vehicle_slug` so Part 2 adds pricing and UI but no migration, and
-- `booking_custom_items.starts_at` is indexed so Part 3 is a read change, not a migration.
--
-- Idempotent throughout (this file is appended verbatim to supabase/catch-up.sql).

-- MUST be the first statement, and 'quote' must NOT be USED anywhere later in this same migration:
-- Postgres forbids using an enum value added by ALTER TYPE in the transaction that added it.
-- api_convert_quote only references 'quote' at runtime (a later transaction), which is fine.
alter type booking_source add value if not exists 'quote';

do $$
begin
  create type quote_status as enum ('draft', 'sent', 'accepted', 'expired', 'cancelled');
exception when duplicate_object then null;
end $$;

do $$
begin
  create type quote_item_kind as enum ('catalogue', 'custom', 'rental');
exception when duplicate_object then null;
end $$;

-- ---------------------------------------------------------------------------
-- 1) quotes — the draft offer and its public link.
-- ---------------------------------------------------------------------------
create table if not exists quotes (
  id uuid primary key default gen_random_uuid(),
  ref text not null unique,
  customer_name text not null,
  customer_email text not null,
  customer_phone text,
  status quote_status not null default 'draft',
  currency text not null default 'EUR',
  -- Minor units, and `bigint` like every other money column on the money path: 20260615121000
  -- widened bookings.total_minor and booking_items' amounts precisely because int caps at ~21.4M
  -- EUR-cents and a full-boat charter overflows it. A bespoke quote IS that case, and this figure is
  -- copied straight into bookings.total_minor at conversion, so it must be the same width.
  total_minor bigint not null default 0,
  valid_until date not null,
  intro_note text,
  -- Staff-only. Never rendered into the guest email or the public page.
  internal_notes text,
  -- SHA-256 of the raw link token. The raw token exists only in the emailed URL.
  token_hash text,
  sent_at timestamptz,
  -- Set once the guest pays. UNIQUE so one quote can never mint two payable bookings.
  booking_id uuid unique references bookings (id) on delete set null,
  locale content_locale not null default 'en',
  -- `set null`: a quote is a financial record that outlives its author, so deleting a departed
  -- colleague's auth user must forget who drafted it, never be blocked by it or delete it with them.
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- 2) quote_items — catalogue lines and free-text lines, in the owner's order.
-- ---------------------------------------------------------------------------
create table if not exists quote_items (
  id uuid primary key default gen_random_uuid(),
  quote_id uuid not null references quotes (id) on delete cascade,
  position int not null,
  kind quote_item_kind not null,
  session_occurrence_id uuid references session_occurrences (id),
  activity_option_id uuid references activity_options (id),
  price_label text,
  description text,
  starts_at timestamptz,
  ends_at timestamptz,
  rental_vehicle_slug text references rental_vehicles (slug),
  quantity int not null check (quantity > 0),
  unit_amount_minor bigint not null check (unit_amount_minor >= 0),
  subtotal_minor bigint not null check (subtotal_minor >= 0),
  -- A catalogue line must name an occurrence + option; a custom/rental line must not.
  constraint quote_item_shape check (
    (kind = 'catalogue' and session_occurrence_id is not null and activity_option_id is not null)
    or (kind <> 'catalogue' and session_occurrence_id is null and activity_option_id is null
        and description is not null)
  )
);
-- The editor, the email and the public page all read the lines in the owner's order. Ordering by id
-- would be ordering by gen_random_uuid() — i.e. random per quote.
create index if not exists quote_items_quote_idx on quote_items (quote_id, position);

-- ---------------------------------------------------------------------------
-- 3) booking_custom_items — priced booking lines with no session_occurrence.
-- ---------------------------------------------------------------------------
create table if not exists booking_custom_items (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references bookings (id) on delete cascade,
  position int not null,
  kind quote_item_kind not null check (kind <> 'catalogue'),
  description text not null,
  starts_at timestamptz,
  ends_at timestamptz,
  rental_vehicle_slug text references rental_vehicles (slug),
  quantity int not null check (quantity > 0),
  unit_amount_minor bigint not null check (unit_amount_minor >= 0),
  subtotal_minor bigint not null check (subtotal_minor >= 0),
  created_at timestamptz not null default now()
);
create index if not exists booking_custom_items_booking_idx on booking_custom_items (booking_id, position);
-- Part 3 (calendar union) reads by day; index it now so that stays a read-only change.
create index if not exists booking_custom_items_starts_idx on booking_custom_items (starts_at)
  where starts_at is not null;

-- ---------------------------------------------------------------------------
-- 4) `converted_at` — the conversion record a foreign key cannot clear.
--
-- `booking_id` is UNIQUE, which is what stops a second payable booking. But it is also
-- `on delete set null`, and bookings ARE hard-deleted: api_erase_user (20260816000000) deletes every
-- unpaid/pending booking for a person outright. That delete silently reverts booking_id to null, so
-- a quote that HAS been converted looks unconverted again — and the conversion guard being built on
-- top of it in the next task would mint a fresh booking. Today that only re-mints a never-paid
-- booking, so it is not a double charge; it is a guard resting on a column another statement can
-- reset, which is not a foundation to build the money path on.
--
-- CONTRACT for api_convert_quote and the pay route: set `converted_at` alongside `booking_id`, and
-- guard on `converted_at is null` — never on `booking_id is null`. The UNIQUE stays as the second
-- line of defence.
--
-- And the contract is a CONSTRAINT, not a comment: this is the schema half of "a quote must never
-- mint two payable bookings", so a conversion path that sets booking_id and forgets converted_at must
-- be impossible rather than merely discouraged. It holds under the `on delete set null` above —
-- booking_id clears, converted_at stays, and (null, not-null) is legal — which is precisely the
-- direction this column exists to survive.
-- ---------------------------------------------------------------------------
alter table quotes add column if not exists converted_at timestamptz;

alter table quotes drop constraint if exists quote_converted_shape;
alter table quotes add constraint quote_converted_shape
  check (booking_id is null or converted_at is not null);

-- ---------------------------------------------------------------------------
-- 4b) The DENOMINATION is re-checked, exactly as the amount already is.
--
-- api_convert_quote carefully re-derives `total_minor` from the lines and refuses to mint a booking
-- on any drift — and then copies `currency` across untouched, because nothing had ever questioned it.
-- Downstream nothing questions it either: payments_ledger_currency_eur (20260830000000) pins
-- `payments.currency = 'EUR'`, and api_create_payment inserts the payments row from
-- (booking_id, idempotency_key, amount_minor) without ever reading the booking's currency.
--
-- So a quote stored as 'MUR' would be shown "MUR 50000" on the public page, emailed as "MUR 50000",
-- and then charged 500 EUR. Not a failure anyone would see: a silent denomination mismatch on the
-- money path, reached through a column that carried a DEFAULT and no CHECK, i.e. through convention
-- alone. An amount deserves the second look it already gets; the unit it is counted in deserves the
-- same one.
--
-- src/lib/admin/quotes.ts refuses a non-EUR quote in the editor. This is the half that a cast, a raw
-- PostgREST write or a psql session cannot get past.
--
-- WIDEN IT THE DAY A SECOND SETTLEMENT CURRENCY EXISTS — and that day belongs to the LEDGER, not to
-- the quote: relax payments_ledger_currency_eur and teach api_create_payment to read the booking's
-- currency first, then this constraint, in that order. Relaxing this one alone only re-opens the
-- mismatch it was added to close.
--
-- drop-then-add so the whole file stays idempotent: `create table if not exists` above is a no-op on
-- a database that already has the table, so it would never restate the constraint.
-- ---------------------------------------------------------------------------
alter table quotes drop constraint if exists quotes_currency_eur;
alter table quotes add constraint quotes_currency_eur check (currency = 'EUR');

-- ---------------------------------------------------------------------------
-- 5) The two rental foreign keys say what they mean.
--
-- Both were declared with no ON DELETE action, i.e. NO ACTION, i.e. "block the delete" — by accident
-- rather than by intent. deleteRentalVehicle (src/lib/admin/rental.ts) deletes straight from
-- rental_vehicles, so once Part 2 writes rental lines, retiring a vehicle would fail with a raw
-- constraint string on both tables. The two tables want OPPOSITE things:
--
--   * quote_items    — a DRAFT may lose its link. The line keeps its own description, quantity and
--                      price, so it stays complete without the vehicle row -> `on delete set null`.
--   * booking_custom_items — a PAID line must keep naming what was sold -> `on delete restrict`,
--                      declared so the block is a decision, not a leftover. `description` is NOT NULL
--                      precisely so the writer carries the vehicle name into the line and it stays
--                      readable without the join; deleteRentalVehicle translates the 23503 into an
--                      explanation the operator can act on.
--
-- Written as drop-then-add so the whole file stays idempotent: `create table if not exists` above is
-- a no-op on a database that already has these tables, which means it would never restate the FKs.
-- ---------------------------------------------------------------------------
alter table quote_items drop constraint if exists quote_items_rental_vehicle_slug_fkey;
alter table quote_items add constraint quote_items_rental_vehicle_slug_fkey
  foreign key (rental_vehicle_slug) references rental_vehicles (slug) on delete set null;

alter table booking_custom_items drop constraint if exists booking_custom_items_rental_vehicle_slug_fkey;
alter table booking_custom_items add constraint booking_custom_items_rental_vehicle_slug_fkey
  foreign key (rental_vehicle_slug) references rental_vehicles (slug) on delete restrict;

-- ---------------------------------------------------------------------------
-- 6) The existing code has to learn that quotes exist.
--
-- `quote_items.session_occurrence_id` is deliberately NOT `on delete set null` (quote_item_shape
-- requires a catalogue line to keep its occurrence, so that action would only trade a
-- foreign_key_violation for a check_violation) and NOT `on delete cascade` (a quote line must not
-- vanish because someone tidied the calendar). It stays NO ACTION, and so does
-- `activity_option_id` — and because session_occurrences CASCADEs from activity_options
-- (20260615120200), deleting an OPTION reaches quote_items down both foreign keys at once.
--
-- Three callers delete those rows, and each is taught here or in its own file:
--   * stop_availability_atomic          — 6a below (a quoted slot is closed, not deleted);
--   * reconcileOptions (src/lib/admin/activity-write.ts) — keeps a quoted option, like a booked one;
--   * deleteActivity   (src/lib/admin/activity-write.ts) — translates the 23503 for the operator.
-- ---------------------------------------------------------------------------

-- 6a) stop_availability_atomic — a quoted slot is CLOSED, never deleted.
--
-- The original (20260617220000) DELETEs every empty future occurrence, guarded only by "no
-- booking_items, no active booking_holds". A draft quote's catalogue line has neither, so the delete
-- hit the NO ACTION foreign key, the exception aborted the whole SECURITY DEFINER transaction, and
-- admin "stop availability" was dead for any activity that appears on any quote — surfacing as a raw
-- Postgres error in src/lib/admin/availability-write.ts. A quote is a live offer to a guest, so the
-- right answer is the one already used for a booked slot: keep the row, close it.
--
-- Re-applied in FULL from its winning definition with the quote branch added to BOTH halves, so this
-- migration cannot silently revert anything that landed in it since.
create or replace function stop_availability_atomic(p jsonb)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_activity_id uuid := nullif(p ->> 'activityId', '')::uuid;
begin
  if not is_staff() then
    raise exception 'forbidden';
  end if;
  if v_activity_id is null then
    raise exception 'invalid_request';
  end if;

  update activities set daily_capacity = null where id = v_activity_id;

  -- Close future slots with a booking item, an active hold, OR a quote line (never strand a confirmed
  -- booking, a live hold, or an offer already sitting in a guest's inbox).
  update session_occurrences so
     set status = 'closed'
    from activity_options o
   where so.activity_option_id = o.id
     and o.activity_id = v_activity_id
     and so.starts_at >= now()
     and (
       exists (select 1 from booking_items bi where bi.session_occurrence_id = so.id)
       or exists (select 1 from booking_holds bh where bh.session_occurrence_id = so.id and bh.status = 'active')
       or exists (select 1 from quote_items qi where qi.session_occurrence_id = so.id)
     );

  -- Delete empty future slots (no booking, no active hold, no quote line).
  delete from session_occurrences so
   using activity_options o
   where so.activity_option_id = o.id
     and o.activity_id = v_activity_id
     and so.starts_at >= now()
     and not exists (select 1 from booking_items bi where bi.session_occurrence_id = so.id)
     and not exists (select 1 from booking_holds bh where bh.session_occurrence_id = so.id and bh.status = 'active')
     and not exists (select 1 from quote_items qi where qi.session_occurrence_id = so.id);
end;
$$;
-- `from public, anon`, not `from public`. Supabase's stock ALTER DEFAULT PRIVILEGES grants EXECUTE on
-- every new function to anon and authenticated EXPLICITLY — not through PUBLIC — so a revoke naming
-- only PUBLIC leaves anon holding the grant, and CREATE OR REPLACE never resets an existing ACL. That
-- exact one-word omission has shipped a live leak from this repo twice (api_booking_receipt,
-- api_pending_payment_checkouts). is_staff() is this function's first statement so anon could not have
-- got anything out of it, but the ACL is stated correctly at the point of definition all the same.
revoke execute on function stop_availability_atomic(jsonb) from public, anon;
grant execute on function stop_availability_atomic(jsonb) to authenticated, service_role;

-- 6b) api_erase_user — a GDPR erasure has to reach the quotes tables too.
--
-- api_erase_user enumerates its tables by hand and could not know about a module that did not exist
-- when it was written, so customer_name / customer_email / customer_phone — and the free text in
-- internal_notes and quote_items.description, which routinely names the guest — would have survived
-- an Art. 17 request indefinitely, in two brand-new tables.
--
-- The split mirrors bookings exactly:
--   * a quote that never became a booking carries NO retention duty -> hard-deleted, children first;
--   * a CONVERTED quote is the paper behind a real payment -> retained and anonymized in place.
-- `converted_at` is what makes that split survive the hard-delete of an unpaid booking a few
-- statements earlier (which nulls booking_id) — see section 4.
--
-- Scope: quotes carry no user_id (created_by is the STAFF author, not the guest), so they are matched
-- by customer_email only, exactly like `leads`. A staff erase given a userId and no email therefore
-- does not reach them — the same limitation leads has always had, and the account-deletion path
-- always supplies both.
--
-- Re-applied in FULL from its winning definition (20260816000000) so this migration cannot revert the
-- caller-identity binding or the pickup/dropoff nulling that landed there.
create or replace function api_erase_user(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := nullif(p ->> 'userId', '')::uuid;
  v_email text := lower(nullif(btrim(p ->> 'email'), ''));
  -- Non-paid booking statuses that are safe to hard-delete (only ever combined with payment_state pending).
  v_del_states text[] := array['draft', 'held', 'payment_pending', 'expired', 'cancelled', 'failed'];
  -- Paid / terminal statuses that must be retained (financial records) and only anonymized.
  v_anon_states text[] := array['confirmed', 'completed', 'refund_pending', 'refunded'];
  v_del_ids uuid[];
  v_anon_ids uuid[];
  v_del_bookings int := 0;
  v_anon_bookings int := 0;
  v_del_leads int := 0;
  v_del_quotes int := 0;
  v_anon_quotes int := 0;
begin
  -- Guard: staff, or the signed-in user erasing their own account.
  if not (is_staff() or (auth.uid() is not null and v_uid is not null and auth.uid() = v_uid)) then
    raise exception 'forbidden';
  end if;

  -- Bind the email scope to the CALLER'S identity for a non-staff self-erase. The caller-supplied email
  -- is untrusted: a signed-in user could pass a stranger's address and, because the row scope matches on
  -- lower(customer_email) = v_email, sweep that stranger's GUEST bookings/leads (user_id null) -- broken
  -- access control. So for non-staff we IGNORE the supplied email and force v_email to the caller's own
  -- JWT identity, read from auth.users (the SECURITY DEFINER owner can see it; auth.email() is not
  -- relied on here). This still catches the user's own pre-account guest bookings (made under their own
  -- email before they had an account), while making a stranger's email unreachable. Staff keep the
  -- supplied email -- they legitimately erase a pure-guest record by its address.
  if not is_staff() then
    select lower(email) into v_email from auth.users where id = auth.uid();
  end if;

  if v_uid is null and v_email is null then
    raise exception 'invalid_request' using detail = 'erase_user: userId or email required';
  end if;

  -- ---- Hard-delete the non-retained (unpaid/abandoned) bookings + their children -------------------
  -- Identify them first; a booking matches by ownership OR guest email, must be in a deletable status
  -- AND have never carried money (payment_state pending). Anything paid is excluded here on purpose.
  select array_agg(id) into v_del_ids
    from bookings
   where ((v_uid is not null and user_id = v_uid)
          or (v_email is not null and lower(customer_email) = v_email))
     and status = any(v_del_states::booking_status[])
     and payment_state = 'pending';

  if v_del_ids is not null then
    -- FK order: holds (FK on delete set null, so delete explicitly) + items (cascades, but be explicit),
    -- then the parent bookings. payments cannot exist on a pending booking, so none to clear here.
    -- booking_custom_items cascades from bookings, so the quote's non-occurrence lines go with it.
    delete from booking_holds where booking_id = any(v_del_ids);
    delete from booking_items where booking_id = any(v_del_ids);
    delete from bookings where id = any(v_del_ids);
    get diagnostics v_del_bookings = row_count;
  end if;

  -- Snapshot the person's REMAINING booking ids now, before the anonymize below overwrites
  -- customer_email. The unpaid rows are already gone, so this is exactly the retained set; the
  -- outbox/bell/audit scrubs downstream target it by id so an email-only (guest) match is not lost.
  select coalesce(array_agg(id), '{}') into v_anon_ids
    from bookings
   where (v_uid is not null and user_id = v_uid)
      or (v_email is not null and lower(customer_email) = v_email);

  -- ---- Anonymize the retained (paid/terminal) bookings --------------------------------------------
  -- Keep the row + every financial column (total_minor, payouts, payment_state, status); strip the PII.
  -- customer_name + customer_email are NOT NULL in the schema, so they are redacted to placeholders
  -- (a routed-nowhere .invalid sentinel) rather than nulled. customer_phone + notes are nullable -> null.
  -- pickup_location / dropoff_location are addresses the customer typed -- PII, and not part of the
  -- retained money trail -- so they are nulled alongside the other traveller fields.
  -- This is an UPDATE that does NOT touch status, so the status-only enqueue trigger never re-fires.
  update bookings
     set customer_name = '(Deleted user)',
         customer_email = 'deleted@privacy.invalid',
         customer_phone = null,
         notes = null,
         pickup_location = null,
         dropoff_location = null,
         traveller_gender = null,
         traveller_company = null,
         traveller_country = null,
         special_notes = null,
         room_or_cabin = null,
         luggage_details = null,
         child_seat_age = null,
         flight_number = null,
         arrival_time = null,
         return_date = null,
         return_time = null,
         departure_flight_number = null
   where ((v_uid is not null and user_id = v_uid)
          or (v_email is not null and lower(customer_email) = v_email))
     and status = any(v_anon_states::booking_status[])
     -- idempotent: skip rows already anonymized (so a second call updates 0 rows, never re-counts).
     and customer_name is distinct from '(Deleted user)';
  get diagnostics v_anon_bookings = row_count;

  -- ---- Redact the notification outbox -------------------------------------------------------------
  -- Strip recipient (the email) + the customerName key from any queued/sent message for this person,
  -- matched by the recipient address OR by linkage to one of their (still-existing, anonymized) bookings.
  -- recipient is NOT NULL in the schema, so it is redacted to the sentinel rather than nulled. Removing
  -- customerName from the payload (jsonb - key) is a no-op when the key is already absent -> idempotent.
  update notification_outbox
     set recipient = 'deleted@privacy.invalid',
         payload = payload - 'customerName'
   where v_email is not null and lower(recipient) = v_email;
  -- Booking-linked rows keep their RECIPIENT -- they may address the OWNER (the 'owner' sentinel or
  -- the ops inbox), and severing that address would silently kill a pending owner alert for a real
  -- paid booking. Only the person's name leaves the payload. Matched by the pre-captured id set.
  update notification_outbox
     set payload = payload - 'customerName'
   where booking_id = any(v_anon_ids);
  -- Staff bell rows (admin_new_booking / admin_refund_pending) embed the customer's name in `body` --
  -- rebuild them anonymously so no feed retains PII after erasure.
  update notifications n
     set body = '(Deleted user) -- booking ' || coalesce(n.data ->> 'ref', '') || '.'
   where n.type in ('admin_new_booking', 'admin_refund_pending')
     and n.data ->> 'bookingId' = any(v_anon_ids::text[]);

  -- ---- Redact audit_logs diffs that captured this person's PII ------------------------------------
  -- Older admin actions may have snapshotted customer fields into diff. Null the diff on rows whose
  -- entity is one of their bookings (the anonymized financial rows). Counts only; we keep the action row.
  update audit_logs
     set diff = null
   where diff is not null
     and entity_type = 'booking'
     and entity_id = any(v_anon_ids);

  -- ---- Hard-delete the remaining personal data ----------------------------------------------------
  -- leads: PII lives in (name, contact); contact holds the email/phone. Delete by email match.
  if v_email is not null then
    delete from leads where lower(contact) = v_email;
    get diagnostics v_del_leads = row_count;
  end if;

  -- ---- Quotes: the offer the owner drafted for this person ----------------------------------------
  -- A quote that never minted a booking is not a financial record -> delete it and its lines outright
  -- (children first; quote_items cascades, but be explicit, exactly as the bookings block above is).
  -- A CONVERTED quote is retained and stripped instead. Keyed on converted_at, NOT booking_id: the
  -- bookings delete a few statements up nulls booking_id via its `on delete set null` FK.
  if v_email is not null then
    delete from quote_items qi
     using quotes q
     where qi.quote_id = q.id
       and lower(q.customer_email) = v_email
       and q.converted_at is null
       and q.booking_id is null;

    delete from quotes q
     where lower(q.customer_email) = v_email
       and q.converted_at is null
       and q.booking_id is null;
    get diagnostics v_del_quotes = row_count;

    -- Retained (converted) quotes: same redaction as the bookings they minted. internal_notes (staff
    -- free text) and intro_note (the guest-FACING covering note, which opens by addressing the guest
    -- by name) both routinely carry the guest, so they go too. Idempotent via the same
    -- already-anonymized skip.
    update quotes
       set customer_name = '(Deleted user)',
           customer_email = 'deleted@privacy.invalid',
           customer_phone = null,
           intro_note = null,
           internal_notes = null
     where lower(customer_email) = v_email
       and (converted_at is not null or booking_id is not null)
       and customer_name is distinct from '(Deleted user)';
    get diagnostics v_anon_quotes = row_count;
  end if;

  -- chat: messages cascade from sessions, but delete explicitly for clarity. By user only (no email link).
  if v_uid is not null then
    delete from chat_messages where session_id in (select id from chat_sessions where user_id = v_uid);
    delete from chat_sessions where user_id = v_uid;
    -- profile last (auth.users row itself is removed by the caller's service-role admin.deleteUser).
    delete from profiles where id = v_uid;
  end if;

  -- ---- One audit row, counts only (NO PII) -------------------------------------------------------
  insert into audit_logs (actor_id, actor_role, action, entity_type, entity_id, summary)
  values (
    auth.uid(),
    case when is_staff() then 'staff' else 'user' end,
    'erase_user',
    'user',
    v_uid,
    'gdpr erasure: deleted ' || v_del_bookings || ' booking(s), ' || v_del_leads
      || ' lead(s), ' || v_del_quotes || ' quote(s); anonymized ' || v_anon_bookings
      || ' retained booking(s), ' || v_anon_quotes || ' retained quote(s)'
  );

  return jsonb_build_object(
    'ok', true,
    'deletedBookings', v_del_bookings,
    'anonymizedBookings', v_anon_bookings,
    'deletedLeads', v_del_leads,
    'deletedQuotes', v_del_quotes,
    'anonymizedQuotes', v_anon_quotes
  );
end;
$$;
-- Stated here rather than inherited: CREATE OR REPLACE keeps whatever ACL the ORIGINAL definition was
-- given, so re-applying a function is the moment to say what its grants are. Same `public, anon` as
-- above — a self-erase is called by the signed-in user, so `authenticated` keeps EXECUTE.
revoke execute on function api_erase_user(jsonb) from public, anon;
grant execute on function api_erase_user(jsonb) to authenticated, service_role;

-- 6c) A retained quote's FREE TEXT — its lines, and its own covering note — is redacted with it.
--
-- The anonymize branch above scrubs customer_name / _email / _phone / intro_note / internal_notes, but
-- the guest's name is just as routinely typed into a line: "Skipper for the Ramdin family, full day".
-- A DELETED quote loses that text with the row; a CONVERTED one is retained forever, which is exactly
-- the case an Art. 17 request is about. The money shape of the line (quantity, unit_amount_minor,
-- subtotal_minor, dates) is the retention duty and is never touched — the same split the bookings half
-- makes when it nulls `notes` and keeps `total_minor`.
--
-- Why a TRIGGER on the parent rather than one more statement inside api_erase_user: the delete half of
-- this relationship is declarative (`on delete cascade`) and no caller can forget it. The anonymize
-- half has no declarative form, so it lives in ONE place attached to the parent row instead of being
-- restated by every path that redacts a quote — including a future migration that re-applies
-- api_erase_user from an older body, which is the migration-revert drift documented in
-- docs/handbook/landmines.md and has already cost this repo a guard once. It cost it a second one
-- here: 20260910000000_late_pickup_addon.sql landed after this file carrying a copy of api_erase_user
-- that predated the intro_note line, and — the last definition wins — that copy was the live one.
-- THAT IS FIXED AT SOURCE: 20260910000000's UPDATE now nulls intro_note itself. This trigger stays
-- anyway, as the belt to those braces and because it is the only thing that reaches the LINE text.
--
-- `'deleted@privacy.invalid'` is the schema's erasure marker, already load-bearing above (it is what
-- makes the anonymize idempotent). SECURITY DEFINER so the redaction cannot be half-applied by a
-- caller whose RLS reaches the quote but not every one of its lines.
create or replace function quotes_redact_lines()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- `description` is nullable ONLY on a catalogue line; quote_item_shape requires a custom/rental line
  -- to carry one, so those are redacted to a sentinel instead of nulled. The filter makes a re-run a
  -- no-op (0 rows), matching the idempotency of the update that fires it.
  update quote_items
     set description = case when kind = 'catalogue' then null else '(Redacted)' end
   where quote_id = new.id
     and coalesce(description, '') not in ('', '(Redacted)');

  -- …and the parent's own guest-facing free text. `intro_note` is the covering note a staff member
  -- types above the priced lines ("Dear …, here is the private boat day we discussed"), so it names
  -- the guest as reliably as the lines do. api_erase_user's anonymize UPDATE nulls it as well, but
  -- THAT statement is precisely the one a later migration re-applies from an older body — the drift
  -- this trigger was created to be immune to, and which did happen here (20260910000000 landed after
  -- this file with a copy of api_erase_user predating the intro_note line, and won). Its UPDATE has
  -- since been corrected, so this is now belt AND braces rather than the only scrub standing; the
  -- durable place for it is still beside the lines, on the parent. Filtered, so a re-run is 0 rows.
  --
  -- No recursion: the trigger is `after update OF customer_email`, and this statement's target list
  -- is intro_note alone, so it cannot re-fire (and the WHEN clause would reject it regardless).
  update quotes
     set intro_note = null
   where id = new.id
     and intro_note is not null;
  return null;
end;
$$;
-- `authenticated` is named too, and it is the word this repo has now dropped THREE times
-- (api_booking_receipt, api_pending_payment_checkouts, and here): Supabase's default privileges grant
-- EXECUTE to anon AND authenticated explicitly at creation, so `from public, anon` leaves every
-- signed-in account able to POST /rpc/quotes_redact_lines and blank the line text of any quote it can
-- name. It costs the trigger nothing — 20260814000000 established that trigger execution never checks
-- the caller's EXECUTE — so the only caller left is the one that should have it.
revoke execute on function quotes_redact_lines() from public, anon, authenticated;
grant execute on function quotes_redact_lines() to service_role;

drop trigger if exists quotes_redact_lines_on_anonymize on quotes;
create trigger quotes_redact_lines_on_anonymize
  after update of customer_email on quotes
  for each row
  when (new.customer_email = 'deleted@privacy.invalid'
        and old.customer_email is distinct from new.customer_email)
  execute function quotes_redact_lines();

-- ---------------------------------------------------------------------------
-- 6c-bis) quote_email_key — THE ONE DEFINITION OF "THE SAME ADDRESS".
--
-- Two places decide whether an address on a quote is the address on an account: quote_owner_for_email
-- (6d), at conversion, and api_claim_quote_bookings (7c), for the guest who signs up afterwards. They
-- have to normalise IDENTICALLY or the pair produces a booking that matches at payment and can never
-- be claimed again.
--
-- That is not hypothetical. `quotes.customer_email` has no trimming trigger and api_convert_quote
-- copies the column into `bookings.customer_email` verbatim, so an address the operator pasted out of
-- a mail client — ' nina@example.com' — really is what gets stored. The owner match btrimmed its
-- ARGUMENT while the claim compared the booking column with `lower()` alone: the guest paid, their
-- booking was minted, and their later sign-in could never pick it up. Nothing on any screen shows the
-- space, which is exactly what makes that class of bug unreproducible six months later.
--
-- So the rule lives in one function and both sides call it on BOTH operands. Plain (not definer) and
-- left with its default grants, like is_staff(): it reads nothing, touches no table, and hands back a
-- lowercased trim of a string the caller already had — there is nothing here to leak. Its callers are
-- the definers, and the privilege check for their inner calls runs as the owner regardless.
--
-- NULL for an address that is empty or all whitespace, so "no address" can never compare equal to
-- another "no address" — a null propagates through `=` and the match simply fails, which is the
-- answer both callers want.
-- ---------------------------------------------------------------------------
create or replace function quote_email_key(p_email text)
returns text
language sql
immutable
as $$
  select lower(nullif(btrim(p_email), ''));
$$;

comment on function quote_email_key(text) is
  'The one normalisation behind every quote email match: lower(btrim(...)), null for blank. '
  'quote_owner_for_email and api_claim_quote_bookings both apply it to BOTH sides of their compare, '
  'so an address that matched at conversion can never be one a later claim cannot see.';

-- ---------------------------------------------------------------------------
-- 6d) quote_owner_for_email — WHO, IF ANYONE, OWNS A BOOKING MADE FOR THIS ADDRESS.
--
-- Every booking in this schema until now has carried a `user_id`; a quote booking is the first
-- ownerless one, because the guest has no account — that is the entire point of an emailed offer. The
-- bookings policy is `using (user_id = auth.uid() or is_staff())`, and `null = auth.uid()` evaluates to
-- NULL rather than true, so a PAID quote booking with a null user_id is invisible to every customer
-- forever, including the guest who paid for it. /bookings/{ref} — the page the confirmation email's
-- e-voucher button points at — is guarded by that policy.
--
-- The owner's decision is to match by EMAIL: at conversion (below) and, for a guest who signs up
-- afterwards, again at claim time (7c). Both go through this one function so the rule cannot be stated
-- twice and drift, and the rule is deliberately NARROW:
--
--   * CASE-INSENSITIVE AND TRIMMED, through quote_email_key (6c-bis) — on BOTH operands, never just
--     the argument. The operator types or pastes the address into the quote editor by hand, and
--     "Anouk.Leclerc@Example.com" (or " anouk.leclerc@example.com") is the same mailbox as the one
--     the account was opened with. A case-sensitive compare would leave most genuine matches
--     ownerless for no visible reason; normalising one side only would leave the claim path (7c)
--     unable to see a booking this function had already matched.
--   * CONFIRMED ACCOUNTS ONLY (`email_confirmed_at is not null`). This is the whole of the difference
--     between an address someone TYPED and one they have demonstrably received mail at. Without it,
--     signing up with a stranger's address — and never confirming it, which you could not, since the
--     mail goes to them — would be a way to be handed their booking, with its name, phone, pickup
--     address and amount.
--   * EXACTLY ONE MATCH, or none. `auth.users` does not constrain `email` to be unique, and picking
--     "the oldest" of two confirmed accounts on one address would be a coin toss on a money record.
--     Ownerless is already a fully supported state, so ambiguity fails closed into it.
--
-- KNOWN AND ACCEPTED BY THE OWNER: a mistyped address that belongs to a real confirmed account
-- attaches that booking to the wrong person. The same typo already emailed them the offer itself, so
-- the first disclosure happens either way — which is precisely why this must never widen beyond a
-- confirmed, exact (case-insensitive) address.
--
-- SECURITY DEFINER because `auth.users` is not readable by the roles that reach the callers, and
-- service_role-only because it answers "does an account exist at this address?" — an enumeration
-- oracle if anything reachable from a browser could ask it. api_claim_quote_bookings is granted to
-- `authenticated` and calls this; that works because the privilege check for the inner call runs as the
-- (shared) owner of both functions, the same arrangement api_create_payment/create_payment uses.
-- ---------------------------------------------------------------------------
create or replace function quote_owner_for_email(p_email text)
returns uuid
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_email text := quote_email_key(p_email);
  v_ids uuid[];
begin
  if v_email is null then
    return null;
  end if;

  select array_agg(u.id) into v_ids
    from auth.users u
   where quote_email_key(u.email) = v_email
     and u.email_confirmed_at is not null;

  -- No account, or more than one confirmed account on this address: no answer, not a guess.
  if v_ids is null or array_length(v_ids, 1) <> 1 then
    return null;
  end if;
  return v_ids[1];
end;
$$;
revoke execute on function quote_owner_for_email(text) from public, anon, authenticated;
grant execute on function quote_owner_for_email(text) to service_role;

comment on function quote_owner_for_email(text) is
  'The single CONFIRMED account holding this address, normalised by quote_email_key on both sides — or '
  'null for none, and null '
  'for more than one. The one place the quote-booking owner match is defined; api_convert_quote and '
  'api_claim_quote_bookings both read it so the rule cannot drift into two versions.';

-- ---------------------------------------------------------------------------
-- 7) api_convert_quote — the one step that mints a PAYABLE booking.
--
-- Everything downstream of it is the existing, untouched money path (Peach checkout → HMAC webhook →
-- append_payment_event → confirmation + VAT invoice), so this function is the whole of the new code
-- standing between a staff-drafted offer and a real charge. The rules baked in:
--
--   * "converts once" means ONE PAYABLE BOOKING AT A TIME, not one attempt ever — see the
--     re-arm note below.
--   * `for update` on the quote row, so two guests clicking Pay at the same instant serialise here
--     rather than both reading an unconverted quote and both minting a booking.
--   * a catalogue line TAKES ITS SEAT here, through create_hold and booking_items, in this same
--     transaction — see the hold path below. Capacity that is reserved a round trip later is not
--     reserved: it is a payable booking with nothing behind it.
--   * every refusal raises a repo error TOKEN, never a human sentence. src/lib/services/db-errors.ts
--     matches snake_case tokens on word boundaries; anything else falls through to
--     `console.error('[db] unmapped database error')` + ProviderError, i.e. HTTP 500 "Database
--     error". On the money path that reads as a broken site and invites the retry loop the
--     convert-once guard exists to end, and it floods error_logs with unmapped noise. Each token
--     below has a branch in mapDbError; add them together or the guard is invisible to the guest.
--
-- WHY THE GUARD READS `converted_at`, NEVER `booking_id`: that is the contract stated in section 4.
-- api_erase_user hard-deletes unpaid bookings and the `on delete set null` FK then silently clears
-- booking_id, so a guard on `booking_id is null` would see an erased quote as unconverted and mint a
-- second payable booking. Both columns are written together; quote_converted_shape makes forgetting
-- one impossible, and the UNIQUE on booking_id is the second line of defence.
--
-- WHY CONVERSION IS NOT A ONE-WAY DOOR: the minted booking is `payment_pending`, and
-- run_booking_maintenance expires such a booking 30 minutes after it was created. A guest who
-- converts and then leaves to fetch their card would come back to a booking api_create_payment
-- refuses ('booking_not_payable' on 'expired') attached to a quote this function refused to convert
-- again — payable by nobody, recoverable only by hand-editing production. That is precisely the
-- "cancelled-checkout trap" this repo already fixed once (2026-07-25). So when `converted_at` is
-- set, the linked booking is inspected inside the same `for update`: if it is DEAD, never took a
-- cent, and can no longer take one (expired/cancelled/failed, booking-level payment_state pending or
-- failed, no payments row that settled, refunded, part-settled or is under settlement review, and no
-- Peach session still completable or being minted) the quote re-arms and mints afresh, leaving the
-- dead booking behind as the audit trail. Everything else keeps refusing — including, and
-- deliberately, the case where the linked booking is GONE (booking_id null after an erasure), which
-- is the section-4 invariant and must never be softened into "no booking, so mint one". The money is
-- read under the payments row locks, in append_payment_event's own lock order, so a settlement in
-- flight serialises here rather than being read stale.
--
-- `ref` is deliberately NOT supplied. The column default has been the Peach-safe generator since
-- 20260736000000 ('BMT' + 13 hex, 16 alnum chars, no separator) — and that default has already been
-- changed once, precisely to satisfy Peach's merchantTransactionId limit. Re-deriving the format
-- here would be a second copy that a third change would silently leave behind, on the money path.
--
-- `operator_payout_minor` is set alongside `total_minor` because payout == total is the invariant
-- every other booking-minting path in the repo maintains (the bookings table header states it;
-- 20260805000000 inserts `v_total, v_total, 0`). It is not self-healing either:
-- enforce_booking_admin_update (20260615121600) pins the column for any anon/authenticated write, so
-- a quote booking minted with the 0 default is permanently wrong in the payout report.
--
-- It returns `booking_json(id)` — the camelCase DTO every other booking-returning RPC returns and
-- the shape the service layer and the booking Zod schema parse. `to_jsonb(v_booking)` would return
-- the raw 46-column row AND silently widen this function's output contract every time a column is
-- added to `bookings`, which for a service_role-only function on the money path is a contract that
-- changes with nobody editing it.
--
-- No in-function caller guard by design: like every other server-only api_* function here, the
-- EXECUTE grant IS the authorization, which is why the revoke below names anon and authenticated
-- explicitly and not just PUBLIC (see the note in 6a — that one-word omission has shipped a live
-- leak from this repo twice).
-- ---------------------------------------------------------------------------
create or replace function api_convert_quote(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_quote quotes;
  v_prior bookings;
  v_booking bookings;
  v_reusable boolean := false;
  v_lines_minor bigint;
  v_owner uuid;
  v_seats record;
  v_hold booking_holds;
begin
  select * into v_quote
    from quotes
   where id = nullif(p ->> 'quoteId', '')::uuid
   for update;

  if v_quote.id is null then
    raise exception 'quote_not_found';
  end if;

  -- Convert-once, read off converted_at, and meaning "one PAYABLE booking at a time" (see above).
  if v_quote.converted_at is not null then
    -- LOCK THE MONEY BEFORE JUDGING IT. append_payment_event locks the payments row, writes paid_minor
    -- and status onto it, and only THEN rolls the projection onto bookings — so an unlocked read of
    -- either table can catch a settlement mid-flight, conclude "this booking never took a cent", mint
    -- booking B, commit, and let the settlement land on A afterwards. Taking the payments locks in the
    -- same order that function does serialises the two instead of racing them.
    --
    -- `bookings` is deliberately NOT locked here as well: api_create_payment locks bookings and then
    -- payments, so adding payments -> bookings on this side would close a deadlock cycle on the money
    -- path. It is also unnecessary — read committed gives every later statement in this function a
    -- fresh snapshot, so once the payments locks are held the reads below see post-settlement state.
    -- A booking with no payments row locks nothing, which is safe: api_create_payment refuses a dead
    -- booking ('booking_not_payable'), so no first payment can appear on one.
    perform 1 from payments where booking_id = v_quote.booking_id for update;

    -- booking_id is null here when an erasure hard-deleted the booking; the select finds nothing and
    -- v_reusable stays false, which is the section-4 invariant.
    select * into v_prior from bookings where id = v_quote.booking_id;
    v_reusable := found
      and v_prior.status in ('expired', 'cancelled', 'failed')
      and v_prior.payment_state in ('pending', 'failed')
      -- Money already HELD, including the shapes the booking-level projection above cannot see: an
      -- underpayment (append_payment_event sets 'pending' when v_paid > 0 but below amount_minor, so
      -- paid_minor is positive while payment_state is not) and a wrong-currency settlement quarantine
      -- (settlement_review_at, 20260830000000), which is stamped precisely so the projection is left
      -- alone. Both hold a capture on a booking that still reads clean.
      and not exists (
        select 1 from payments pay
         where pay.booking_id = v_prior.id
           and (pay.paid_minor > 0
                or pay.refunded_minor > 0
                or pay.status in ('paid', 'partially_refunded', 'refunded')
                or pay.settlement_review_at is not null)
      )
      -- Money that can still be TAKEN. A dead booking is not a dead checkout: run_booking_maintenance
      -- expires a booking 30 minutes after it was CREATED, while a Peach session stays completable
      -- ~30 minutes after it was MINTED (api_pending_payment_checkouts says exactly that in its own
      -- comment). A guest who converts at T0, clicks Pay at T0+26 and wanders off has an expired
      -- booking at T0+30 and a live session until roughly T0+56; re-arming in that gap leaves TWO
      -- payable sessions for one quote — the double charge api_create_payment's reuse guard refuses
      -- to create one level down ("Minting a replacement while the original is still live would leave
      -- TWO payable sessions for one booking") and the one 20260902000000 removed. It is also
      -- unreconcilable: api_pending_payment_checkouts only re-queries bookings still in
      -- 'payment_pending', so once the booking is expired a lost webhook on that capture is never
      -- swept — money taken, no ledger row, no link back to the quote.
      --
      -- 30 minutes, not api_create_payment's 25: 25 is the REUSE window, deliberately short of the
      -- session's life so a session handed back cannot die under the guest. The hazard here lasts as
      -- long as the session can be COMPLETED, so this window has to be the wider of the two.
      --
      -- The claimed-lease arm covers the ~90 seconds where a caller is out at Peach and the session
      -- id has not been recorded yet: provider_checkout_id is still null, so freshness alone sees
      -- nothing and would re-arm into the same double charge moments before the session appears.
      --
      -- The refusal is a wait, not a wall: mapDbError already reads quote_already_converted as "has
      -- already been paid for or is being paid", and the quote converts again once the session dies.
      and not exists (
        select 1 from payments pay
         where pay.booking_id = v_prior.id
           and ((pay.provider_checkout_id is not null
                 and coalesce(pay.checkout_created_at, pay.updated_at) > now() - interval '30 minutes')
                or (pay.checkout_claimed_until is not null and pay.checkout_claimed_until > now()))
      );
    if not v_reusable then
      raise exception 'quote_already_converted'
        using detail = coalesce(v_prior.status::text, 'linked booking no longer exists');
    end if;

    -- THE DEAD BOOKING'S SEATS GO BACK BEFORE THIS CONVERSION TAKES FRESH ONES.
    --
    -- Re-arming mints a SECOND booking, which takes its own holds below — so unless the first
    -- booking's holds are released here, one quote reserves two sets of seats for the rest of their
    -- 30-minute life. Nothing else does it: run_booking_maintenance releases holds only for the
    -- bookings IT expired, so a hand-cancelled booking (or one already swept while its hold ran on)
    -- keeps them. On a nearly-full departure that is the guest's own abandoned attempt selling the
    -- trip out from under them — create_hold would raise `insufficient_capacity` and the quote would
    -- read as sold out to the only person entitled to those seats.
    --
    -- Safe because of what the branch above has already established: this booking is dead
    -- (expired/cancelled/failed), never took a cent, and cannot take one.
    update booking_holds set status = 'released'
     where booking_id = v_prior.id and status = 'active';
  end if;

  -- Status: an explicit WHITELIST, the shape api_create_payment uses next door. A blacklist of one
  -- let a 'draft' (a half-built offer the owner has not sent, whose total may be mid-edit) and an
  -- 'expired' quote — a terminal state of the very enum this migration created — both convert.
  -- 'accepted' is in the list because that is what a converted quote's status already is, and the
  -- re-arm branch above has to be able to get past here.
  if v_quote.status = 'cancelled' then
    raise exception 'quote_cancelled';
  end if;
  if v_quote.status = 'expired' or v_quote.valid_until < current_date then
    raise exception 'quote_expired';
  end if;
  if v_quote.status not in ('sent', 'accepted') then
    raise exception 'quote_not_convertible' using detail = v_quote.status::text;
  end if;

  -- A zero-total quote mints a booking that can NEVER confirm: api_create_payment skips the FX pin
  -- for a zero amount, and append_payment_event carries an explicit guard whose own comment says "a
  -- zero-amount payment must never read as fully paid (0 >= 0)". The booking would sit in
  -- payment_pending until the sweep expired it. quotes.total_minor DEFAULTS to 0, so an empty or
  -- never-priced draft reaches this state by default rather than by accident.
  if coalesce(v_quote.total_minor, 0) <= 0 then
    raise exception 'quote_not_convertible' using detail = 'zero total';
  end if;

  -- THE TWO CATALOGUE LINES THIS FUNCTION WILL NOT PRICE INTO A SEAT. Both fail closed here, before
  -- anything is minted, because both are shapes whose capacity meaning cannot be read off the line.
  --
  -- 1. AN OPTION THAT IS NOT COUNTED IN PEOPLE. For a private or vehicle option one BOOKING is one
  --    unit of the pool — the pool counts trips, not heads (20260908000000), and create_booking
  --    records the real party size in booking_items.pax while writing quantity 1. A quote line for
  --    six guests would therefore reserve SIX DEPARTURES if it were held like a per-person line, and
  --    reserve one while charging for six if it were not. Neither is a guess worth making on the
  --    money path: there is no editor that can draft such a line yet, and the pay route's re-price
  --    gate refuses it one step earlier anyway (a private option has no activity_option_prices row
  --    to re-price against). The day the editor learns to quote a private charter, this is the
  --    branch that teaches the conversion the trips-vs-heads mapping — deliberately, with a test.
  --
  -- 2. AN OPTION THAT IS NOT THE OCCURRENCE'S OWN. `quote_item_shape` makes a catalogue line name
  --    both, and nothing checks they agree; a mismatch would write a booking_items row whose option
  --    contradicts its occurrence, i.e. a voucher and a day sheet naming a trip the guest is not on.
  --
  -- Both reuse `quote_not_convertible` rather than minting a token of their own: mapDbError already
  -- reads it as "This quote is not ready to pay yet — please message us", which is exactly true, and
  -- an unfinished offer is the operator's to fix.
  if exists (
    select 1
      from quote_items qi
      join activity_options o on o.id = qi.activity_option_id
      join activities a on a.id = o.activity_id
     where qi.quote_id = v_quote.id
       and qi.kind = 'catalogue'
       and (o.private_base_minor is not null
            or coalesce(a.pricing_mode::text, 'per_person') in ('vehicle', 'vehicle_custom'))
  ) then
    raise exception 'quote_not_convertible' using detail = 'private/vehicle catalogue line';
  end if;
  if exists (
    select 1
      from quote_items qi
      join session_occurrences so on so.id = qi.session_occurrence_id
     where qi.quote_id = v_quote.id
       and qi.kind = 'catalogue'
       and qi.activity_option_id is distinct from so.activity_option_id
  ) then
    raise exception 'quote_not_convertible' using detail = 'catalogue line option is not its occurrence''s';
  end if;

  -- THE CHARGE AND THE ITEMISATION MUST AGREE, or nothing is minted.
  --
  -- The amount charged is copied from quotes.total_minor while the lines are copied by the separate
  -- statement below, and nothing else ties the two together: total_minor carries no CHECK against its
  -- lines and no trigger recomputing it, and the editor writes the total in a different statement from
  -- the lines. src/lib/quotes/totals.ts states in its own header that there is no Zod layer above it
  -- yet and that its guards "ARE the only validation between a browser-supplied line and
  -- quotes.total_minor" — so this function is the last gate before a card is charged, and failing OPEN
  -- on the drift charges the guest a figure the itemisation does not support and renders a VAT
  -- invoice whose lines do not sum to the charge.
  --
  -- The sum is over ALL lines, of every kind: the custom ones are copied into booking_custom_items
  -- below and the catalogue ones take the hold path into booking_items, so every line reaches the
  -- booking and every line was priced into the total the guest agreed to.
  --
  -- It subsumes the zero-lines case too — a hand-set total with no itemisation at all would otherwise
  -- mint a booking with no lines and a booking_json carrying no items: charged for something with no
  -- record of what it was.
  select coalesce(sum(qi.subtotal_minor), 0) into v_lines_minor
    from quote_items qi
   where qi.quote_id = v_quote.id;
  if v_quote.total_minor <> v_lines_minor then
    raise exception 'quote_total_mismatch'
      using detail = format('total %s vs lines %s', v_quote.total_minor, v_lines_minor);
  end if;

  -- WHO WILL BE ABLE TO SEE THIS BOOKING. `user_id` is what the bookings RLS policy reads
  -- (`user_id = auth.uid() or is_staff()`), so a booking minted with a null one is invisible to every
  -- customer — including the guest about to pay for it, whose confirmation email links to
  -- /bookings/{ref}. quote_owner_for_email (section 6d) answers with the single CONFIRMED account
  -- holding the quoted address, or null; see its header for why that rule is exactly this narrow.
  --
  -- NULL IS A SUPPORTED ANSWER, NOT A FAILURE. Most quote guests never open an account, and nothing
  -- downstream requires an owner: api_create_quote_payment (20260911000000) exists precisely because a
  -- quote booking has none, the guest's own record stays reachable through the link token, and
  -- api_claim_quote_bookings (7c) fills the column in later if they ever do sign up.
  v_owner := quote_owner_for_email(v_quote.customer_email);

  insert into bookings (
    user_id, customer_name, customer_email, customer_phone, status, source,
    currency, total_minor, operator_payout_minor, payment_state, locale
  )
  values (
    v_owner, v_quote.customer_name, v_quote.customer_email, v_quote.customer_phone, 'payment_pending',
    'quote', v_quote.currency, v_quote.total_minor, v_quote.total_minor, 'pending', v_quote.locale
  )
  returning * into v_booking;

  -- The `kind <> 'catalogue'` filter is what keeps this statement and the hold path below from both
  -- claiming the same line: booking_custom_items carries `check (kind <> 'catalogue')`, and a
  -- catalogue line belongs in booking_items, where it can be counted against a departure.
  insert into booking_custom_items (
    booking_id, position, kind, description, starts_at, ends_at,
    rental_vehicle_slug, quantity, unit_amount_minor, subtotal_minor
  )
  select v_booking.id, qi.position, qi.kind, qi.description, qi.starts_at, qi.ends_at,
         qi.rental_vehicle_slug, qi.quantity, qi.unit_amount_minor, qi.subtotal_minor
    from quote_items qi
   where qi.quote_id = v_quote.id
     and qi.kind <> 'catalogue';

  -- ── THE CATALOGUE LINES TAKE THEIR SEATS, HERE, IN THIS TRANSACTION ─────────────────────────
  --
  -- A catalogue line names a session_occurrence, so unlike a custom line it is a place on a real
  -- departure. It is only actually reserved if it is reserved the way every other booking reserves
  -- one: create_hold — the universal gate, which api_create_hold and api_book both delegate their
  -- hold INSERT to — takes `select … for update` on the occurrence, re-reads used_capacity() under
  -- that lock and refuses an oversell; and the booking_items row is what used_capacity() counts once
  -- the booking confirms, what append_payment_event's oversell re-check reads before it confirms
  -- anything, and what puts the guest on the day sheet. Re-deriving either here would be a second,
  -- quieter definition of "a seat exists" on the money path.
  --
  -- WHY IT IS IN THIS FUNCTION AND NOT IN THE PAY ROUTE (which is where the plan first put it): a
  -- route does it in a SECOND transaction, so a hold that fails leaves a converted quote and a
  -- payable booking with no seat behind it — the guest pays for a place nobody reserved, which is
  -- the precise state the placeholder guard this replaces existed to prevent, now reached by a
  -- different road. In here, a refusal takes the booking, its custom lines and `converted_at` back
  -- with it, and the guest sees a refusal instead of a charge.
  --
  -- UNITS, NOT PEOPLE. used_capacity() sums booking_holds.quantity and booking_items.quantity, and
  -- append_payment_event re-checks this booking's own booking_items sum against the occurrence's
  -- capacity — so the hold's quantity must equal the quantities of the lines it covers, or the seat
  -- count drifts the moment the payment lands. Lines that share an occurrence are aggregated into
  -- ONE hold for exactly that reason (two 'Adult' and 'Child' lines on one boat are three seats on
  -- one trip, not two reservations).
  --
  -- The idempotency key is scoped to THIS booking, so a re-arm (a fresh booking for the same quote)
  -- takes fresh holds rather than being handed create_hold's idempotent replay of a released one.
  --
  -- WHAT IS DELIBERATELY *NOT* RE-USED FROM THE CHECKOUT: create_booking's per-booking guests-per-trip
  -- cap (20260908000000). That cap exists because a self-serve guest cannot know the day's pool is
  -- several departures — "the boat only seats so many, however big the day's pool is" — and it is
  -- enforced per BOOKING, so one quote line could never express "twenty guests, two boats" with it in
  -- the way. The operator drafting this quote chose the departure and the party size, and the POOL is
  -- still enforced by create_hold, so no other guest can be oversold; what a big party costs is two
  -- boats' worth of units out of the day, which is what it consumes. Revisit this the day quotes are
  -- drafted by anyone but staff.
  for v_seats in
    select qi.session_occurrence_id as occurrence_id, sum(qi.quantity)::int as units
      from quote_items qi
     where qi.quote_id = v_quote.id and qi.kind = 'catalogue'
     group by qi.session_occurrence_id
  loop
    begin
      v_hold := create_hold(
        v_seats.occurrence_id, v_seats.units,
        'quote:' || v_booking.id::text || ':' || v_seats.occurrence_id::text
      );
    exception when raise_exception then
      -- create_hold refuses in the CHECKOUT's vocabulary — insufficient_capacity,
      -- occurrence_not_bookable, occurrence_in_past, occurrence_too_soon — and mapDbError turns those
      -- into "Not enough availability for this selection" or the bare "Invalid booking request",
      -- neither of which tells a quote guest anything they can act on: they cannot pick another date,
      -- because the date was arranged for them. One token for all of them, carrying the real reason in
      -- DETAIL for error_logs, and mapped to a sold-out 409 that says to message us.
      raise exception 'quote_seats_unavailable'
        using detail = format('occurrence %s x%s: %s', v_seats.occurrence_id, v_seats.units, sqlerrm);
    end;

    -- ATTACH THE HOLD TO THE BOOKING. Not tidiness: append_payment_event's oversell re-check counts
    -- every active hold that is NOT this booking's own against it, so a detached hold is the guest's
    -- own reservation blocking their own confirmation and routing a good payment to refund_pending.
    -- It is also what makes the confirmation mark it 'consumed' rather than leaving it to lapse.
    update booking_holds set booking_id = v_booking.id where id = v_hold.id;
  end loop;

  -- One row per LINE (the hold above is one row per occurrence): the tiers are what the voucher, the
  -- day sheet and the VAT invoice itemise. Prices are the quote's own — the negotiated figure the
  -- guest saw and `quote_total_mismatch` has just re-checked — never re-derived from the catalogue
  -- here; the pay route compares them against the live price list and refuses on drift before this
  -- function is ever called. `price_label` is NOT NULL on booking_items, so a line that carries no
  -- tier name falls back to its description rather than failing at the constraint.
  insert into booking_items (
    booking_id, session_occurrence_id, activity_option_id, price_label,
    quantity, unit_amount_minor, subtotal_minor
  )
  select v_booking.id, qi.session_occurrence_id, qi.activity_option_id,
         coalesce(nullif(btrim(qi.price_label), ''), nullif(btrim(qi.description), ''), 'Quoted place'),
         qi.quantity, qi.unit_amount_minor, qi.subtotal_minor
    from quote_items qi
   where qi.quote_id = v_quote.id
     and qi.kind = 'catalogue'
   order by qi.position;

  -- Overwrites booking_id on a re-arm, which releases the dead booking from the UNIQUE.
  update quotes
     set booking_id = v_booking.id,
         converted_at = now(),
         status = 'accepted',
         updated_at = now()
   where id = v_quote.id;

  return booking_json(v_booking.id);
end;
$$;
revoke execute on function api_convert_quote(jsonb) from public, anon, authenticated;
grant execute on function api_convert_quote(jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- 7c) api_claim_quote_bookings — the guest who signs up AFTER paying.
--
-- The other half of section 6d. At conversion there may simply be no account yet: the guest reads an
-- emailed offer and pays it, and only weeks later — booking their next trip — do they register. Their
-- paid booking is sitting there with a null `user_id`, which the bookings policy can never match, so
-- "My trips" would be empty and /bookings/{ref} would 404 the person who paid. This is what fills the
-- column in, and the app calls it once per sign-in (AuthProvider, right after the profile row is
-- ensured).
--
-- FOUR PROPERTIES, and each one is a hole if it is dropped:
--
--   1. THE CLAIMER'S OWN ADDRESS, read from `auth.users` by `auth.uid()` — never anything in `p`. The
--      function takes a jsonb argument only because every api_* RPC in this schema does; nothing in it
--      is read. A caller-supplied address is untrusted input, and matching on one would let any
--      signed-in account name a stranger's address and be handed that stranger's booking.
--      api_erase_user closed the identical hole by forcing its email scope to the caller's own JWT
--      identity.
--   2. CONFIRMED ONLY, and via the SAME function conversion uses. Rather than restating
--      `email_confirmed_at is not null` here — a second copy of the rule, free to drift from the first
--      — the claimer's own address is put through quote_owner_for_email and the answer must come back
--      as the caller themselves. An unconfirmed account resolves to null and matches nobody; an address
--      shared by two confirmed accounts resolves to null and neither of them can claim it.
--   3. NULL -> A USER ONLY, NEVER USER A -> USER B. `b.user_id is null` is part of the WHERE, so a
--      booking that already has an owner is untouchable here. Without it, a quote whose address was
--      later re-registered — or simply mistyped onto a real account — would silently transfer someone
--      else's paid booking away from them.
--   4. QUOTE BOOKINGS ONLY. `source = 'quote'` is written by api_convert_quote and by nothing else
--      (enforce_booking_admin_update pins the column against any browser write), so this cannot grow
--      into a general "claim any booking that carries my address" mechanism — which would be a far
--      wider blast radius than the one case the owner decided on.
--   5. THE SAME NORMALISATION AS CONVERSION, on both operands, through quote_email_key (6c-bis). This
--      one is not a hole but a dead end: an address the owner match trimmed into a hit was a booking a
--      `lower()`-only claim could never see again, so the guest who paid was locked out of their own
--      record by a space nothing on screen displays.
--
-- IDEMPOTENT by construction: the second run finds no null-owner rows left and updates none, which is
-- what makes it safe to fire on every sign-in.
--
-- SECURITY DEFINER is load-bearing twice over: `authenticated` deliberately has no EXECUTE on
-- quote_owner_for_email, and enforce_booking_admin_update pins `new.user_id := old.user_id` for any
-- write whose `current_user` is anon or authenticated — so the same UPDATE run through PostgREST would
-- be silently reverted by the trigger rather than refused.
-- ---------------------------------------------------------------------------
create or replace function api_claim_quote_bookings(p jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_email text;
  v_claimed int := 0;
begin
  -- No identity, nothing to claim FOR. service_role holds EXECUTE (it is an ordinary server-callable
  -- RPC) but has no auth.uid(), and a claim that matched on nothing would be a mass re-assignment.
  if v_uid is null then
    raise exception 'unauthorized' using errcode = '42501';
  end if;

  select quote_email_key(u.email) into v_email from auth.users u where u.id = v_uid;
  if v_email is null then
    return jsonb_build_object('claimed', 0);
  end if;

  -- Property 2: the SAME rule conversion applies, asked in the same place. Unconfirmed or ambiguous
  -- comes back as null (or as somebody else), and this is where both stop.
  if quote_owner_for_email(v_email) is distinct from v_uid then
    return jsonb_build_object('claimed', 0);
  end if;

  -- Property 3, and the reason it is in the WHERE rather than in a caller: `user_id is null` makes an
  -- already-owned booking unreachable from here, so this can only ever fill an empty column. Property
  -- 4 is the `source` filter — a claim must never grow into "any booking carrying my address".
  -- quote_email_key on the BOOKING column too, not `lower()` alone. api_convert_quote copies
  -- `quotes.customer_email` into this column verbatim, so a pasted ' nina@example.com' is stored with
  -- its space — and matching it against a key that has been trimmed would make the one address
  -- conversion DID match unclaimable forever. Section 6c-bis is the whole of that story.
  update bookings b
     set user_id = v_uid
   where b.source = 'quote'
     and b.user_id is null
     and quote_email_key(b.customer_email) = v_email;
  get diagnostics v_claimed = row_count;

  return jsonb_build_object('claimed', v_claimed);
end;
$$;
-- `authenticated` KEEPS execute — the signed-in guest is the only real caller. anon is named
-- explicitly alongside public because Supabase's stock ALTER DEFAULT PRIVILEGES grants EXECUTE on
-- every new function to anon AND authenticated directly, so `from public` alone strips neither; that
-- one-word omission has shipped a live hole from this repo three times.
revoke execute on function api_claim_quote_bookings(jsonb) from public, anon;
grant execute on function api_claim_quote_bookings(jsonb) to authenticated, service_role;

comment on function api_claim_quote_bookings(jsonb) is
  'Attaches the caller''s previously ownerless QUOTE bookings to their account, matched on their own '
  'CONFIRMED address (quote_owner_for_email) and never on anything in the payload. Only ever fills a '
  'null user_id — it can never move a booking from one account to another — and is idempotent, so the '
  'app fires it once per sign-in.';

-- ---------------------------------------------------------------------------
-- 7b) api_booking_receipt — the VAT invoice has to see the lines a quote booking actually has.
--
-- api_convert_quote mints a booking whose every line lives in `booking_custom_items`; by
-- construction such a booking has ZERO booking_items. api_booking_receipt builds its `items` array
-- out of booking_json, which reads `from booking_items bi` and nothing else — so the receipt DTO
-- reached buildInvoice (src/lib/invoice/model.ts) with `items: []`.
--
-- That is not a cosmetic gap, it is a WRONG TAX DOCUMENT. buildInvoice backs the 15% out of the
-- gross PER LINE and sums: with no lines, `subtotalNetEur` is 0 and
-- `vatAmountEur = round2(totalGrossEur - 0)` becomes the entire charge. The guest is emailed an
-- invoice stating that a EUR 500 order was EUR 500 of VAT, with nothing itemised beneath it — and
-- the confirmation email, the invoice PDF and the voucher all render off that same model.
--
-- THE FIX is to union the custom lines into the items array the receipt already returns:
--   * `priceLabel` <- `description`. A custom line has no price label (it is not a catalogue price
--     band) and `booking_custom_items.description` is NOT NULL precisely so the line stays readable
--     on its own; receiptSchema types priceLabel as a required string, so this is the field it maps
--     to. buildInvoice then renders "<activityTitle> — <priceLabel>", or just the label when the
--     booking has no activity behind it, which a quote booking does not.
--   * `quantity` verbatim, and `pax` explicitly null — a custom line is priced per LINE, not per
--     person, and buildInvoice reads `pax ?? quantity`, so null is what makes it use the quantity.
--   * `subtotalEur` <- `subtotal_minor / 100.0`, the same minor->major conversion booking_json does
--     for booking_items. `unitAmountEur` rides along so the two item shapes stay identical.
-- Ordered by `position`, and APPENDED AFTER any booking_items rows: buildInvoice's own header notes
-- that voucher-pdf.ts reads `lines[0].quantity` positionally for its pax count, so the catalogue
-- lines must stay first for the day the hold path lands and a booking carries both kinds.
--
-- The arithmetic then needs no special case: api_convert_quote already refuses to mint unless
-- `total_minor` equals the sum of the lines, so the lines reconcile to `totalEur` by construction
-- and the net/VAT split is the identical rule every other booking gets.
--
-- Re-applied in FULL from its winning definition (20260901000300_booking_locale.sql) so this
-- migration cannot silently revert the `customerPhone` (20260826000000) or `locale` fields that
-- landed there.
--
-- ORDERING — THIS DEFINITION IS NOT THE LIVE ONE, AND DOES NOT NEED TO BE. The rule in this repo is
-- "the LAST migration to define a function wins", and 20260910000000_late_pickup_addon.sql defines
-- api_booking_receipt after this file — so on any database built from the whole directory (and on
-- catch-up.sql / setup.sql, which concatenate in the same order) THAT body is the one that runs.
-- It originally predated this union and threw it away, which is the migration-revert drift in
-- docs/handbook/landmines.md; it now carries the union itself, merged with its own `purpose` scoping
-- and supplement fold-in. This copy is kept because it is CORRECT AS OF THIS POINT IN HISTORY: a
-- database replayed only this far still invoices a quote with its lines, and deleting it would make
-- the file's own section 7b describe a fix it no longer performs. Do not "simplify" by dropping
-- either copy — drop the LATER one and the bug is back.
-- tests/integration/resolved-function-bodies.test.ts asserts on pg_proc.prosrc which body won.
-- ---------------------------------------------------------------------------
create or replace function api_booking_receipt(p jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_booking_id uuid := nullif(p ->> 'bookingId', '')::uuid;
  v_base jsonb;
  v_title text;
  v_when timestamptz;
  v_payment jsonb;
  v_phone text;
  v_locale text;
  v_custom jsonb;
begin
  if v_booking_id is null then
    raise exception 'invalid_request' using detail = 'booking_receipt: bookingId required';
  end if;

  v_base := booking_json(v_booking_id);
  if v_base is null then
    return null;
  end if;

  -- Primary activity title + the earliest trip date, joined off the booking's items.
  select a.title, o.starts_at
    into v_title, v_when
    from booking_items bi
    join session_occurrences o on o.id = bi.session_occurrence_id
    join activity_options ao on ao.id = bi.activity_option_id
    join activities a on a.id = ao.activity_id
   where bi.booking_id = v_booking_id
   order by o.starts_at asc, bi.created_at asc
   limit 1;

  -- The booking's most recent payment, with the real charge (or the EUR ledger fallback), the paid
  -- timestamp (first 'paid' event) and the provider event ref.
  select jsonb_build_object(
           'chargedAmountMinor', coalesce(pay.charged_amount_minor, pay.amount_minor),
           'chargedCurrency', coalesce(pay.charged_currency, pay.currency),
           'paidAt', paid.occurred_at,
           'providerRef', paid.provider_event_id
         )
    into v_payment
    from payments pay
    left join lateral (
      select pe.occurred_at, pe.provider_event_id
        from payment_events pe
       where pe.payment_id = pay.id and pe.type in ('paid', 'captured')
       order by pe.occurred_at asc
       limit 1
    ) paid on true
   where pay.booking_id = v_booking_id
   order by pay.created_at desc
   limit 1;

  -- The guest's stored booking locale (Task 15): the notification drain runs off-request (cron), so
  -- this is the only correct source for which language the confirmation email + PDFs render in.
  select b.customer_phone, b.locale::text into v_phone, v_locale from bookings b where b.id = v_booking_id;

  -- ADDITION 1 of 2 — the priced lines that have no session_occurrence: a converted quote's lines
  -- today, rentals in Part 2. Empty (and therefore free) for every booking that has none.
  select coalesce(jsonb_agg(jsonb_build_object(
           'priceLabel', ci.description,
           'quantity', ci.quantity,
           'pax', null::int,
           'unitAmountEur', ci.unit_amount_minor::float / 100,
           'subtotalEur', ci.subtotal_minor::float / 100
         ) order by ci.position), '[]'::jsonb)
    into v_custom
    from booking_custom_items ci
   where ci.booking_id = v_booking_id;

  -- ADDITION 2 of 2 — appended AFTER booking_json's own items, never merged into them.
  return v_base
    || jsonb_build_object('items', coalesce(v_base -> 'items', '[]'::jsonb) || v_custom)
    || jsonb_build_object('activityTitle', v_title, 'when', v_when)
    || jsonb_build_object('payment', coalesce(v_payment, 'null'::jsonb))
    || jsonb_build_object('customerPhone', v_phone)
    || jsonb_build_object('locale', v_locale);
end;
$$;
-- Stated at the point of definition, and naming anon + authenticated rather than PUBLIC alone:
-- Supabase's stock ALTER DEFAULT PRIVILEGES grants EXECUTE on every new function to those two roles
-- EXPLICITLY, CREATE OR REPLACE never resets an existing ACL, and this exact function is one of the
-- two that shipped a live leak from this repo for that reason (closed by 20260818000000).
revoke execute on function api_booking_receipt(jsonb) from public, anon, authenticated;
grant execute on function api_booking_receipt(jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- 8) RLS + grants. A quote is staff data; the guest never reads it with the anon key — the public
--    page resolves it server-side behind the link token (a later task).
--
--    Kept LAST in the file on purpose: tests/integration/quotes-schema.test.ts re-executes this
--    section verbatim (it slices the file from the first revoke statement to EOF) to make the revoke
--    load-bearing under PGlite. Append new statements ABOVE this section, never below it.
-- ---------------------------------------------------------------------------
alter table quotes enable row level security;
alter table quote_items enable row level security;
alter table booking_custom_items enable row level security;

drop policy if exists quotes_staff on quotes;
create policy quotes_staff on quotes for all to authenticated
  using (is_staff()) with check (is_staff());
drop policy if exists quote_items_staff on quote_items;
create policy quote_items_staff on quote_items for all to authenticated
  using (is_staff()) with check (is_staff());
drop policy if exists booking_custom_items_staff on booking_custom_items;
create policy booking_custom_items_staff on booking_custom_items for all to authenticated
  using (is_staff()) with check (is_staff());

-- Stock Supabase ALTER DEFAULT PRIVILEGES hands every new table to anon + authenticated, so the
-- revoke is what actually closes anon. The grants are then explicit because a fresh database built
-- from setup.sql (and the PGlite harness) has no default privileges at all — without them the staff
-- policies above would gate a table nobody may touch.
revoke all on quotes, quote_items, booking_custom_items from public, anon;
grant select, insert, update, delete on quotes to authenticated, service_role;
grant select, insert, update, delete on quote_items to authenticated, service_role;
grant select, insert, update, delete on booking_custom_items to authenticated, service_role;


-- ---- migration 20260910000000_late_pickup_addon (late pickup: pay the supplement, 48h/24h chase) ----
-- Late pickup: the guest who chose "I don't know yet" finishes the job themselves.
--
-- A booking taken with `pickup_pending = true` has no address and paid no transport supplement (the
-- checkout sends no coordinates, so api_book's region fare never fires). Until now nothing chased it
-- and nobody could fix it: the guest's booking page was read-only, admin had no write path for
-- pickup_location, and the owner ran the pickup for free or phoned around on the morning.
--
-- This migration adds the missing half of that flow:
--   1. the guest picks their address on /bookings/:ref, is quoted the region transport supplement,
--      and pays it through the SAME Peach checkout they already know;
--   2. 48h and 24h before departure a reminder chases a still-missing pickup, and at 24h the owner
--      gets told which bookings are still blind.
--
-- ── WHY A SECOND PAYMENTS ROW ────────────────────────────────────────────────────────────────────
-- api_create_payment refuses a confirmed/paid booking (`booking_not_payable`), and that guard MUST
-- stay: it is what stops a second payable session for money we already hold. The supplement is
-- DIFFERENT money, so it gets its own payments row tagged `purpose = 'pickup_addon'`.
--
-- That is safe by construction on the paths that already exist:
--   * append_payment_event's booking-level projection is already a roll-up across every payments row
--     of a booking (best row wins), so a pending add-on never drags a paid booking backwards;
--   * it only confirms a booking whose status is draft/held/payment_pending, so an add-on settling on
--     an already-confirmed booking is a no-op for status.
-- What was NOT safe, and is fixed below: api_create_payment's "latest row for this booking" lookup
-- would have handed a booking re-pay the add-on row. It is now scoped by purpose.
--
-- ── WHY THE ADDRESS IS NOT WRITTEN UNTIL THE MONEY LANDS ─────────────────────────────────────────
-- Writing pickup_location at request time would let a guest clear their own "pickup to be arranged"
-- badge without paying — the owner would drive to Le Morne for free and only find out on the day. The
-- requested address parks in `booking_pickup_requests` and is applied when, and only when, the
-- supplement settles.
--
-- ── WHY A TRIGGER RATHER THAN A CHANGE TO append_payment_event ───────────────────────────────────
-- landmines.md: "never confirm a booking outside append_payment_event". This does not confirm
-- anything — the booking is already confirmed — and re-declaring 170 lines of the most dangerous
-- function in the codebase to bolt on one call is exactly the migration-revert drift that page warns
-- about twice. The apply step hangs off the payments-row status write that append_payment_event
-- itself performs, so it runs inside the same transaction, under the same authority, and it is
-- idempotent (`applied_at is null`). reconcile.ts credits through the same function, so the
-- webhook-less recovery path is covered too.


-- ---------------------------------------------------------------------------
-- 1) payments.purpose — which money a row represents.
-- ---------------------------------------------------------------------------
alter table payments add column if not exists purpose text not null default 'booking';
alter table payments drop constraint if exists payments_purpose_check;
alter table payments add constraint payments_purpose_check
  check (purpose in ('booking', 'pickup_addon'));
create index if not exists payments_booking_purpose_idx on payments (booking_id, purpose);

-- ---------------------------------------------------------------------------
-- 2) booking_pickup_requests — the requested address, held until it is paid for.
-- ---------------------------------------------------------------------------
create table if not exists booking_pickup_requests (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references bookings (id) on delete cascade,
  -- Null only for a zero-fee request (same region, no supplement due), which is applied immediately.
  payment_id uuid references payments (id) on delete set null,
  -- Nullable so a GDPR erasure can strip the address WITHOUT deleting the row: api_booking_receipt
  -- reads applied_at as its proof that a settled supplement belongs on the invoice, and the fare
  -- stays inside bookings.total_minor forever. Deleting the row made the retained financial record
  -- contradict itself. api_request_pickup always writes all three.
  pickup_location text,
  pickup_lat double precision,
  pickup_lng double precision,
  pickup_region text,
  dropoff_location text,
  fee_minor int not null default 0 check (fee_minor >= 0),
  applied_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- At most ONE open request per booking: the guest may revise the address they are about to pay for,
-- never fork it into two payable supplements.
create unique index if not exists booking_pickup_requests_open_idx
  on booking_pickup_requests (booking_id) where applied_at is null;
create index if not exists booking_pickup_requests_payment_idx
  on booking_pickup_requests (payment_id);

alter table booking_pickup_requests enable row level security;

drop policy if exists booking_pickup_requests_staff on booking_pickup_requests;
create policy booking_pickup_requests_staff on booking_pickup_requests for all to authenticated
  using (is_staff()) with check (is_staff());

-- The guest reads their own open request (booking_json surfaces it so the booking page can say
-- "we're waiting on your supplement"). Read-only: every write goes through the RPCs below.
drop policy if exists booking_pickup_requests_own on booking_pickup_requests;
create policy booking_pickup_requests_own on booking_pickup_requests for select to authenticated
  using (exists (
    select 1 from bookings b where b.id = booking_pickup_requests.booking_id and b.user_id = auth.uid()
  ));

-- Stock Supabase ALTER DEFAULT PRIVILEGES hands every new table to anon + authenticated, so the
-- revoke is what actually closes anon; the grant is explicit because a database built from setup.sql
-- (and the PGlite harness) has no default privileges at all.
revoke all on booking_pickup_requests from public, anon;
grant select on booking_pickup_requests to authenticated;
grant select, insert, update, delete on booking_pickup_requests to service_role;

-- ---------------------------------------------------------------------------
-- 3) pickup_addon_quote — ONE body for "may this booking add a pickup, and what does it cost?".
--
--    Shared by the quote RPC (live, as the guest drags the pin), the request RPC (authoritative, at
--    the moment money is committed) and the tests. A second copy of this eligibility ladder would
--    drift, and the drift would be a wrong price.
--
--    Mirrors api_book's transport block: region re-derived from coordinates server-side, fare from
--    transport_fare_minor, never a client-sent price.
-- ---------------------------------------------------------------------------
create or replace function pickup_addon_quote(
  p_booking_id uuid,
  p_lat double precision,
  p_lng double precision
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_booking bookings;
  v_mode text;
  v_activity_region text;
  v_pickup_available boolean;
  v_is_airport boolean;
  v_is_hotel boolean;
  v_qty int;
  v_suv boolean;
  v_region text;
  v_starts_at timestamptz;
  v_fee bigint;
begin
  select * into v_booking from bookings where id = p_booking_id;
  if not found then
    return jsonb_build_object('eligible', false, 'reason', 'booking_not_found', 'feeMinor', 0);
  end if;

  -- Only a booking that ASKED for a pickup and never gave an address. A booking with no pickup at all
  -- (the guest makes their own way) is a different intent and is deliberately not upgradable here.
  if not coalesce(v_booking.pickup_pending, false) or v_booking.pickup_location is not null then
    return jsonb_build_object('eligible', false, 'reason', 'pickup_not_pending', 'feeMinor', 0);
  end if;
  if v_booking.status <> 'confirmed' or v_booking.payment_state <> 'paid' then
    return jsonb_build_object('eligible', false, 'reason', 'booking_not_confirmed', 'feeMinor', 0);
  end if;

  select coalesce(a.pricing_mode, 'per_person'),
         coalesce(a.region, region_from_coords(a.lat, a.lng)),
         coalesce(a.pickup_available, false),
         coalesce(a.is_airport_transfer, false),
         coalesce(a.is_hotel_transfer, false)
    into v_mode, v_activity_region, v_pickup_available, v_is_airport, v_is_hotel
  from booking_items bi
  join activity_options o on o.id = bi.activity_option_id
  join activities a on a.id = o.activity_id
  where bi.booking_id = p_booking_id
  order by bi.id
  limit 1;

  if v_mode is null then
    return jsonb_build_object('eligible', false, 'reason', 'no_activity', 'feeMinor', 0);
  end if;
  -- Same gate as api_book's transport block. Both transfer products carry a fixed band/zone fare and
  -- always have a pickup end, so they can never be pickup_pending in the first place.
  if v_is_airport or v_is_hotel or not v_pickup_available or v_mode not in ('per_person', 'per_group') then
    return jsonb_build_object('eligible', false, 'reason', 'transport_not_applicable', 'feeMinor', 0);
  end if;

  -- Past departures cannot be fixed by paying for a pickup.
  select min(so.starts_at) into v_starts_at
    from booking_items bi
    join session_occurrences so on so.id = bi.session_occurrence_id
   where bi.booking_id = p_booking_id;
  if v_starts_at is null or v_starts_at <= now() then
    return jsonb_build_object('eligible', false, 'reason', 'departed', 'feeMinor', 0);
  end if;

  -- Nor can a departure WE called off. api_weather_cancel_occurrence leaves the booking 'confirmed'
  -- with its items still pointing at the cancelled occurrence and starts_at unmoved, so every check
  -- above still passes — selling a transport supplement for a trip that is not running, and (via the
  -- reminder sweep, which shares this ladder) chasing the guest for a pickup hours after telling them
  -- the trip was cancelled. A guest still owed a reschedule/refund choice is in the same position.
  if exists (
    select 1
      from booking_items bi
      join session_occurrences so on so.id = bi.session_occurrence_id
     where bi.booking_id = p_booking_id and so.status = 'cancelled'
  ) or booking_awaiting_choice(v_booking.disruption) then
    return jsonb_build_object('eligible', false, 'reason', 'departure_cancelled', 'feeMinor', 0);
  end if;

  -- Party size in the same unit api_book used: the headcount, not the line count.
  select coalesce(sum(coalesce(bi.pax, bi.quantity)), 0)::int into v_qty
    from booking_items bi where bi.booking_id = p_booking_id;

  -- The SUV upgrade is a vehicle-tour concept and the modes eligible here never offer it, so this is
  -- false for every real booking. Read from the booking's own price labels rather than hardcoding
  -- false, so a future per_group SUV line prices honestly instead of silently under-charging.
  select exists (
    select 1 from booking_items bi
     where bi.booking_id = p_booking_id and bi.price_label ilike '%suv%'
  ) into v_suv;

  if p_lat is null or p_lng is null then
    return jsonb_build_object('eligible', true, 'reason', null, 'feeMinor', 0, 'region', null);
  end if;

  v_region := region_from_coords(p_lat, p_lng);
  if v_region is null then
    -- Outside the five Mauritius zones: no band, so no fare. Accept the address, charge nothing.
    return jsonb_build_object('eligible', true, 'reason', null, 'feeMinor', 0, 'region', null);
  end if;

  v_fee := transport_fare_minor(v_region, v_activity_region, v_qty, v_suv);
  return jsonb_build_object(
    'eligible', true,
    'reason', null,
    'feeMinor', coalesce(v_fee, 0),
    'region', v_region,
    'activityRegion', v_activity_region,
    'band', region_distance_band(v_region, v_activity_region),
    'pax', v_qty
  );
end;
$$;

revoke execute on function pickup_addon_quote(uuid, double precision, double precision)
  from public, anon, authenticated;
grant execute on function pickup_addon_quote(uuid, double precision, double precision) to service_role;

-- ---------------------------------------------------------------------------
-- 4) api_quote_pickup_addon — the live quote the booking page shows as the pin moves.
--    Ownership-gated, read-only, no rows written: dragging a map pin must not mint payments.
-- ---------------------------------------------------------------------------
create or replace function api_quote_pickup_addon(p jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_booking bookings;
begin
  select * into v_booking from bookings where ref = p ->> 'bookingRef';
  if not found then
    raise exception 'booking_not_found';
  end if;
  if not (is_staff() or (auth.uid() is not null and v_booking.user_id = auth.uid())) then
    raise exception 'forbidden';
  end if;
  return pickup_addon_quote(
    v_booking.id,
    nullif(p ->> 'pickupLat', '')::double precision,
    nullif(p ->> 'pickupLng', '')::double precision
  );
end;
$$;

revoke execute on function api_quote_pickup_addon(jsonb) from public, anon;
grant execute on function api_quote_pickup_addon(jsonb) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 5) api_request_pickup — commit to an address.
--
--    Zero fee  -> applied immediately (nothing to pay, so nothing to wait for).
--    Fee due   -> the address parks in booking_pickup_requests behind a 'pickup_addon' payments row;
--                 the caller then mints a checkout for it through api_create_payment.
--
--    Idempotent and revisable: a guest who comes back and picks a different address updates the OPEN
--    request in place. The amount may only move while no live checkout session exists for it —
--    otherwise a session minted for the old figure could still be paid, and the pinned settlement
--    expectation would no longer match what we asked for.
-- ---------------------------------------------------------------------------
create or replace function api_request_pickup(p jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_booking bookings;
  v_quote jsonb;
  v_fee bigint;
  v_region text;
  v_pickup text;
  v_dropoff text;
  v_lat double precision;
  v_lng double precision;
  v_req booking_pickup_requests;
  v_payment payments;
  v_in_flight boolean := false;
begin
  -- FOR UPDATE: two tabs committing an address at once must serialise, or both insert an open request
  -- (the partial unique index would reject the loser with a raw constraint error instead of a merge).
  select * into v_booking from bookings where ref = p ->> 'bookingRef' for update;
  if not found then
    raise exception 'booking_not_found';
  end if;
  if not (is_staff() or (auth.uid() is not null and v_booking.user_id = auth.uid())) then
    raise exception 'forbidden';
  end if;

  v_pickup := nullif(btrim(p ->> 'pickupLocation'), '');
  v_dropoff := nullif(btrim(p ->> 'dropoffLocation'), '');
  v_lat := nullif(p ->> 'pickupLat', '')::double precision;
  v_lng := nullif(p ->> 'pickupLng', '')::double precision;
  if v_pickup is null or v_lat is null or v_lng is null then
    raise exception 'pickup_incomplete';
  end if;
  -- Bounded like every other free-text booking field: a tampered payload is a clean error, not a
  -- runaway row.
  v_pickup := left(v_pickup, 200);
  v_dropoff := left(v_dropoff, 200);

  v_quote := pickup_addon_quote(v_booking.id, v_lat, v_lng);
  if not coalesce((v_quote ->> 'eligible')::boolean, false) then
    raise exception 'pickup_not_allowed' using detail = coalesce(v_quote ->> 'reason', 'unknown');
  end if;
  v_fee := coalesce((v_quote ->> 'feeMinor')::bigint, 0);
  v_region := coalesce(v_quote ->> 'region', '');

  select * into v_req from booking_pickup_requests
   where booking_id = v_booking.id and applied_at is null
   for update;
  if v_req.payment_id is not null then
    select * into v_payment from payments where id = v_req.payment_id for update;
  end if;

  -- ── Is a checkout for the CURRENT figure already out in the world? ─────────────────────────────
  -- Two states count as "in flight", and missing either one is a double-charge:
  --   * a recorded session inside the 25-minute reuse window — still payable at Peach;
  --   * a held single-flight lease — api_create_payment has stamped it and the edge worker is at
  --     Peach right now, 1-2s during which provider_checkout_id is STILL NULL. Revising in that
  --     window used to clear the lease and re-price the row underneath the winner, so the loser
  --     minted a second session: two live sessions, both handed to a browser. Peach's nonce is per
  --     REQUEST and never dedupes, which is exactly why that lease exists.
  v_in_flight := v_payment.id is not null
    and (
      (v_payment.provider_checkout_id is not null
        and coalesce(v_payment.checkout_created_at, v_payment.updated_at) > now() - interval '25 minutes')
      or (v_payment.checkout_claimed_until is not null and v_payment.checkout_claimed_until > now())
    );

  -- ── Nothing to pay: apply now ──────────────────────────────────────────────────────────────────
  if v_fee = 0 then
    -- …unless a supplement checkout for the PREVIOUS address is live. Applying here would stamp
    -- applied_at, and the guest could then still complete that session — money taken for a pickup the
    -- trigger would find already applied and silently discard. Same answer as the fee>0 path: finish
    -- it or let it lapse.
    if v_in_flight then
      raise exception 'pickup_payment_in_flight';
    end if;

    update bookings
       set pickup_location = v_pickup,
           dropoff_location = coalesce(v_dropoff, dropoff_location),
           pickup_pending = false,
           pickup_lat = v_lat,
           pickup_lng = v_lng,
           pickup_region = nullif(v_region, ''),
           updated_at = now()
     where id = v_booking.id;

    if v_req.id is not null then
      -- payment_id is CUT LOOSE. This row is being applied at zero, so it is no longer the record of
      -- what that payment bought — and two things read it that way: notify_pickup_orphan_payment
      -- (which must still alert if the old session settles) and api_booking_receipt's fold-in gate
      -- (which would otherwise put a charge on the invoice that never reached the booking total).
      update booking_pickup_requests
         set pickup_location = v_pickup, pickup_lat = v_lat, pickup_lng = v_lng,
             pickup_region = v_region, dropoff_location = v_dropoff, fee_minor = 0,
             payment_id = null, applied_at = now(), updated_at = now()
       where id = v_req.id;
    else
      insert into booking_pickup_requests (
        booking_id, payment_id, pickup_location, pickup_lat, pickup_lng, pickup_region,
        dropoff_location, fee_minor, applied_at
      ) values (
        v_booking.id, null, v_pickup, v_lat, v_lng, v_region, v_dropoff, 0, now()
      ) returning * into v_req;
    end if;

    perform notify_pickup_set(v_booking.id, v_req.id, 0);
    return jsonb_build_object('applied', true, 'feeMinor', 0, 'paymentId', null);
  end if;

  -- ── Supplement due ─────────────────────────────────────────────────────────────────────────────
  if v_req.id is not null then
    -- Re-pricing under a live session is the refusal case: that session is still payable at the OLD
    -- figure, and moving amount_minor + the FX pin underneath it would make the guest's real
    -- settlement fail reconcile's pinned-expectation check and quarantine. Re-pointing the SAME
    -- figure at a new address is harmless, so it stays allowed.
    if v_in_flight and v_payment.amount_minor <> v_fee then
      raise exception 'pickup_payment_in_flight';
    end if;

    update booking_pickup_requests
       set pickup_location = v_pickup, pickup_lat = v_lat, pickup_lng = v_lng,
           pickup_region = v_region, dropoff_location = v_dropoff, fee_minor = v_fee,
           updated_at = now()
     where id = v_req.id
    returning * into v_req;

    if v_payment.id is not null and v_payment.amount_minor <> v_fee then
      -- Re-pin the FX charge from scratch: charged_amount_minor is first-write-wins, so leaving the
      -- old pin would charge the card the old supplement.
      --
      -- The checkout columns are deliberately NOT touched. Clearing provider_checkout_id would hide a
      -- stale session from the recovery sweep (money captured on it would then reach nothing), and
      -- clearing checkout_claimed_until would break another caller's single-flight lease. The guard
      -- above has already established that neither is live; api_create_payment's own liveness
      -- re-query + api_clear_payment_checkout are what retire a dead pointer, under compare-and-clear.
      update payments
         set amount_minor = v_fee,
             charged_amount_minor = null, charged_currency = null, charged_fx_rate = null,
             charged_fx_source = null, charged_fx_at = null,
             updated_at = now()
       where id = v_payment.id
      returning * into v_payment;
      insert into payment_events (payment_id, type, amount_minor)
      values (v_payment.id, 'intent', v_fee);
    end if;

    if v_payment.id is not null then
      return jsonb_build_object('applied', false, 'feeMinor', v_fee, 'paymentId', v_payment.id);
    end if;
  end if;

  -- No usable payment row yet (first request, or a zero-fee request that has now become chargeable).
  insert into payments (booking_id, idempotency_key, amount_minor, purpose)
  values (v_booking.id, 'pickup:' || v_booking.id::text || ':' || gen_random_uuid()::text, v_fee, 'pickup_addon')
  returning * into v_payment;
  insert into payment_events (payment_id, type, amount_minor)
  values (v_payment.id, 'intent', v_fee);

  if v_req.id is not null then
    update booking_pickup_requests set payment_id = v_payment.id, updated_at = now()
     where id = v_req.id;
  else
    insert into booking_pickup_requests (
      booking_id, payment_id, pickup_location, pickup_lat, pickup_lng, pickup_region,
      dropoff_location, fee_minor
    ) values (
      v_booking.id, v_payment.id, v_pickup, v_lat, v_lng, v_region, v_dropoff, v_fee
    );
  end if;

  return jsonb_build_object('applied', false, 'feeMinor', v_fee, 'paymentId', v_payment.id);
end;
$$;

revoke execute on function api_request_pickup(jsonb) from public, anon;
grant execute on function api_request_pickup(jsonb) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 6) notify_pickup_set / apply_pickup_request — what happens when the supplement lands.
--
--    Owner alert is EMAIL ONLY on purpose. resolveOwnerRecipient() throws for an unset Telegram chat
--    id or WhatsApp number, and both are unset in production — enqueuing those rows would create
--    permanently-failing outbox rows rather than delivering anything.
-- ---------------------------------------------------------------------------
create or replace function notify_pickup_set(
  p_booking_id uuid,
  p_request_id uuid,
  p_fee_minor bigint
)
returns void
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_booking bookings;
  v_title text;
  v_starts_at timestamptz;
begin
  select * into v_booking from bookings where id = p_booking_id;
  if not found then
    return;
  end if;

  select a.title, min(so.starts_at)
    into v_title, v_starts_at
  from booking_items bi
  join session_occurrences so on so.id = bi.session_occurrence_id
  join activity_options o on o.id = bi.activity_option_id
  join activities a on a.id = o.activity_id
  where bi.booking_id = p_booking_id
  group by a.title
  order by min(so.starts_at)
  limit 1;

  insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
  values (
    'email', 'owner', 'owner_pickup_set',
    jsonb_build_object(
      'ref', v_booking.ref,
      'customerName', v_booking.customer_name,
      'customerPhone', v_booking.customer_phone,
      'pickupLocation', v_booking.pickup_location,
      'dropoffLocation', v_booking.dropoff_location,
      'activityTitle', v_title,
      'startsAt', v_starts_at,
      'feeEur', p_fee_minor::float / 100
    ),
    p_booking_id,
    'pickup_set_owner:' || p_request_id::text
  )
  on conflict (idempotency_key) do nothing;

  if v_booking.customer_email is not null then
    insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
    values (
      'email', v_booking.customer_email, 'pickup_confirmed',
      jsonb_build_object(
        'ref', v_booking.ref,
        'customerName', v_booking.customer_name,
        'pickupLocation', v_booking.pickup_location,
        'activityTitle', v_title,
        'startsAt', v_starts_at,
        'feeEur', p_fee_minor::float / 100,
        'locale', v_booking.locale::text
      ),
      p_booking_id,
      'pickup_set_guest:' || p_request_id::text
    )
    on conflict (idempotency_key) do nothing;
  end if;
end;
$$;

revoke execute on function notify_pickup_set(uuid, uuid, bigint) from public, anon, authenticated;
grant execute on function notify_pickup_set(uuid, uuid, bigint) to service_role;

-- A settled supplement that could NOT be applied. Every branch that refuses to write a pickup routes
-- here, because the alternative is keeping a guest's money with no record anyone will ever look at.
-- Email only, and idempotent per payment: the reconcile sweep re-queries the same capture for hours.
create or replace function notify_pickup_orphan_payment(p_payment_id uuid)
returns void
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_payment payments;
  v_booking bookings;
  v_applied bigint;
begin
  select * into v_payment from payments where id = p_payment_id;
  if not found or v_payment.purpose <> 'pickup_addon' or v_payment.paid_minor <= 0 then
    return;
  end if;

  -- How much of THIS payment actually reached a booking. A normal apply puts exactly amount_minor
  -- there, so the common replay path (request already applied, in full) is silent. A request applied
  -- at a different figure — the zero-fee revision — is not.
  select coalesce(sum(r.fee_minor), 0) into v_applied
    from booking_pickup_requests r
   where r.payment_id = p_payment_id and r.applied_at is not null;
  if v_applied >= v_payment.amount_minor then
    return;
  end if;

  select * into v_booking from bookings where id = v_payment.booking_id;
  -- A booking that is already cancelled/expired/refunded had this capture routed to refund_pending by
  -- append_payment_event, which raises its own owner alert. Don't send a second one for it.
  if v_booking.status not in ('confirmed', 'completed') then
    return;
  end if;

  insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
  values (
    'email', 'owner', 'owner_pickup_orphan_payment',
    jsonb_build_object(
      'ref', v_booking.ref,
      'customerName', v_booking.customer_name,
      'feeEur', v_payment.amount_minor::float / 100,
      'chargedAmountMinor', v_payment.charged_amount_minor,
      'chargedCurrency', v_payment.charged_currency
    ),
    v_booking.id,
    'pickup_orphan:' || p_payment_id::text
  )
  on conflict (idempotency_key) do nothing;
end;
$$;

revoke execute on function notify_pickup_orphan_payment(uuid) from public, anon, authenticated;
grant execute on function notify_pickup_orphan_payment(uuid) to service_role;

create or replace function apply_pickup_request(p_payment_id uuid)
returns void
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_req booking_pickup_requests;
  v_status booking_status;
  v_disruption jsonb;
  v_called_off boolean;
begin
  -- `applied_at is null` is the whole idempotency story: a replayed webhook, the reconcile sweep and
  -- the customer's own sync poll all land here, and only the first one moves money onto the booking.
  select * into v_req from booking_pickup_requests
   where payment_id = p_payment_id and applied_at is null
   for update;
  if not found then
    -- Money with nothing to apply it to. The ONE case that is normal is a replay of a supplement
    -- already applied in full; anything else is a real capture we would otherwise keep silently
    -- (the guest revised to a zero-fee address while this session was still payable, or the request
    -- was superseded). Alerting is the whole point: nobody can refund what nobody knows about.
    perform notify_pickup_orphan_payment(p_payment_id);
    return;
  end if;

  -- The booking must still be live. A supplement captured on a session minted before the guest
  -- cancelled (Peach sessions stay completable ~30 min) would otherwise add a pickup and its fare to
  -- a cancelled/refunded booking. append_payment_event's own "money on a non-live booking" branch
  -- routes that capture to refund_pending, which is the right answer; this must not undo it by
  -- writing a pickup onto it.
  --
  -- 'completed' counts as live, exactly as it does in append_payment_event, api_mark_refunded and the
  -- capacity count. Excluding it meant a supplement that settled late on a trip the owner had already
  -- marked complete was KEPT and never applied — that branch does not route to refund_pending either,
  -- so the money simply vanished from view.
  select status, disruption into v_status, v_disruption from bookings where id = v_req.booking_id;
  if v_status not in ('confirmed', 'completed') then
    return;
  end if;

  -- …and the departure must still be running. api_weather_cancel_occurrence leaves the booking
  -- 'confirmed' with its items on the cancelled occurrence, so the status check above sails past a
  -- called-off trip. Every SELL-side path already refuses this (pickup_addon_quote), but this is the
  -- path that actually takes the money onto the booking, and it was the only one that did not: the
  -- guest was charged for transport to a trip we had just told them was cancelled, and the pickup was
  -- stamped onto a booking that still owes them a reschedule-or-refund choice.
  select exists (
    select 1
      from booking_items bi
      join session_occurrences so on so.id = bi.session_occurrence_id
     where bi.booking_id = v_req.booking_id and so.status = 'cancelled'
  ) into v_called_off;
  if v_called_off or booking_awaiting_choice(v_disruption) then
    perform notify_pickup_orphan_payment(p_payment_id);
    return;
  end if;

  update bookings
     set pickup_location = v_req.pickup_location,
         dropoff_location = coalesce(v_req.dropoff_location, dropoff_location),
         pickup_pending = false,
         pickup_lat = v_req.pickup_lat,
         pickup_lng = v_req.pickup_lng,
         pickup_region = nullif(v_req.pickup_region, ''),
         transport_minor = transport_minor + v_req.fee_minor,
         total_minor = total_minor + v_req.fee_minor,
         operator_payout_minor = operator_payout_minor + v_req.fee_minor,
         updated_at = now()
   where id = v_req.booking_id;

  update booking_pickup_requests set applied_at = now(), updated_at = now() where id = v_req.id;

  perform notify_pickup_set(v_req.booking_id, v_req.id, v_req.fee_minor);
end;
$$;

revoke execute on function apply_pickup_request(uuid) from public, anon, authenticated;
grant execute on function apply_pickup_request(uuid) to service_role;

create or replace function trg_apply_pickup_request()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform apply_pickup_request(new.id);
  return new;
end;
$$;

drop trigger if exists payments_apply_pickup_addon on payments;
create trigger payments_apply_pickup_addon
after update of status on payments
for each row
when (new.purpose = 'pickup_addon' and new.status = 'paid' and old.status is distinct from 'paid')
execute function trg_apply_pickup_request();

-- ---------------------------------------------------------------------------
-- 7) api_create_payment — the 20260902000000 body VERBATIM with the purpose branch.
--
--    Three changes, all of them about keeping the two kinds of money apart:
--      a. `purpose` is read from the payload (default 'booking' — every existing caller is unchanged);
--      b. the booking-payability guard applies to a 'booking' payment; a 'pickup_addon' instead
--         requires an open, unapplied request with a row already minted by api_request_pickup (this
--         function never invents an add-on amount);
--      c. every payments lookup and the insert are scoped by purpose, so a booking re-pay can no
--         longer pick up the add-on row (and vice versa).
--    The FX pin, the checkout lease, the reuse window and the ownership check are untouched.
-- ---------------------------------------------------------------------------
create or replace function api_create_payment(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking bookings;
  v_payment payments;
  v_rate numeric;
  v_src text;
  v_at timestamptz;
  v_charged bigint;
  v_purpose text := coalesce(nullif(p ->> 'purpose', ''), 'booking');
  v_req booking_pickup_requests;
begin
  if v_purpose not in ('booking', 'pickup_addon') then
    raise exception 'invalid_payment_purpose' using detail = v_purpose;
  end if;

  -- FOR UPDATE: every concurrent create-payment call for one booking serialises on this row for the
  -- rest of the transaction. That closes two races at once: two callers both inserting a payments row
  -- below, and — via the checkout lease — two callers both getting a green light to mint a Peach
  -- session. Peach's nonce is unique per REQUEST (it never dedupes), so without this lease two tabs
  -- or a retry could create two independently payable sessions for the same booking.
  -- (It also makes the charge pin race-free: one caller pins, the loser re-reads the pinned row.)
  select * into v_booking from bookings where ref = p ->> 'bookingRef' for update;
  if not found then
    raise exception 'booking_not_found';
  end if;
  if v_purpose = 'booking' then
    if v_booking.status in ('confirmed', 'completed', 'cancelled', 'expired', 'refund_pending', 'refunded', 'failed')
       or v_booking.payment_state in ('paid', 'partially_refunded', 'refunded') then
      raise exception 'booking_not_payable' using detail = v_booking.status::text;
    end if;
  else
    -- The add-on's own payability: an open request must exist, and the trip must not have left.
    select * into v_req from booking_pickup_requests
     where booking_id = v_booking.id and applied_at is null and payment_id is not null;
    if not found then
      raise exception 'pickup_request_not_found';
    end if;
    -- …and it must not ALREADY hold the guest's money. A request refused at settlement (the departure
    -- was called off) stays open behind a payments row that is already 'paid'. If the trip is then
    -- rescheduled onto a live date the eligibility ladder goes green again, and without this guard
    -- the booking page's "Complete payment" button minted a SECOND Peach session on that same row —
    -- charging the card twice for one supplement, invisibly: the apply trigger cannot fire again
    -- (its WHEN clause needs old.status distinct from 'paid'), so no second alert is raised either.
    if exists (
      select 1 from payments pay
       where pay.id = v_req.payment_id and pay.paid_minor >= pay.amount_minor and pay.amount_minor > 0
    ) then
      raise exception 'pickup_already_paid';
    end if;
    if not coalesce((pickup_addon_quote(v_booking.id, v_req.pickup_lat, v_req.pickup_lng) ->> 'eligible')::boolean, false) then
      raise exception 'booking_not_payable' using detail = 'pickup_addon';
    end if;
  end if;
  if not (is_staff() or (auth.uid() is not null and v_booking.user_id = auth.uid())) then
    raise exception 'forbidden';
  end if;

  -- No `and status <> 'failed'`: that skipped the row a declined attempt had latched to 'failed' and
  -- minted a SECOND payments row, orphaning the checkout-reuse window and the single-flight lease
  -- (both columns on the skipped row) and leaving two independently payable Peach sessions.
  if v_purpose = 'booking' then
    select * into v_payment from payments
    where booking_id = v_booking.id and purpose = 'booking'
    order by created_at desc
    limit 1;

    if not found then
      -- Scoped to THIS booking: an unscoped key lookup let a caller echo another payment's key and
      -- receive that payment's id/amount back.
      select * into v_payment from payments
      where idempotency_key = p ->> 'idempotencyKey' and booking_id = v_booking.id and purpose = 'booking';
    end if;
  else
    -- Exactly the row the open request points at — never "the newest add-on row", which after a
    -- superseded request could be a different, abandoned one.
    select * into v_payment from payments where id = v_req.payment_id and purpose = 'pickup_addon';
  end if;

  if not found then
    if v_purpose <> 'booking' then
      -- api_request_pickup owns the add-on row (it is the only place that knows the fare). Never
      -- invent one here, or the amount would come from nowhere.
      raise exception 'pickup_request_not_found';
    end if;
    insert into payments (booking_id, idempotency_key, amount_minor, purpose)
    values (v_booking.id, p ->> 'idempotencyKey', v_booking.total_minor, 'booking')
    returning * into v_payment;
    insert into payment_events (payment_id, type, amount_minor)
    values (v_payment.id, 'intent', v_booking.total_minor);
  end if;

  -- ── Pin the charge (once per payment row) ────────────────────────────────────────────────────
  -- The EUR ledger total converted to WHOLE MUR RUPEES at the server-controlled rate. Derived here,
  -- in SQL, from fx_rates — NEVER from caller input (this function is granted to authenticated; a
  -- caller-supplied rate would let a booking owner pin their own MUR 0.05 charge). First-write-wins:
  -- every later call — every re-minted checkout session, the pay page, reconcile — reads THIS figure,
  -- so a moved FX rate between sessions can never make the charge and the expected settlement drift.
  if v_payment.charged_amount_minor is null and v_payment.amount_minor > 0 then
    select r.rate, r.source, r.fetched_at into v_rate, v_src, v_at
      from fx_rates r where r.base = 'EUR' and r.quote = 'MUR';
    -- Band-clamped on READ as well as write: an inverted or foreign payload that somehow reached the
    -- table (0.0185 would bill MUR 1.85 for a EUR 100 booking — and, because settled == charged,
    -- CONFIRM it) falls back to the floor instead of being trusted.
    if v_rate is null or v_rate < 40 or v_rate > 70 then
      v_rate := 53.00; -- cold-start floor; see the fx_rates seed comment (kept below mid on purpose)
      v_src := 'fallback';
      v_at := now();
    end if;
    -- Whole rupees: kills every sub-unit disagreement between what we send Peach and what Peach
    -- reports back. Costs at most MUR 0.50 (~EUR 0.01) per booking.
    v_charged := (round(v_payment.amount_minor * v_rate / 100.0) * 100)::bigint;
    update payments
       set charged_amount_minor = v_charged,
           charged_currency = 'MUR',
           charged_fx_rate = v_rate,
           charged_fx_source = v_src,
           charged_fx_at = v_at,
           updated_at = now()
     where id = v_payment.id and charged_amount_minor is null
     returning * into v_payment;
    if not found then
      -- Another transaction pinned first (or a legacy row already carried a charge): read the truth.
      select * into v_payment from payments where id = v_payment.id;
    end if;
  end if;

  -- Checkout lease (single-flight): exactly one caller may be out creating a Peach session at any
  -- moment. Order matters — reuse beats pending beats claim:
  --   1. a still-fresh recorded checkout        -> hand the SAME session back (reuse; no Peach call);
  --   2. someone else holds an unexpired lease  -> checkoutPending (caller retries shortly);
  --   3. otherwise                              -> stamp the lease and let THIS caller call Peach.
  -- api_record_payment_checkout clears the lease when the session id is recorded; a Peach failure
  -- releases it via api_release_checkout_claim, and the 90-second expiry is the crash backstop.
  --
  -- Freshness is measured from checkout_created_at (when the session was MINTED), never from
  -- updated_at: the reconcile sweep touches updated_at on every pass, which used to re-arm this
  -- window forever and trap the customer on a dead session. The caller still verifies liveness with
  -- the provider before actually reusing what this returns.
  if v_payment.provider_checkout_id is not null
     and coalesce(v_payment.checkout_created_at, v_payment.updated_at) > now() - interval '25 minutes' then
    return jsonb_build_object(
      'paymentId', v_payment.id, 'amountMinor', v_payment.amount_minor,
      'bookingRef', v_booking.ref, 'customerEmail', v_booking.customer_email,
      'existingCheckoutId', v_payment.provider_checkout_id,
      'chargedAmountMinor', v_payment.charged_amount_minor,
      'chargedCurrency', v_payment.charged_currency,
      'chargedFxRate', v_payment.charged_fx_rate
    );
  end if;

  if v_payment.checkout_claimed_until is not null and v_payment.checkout_claimed_until > now() then
    return jsonb_build_object(
      'paymentId', v_payment.id, 'amountMinor', v_payment.amount_minor,
      'bookingRef', v_booking.ref, 'customerEmail', v_booking.customer_email,
      'existingCheckoutId', null,
      'checkoutPending', true,
      'chargedAmountMinor', v_payment.charged_amount_minor,
      'chargedCurrency', v_payment.charged_currency,
      'chargedFxRate', v_payment.charged_fx_rate
    );
  end if;

  update payments set checkout_claimed_until = now() + interval '90 seconds'
  where id = v_payment.id;

  return jsonb_build_object(
    'paymentId', v_payment.id, 'amountMinor', v_payment.amount_minor,
    'bookingRef', v_booking.ref, 'customerEmail', v_booking.customer_email,
    'existingCheckoutId', null,
    'chargedAmountMinor', v_payment.charged_amount_minor,
    'chargedCurrency', v_payment.charged_currency,
    'chargedFxRate', v_payment.charged_fx_rate
  );
end;
$$;

revoke execute on function api_create_payment(jsonb) from public, anon;
grant execute on function api_create_payment(jsonb) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 8) api_pending_payment_checkouts — the 20260912000000 body: the add-on branch PLUS the balance branch.
--
--    The sweep enumerated by BOOKING state (`status = 'payment_pending'`), which is exactly wrong for
--    a supplement OR a balance on a confirmed booking: a lost webhook would strand the guest's money
--    forever with nothing re-querying it. Both are therefore enumerated by their OWN state, and their
--    grace window runs from the payment's creation rather than the booking's (a balance is chased weeks
--    after the deposit confirmed the booking, so keying its window off b.created_at would drop it).
--
--    `distinct on` keys on (booking, purpose) so a booking carrying a paid deposit and a stuck balance
--    surfaces the balance.
-- ---------------------------------------------------------------------------
create or replace function api_pending_payment_checkouts(p jsonb)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object('ref', t.ref, 'paymentId', t.payment_id, 'checkoutId', t.provider_checkout_id)
      order by t.created_at desc
    ),
    '[]'::jsonb
  )
  from (
    -- latest payment per booking+purpose (a re-pay opens a fresh checkout the sweep must query), then
    -- the most-recent stuck rows up to the batch cap. The two orderings need separate query levels:
    -- distinct-on requires its leading sort be (b.id, pay.purpose, pay.created_at), so recency + limit
    -- wrap it.
    -- LATERAL over (current, previous) checkout ids: a customer can complete a checkout minted
    -- before a re-pay overwrote the pointer (Peach sessions stay completable ~30 min) -- sweeping
    -- both ids means that capture is ingested instead of stranded.
    select c.ref, c.payment_id, v.checkout_id as provider_checkout_id, c.created_at
    from (
      select distinct on (b.id, pay.purpose)
             b.id, b.ref,
             -- For an add-on OR a balance, from whichever is later: the row is created when the guest
             -- commits (the add-on's ADDRESS, or the balance link), but they can mint the Peach session
             -- on it hours -- for a balance, weeks -- later, and the grace window has to cover the
             -- session, not the intent.
             case when pay.purpose in ('pickup_addon', 'balance')
                  then greatest(pay.created_at, coalesce(pay.checkout_created_at, pay.created_at))
                  else b.created_at end as created_at,
             pay.id as payment_id, pay.provider_checkout_id, pay.prev_provider_checkout_id
        from bookings b
        join payments pay on pay.booking_id = b.id
       where (
               (pay.purpose = 'booking'
                 and b.status = 'payment_pending'
                 and b.payment_state in ('pending', 'failed'))
               or
               (pay.purpose = 'pickup_addon' and pay.status in ('pending', 'failed'))
               or
               -- The balance lives on a CONFIRMED booking, so it is swept by the payment row's OWN state,
               -- exactly like the add-on -- never by b.status, which the `booking` branch keys on.
               (pay.purpose = 'balance' and pay.status in ('pending', 'failed'))
             )
         and (case when pay.purpose in ('pickup_addon', 'balance')
                   then greatest(pay.created_at, coalesce(pay.checkout_created_at, pay.created_at))
                   else b.created_at end)
               > now() - make_interval(
                   mins => least(greatest(coalesce((p ->> 'graceMinutes')::int, 240), 1), 10080)
                 )
         and pay.provider_checkout_id is not null
         and not exists (
               select 1 from payment_events pe
                where pe.payment_id = pay.id and pe.type in ('paid', 'refunded')
             )
       order by b.id, pay.purpose, pay.created_at desc
    ) c
    cross join lateral (values (c.provider_checkout_id), (c.prev_provider_checkout_id)) as v(checkout_id)
    where v.checkout_id is not null
    -- recency-ordered batch, capped (default 100, hard ceiling 1000) to bound Peach API calls per run
    order by c.created_at desc
    limit least(greatest(coalesce((p ->> 'limit')::int, 100), 1), 1000)
  ) t;
$$;

revoke execute on function api_pending_payment_checkouts(jsonb) from public, anon, authenticated;
grant execute on function api_pending_payment_checkouts(jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- 9) booking_json — the 20260908000000 body VERBATIM plus `pendingPickup`, so the booking page can
--    tell "you still owe us an address" from "we're waiting for your supplement to settle" (and keep
--    polling through the second one — the status-based poll stops dead on a confirmed booking).
--    STAYS `security invoker`: the guest reads their own request row through its RLS policy.
-- ---------------------------------------------------------------------------
create or replace function booking_json(p_booking_id uuid)
returns jsonb
language sql
stable
security invoker
set search_path = public
as $$
  select jsonb_build_object(
    'id', b.id, 'ref', b.ref, 'status', b.status, 'paymentState', b.payment_state,
    'customerName', b.customer_name, 'customerEmail', b.customer_email,
    'totalEur', b.total_minor::float / 100, 'currency', b.currency, 'source', b.source,
    'createdAt', b.created_at,
    'customItinerary', b.custom_itinerary,
    'pickupLocation', b.pickup_location,
    'dropoffLocation', b.dropoff_location,
    'pickupPending', b.pickup_pending,
    'pickupHotelSlug', b.pickup_hotel_slug,
    'childSeats', b.child_seats,
    'transportEur', b.transport_minor::float / 100,
    'supplements', coalesce((
      select jsonb_agg(jsonb_build_object(
        'name', bs.name, 'qty', bs.qty,
        'unitEur', bs.unit_minor::float / 100, 'totalEur', bs.total_minor::float / 100
      ) order by bs.position, bs.name)
      from booking_supplements bs where bs.booking_id = b.id
    ), '[]'::jsonb),
    'pendingPickup', (
      select jsonb_build_object(
        'pickupLocation', r.pickup_location,
        'dropoffLocation', r.dropoff_location,
        'feeEur', r.fee_minor::float / 100,
        'paymentId', r.payment_id,
        'createdAt', r.created_at
      )
      from booking_pickup_requests r
      where r.booking_id = b.id and r.applied_at is null and r.fee_minor > 0
      order by r.created_at desc
      limit 1
    ),
    'pickupRegion', b.pickup_region,
    'tripType', b.trip_type,
    'tripDirection', b.trip_direction,
    'flightNumber', b.flight_number,
    'arrivalTime', b.arrival_time,
    'returnDate', b.return_date,
    'returnTime', b.return_time,
    'departureFlightNumber', b.departure_flight_number,
    'roomOrCabin', b.room_or_cabin,
    'luggageDetails', b.luggage_details,
    'childSeatAge', b.child_seat_age,
    'travellerGender', b.traveller_gender,
    'travellerCompany', b.traveller_company,
    'travellerCountry', b.traveller_country,
    'specialNotes', b.special_notes,
    'disruption', b.disruption,
    'partySize', coalesce((
      select sum(coalesce(bi.pax, bi.quantity))
        from booking_items bi where bi.booking_id = b.id
    ), 0),
    -- The BOOKING-UNIT count, the unit seatsLeft is denominated in. For a per-person option it equals
    -- partySize; for a vehicle/private one it is 1 (one van / one trip, any group size). The date
    -- picker must filter on THIS, not partySize, or a 6-guest transfer is offered nothing.
    'unitsNeeded', coalesce((
      select sum(bi.quantity)
        from booking_items bi where bi.booking_id = b.id
    ), 0),
    'activityOptionId', (
      select bi.activity_option_id
        from booking_items bi where bi.booking_id = b.id order by bi.id limit 1
    ),
    'activitySlug', (
      select a.slug
        from booking_items bi
        join activity_options ao on ao.id = bi.activity_option_id
        join activities a on a.id = ao.activity_id
       where bi.booking_id = b.id
       order by bi.id limit 1
    ),
    'cancellable', (
      b.status = 'confirmed' and b.payment_state = 'paid'
      and (
        booking_awaiting_choice(b.disruption)
        or coalesce((
          select min(so.starts_at)
            from booking_items bi
            join session_occurrences so on so.id = bi.session_occurrence_id
           where bi.booking_id = b.id
        ), 'epoch'::timestamptz) > now() + interval '24 hours'
      )
    ),
    'reschedulable', (
      b.status = 'confirmed' and b.payment_state = 'paid'
      and (
        booking_awaiting_choice(b.disruption)
        or coalesce((
          select min(so.starts_at)
            from booking_items bi
            join session_occurrences so on so.id = bi.session_occurrence_id
           where bi.booking_id = b.id
        ), 'epoch'::timestamptz) > now() + interval '24 hours'
      )
    ),
    'serviceDate', (
      select min(so.starts_at)
        from booking_items bi
        join session_occurrences so on so.id = bi.session_occurrence_id
       where bi.booking_id = b.id
    ),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'priceLabel', bi.price_label, 'quantity', bi.quantity, 'pax', bi.pax,
        'unitAmountEur', bi.unit_amount_minor::float / 100, 'subtotalEur', bi.subtotal_minor::float / 100,
        'occurrenceId', bi.session_occurrence_id
      ))
      from booking_items bi where bi.booking_id = b.id
    ), '[]'::jsonb)
  )
  from bookings b where b.id = p_booking_id;
$$;

-- ---------------------------------------------------------------------------
-- 10) api_enqueue_pickup_reminders — the 48h / 24h chase.
--
--     Service-role only (the maintenance cron), and modelled on api_enqueue_review_invites: find the
--     candidates, insert the outbox rows, let the drain send them.
--
--     THE SIGNATURE IS LOAD-BEARING. It takes a single defaulted jsonb `p` it never reads, because the
--     shared Supabase adapter (src/lib/supabase/rpc.ts) invokes EVERY api_* function as fn(p := jsonb).
--     A niladic function is invisible to PostgREST through that adapter — it 404s with PGRST202, the
--     maintenance route 503s on every tick, and no reminder is ever sent. That is not hypothetical:
--     20260828000000_review_invites_p_arg.sql exists solely because api_enqueue_review_invites shipped
--     niladic and silently sent nothing for weeks. Its integration test masked it exactly the way one
--     here would — by calling `select api_enqueue_pickup_reminders()` directly, bypassing the wrapper.
--
--     No Mauritius-time bucketing here and none is needed: these are intervals BEFORE a timestamptz,
--     not calendar days, so the timezone landmine does not apply.
-- ---------------------------------------------------------------------------
drop function if exists public.api_enqueue_pickup_reminders();

create or replace function api_enqueue_pickup_reminders(p jsonb default '{}'::jsonb)
returns int
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_count int := 0;
  v_candidate record;
begin
  if auth.role() <> 'service_role' then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  for v_candidate in (
    select b.id as booking_id, b.ref, b.customer_email, b.customer_name, b.locale::text as locale,
           a.title as activity_title, fo.starts_at,
           case when fo.starts_at <= now() + interval '24 hours' then 24 else 48 end as window_hours,
           -- The eligibility ladder, evaluated ONCE per candidate. It gates the guest chase (there is
           -- no point mailing "add it now" to someone the booking page will refuse) but deliberately
           -- NOT the owner escalation — see the split below.
           pickup_addon_quote(b.id, null, null) ->> 'reason' as refusal
    from bookings b
    join lateral (
      select min(so.starts_at) as starts_at
        from booking_items bi
        join session_occurrences so on so.id = bi.session_occurrence_id
       where bi.booking_id = b.id
    ) fo on true
    join lateral (
      select a2.title
        from booking_items bi
        join activity_options o on o.id = bi.activity_option_id
        join activities a2 on a2.id = o.activity_id
       where bi.booking_id = b.id
       order by bi.id
       limit 1
    ) a on true
    where b.status = 'confirmed'
      and coalesce(b.pickup_pending, false)
      and b.pickup_location is null
      and b.customer_email is not null
      and fo.starts_at > now()
      and fo.starts_at <= now() + interval '48 hours'
  )
  loop
    -- A trip that has departed or been called off needs no signal to anyone; every OTHER refusal
    -- (no pickup service on this activity, a pricing mode the add-on does not serve) still leaves a
    -- guest the owner must collect, so it must still reach the owner below.
    if v_candidate.refusal in ('departed', 'departure_cancelled', 'pickup_not_pending') then
      continue;
    end if;

    -- Guest chase: only when they can actually comply. Chasing someone whose booking page answers
    -- "this trip doesn't include a pickup service" is a demand with no way to satisfy it.
    if v_candidate.refusal is null then
    insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
    values (
      'email', v_candidate.customer_email, 'pickup_reminder',
      jsonb_build_object(
        'ref', v_candidate.ref,
        'customerName', v_candidate.customer_name,
        'activityTitle', v_candidate.activity_title,
        'startsAt', v_candidate.starts_at,
        'hoursBefore', v_candidate.window_hours,
        'locale', v_candidate.locale
      ),
      v_candidate.booking_id,
      -- The DEPARTURE is part of the key, not just the booking. A reschedule keeps the booking id, so
      -- a booking-scoped key would let the first date's chase permanently suppress the new date's —
      -- the driver arrives at a rearranged trip with no address and nobody warned.
      'pickup_reminder_' || v_candidate.window_hours::text || ':' || v_candidate.booking_id::text
        || ':' || to_char(v_candidate.starts_at at time zone 'UTC', 'YYYYMMDDHH24MI')
    )
    on conflict (idempotency_key) do nothing;
    end if;

    -- The owner nudge fires at the 24h mark only: at 48h the guest still has plenty of time, and an
    -- alert the owner cannot act on yet is an alert they learn to ignore. It fires whether or not the
    -- guest could be chased — a booking that still says "pickup to be arranged" the day before
    -- departure is exactly the thing the owner must know about, and on an activity with no online
    -- pickup service they are the ONLY one who can resolve it. `refusal` rides along so the alert can
    -- say whether the guest was chased twice or never chased at all.
    if v_candidate.window_hours = 24 then
      insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
      values (
        'email', 'owner', 'owner_pickup_missing',
        jsonb_build_object(
          'ref', v_candidate.ref,
          'customerName', v_candidate.customer_name,
          'activityTitle', v_candidate.activity_title,
          'startsAt', v_candidate.starts_at,
          'guestChased', (v_candidate.refusal is null),
          'refusal', v_candidate.refusal
        ),
        v_candidate.booking_id,
        'pickup_missing_owner:' || v_candidate.booking_id::text
          || ':' || to_char(v_candidate.starts_at at time zone 'UTC', 'YYYYMMDDHH24MI')
      )
      on conflict (idempotency_key) do nothing;
    end if;

    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;

revoke execute on function api_enqueue_pickup_reminders(jsonb) from public, anon, authenticated;
grant execute on function api_enqueue_pickup_reminders(jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- 11) append_payment_event - the 20260902000000 body VERBATIM with ONE condition added to the
--     refunded branch.
--
--     That branch wrote BOOKING-level state from a SINGLE payments row: any row reaching 'refunded'
--     stamped `bookings.status = 'refunded'` and released the holds. It predates multi-purpose rows
--     and is the same class of bug as the sticky payment_state latch fixed in 20260902000000 - a
--     booking-level projection derived from one child row.
--
--     With a second row it is live: refund the EUR 30 transport supplement in Peach (a legitimate
--     thing to do when a pickup cannot be serviced) and a fully-paid EUR 500 booking reads 'refunded'
--     on the guest's page and in /admin while the trip is still on and the money is still held - its
--     seats freed, its cancel/reschedule affordances gone, and a "your booking has been refunded"
--     email sent.
--
--     The roll-up `v_booking_state` computed above is already the honest booking-level answer (it
--     ranks paid > partially_refunded > refunded), so the transition now requires it: the booking
--     flips to refunded only when NO row of it still holds money. The single-payment case - every
--     booking that never had an add-on - projects exactly what it projected before.
-- ---------------------------------------------------------------------------

create or replace function append_payment_event(
  p_payment_id uuid,
  p_type text,
  p_provider_event_id text,
  p_amount_minor bigint,
  p_occurred_at timestamptz,
  p_payload jsonb
)
returns payments
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payment payments;
  v_paid bigint;
  v_refunded bigint;
  v_failed boolean;
  v_state payment_state;
  v_booking_state payment_state;
  v_booking_status booking_status;
  v_occ_id uuid;
  v_needed bigint;
  v_cap bigint;
  v_used_conf bigint;
  v_used_hold bigint;
  v_oversold boolean := false;
  v_called_off boolean := false;
begin
  select * into v_payment from payments where id = p_payment_id for update;
  if not found then
    raise exception 'payment_not_found';
  end if;

  insert into payment_events (payment_id, type, provider_event_id, amount_minor, occurred_at, payload)
  values (
    p_payment_id, p_type, p_provider_event_id, coalesce(p_amount_minor, 0),
    coalesce(p_occurred_at, now()), coalesce(p_payload, '{}'::jsonb)
  )
  on conflict (payment_id, provider_event_id, type) do nothing;

  select
    coalesce(sum(amount_minor) filter (where type in ('paid', 'captured')), 0),
    coalesce(sum(amount_minor) filter (where type = 'refunded'), 0),
    bool_or(type = 'failed')
  into v_paid, v_refunded, v_failed
  from payment_events
  where payment_id = p_payment_id;

  if v_paid > 0 and v_refunded >= v_paid then
    v_state := 'refunded';
  elsif v_paid > 0 and v_refunded > 0 then
    v_state := 'partially_refunded';
  -- amount_minor > 0: a zero-amount payment must never read as fully paid (0 >= 0) -- the 'failed'
  -- branch below has to win for it.
  elsif v_payment.amount_minor > 0 and v_paid >= v_payment.amount_minor then
    v_state := 'paid';
  elsif v_paid > 0 then
    v_state := 'pending'; -- underpaid: do not confirm
  elsif coalesce(v_failed, false) then
    v_state := 'failed';
  else
    v_state := 'pending';
  end if;

  update payments
  set status = v_state, paid_minor = v_paid, refunded_minor = v_refunded, updated_at = now()
  where id = p_payment_id
  returning * into v_payment;

  -- MORE money than we asked for, on one payments row. Nothing else in this system can see that: the
  -- reducer's own branches all read `>= amount_minor`, so a second capture on an already-paid row is
  -- indistinguishable from the first, and the late-pickup apply trigger cannot re-fire on it. It
  -- should be impossible — but "impossible" is what the double-charge guards keep discovering it is
  -- not, and the only honest response to money we did not ask for is to tell someone who can return it.
  if v_payment.amount_minor > 0 and v_paid > v_payment.amount_minor then
    insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
    select 'email', 'owner', 'owner_overpayment',
           jsonb_build_object(
             'ref', b.ref,
             'customerName', b.customer_name,
             'expectedEur', v_payment.amount_minor::float / 100,
             'paidEur', v_paid::float / 100,
             'purpose', v_payment.purpose
           ),
           b.id,
           'overpaid:' || v_payment.id::text
      from bookings b where b.id = v_payment.booking_id
    on conflict (idempotency_key) do nothing;
  end if;

  -- BOOKING-level projection, rolled up across every payment row of this booking -- best row wins,
  -- and 'failed' only when EVERY row failed. Written from the single touched row it was a latch: one
  -- declined attempt stamped the booking 'failed' forever (nothing else writes this column), which
  -- silently removed it from api_pending_payment_checkouts and run_booking_maintenance. Ranking
  -- rather than re-summing the ledger keeps this a pure widening: a booking with one payment row --
  -- every booking that never hit the fork -- projects exactly what it projected before.
  -- Ordered paid > partially_refunded > refunded > pending > failed: with two rows after a double
  -- charge, one refunded and one not, money is still held and 'paid' is the honest answer.
  select case min(
           case pay.status
             when 'paid' then 1
             when 'partially_refunded' then 2
             when 'refunded' then 3
             when 'pending' then 4
             when 'failed' then 5
           end
         )
         when 1 then 'paid'
         when 2 then 'partially_refunded'
         when 3 then 'refunded'
         when 5 then 'failed'
         else 'pending'
         end::payment_state
    into v_booking_state
    from payments pay
   where pay.booking_id = v_payment.booking_id;

  update bookings set payment_state = coalesce(v_booking_state, v_state), updated_at = now()
  where id = v_payment.booking_id;

  -- Confirmation stays driven by THIS row reaching 'paid' (v_state), never by the roll-up: a row
  -- that just captured the full amount is what licenses confirming, and reusing the roll-up here
  -- would re-run the capacity re-check on every later event of an already-paid booking.
  if v_state = 'paid' then
    select status into v_booking_status from bookings where id = v_payment.booking_id;

    if v_booking_status in ('draft', 'held', 'payment_pending') then
      -- Re-validate capacity per occurrence, excluding this booking's own items/holds.
      for v_occ_id in
        select distinct session_occurrence_id from booking_items where booking_id = v_payment.booking_id
      loop
        perform 1 from session_occurrences where id = v_occ_id for update;
        select coalesce(sum(quantity), 0) into v_needed
        from booking_items where booking_id = v_payment.booking_id and session_occurrence_id = v_occ_id;
        select capacity into v_cap from session_occurrences where id = v_occ_id;
        select coalesce(sum(bi.quantity), 0) into v_used_conf
        from booking_items bi join bookings b on b.id = bi.booking_id
        where bi.session_occurrence_id = v_occ_id
          and b.status in ('confirmed', 'completed')
          and b.id <> v_payment.booking_id;
        select coalesce(sum(h.quantity), 0) into v_used_hold
        from booking_holds h
        where h.session_occurrence_id = v_occ_id
          and h.status = 'active' and h.expires_at > now()
          and (h.booking_id is null or h.booking_id <> v_payment.booking_id);
        if v_needed > v_cap - v_used_conf - v_used_hold then
          v_oversold := true;
        end if;
      end loop;

      -- Was the departure called off while this payment was in flight?
      --
      -- Confirming here would tell the guest they are booked onto a trip that is not running. Worse,
      -- they could never be put right afterwards: api_weather_cancel_occurrence stamps only bookings
      -- that were ALREADY confirmed+paid when it ran, and it refuses to re-run on an occurrence it
      -- has already cancelled — so this booking would never receive a `disruption` stamp, and that
      -- stamp is the ONLY thing that opens the 24h bypass in api_cancel_booking and
      -- api_reschedule_booking (via booking_awaiting_choice). Charged, told "confirmed", and locked
      -- out of both the refund and the free reschedule /refunds promises.
      --
      -- Route the money back instead — the same answer this function already gives when the seats
      -- turn out to be gone (oversold) or the booking is no longer live. refund_pending frees the
      -- capacity immediately and fires enqueue_booking_notification's refund_pending branch, so the
      -- owner gets a work item and the guest is told.
      select exists (
        select 1
          from booking_items bi
          join session_occurrences so on so.id = bi.session_occurrence_id
         where bi.booking_id = v_payment.booking_id
           and so.status = 'cancelled'
      ) into v_called_off;

      if v_oversold or v_called_off then
        update bookings set status = 'refund_pending', updated_at = now() where id = v_payment.booking_id;
      else
        update bookings set status = 'confirmed', updated_at = now() where id = v_payment.booking_id;
        update booking_holds set status = 'consumed'
        where booking_id = v_payment.booking_id and status = 'active';
      end if;
    elsif v_booking_status not in ('confirmed', 'completed') then
      -- Money captured on an expired/cancelled booking: must be refunded, not confirmed.
      update bookings set status = 'refund_pending', updated_at = now() where id = v_payment.booking_id;
    end if;
  elsif v_state = 'refunded' and coalesce(v_booking_state, v_state) = 'refunded' then
    update bookings set status = 'refunded', updated_at = now()
    where id = v_payment.booking_id and status <> 'cancelled';
    update booking_holds set status = 'released'
    where booking_id = v_payment.booking_id and status = 'active';
  end if;

  return v_payment;
end;
$$;

revoke execute on function append_payment_event(uuid, text, text, bigint, timestamptz, jsonb) from public, anon, authenticated;
grant execute on function append_payment_event(uuid, text, text, bigint, timestamptz, jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- 12) api_mark_refunded - the 20260726000000 body, re-pointed from "the newest payments row" to
--     "every row of this booking that still holds money".
--
--     `order by created_at desc limit 1` meant the staff "Mark refunded" button reversed whichever row
--     was newest. After a late-pickup supplement settles that is ALWAYS the add-on row, so an owner
--     who refunded EUR 530 in Peach recorded a EUR 30 refund against the supplement, left the EUR 500
--     booking payment reading paid_minor = 50000 / refunded_minor = 0 - and could never fix it,
--     because the `alreadyRefunded` short-circuit fires on the second click and the booking-status
--     gate rejects every call after that. (The admin dialog quotes `netPaidEur`, which sums across
--     rows, so the owner was told EUR 530 while the RPC reversed EUR 30.)
--
--     A merely PENDING add-on row was worse: the `v_payment.status in ('paid','partially_refunded')`
--     gate saw 'pending' and raised not_refundable, so a guest who opened a supplement checkout and
--     abandoned it made their whole booking impossible to mark refunded.
--
--     Now: loop every money-holding row oldest-first, reverse each one's own outstanding amount
--     through append_payment_event, and move BOTH gates (idempotency and not_refundable) from "the
--     newest row" to "does any row of this booking still hold money". The event id is per-payment
--     ('manual:refund:<payment id>') - the ledger's conflict target is (payment_id,
--     provider_event_id, type), so replay-idempotency is preserved while two rows no longer collide
--     on one key.
-- ---------------------------------------------------------------------------
create or replace function api_mark_refunded(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking_id uuid := nullif(p ->> 'bookingId', '')::uuid;
  v_booking bookings;
  v_payment payments;
  v_amount bigint;
  v_reversed int := 0;
begin
  if not is_staff() then
    raise exception 'forbidden';
  end if;
  if v_booking_id is null then
    raise exception 'invalid_request' using detail = 'mark_refunded: bookingId required';
  end if;

  select * into v_booking from bookings where id = v_booking_id;
  if not found then
    raise exception 'booking_not_found';
  end if;

  if not exists (select 1 from payments where booking_id = v_booking_id) then
    raise exception 'payment_not_found';
  end if;

  -- Already fully reversed -> no-op (idempotent: a repeat click must not error or re-enqueue). Asked
  -- of the WHOLE booking, not of one row: with two rows, "the newest is refunded" was true while the
  -- booking payment was still fully held.
  if not exists (
    select 1 from payments
     where booking_id = v_booking_id
       and (status in ('paid', 'partially_refunded') or paid_minor > refunded_minor)
  ) then
    return jsonb_build_object('ok', true, 'alreadyRefunded', true);
  end if;

  -- Only a booking whose money is actually held may be refunded: the cancel path lands it in
  -- refund_pending (payment_state stays paid), or staff refund a confirmed/completed paid booking
  -- directly. Anything else (unpaid, draft, already cancelled with no money) is rejected. The payment
  -- half of the gate is the `not exists` above - a pending sibling row must not veto the refund.
  if v_booking.status not in ('refund_pending', 'confirmed', 'completed') then
    raise exception 'not_refundable'
      using detail = format('booking %s', v_booking.status);
  end if;

  -- Reverse the full outstanding (paid - already-refunded) amount of EVERY row that still holds money,
  -- oldest first, so the booking-level roll-up inside append_payment_event only reaches 'refunded' on
  -- the last one. append_payment_event derives the refunded state from the SUM of refund events.
  for v_payment in
    select * from payments
     where booking_id = v_booking_id
       and (status in ('paid', 'partially_refunded') or paid_minor > refunded_minor)
     order by created_at
  loop
    v_amount := greatest(v_payment.paid_minor - v_payment.refunded_minor, 0);
    if v_amount > 0 then
      -- Record through the SAME path the webhook uses. The synthesised provider_event_id makes it
      -- idempotent at the ledger: a second call with the same id hits the
      -- (payment_id, provider_event_id, type) conflict and is a no-op, so the booking_refunded enqueue
      -- (which also guards old.status is distinct from 'refunded') never double-fires.
      perform append_payment_event(
        v_payment.id,
        'refunded',
        'manual:refund:' || v_payment.id::text,
        v_amount,
        now(),
        jsonb_build_object('source', 'admin_mark_refunded', 'bookingId', v_booking_id)
      );
      v_reversed := v_reversed + 1;
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'paymentsReversed', v_reversed);
end;
$$;

revoke execute on function api_mark_refunded(jsonb) from public;
grant execute on function api_mark_refunded(jsonb) to authenticated, service_role;


-- ---------------------------------------------------------------------------
-- 13) api_booking_receipt - the payment select scoped to `purpose = 'booking'`, the settled
--     supplement folded into the charged figure, AND the `booking_custom_items` union that
--     20260909000000_quotes.sql section 7b added.
--
--     THE SCOPING FIX: this body picked "the booking's most recent payment" unscoped, so once a
--     supplement settled the VAT invoice reported the ADD-ON's charge, timestamp and provider
--     reference as the booking's: a EUR 150 invoice showing MUR 1,590 settled on the wrong date
--     under the wrong reference, with buildPaymentBlock deriving an FX rate of ~10 against a real
--     ~53. That is a customer-facing tax document and the owner's own refund evidence.
--
--     THE UNION, and why it is HERE rather than only in the file that wrote it: this repo's rule is
--     "the LAST migration to define a function wins", and this file is that migration. 20260909000000
--     taught api_booking_receipt to read `booking_custom_items` — a converted quote's lines live in
--     that table and NOWHERE else (api_convert_quote refuses a catalogue line, so such a booking has
--     ZERO booking_items) - and this definition, written from a body that predated it, silently threw
--     the union away on every database built from the directory. buildInvoice backs the 15% out of
--     the gross PER LINE and sums, so with no lines `subtotalNetEur` is 0 and
--     `vatAmountEur = round2(totalGrossEur - 0)` becomes the WHOLE charge: a EUR 1200 quote was
--     invoiced as EUR 1200 of VAT, with nothing itemised beneath it, and the confirmation email, the
--     invoice PDF and the voucher all render off that same model. Merged in below rather than
--     re-applied over the top, so this file carries BOTH contracts and no third migration is needed.
--     tests/integration/resolved-function-bodies.test.ts reads pg_proc.prosrc and fails if a future
--     re-definition drops either one again.
-- ---------------------------------------------------------------------------

create or replace function api_booking_receipt(p jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_booking_id uuid := nullif(p ->> 'bookingId', '')::uuid;
  v_base jsonb;
  v_title text;
  v_when timestamptz;
  v_payment jsonb;
  v_phone text;
  v_locale text;
  v_addon_charged bigint := 0;
  v_custom jsonb;
begin
  if v_booking_id is null then
    raise exception 'invalid_request' using detail = 'booking_receipt: bookingId required';
  end if;

  v_base := booking_json(v_booking_id);
  if v_base is null then
    return null;
  end if;

  -- Primary activity title + the earliest trip date, joined off the booking's items.
  select a.title, o.starts_at
    into v_title, v_when
    from booking_items bi
    join session_occurrences o on o.id = bi.session_occurrence_id
    join activity_options ao on ao.id = bi.activity_option_id
    join activities a on a.id = ao.activity_id
   where bi.booking_id = v_booking_id
   order by o.starts_at asc, bi.created_at asc
   limit 1;

  -- The booking's most recent payment, with the real charge (or the EUR ledger fallback), the paid
  -- timestamp (first 'paid' event) and the provider event ref.
  select jsonb_build_object(
           'chargedAmountMinor', coalesce(pay.charged_amount_minor, pay.amount_minor),
           'chargedCurrency', coalesce(pay.charged_currency, pay.currency),
           'paidAt', paid.occurred_at,
           'providerRef', paid.provider_event_id
         )
    into v_payment
    from payments pay
    left join lateral (
      select pe.occurred_at, pe.provider_event_id
        from payment_events pe
       where pe.payment_id = pay.id and pe.type in ('paid', 'captured')
       order by pe.occurred_at asc
       limit 1
    ) paid on true
   where pay.booking_id = v_booking_id
     and pay.purpose = 'booking'
   order by pay.created_at desc
   limit 1;

  -- A settled late-pickup supplement is a SECOND charge on the same card, and its fare is already
  -- inside the booking's total_minor - so the receipt's charged figure has to include it, or the
  -- invoice states that a EUR 150 order settled with the EUR 120 charge and buildPaymentBlock's
  -- derived fx rate (charged / total) becomes fiction. Summed only across rows in the SAME charge
  -- currency: a legacy EUR booking row and an MUR add-on cannot be added together, and omitting the
  -- add-on understates by less than a cross-currency sum would misstate.
  if v_payment is not null then
    select coalesce(sum(coalesce(pay.charged_amount_minor, pay.amount_minor)), 0)
      into v_addon_charged
      from payments pay
     where pay.booking_id = v_booking_id
       and pay.purpose = 'pickup_addon'
       and pay.paid_minor > 0
       -- APPLIED, not merely settled. apply_pickup_request adds the fare to total_minor only for a
       -- live booking on a running departure; a capture it refused leaves the total untouched, so
       -- folding its charge in here would print a charged figure the invoice's own lines do not add
       -- up to — and buildPaymentBlock derives its fx rate from charged/total.
       and exists (
         select 1 from booking_pickup_requests r
          where r.payment_id = pay.id and r.applied_at is not null
       )
       and coalesce(pay.charged_currency, pay.currency)
             is not distinct from (v_payment ->> 'chargedCurrency');
    if v_addon_charged > 0 then
      v_payment := v_payment || jsonb_build_object(
        'chargedAmountMinor', (v_payment ->> 'chargedAmountMinor')::bigint + v_addon_charged
      );
    end if;
  end if;

  -- The guest's stored booking locale (Task 15): the notification drain runs off-request (cron), so
  -- this is the only correct source for which language the confirmation email + PDFs render in.
  select b.customer_phone, b.locale::text into v_phone, v_locale from bookings b where b.id = v_booking_id;

  -- FROM 20260909000000 SECTION 7b - the priced lines that have no session_occurrence: a converted
  -- quote's lines today, rentals in Part 2. Empty (and therefore free) for every booking that has
  -- none, which is every ordinary catalogue booking.
  --   * `priceLabel` <- `description`. A custom line has no price label (it is not a catalogue price
  --     band) and `booking_custom_items.description` is NOT NULL precisely so the line stays readable
  --     on its own; receiptSchema types priceLabel as a required string, so this is the field it maps
  --     to. buildInvoice then renders "<activityTitle> - <priceLabel>", or just the label when the
  --     booking has no activity behind it, which a quote booking does not.
  --   * `quantity` verbatim, and `pax` explicitly null - a custom line is priced per LINE, not per
  --     person, and buildInvoice reads `pax ?? quantity`, so null is what makes it use the quantity.
  --   * `subtotalEur` <- `subtotal_minor / 100.0`, the same minor->major conversion booking_json does
  --     for booking_items. `unitAmountEur` rides along so the two item shapes stay identical.
  select coalesce(jsonb_agg(jsonb_build_object(
           'priceLabel', ci.description,
           'quantity', ci.quantity,
           'pax', null::int,
           'unitAmountEur', ci.unit_amount_minor::float / 100,
           'subtotalEur', ci.subtotal_minor::float / 100
         ) order by ci.position), '[]'::jsonb)
    into v_custom
    from booking_custom_items ci
   where ci.booking_id = v_booking_id;

  -- Ordered by `position`, and APPENDED AFTER booking_json's own items - never merged into them.
  -- buildInvoice's own header notes that voucher-pdf.ts reads `lines[0].quantity` positionally for
  -- its pax count, so the catalogue lines must stay first for the day a booking carries both kinds.
  return v_base
    || jsonb_build_object('items', coalesce(v_base -> 'items', '[]'::jsonb) || v_custom)
    || jsonb_build_object('activityTitle', v_title, 'when', v_when)
    || jsonb_build_object('payment', coalesce(v_payment, 'null'::jsonb))
    || jsonb_build_object('customerPhone', v_phone)
    || jsonb_build_object('locale', v_locale);
end;
$$;

revoke execute on function api_booking_receipt(jsonb) from public, anon, authenticated;
grant execute on function api_booking_receipt(jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- 14) api_erase_user - the 20260909000000 body (the quotes-module version, which is the WINNING one:
--     it re-applied 20260816000000 and added the quotes erasure) with one statement added, deleting
--     the late-pickup request rows alongside the booking fields they duplicate.
--
--     Basing this on 20260816000000 instead - the last definition a naive grep surfaces - silently
--     reverts the quotes erasure and re-opens an Art. 17 hole in two other tables. That is
--     migration-revert drift, the worst landmine in docs/handbook/landmines.md, and the reason the
--     rule is "the LAST migration to define it wins", verified against the whole directory.
--
--     EVERY EMAIL COMPARE IN HERE GOES THROUGH quote_email_key (20260909000000, section 6c-bis), ON
--     BOTH OPERANDS. It used to normalise only the REQUEST - `lower(nullif(btrim(p ->> 'email'),''))`
--     - and then compare that against a raw `lower(customer_email)`, `lower(contact)` or
--     `lower(recipient)`. So the erasure's scope was "rows whose address is stored exactly as typed",
--     not "this person". `bookings.customer_email` and `quotes.customer_email` have no trimming
--     trigger and api_book / the quote editor store what they are handed, so an address pasted out of
--     a mail client - ' nina@example.com ' - really is what sits in the column, and NOTHING ON ANY
--     SCREEN SHOWS THE SPACE. That row fell outside the sweep and was retained forever with the
--     guest's name, address, phone and free text on it, while the call returned ok: true. An Art. 17
--     request quietly not honoured is the worst possible failure mode here, because the evidence that
--     it failed is the very data nobody can see.
--
--     The compare is therefore quote_email_key(customer_email) = v_email - the same shape the quote
--     owner match and the quote claim already use, and the same bug those two were written for (see
--     6c-bis: the owner btrimmed its argument, the claim did not, and a booking matched at payment
--     became unclaimable forever). One definition of "the same address", applied everywhere.
--
--     The columns are NOT all the same: bookings and quotes key on customer_email, leads on the
--     packed `contact` blob, and the outbox on `recipient` - so each call site is normalised on the
--     column it actually reads. The id-keyed statements (the booking_pickup_requests / outbox-payload
--     / bell / audit_logs scrubs off v_anon_ids, and the chat + profile deletes off v_uid) compare no
--     address at all and are left exactly as they were.
--
--     The REQUEST side was already trimmed on the staff path - `lower(nullif(btrim(...), ''))` is
--     literally quote_email_key inlined - so the mirror-image case (a clean stored address requested
--     WITH whitespace) was never broken there; it is routed through the function only so the rule is
--     stated once. The SELF-ERASE path was NOT: it read `lower(email)` from auth.users, untrimmed,
--     and would have compared '' rather than null for a blank one. That one is a real fix.
-- ---------------------------------------------------------------------------
create or replace function api_erase_user(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := nullif(p ->> 'userId', '')::uuid;
  -- quote_email_key IS `lower(nullif(btrim(...), ''))` - the request side was already correct, and is
  -- routed through the function so the rule has exactly one definition rather than a copy here.
  v_email text := quote_email_key(p ->> 'email');
  -- Non-paid booking statuses that are safe to hard-delete (only ever combined with payment_state pending).
  v_del_states text[] := array['draft', 'held', 'payment_pending', 'expired', 'cancelled', 'failed'];
  -- Paid / terminal statuses that must be retained (financial records) and only anonymized.
  v_anon_states text[] := array['confirmed', 'completed', 'refund_pending', 'refunded'];
  v_del_ids uuid[];
  v_anon_ids uuid[];
  v_del_bookings int := 0;
  v_anon_bookings int := 0;
  v_del_leads int := 0;
  v_del_quotes int := 0;
  v_anon_quotes int := 0;
begin
  -- Guard: staff, or the signed-in user erasing their own account.
  if not (is_staff() or (auth.uid() is not null and v_uid is not null and auth.uid() = v_uid)) then
    raise exception 'forbidden';
  end if;

  -- Bind the email scope to the CALLER'S identity for a non-staff self-erase. The caller-supplied email
  -- is untrusted: a signed-in user could pass a stranger's address and, because the row scope matches on
  -- quote_email_key(customer_email) = v_email, sweep that stranger's GUEST bookings/leads (user_id null)
  -- -- broken access control. So for non-staff we IGNORE the supplied email and force v_email to the
  -- caller's own JWT identity, read from auth.users (the SECURITY DEFINER owner can see it; auth.email()
  -- is not relied on here). This still catches the user's own pre-account guest bookings (made under
  -- their own email before they had an account), while making a stranger's email unreachable. Staff keep
  -- the supplied email -- they legitimately erase a pure-guest record by its address.
  --
  -- Through quote_email_key as well, so this branch cannot produce a v_email the request branch never
  -- could: `lower(email)` alone left any padding auth.users happens to carry, and turned a blank
  -- address into '' rather than null -- a value every `v_email is not null` guard below would wave
  -- through to match nothing.
  if not is_staff() then
    select quote_email_key(email) into v_email from auth.users where id = auth.uid();
  end if;

  if v_uid is null and v_email is null then
    raise exception 'invalid_request' using detail = 'erase_user: userId or email required';
  end if;

  -- ---- Hard-delete the non-retained (unpaid/abandoned) bookings + their children -------------------
  -- Identify them first; a booking matches by ownership OR guest email, must be in a deletable status
  -- AND have never carried money (payment_state pending). Anything paid is excluded here on purpose.
  select array_agg(id) into v_del_ids
    from bookings
   where ((v_uid is not null and user_id = v_uid)
          or (v_email is not null and quote_email_key(customer_email) = v_email))
     and status = any(v_del_states::booking_status[])
     and payment_state = 'pending';

  if v_del_ids is not null then
    -- FK order: holds (FK on delete set null, so delete explicitly) + items (cascades, but be explicit),
    -- then the parent bookings. payments cannot exist on a pending booking, so none to clear here.
    -- booking_custom_items cascades from bookings, so the quote's non-occurrence lines go with it.
    delete from booking_holds where booking_id = any(v_del_ids);
    delete from booking_items where booking_id = any(v_del_ids);
    delete from bookings where id = any(v_del_ids);
    get diagnostics v_del_bookings = row_count;
  end if;

  -- Snapshot the person's REMAINING booking ids now, before the anonymize below overwrites
  -- customer_email. The unpaid rows are already gone, so this is exactly the retained set; the
  -- outbox/bell/audit scrubs downstream target it by id so an email-only (guest) match is not lost.
  select coalesce(array_agg(id), '{}') into v_anon_ids
    from bookings
   where (v_uid is not null and user_id = v_uid)
      or (v_email is not null and quote_email_key(customer_email) = v_email);

  -- ---- Anonymize the retained (paid/terminal) bookings --------------------------------------------
  -- Keep the row + every financial column (total_minor, payouts, payment_state, status); strip the PII.
  -- customer_name + customer_email are NOT NULL in the schema, so they are redacted to placeholders
  -- (a routed-nowhere .invalid sentinel) rather than nulled. customer_phone + notes are nullable -> null.
  -- pickup_location / dropoff_location are addresses the customer typed -- PII, and not part of the
  -- retained money trail -- so they are nulled alongside the other traveller fields.
  -- This is an UPDATE that does NOT touch status, so the status-only enqueue trigger never re-fires.
  update bookings
     set customer_name = '(Deleted user)',
         customer_email = 'deleted@privacy.invalid',
         customer_phone = null,
         notes = null,
         pickup_location = null,
         dropoff_location = null,
         traveller_gender = null,
         traveller_company = null,
         traveller_country = null,
         special_notes = null,
         room_or_cabin = null,
         luggage_details = null,
         child_seat_age = null,
         flight_number = null,
         arrival_time = null,
         return_date = null,
         return_time = null,
         departure_flight_number = null
   where ((v_uid is not null and user_id = v_uid)
          or (v_email is not null and quote_email_key(customer_email) = v_email))
     and status = any(v_anon_states::booking_status[])
     -- idempotent: skip rows already anonymized (so a second call updates 0 rows, never re-counts).
     and customer_name is distinct from '(Deleted user)';
  get diagnostics v_anon_bookings = row_count;

  -- The late-pickup request rows hold their OWN copy of the address the guest typed, plus the exact
  -- GPS coordinates of where they were staying (20260910000000). Nulling bookings.pickup_location
  -- above leaves that copy untouched, and because a late pickup only ever exists on a confirmed+paid
  -- booking, every one of these rows belongs to the RETAINED set - it would survive erasure forever.
  --
  -- ANONYMIZED, not deleted. The row is also the receipt's evidence that a settled supplement was
  -- applied (api_booking_receipt folds a charge in only when applied_at is set), while its fare stays
  -- inside bookings.total_minor for good — so deleting it made the retained VAT invoice report a
  -- charge smaller than its own line items. Keep the money facts (fee_minor, applied_at, payment_id),
  -- strip the person.
  update booking_pickup_requests
     set pickup_location = null, pickup_lat = null, pickup_lng = null,
         pickup_region = null, dropoff_location = null, updated_at = now()
   where booking_id = any(v_anon_ids)
     and (pickup_location is not null or dropoff_location is not null
          or pickup_lat is not null or pickup_lng is not null);

  -- ---- Redact the notification outbox -------------------------------------------------------------
  -- Strip recipient (the email) + the customerName key from any queued/sent message for this person,
  -- matched by the recipient address OR by linkage to one of their (still-existing, anonymized) bookings.
  -- recipient is NOT NULL in the schema, so it is redacted to the sentinel rather than nulled. Removing
  -- customerName from the payload (jsonb - key) is a no-op when the key is already absent -> idempotent.
  update notification_outbox
     set recipient = 'deleted@privacy.invalid',
         payload = coalesce(
           (select jsonb_object_agg(k, v) from jsonb_each(payload) as e(k, v)
             where k in ('ref', 'activityTitle', 'startsAt', 'feeEur', 'totalMinor', 'currency',
                         'locale', 'hoursBefore', 'guestChased', 'refusal', 'token',
                         'previousStartsAt', 'reason', 'chargedAmountMinor', 'chargedCurrency')),
           '{}'::jsonb
         )
   where v_email is not null and quote_email_key(recipient) = v_email;
  -- Booking-linked rows keep their RECIPIENT -- they may address the OWNER (the 'owner' sentinel or
  -- the ops inbox), and severing that address would silently kill a pending owner alert for a real
  -- paid booking. Only the person's name leaves the payload. Matched by the pre-captured id set.
  update notification_outbox
     set payload = coalesce(
           (select jsonb_object_agg(k, v) from jsonb_each(payload) as e(k, v)
             where k in ('ref', 'activityTitle', 'startsAt', 'feeEur', 'totalMinor', 'currency',
                         'locale', 'hoursBefore', 'guestChased', 'refusal', 'token',
                         'previousStartsAt', 'reason', 'chargedAmountMinor', 'chargedCurrency')),
           '{}'::jsonb
         )
   where booking_id = any(v_anon_ids);
  -- Staff bell rows (admin_new_booking / admin_refund_pending) embed the customer's name in `body` --
  -- rebuild them anonymously so no feed retains PII after erasure.
  update notifications n
     set body = '(Deleted user) -- booking ' || coalesce(n.data ->> 'ref', '') || '.'
   where n.type in ('admin_new_booking', 'admin_refund_pending')
     and n.data ->> 'bookingId' = any(v_anon_ids::text[]);

  -- ---- Redact audit_logs diffs that captured this person's PII ------------------------------------
  -- Older admin actions may have snapshotted customer fields into diff. Null the diff on rows whose
  -- entity is one of their bookings (the anonymized financial rows). Counts only; we keep the action row.
  update audit_logs
     set diff = null
   where diff is not null
     and entity_type = 'booking'
     and entity_id = any(v_anon_ids);

  -- ---- Hard-delete the remaining personal data ----------------------------------------------------
  -- leads: PII lives in (name, contact); contact holds the email/phone. Delete by email match.
  -- NOT customer_email -- `contact` is the leads table's own column, so the normalisation goes on
  -- THAT one. (It is a packed "email · phone" blob, so an equality match only ever reaches a lead
  -- captured without a phone number; widening that is a separate question from this one, and
  -- deliberately not answered here.)
  if v_email is not null then
    delete from leads where quote_email_key(contact) = v_email;
    get diagnostics v_del_leads = row_count;
  end if;

  -- ---- Quotes: the offer the owner drafted for this person ----------------------------------------
  -- A quote that never minted a booking is not a financial record -> delete it and its lines outright
  -- (children first; quote_items cascades, but be explicit, exactly as the bookings block above is).
  -- A CONVERTED quote is retained and stripped instead. Keyed on converted_at, NOT booking_id: the
  -- bookings delete a few statements up nulls booking_id via its `on delete set null` FK.
  if v_email is not null then
    delete from quote_items qi
     using quotes q
     where qi.quote_id = q.id
       and quote_email_key(q.customer_email) = v_email
       and q.converted_at is null
       and q.booking_id is null;

    delete from quotes q
     where quote_email_key(q.customer_email) = v_email
       and q.converted_at is null
       and q.booking_id is null;
    get diagnostics v_del_quotes = row_count;

    -- Retained (converted) quotes: same redaction as the bookings they minted. internal_notes (staff
    -- free text) and intro_note (the guest-FACING covering note, which opens by addressing the guest
    -- by name) both routinely carry the guest, so they go too. Idempotent via the same
    -- already-anonymized skip.
    --
    -- `intro_note = null` IS FROM 20260909000000, and this definition was written from a body that
    -- predated it - so on a database built from the whole directory (this file is the LAST to define
    -- api_erase_user, and the last one wins) the column survived an Art. 17 erasure here. The only
    -- reason it did not survive in practice is the quotes_redact_lines() trigger, which fires on the
    -- same anonymize UPDATE and nulls it as a belt to these braces. That trigger STAYS - it also
    -- redacts the quote_items free text, which nothing in this statement reaches - but the
    -- function-level scrub is now correct on its own rather than depending on it.
    update quotes
       set customer_name = '(Deleted user)',
           customer_email = 'deleted@privacy.invalid',
           customer_phone = null,
           intro_note = null,
           internal_notes = null
     where quote_email_key(customer_email) = v_email
       and (converted_at is not null or booking_id is not null)
       and customer_name is distinct from '(Deleted user)';
    get diagnostics v_anon_quotes = row_count;
  end if;

  -- chat: messages cascade from sessions, but delete explicitly for clarity. By user only (no email link).
  if v_uid is not null then
    delete from chat_messages where session_id in (select id from chat_sessions where user_id = v_uid);
    delete from chat_sessions where user_id = v_uid;
    -- profile last (auth.users row itself is removed by the caller's service-role admin.deleteUser).
    delete from profiles where id = v_uid;
  end if;

  -- ---- One audit row, counts only (NO PII) -------------------------------------------------------
  insert into audit_logs (actor_id, actor_role, action, entity_type, entity_id, summary)
  values (
    auth.uid(),
    case when is_staff() then 'staff' else 'user' end,
    'erase_user',
    'user',
    v_uid,
    'gdpr erasure: deleted ' || v_del_bookings || ' booking(s), ' || v_del_leads
      || ' lead(s), ' || v_del_quotes || ' quote(s); anonymized ' || v_anon_bookings
      || ' retained booking(s), ' || v_anon_quotes || ' retained quote(s)'
  );

  return jsonb_build_object(
    'ok', true,
    'deletedBookings', v_del_bookings,
    'anonymizedBookings', v_anon_bookings,
    'deletedLeads', v_del_leads,
    'deletedQuotes', v_del_quotes,
    'anonymizedQuotes', v_anon_quotes
  );
end;
$$;

revoke execute on function api_erase_user(jsonb) from public, anon;
grant execute on function api_erase_user(jsonb) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 15) api_apply_funded_pickups — settle a supplement we already hold but could not apply.
--
--     apply_pickup_request refuses at settlement when the departure has been called off. The guest's
--     money is captured, the request stays open, and the owner is told to refund it — but the usual
--     next step is that the guest takes the RESCHEDULE arm onto a live date, at which point they still
--     want the pickup and we are still holding exactly the right amount for it. Leaving that to a
--     manual refund + a second payment is worse for everyone, and it is what made the double-charge
--     above reachable.
--
--     So the maintenance cron retries. apply_pickup_request re-checks every gate itself (booking live,
--     departure running, not already applied), which is what makes an unconditional retry safe: this
--     function only decides WHICH payments are worth re-offering to it.
-- ---------------------------------------------------------------------------
create or replace function api_apply_funded_pickups(p jsonb default '{}'::jsonb)
returns int
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_count int := 0;
  v_payment_id uuid;
  v_before timestamptz;
begin
  if auth.role() <> 'service_role' then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  for v_payment_id in
    select r.payment_id
      from booking_pickup_requests r
      join payments pay on pay.id = r.payment_id
     where r.applied_at is null
       and r.fee_minor > 0
       and pay.purpose = 'pickup_addon'
       and pay.paid_minor >= r.fee_minor
     order by r.created_at
  loop
    select applied_at into v_before from booking_pickup_requests where payment_id = v_payment_id;
    perform apply_pickup_request(v_payment_id);
    -- Count only what actually landed: the gates inside may still refuse (the trip is still called
    -- off), and this number is read by the cron's health verdict.
    if v_before is null and exists (
      select 1 from booking_pickup_requests where payment_id = v_payment_id and applied_at is not null
    ) then
      v_count := v_count + 1;
    end if;
  end loop;

  return v_count;
end;
$$;

revoke execute on function api_apply_funded_pickups(jsonb) from public, anon, authenticated;
grant execute on function api_apply_funded_pickups(jsonb) to service_role;


-- ---- migration 20260911000000_quote_checkout_entry (the quote path gets its own checkout entry) ----
-- ---------------------------------------------------------------------------
-- The quote path's own way into the checkout — WITHOUT relaxing the customer path.
--
-- THE DEFECT. api_create_payment ends its guard with
--     if not (is_staff() or (auth.uid() is not null and v_booking.user_id = auth.uid()))
-- which is exactly right for a customer checkout: the public booking ref travels in emails and URLs
-- and is NOT a bearer credential, so only the booking's owner (or staff) may open a payable session
-- against it. A QUOTE booking has `user_id` null — the guest has no account, which is the entire point
-- of an emailed offer — and POST /api/v1/quotes/{ref}/pay calls as service_role, for which auth.uid()
-- is null. Every quote payment was therefore refused with `forbidden`, and the module could not take a
-- cent end to end.
--
-- THE SHAPE OF THE FIX, decided by the owner: a SEPARATE entry point, not a softened guard. The path
-- every normal customer checkout takes is bit-for-bit what it was.
--
--   1. `create_payment(p, p_enforce_caller_identity)` — the WHOLE of the previous api_create_payment
--      body, moved here verbatim, with the caller-identity check made conditional and NOTHING else
--      changed: the same booking-payability guard, the same add-on branch, the same first-write-wins
--      FX pin, the same 25-minute reuse window and the same 90-second single-flight checkout lease.
--   2. `api_create_payment(p)` — a wrapper that calls it with the check ON. Same name, same signature,
--      same grants (authenticated + service_role), same behaviour for every existing caller.
--   3. `api_create_quote_payment(p)` — a wrapper that calls it with the check OFF, granted to
--      service_role ONLY.
--
-- WHY THE QUOTE PATH MAY SKIP THE CALLER-IDENTITY CHECK. Authorization for a quote is the LINK TOKEN,
-- not a session. The route reads the token from the httpOnly cookie the open route set (scoped to
-- `/api/v1/quotes/{ref}`), and `resolveQuoteForToken` verifies it against the stored SHA-256 and
-- collapses unknown ref / wrong token / unsent draft / withdrawn offer / lapsed validity into a single
-- refusal — all of that BEFORE this function is reached. So the identity check is not being waived;
-- a different, stronger credential has already been checked. Two things keep that sound in SQL:
--
--   * this entry point is SERVICE-ROLE ONLY. `revoke ... from public, anon, authenticated` (all three
--      roles named — `from public` alone leaves Supabase's stock direct grants in place, an omission
--      that has shipped a live hole from this repo three times), so nothing reachable from a browser
--      can call it and skip the token check that authorizes it;
--   * and it is narrowed to the quote path even for a server caller: a booking that no `quotes` row
--      points at is refused, so the bypass can never be aimed at an ordinary customer's booking.
--
-- WHY ONE SHARED BODY RATHER THAN A SECOND FUNCTION. The single-flight lease is what stops one booking
-- having two payable Peach sessions — Peach's nonce is per-REQUEST and never dedupes — and this repo
-- has shipped that exact defect once already (a declined card forked a second payable session, fixed in
-- ec5ebcf). A second copy of the lease is a second copy free to drift from the first the next time
-- either is edited. Sharing the body makes drift impossible: both entry points contend for the SAME
-- `payments.checkout_claimed_until` on the SAME payments row, which
-- tests/integration/quote-checkout-entry.test.ts asserts directly by having staff claim the lease
-- through api_create_payment and the quote entry point be told `checkoutPending`.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 1) create_payment — the shared body. INTERNAL: service_role only, and never called from the app
--    directly. The `p_enforce_caller_identity` argument IS the authorization decision, so a caller
--    able to reach this function could pass `false` for any booking; that is precisely why the grant
--    below names anon and authenticated.
--
--    The body is 20260910000000's api_create_payment verbatim apart from the one wrapped `if`.
-- ---------------------------------------------------------------------------
create or replace function create_payment(p jsonb, p_enforce_caller_identity boolean default true)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking bookings;
  v_payment payments;
  v_rate numeric;
  v_src text;
  v_at timestamptz;
  v_charged bigint;
  v_purpose text := coalesce(nullif(p ->> 'purpose', ''), 'booking');
  v_req booking_pickup_requests;
begin
  if v_purpose not in ('booking', 'pickup_addon') then
    raise exception 'invalid_payment_purpose' using detail = v_purpose;
  end if;

  -- FOR UPDATE: every concurrent create-payment call for one booking serialises on this row for the
  -- rest of the transaction. That closes two races at once: two callers both inserting a payments row
  -- below, and — via the checkout lease — two callers both getting a green light to mint a Peach
  -- session. Peach's nonce is unique per REQUEST (it never dedupes), so without this lease two tabs
  -- or a retry could create two independently payable sessions for the same booking.
  -- (It also makes the charge pin race-free: one caller pins, the loser re-reads the pinned row.)
  --
  -- It is also what serialises the two ENTRY POINTS against each other: a staff member opening the
  -- checkout for a quote booking through api_create_payment and the guest clicking Pay through
  -- api_create_quote_payment reach this same lock, this same payments row and this same lease.
  select * into v_booking from bookings where ref = p ->> 'bookingRef' for update;
  if not found then
    raise exception 'booking_not_found';
  end if;
  if v_purpose = 'booking' then
    if v_booking.status in ('confirmed', 'completed', 'cancelled', 'expired', 'refund_pending', 'refunded', 'failed')
       or v_booking.payment_state in ('paid', 'partially_refunded', 'refunded') then
      raise exception 'booking_not_payable' using detail = v_booking.status::text;
    end if;
  else
    -- The add-on's own payability: an open request must exist, and the trip must not have left.
    select * into v_req from booking_pickup_requests
     where booking_id = v_booking.id and applied_at is null and payment_id is not null;
    if not found then
      raise exception 'pickup_request_not_found';
    end if;
    -- …and it must not ALREADY hold the guest's money. A request refused at settlement (the departure
    -- was called off) stays open behind a payments row that is already 'paid'. If the trip is then
    -- rescheduled onto a live date the eligibility ladder goes green again, and without this guard
    -- the booking page's "Complete payment" button minted a SECOND Peach session on that same row —
    -- charging the card twice for one supplement, invisibly: the apply trigger cannot fire again
    -- (its WHEN clause needs old.status distinct from 'paid'), so no second alert is raised either.
    if exists (
      select 1 from payments pay
       where pay.id = v_req.payment_id and pay.paid_minor >= pay.amount_minor and pay.amount_minor > 0
    ) then
      raise exception 'pickup_already_paid';
    end if;
    if not coalesce((pickup_addon_quote(v_booking.id, v_req.pickup_lat, v_req.pickup_lng) ->> 'eligible')::boolean, false) then
      raise exception 'booking_not_payable' using detail = 'pickup_addon';
    end if;
  end if;
  -- THE CALLER-IDENTITY CHECK — unchanged, and still what api_create_payment enforces. It is skipped
  -- ONLY for a caller that has already proved a stronger, non-session credential: see the header, and
  -- api_create_quote_payment, which is the only function in the schema that passes `false`.
  if p_enforce_caller_identity
     and not (is_staff() or (auth.uid() is not null and v_booking.user_id = auth.uid())) then
    raise exception 'forbidden';
  end if;

  -- No `and status <> 'failed'`: that skipped the row a declined attempt had latched to 'failed' and
  -- minted a SECOND payments row, orphaning the checkout-reuse window and the single-flight lease
  -- (both columns on the skipped row) and leaving two independently payable Peach sessions.
  if v_purpose = 'booking' then
    select * into v_payment from payments
    where booking_id = v_booking.id and purpose = 'booking'
    order by created_at desc
    limit 1;

    if not found then
      -- Scoped to THIS booking: an unscoped key lookup let a caller echo another payment's key and
      -- receive that payment's id/amount back.
      select * into v_payment from payments
      where idempotency_key = p ->> 'idempotencyKey' and booking_id = v_booking.id and purpose = 'booking';
    end if;
  else
    -- Exactly the row the open request points at — never "the newest add-on row", which after a
    -- superseded request could be a different, abandoned one.
    select * into v_payment from payments where id = v_req.payment_id and purpose = 'pickup_addon';
  end if;

  if not found then
    if v_purpose <> 'booking' then
      -- api_request_pickup owns the add-on row (it is the only place that knows the fare). Never
      -- invent one here, or the amount would come from nowhere.
      raise exception 'pickup_request_not_found';
    end if;
    insert into payments (booking_id, idempotency_key, amount_minor, purpose)
    values (v_booking.id, p ->> 'idempotencyKey', v_booking.total_minor, 'booking')
    returning * into v_payment;
    insert into payment_events (payment_id, type, amount_minor)
    values (v_payment.id, 'intent', v_booking.total_minor);
  end if;

  -- ── Pin the charge (once per payment row) ────────────────────────────────────────────────────
  -- The EUR ledger total converted to WHOLE MUR RUPEES at the server-controlled rate. Derived here,
  -- in SQL, from fx_rates — NEVER from caller input (this function is granted to authenticated; a
  -- caller-supplied rate would let a booking owner pin their own MUR 0.05 charge). First-write-wins:
  -- every later call — every re-minted checkout session, the pay page, reconcile — reads THIS figure,
  -- so a moved FX rate between sessions can never make the charge and the expected settlement drift.
  if v_payment.charged_amount_minor is null and v_payment.amount_minor > 0 then
    select r.rate, r.source, r.fetched_at into v_rate, v_src, v_at
      from fx_rates r where r.base = 'EUR' and r.quote = 'MUR';
    -- Band-clamped on READ as well as write: an inverted or foreign payload that somehow reached the
    -- table (0.0185 would bill MUR 1.85 for a EUR 100 booking — and, because settled == charged,
    -- CONFIRM it) falls back to the floor instead of being trusted.
    if v_rate is null or v_rate < 40 or v_rate > 70 then
      v_rate := 53.00; -- cold-start floor; see the fx_rates seed comment (kept below mid on purpose)
      v_src := 'fallback';
      v_at := now();
    end if;
    -- Whole rupees: kills every sub-unit disagreement between what we send Peach and what Peach
    -- reports back. Costs at most MUR 0.50 (~EUR 0.01) per booking.
    v_charged := (round(v_payment.amount_minor * v_rate / 100.0) * 100)::bigint;
    update payments
       set charged_amount_minor = v_charged,
           charged_currency = 'MUR',
           charged_fx_rate = v_rate,
           charged_fx_source = v_src,
           charged_fx_at = v_at,
           updated_at = now()
     where id = v_payment.id and charged_amount_minor is null
     returning * into v_payment;
    if not found then
      -- Another transaction pinned first (or a legacy row already carried a charge): read the truth.
      select * into v_payment from payments where id = v_payment.id;
    end if;
  end if;

  -- Checkout lease (single-flight): exactly one caller may be out creating a Peach session at any
  -- moment. Order matters — reuse beats pending beats claim:
  --   1. a still-fresh recorded checkout        -> hand the SAME session back (reuse; no Peach call);
  --   2. someone else holds an unexpired lease  -> checkoutPending (caller retries shortly);
  --   3. otherwise                              -> stamp the lease and let THIS caller call Peach.
  -- api_record_payment_checkout clears the lease when the session id is recorded; a Peach failure
  -- releases it via api_release_checkout_claim, and the 90-second expiry is the crash backstop.
  --
  -- Freshness is measured from checkout_created_at (when the session was MINTED), never from
  -- updated_at: the reconcile sweep touches updated_at on every pass, which used to re-arm this
  -- window forever and trap the customer on a dead session. The caller still verifies liveness with
  -- the provider before actually reusing what this returns.
  if v_payment.provider_checkout_id is not null
     and coalesce(v_payment.checkout_created_at, v_payment.updated_at) > now() - interval '25 minutes' then
    return jsonb_build_object(
      'paymentId', v_payment.id, 'amountMinor', v_payment.amount_minor,
      'bookingRef', v_booking.ref, 'customerEmail', v_booking.customer_email,
      'existingCheckoutId', v_payment.provider_checkout_id,
      'chargedAmountMinor', v_payment.charged_amount_minor,
      'chargedCurrency', v_payment.charged_currency,
      'chargedFxRate', v_payment.charged_fx_rate
    );
  end if;

  if v_payment.checkout_claimed_until is not null and v_payment.checkout_claimed_until > now() then
    return jsonb_build_object(
      'paymentId', v_payment.id, 'amountMinor', v_payment.amount_minor,
      'bookingRef', v_booking.ref, 'customerEmail', v_booking.customer_email,
      'existingCheckoutId', null,
      'checkoutPending', true,
      'chargedAmountMinor', v_payment.charged_amount_minor,
      'chargedCurrency', v_payment.charged_currency,
      'chargedFxRate', v_payment.charged_fx_rate
    );
  end if;

  update payments set checkout_claimed_until = now() + interval '90 seconds'
  where id = v_payment.id;

  return jsonb_build_object(
    'paymentId', v_payment.id, 'amountMinor', v_payment.amount_minor,
    'bookingRef', v_booking.ref, 'customerEmail', v_booking.customer_email,
    'existingCheckoutId', null,
    'chargedAmountMinor', v_payment.charged_amount_minor,
    'chargedCurrency', v_payment.charged_currency,
    'chargedFxRate', v_payment.charged_fx_rate
  );
end;
$$;

revoke execute on function create_payment(jsonb, boolean) from public, anon, authenticated;
grant execute on function create_payment(jsonb, boolean) to service_role;

comment on function create_payment(jsonb, boolean) is
  'Shared body behind api_create_payment (identity check ON) and api_create_quote_payment (OFF). '
  'Holds the single-flight checkout lease, the reuse window and the first-write-wins FX pin, so the '
  'two entry points cannot drift into two payable sessions for one booking. Internal: service_role '
  'only — the boolean argument is the authorization decision itself.';

-- ---------------------------------------------------------------------------
-- 2) api_create_payment — the customer entry point. UNCHANGED in name, signature, grants and
--    behaviour; it is now a wrapper so there is exactly one copy of the money logic.
--
--    SECURITY DEFINER is load-bearing on the wrapper, not decoration: `authenticated` deliberately
--    has no EXECUTE on create_payment, so the privilege check for the inner call has to run as the
--    (shared) owner of both functions.
-- ---------------------------------------------------------------------------
create or replace function api_create_payment(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  return create_payment(p, true);
end;
$$;

revoke execute on function api_create_payment(jsonb) from public, anon;
grant execute on function api_create_payment(jsonb) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 3) api_create_quote_payment — the quote entry point. Service-role only.
--
--    Authorization is the LINK TOKEN, verified by resolveQuoteForToken in POST
--    /api/v1/quotes/{ref}/pay before this is ever reached; see the file header for why that is a
--    stronger credential than the session this skips, and why the grant is what keeps it sound.
--
--    TWO NARROWINGS, both so the identity bypass stays pointed at the quote path alone:
--      a. the booking must be one a `quotes` row points at (and `source = 'quote'`, which
--         api_convert_quote sets on the same row it links). A customer's own booking is refused here
--         no matter who is calling;
--      b. only a 'booking' payment. The pickup add-on is a supplement on a CONFIRMED booking, paid
--         from the booking page by its signed-in owner — a quote guest has no such page and no
--         account, so there is no case where this entry point should be opening one.
--
--    Both refusals raise `forbidden` rather than a new token: mapDbError already turns that into a
--    403, and neither is reachable from the route (which only ever passes a quote booking, and never
--    a purpose), so a bespoke guest-facing sentence would be one nobody can ever read.
-- ---------------------------------------------------------------------------
create or replace function api_create_quote_payment(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_purpose text := coalesce(nullif(p ->> 'purpose', ''), 'booking');
begin
  if v_purpose <> 'booking' then
    raise exception 'forbidden' using detail = 'quote_payment_purpose:' || v_purpose;
  end if;

  if not exists (
    select 1
      from bookings b
      join quotes q on q.booking_id = b.id
     where b.ref = p ->> 'bookingRef'
       and b.source = 'quote'
  ) then
    raise exception 'forbidden' using detail = 'not_a_quote_booking';
  end if;

  return create_payment(p, false);
end;
$$;

revoke execute on function api_create_quote_payment(jsonb) from public, anon, authenticated;
grant execute on function api_create_quote_payment(jsonb) to service_role;

comment on function api_create_quote_payment(jsonb) is
  'Opens a checkout for a QUOTE booking, which has no owner to check (the guest has no account). '
  'Authorization is the emailed link token, verified by resolveQuoteForToken before the route calls '
  'this; service_role only, and refuses any booking no quote points at. Shares api_create_payment''s '
  'body, so both take the same single-flight checkout lease.';

-- ---- migration 20260912000000_quote_deposit (quote deposit + balance) -------------------------------
-- Schema half of the deposit/balance feature: a quote guest pays a deposit (default 10%, editable per
-- quote; 100% = pay in full) which confirms the booking; the balance is a SECOND, purpose-scoped
-- payments row chased later. deposit_bps sizes the deposit; balance_due_minor is the "still owed"
-- source of truth. See docs/superpowers/plans/2026-08-06-quote-deposit-balance.md.
--
-- DEFAULT 0 on balance_due_minor is LOAD-BEARING: an existing booking must read "nothing owed", never
-- "full amount owed", so no legacy booking looks part-paid. (Idempotent for the paste-once operator:
-- add-column-if-not-exists + a named check dropped-then-re-added, exactly like payments_purpose_check.)
alter table quotes add column if not exists deposit_bps int not null default 1000;
alter table quotes drop constraint if exists quotes_deposit_bps_check;
alter table quotes add constraint quotes_deposit_bps_check
  check (deposit_bps between 1 and 10000);
alter table bookings add column if not exists deposit_minor     bigint not null default 0;
alter table bookings add column if not exists balance_due_minor bigint not null default 0;
alter table payments drop constraint if exists payments_purpose_check;
alter table payments add constraint payments_purpose_check
  check (purpose in ('booking', 'pickup_addon', 'balance'));


-- ---- migration 20260914000000_quote_balance_link (durable balance link) ----------------------------
-- The staff "Send balance link" flow stores the SHA-256 of a durable, re-openable balance-link token
-- here; the raw token lives only in the URL the operator copies to the guest. Separate from token_hash
-- (the deposit/quote link) so minting a balance link never rotates the guest's original quote link.
-- Nullable, no default: an absent hash is "no balance link", and resolveBalanceForToken fails closed on
-- a null stored hash exactly as the deposit resolver does. App-layer authorization only — nothing
-- SQL-side changes (the balance's payability, amount, lease and reconcile sweep all shipped in
-- 20260912000000).
alter table quotes add column if not exists balance_token_hash text;


-- ---------------------------------------------------------------------------------------------------
-- Task 2 — deposit sizing at conversion + charge. Re-applies api_convert_quote and create_payment (the
-- shared checkout body) verbatim apart from the deposit logic, so this migration — the LATER file — is
-- the winning definition of both. See docs/superpowers/plans/2026-08-06-quote-deposit-balance.md.
--
--   * api_convert_quote now writes deposit_minor / balance_due_minor onto the booking. total_minor and
--     operator_payout_minor stay the FULL quoted price (VAT + operator payout); create_hold still
--     reserves the WHOLE seat regardless of money, untouched.
--   * create_payment sizes the first `booking` payments row to the booking's deposit_minor (with a
--     total_minor fallback for the depositless customer path), read from the booking row, never caller
--     input. Everything downstream — the FX pin, the MUR charge, the confirm-on-paid gate — follows
--     amount_minor unchanged, so paying the deposit confirms the booking exactly as today.
-- ---------------------------------------------------------------------------------------------------

create or replace function api_convert_quote(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_quote quotes;
  v_prior bookings;
  v_booking bookings;
  v_reusable boolean := false;
  v_lines_minor bigint;
  v_owner uuid;
  v_deposit_minor bigint;
  v_seats record;
  v_hold booking_holds;
begin
  select * into v_quote
    from quotes
   where id = nullif(p ->> 'quoteId', '')::uuid
   for update;

  if v_quote.id is null then
    raise exception 'quote_not_found';
  end if;

  -- Convert-once, read off converted_at, and meaning "one PAYABLE booking at a time" (see above).
  if v_quote.converted_at is not null then
    -- LOCK THE MONEY BEFORE JUDGING IT. append_payment_event locks the payments row, writes paid_minor
    -- and status onto it, and only THEN rolls the projection onto bookings — so an unlocked read of
    -- either table can catch a settlement mid-flight, conclude "this booking never took a cent", mint
    -- booking B, commit, and let the settlement land on A afterwards. Taking the payments locks in the
    -- same order that function does serialises the two instead of racing them.
    --
    -- `bookings` is deliberately NOT locked here as well: api_create_payment locks bookings and then
    -- payments, so adding payments -> bookings on this side would close a deadlock cycle on the money
    -- path. It is also unnecessary — read committed gives every later statement in this function a
    -- fresh snapshot, so once the payments locks are held the reads below see post-settlement state.
    -- A booking with no payments row locks nothing, which is safe: api_create_payment refuses a dead
    -- booking ('booking_not_payable'), so no first payment can appear on one.
    perform 1 from payments where booking_id = v_quote.booking_id for update;

    -- booking_id is null here when an erasure hard-deleted the booking; the select finds nothing and
    -- v_reusable stays false, which is the section-4 invariant.
    select * into v_prior from bookings where id = v_quote.booking_id;
    v_reusable := found
      and v_prior.status in ('expired', 'cancelled', 'failed')
      and v_prior.payment_state in ('pending', 'failed')
      -- Money already HELD, including the shapes the booking-level projection above cannot see: an
      -- underpayment (append_payment_event sets 'pending' when v_paid > 0 but below amount_minor, so
      -- paid_minor is positive while payment_state is not) and a wrong-currency settlement quarantine
      -- (settlement_review_at, 20260830000000), which is stamped precisely so the projection is left
      -- alone. Both hold a capture on a booking that still reads clean.
      and not exists (
        select 1 from payments pay
         where pay.booking_id = v_prior.id
           and (pay.paid_minor > 0
                or pay.refunded_minor > 0
                or pay.status in ('paid', 'partially_refunded', 'refunded')
                or pay.settlement_review_at is not null)
      )
      -- Money that can still be TAKEN. A dead booking is not a dead checkout: run_booking_maintenance
      -- expires a booking 30 minutes after it was CREATED, while a Peach session stays completable
      -- ~30 minutes after it was MINTED (api_pending_payment_checkouts says exactly that in its own
      -- comment). A guest who converts at T0, clicks Pay at T0+26 and wanders off has an expired
      -- booking at T0+30 and a live session until roughly T0+56; re-arming in that gap leaves TWO
      -- payable sessions for one quote — the double charge api_create_payment's reuse guard refuses
      -- to create one level down ("Minting a replacement while the original is still live would leave
      -- TWO payable sessions for one booking") and the one 20260902000000 removed. It is also
      -- unreconcilable: api_pending_payment_checkouts only re-queries bookings still in
      -- 'payment_pending', so once the booking is expired a lost webhook on that capture is never
      -- swept — money taken, no ledger row, no link back to the quote.
      --
      -- 30 minutes, not api_create_payment's 25: 25 is the REUSE window, deliberately short of the
      -- session's life so a session handed back cannot die under the guest. The hazard here lasts as
      -- long as the session can be COMPLETED, so this window has to be the wider of the two.
      --
      -- The claimed-lease arm covers the ~90 seconds where a caller is out at Peach and the session
      -- id has not been recorded yet: provider_checkout_id is still null, so freshness alone sees
      -- nothing and would re-arm into the same double charge moments before the session appears.
      --
      -- The refusal is a wait, not a wall: mapDbError already reads quote_already_converted as "has
      -- already been paid for or is being paid", and the quote converts again once the session dies.
      and not exists (
        select 1 from payments pay
         where pay.booking_id = v_prior.id
           and ((pay.provider_checkout_id is not null
                 and coalesce(pay.checkout_created_at, pay.updated_at) > now() - interval '30 minutes')
                or (pay.checkout_claimed_until is not null and pay.checkout_claimed_until > now()))
      );
    if not v_reusable then
      raise exception 'quote_already_converted'
        using detail = coalesce(v_prior.status::text, 'linked booking no longer exists');
    end if;

    -- THE DEAD BOOKING'S SEATS GO BACK BEFORE THIS CONVERSION TAKES FRESH ONES.
    --
    -- Re-arming mints a SECOND booking, which takes its own holds below — so unless the first
    -- booking's holds are released here, one quote reserves two sets of seats for the rest of their
    -- 30-minute life. Nothing else does it: run_booking_maintenance releases holds only for the
    -- bookings IT expired, so a hand-cancelled booking (or one already swept while its hold ran on)
    -- keeps them. On a nearly-full departure that is the guest's own abandoned attempt selling the
    -- trip out from under them — create_hold would raise `insufficient_capacity` and the quote would
    -- read as sold out to the only person entitled to those seats.
    --
    -- Safe because of what the branch above has already established: this booking is dead
    -- (expired/cancelled/failed), never took a cent, and cannot take one.
    update booking_holds set status = 'released'
     where booking_id = v_prior.id and status = 'active';
  end if;

  -- Status: an explicit WHITELIST, the shape api_create_payment uses next door. A blacklist of one
  -- let a 'draft' (a half-built offer the owner has not sent, whose total may be mid-edit) and an
  -- 'expired' quote — a terminal state of the very enum this migration created — both convert.
  -- 'accepted' is in the list because that is what a converted quote's status already is, and the
  -- re-arm branch above has to be able to get past here.
  if v_quote.status = 'cancelled' then
    raise exception 'quote_cancelled';
  end if;
  if v_quote.status = 'expired' or v_quote.valid_until < current_date then
    raise exception 'quote_expired';
  end if;
  if v_quote.status not in ('sent', 'accepted') then
    raise exception 'quote_not_convertible' using detail = v_quote.status::text;
  end if;

  -- A zero-total quote mints a booking that can NEVER confirm: api_create_payment skips the FX pin
  -- for a zero amount, and append_payment_event carries an explicit guard whose own comment says "a
  -- zero-amount payment must never read as fully paid (0 >= 0)". The booking would sit in
  -- payment_pending until the sweep expired it. quotes.total_minor DEFAULTS to 0, so an empty or
  -- never-priced draft reaches this state by default rather than by accident.
  if coalesce(v_quote.total_minor, 0) <= 0 then
    raise exception 'quote_not_convertible' using detail = 'zero total';
  end if;

  -- THE TWO CATALOGUE LINES THIS FUNCTION WILL NOT PRICE INTO A SEAT. Both fail closed here, before
  -- anything is minted, because both are shapes whose capacity meaning cannot be read off the line.
  --
  -- 1. AN OPTION THAT IS NOT COUNTED IN PEOPLE. For a private or vehicle option one BOOKING is one
  --    unit of the pool — the pool counts trips, not heads (20260908000000), and create_booking
  --    records the real party size in booking_items.pax while writing quantity 1. A quote line for
  --    six guests would therefore reserve SIX DEPARTURES if it were held like a per-person line, and
  --    reserve one while charging for six if it were not. Neither is a guess worth making on the
  --    money path: there is no editor that can draft such a line yet, and the pay route's re-price
  --    gate refuses it one step earlier anyway (a private option has no activity_option_prices row
  --    to re-price against). The day the editor learns to quote a private charter, this is the
  --    branch that teaches the conversion the trips-vs-heads mapping — deliberately, with a test.
  --
  -- 2. AN OPTION THAT IS NOT THE OCCURRENCE'S OWN. `quote_item_shape` makes a catalogue line name
  --    both, and nothing checks they agree; a mismatch would write a booking_items row whose option
  --    contradicts its occurrence, i.e. a voucher and a day sheet naming a trip the guest is not on.
  --
  -- Both reuse `quote_not_convertible` rather than minting a token of their own: mapDbError already
  -- reads it as "This quote is not ready to pay yet — please message us", which is exactly true, and
  -- an unfinished offer is the operator's to fix.
  if exists (
    select 1
      from quote_items qi
      join activity_options o on o.id = qi.activity_option_id
      join activities a on a.id = o.activity_id
     where qi.quote_id = v_quote.id
       and qi.kind = 'catalogue'
       and (o.private_base_minor is not null
            or coalesce(a.pricing_mode::text, 'per_person') in ('vehicle', 'vehicle_custom'))
  ) then
    raise exception 'quote_not_convertible' using detail = 'private/vehicle catalogue line';
  end if;
  if exists (
    select 1
      from quote_items qi
      join session_occurrences so on so.id = qi.session_occurrence_id
     where qi.quote_id = v_quote.id
       and qi.kind = 'catalogue'
       and qi.activity_option_id is distinct from so.activity_option_id
  ) then
    raise exception 'quote_not_convertible' using detail = 'catalogue line option is not its occurrence''s';
  end if;

  -- THE CHARGE AND THE ITEMISATION MUST AGREE, or nothing is minted.
  --
  -- The amount charged is copied from quotes.total_minor while the lines are copied by the separate
  -- statement below, and nothing else ties the two together: total_minor carries no CHECK against its
  -- lines and no trigger recomputing it, and the editor writes the total in a different statement from
  -- the lines. src/lib/quotes/totals.ts states in its own header that there is no Zod layer above it
  -- yet and that its guards "ARE the only validation between a browser-supplied line and
  -- quotes.total_minor" — so this function is the last gate before a card is charged, and failing OPEN
  -- on the drift charges the guest a figure the itemisation does not support and renders a VAT
  -- invoice whose lines do not sum to the charge.
  --
  -- The sum is over ALL lines, of every kind: the custom ones are copied into booking_custom_items
  -- below and the catalogue ones take the hold path into booking_items, so every line reaches the
  -- booking and every line was priced into the total the guest agreed to.
  --
  -- It subsumes the zero-lines case too — a hand-set total with no itemisation at all would otherwise
  -- mint a booking with no lines and a booking_json carrying no items: charged for something with no
  -- record of what it was.
  select coalesce(sum(qi.subtotal_minor), 0) into v_lines_minor
    from quote_items qi
   where qi.quote_id = v_quote.id;
  if v_quote.total_minor <> v_lines_minor then
    raise exception 'quote_total_mismatch'
      using detail = format('total %s vs lines %s', v_quote.total_minor, v_lines_minor);
  end if;

  -- WHO WILL BE ABLE TO SEE THIS BOOKING. `user_id` is what the bookings RLS policy reads
  -- (`user_id = auth.uid() or is_staff()`), so a booking minted with a null one is invisible to every
  -- customer — including the guest about to pay for it, whose confirmation email links to
  -- /bookings/{ref}. quote_owner_for_email (section 6d) answers with the single CONFIRMED account
  -- holding the quoted address, or null; see its header for why that rule is exactly this narrow.
  --
  -- NULL IS A SUPPORTED ANSWER, NOT A FAILURE. Most quote guests never open an account, and nothing
  -- downstream requires an owner: api_create_quote_payment (20260911000000) exists precisely because a
  -- quote booking has none, the guest's own record stays reachable through the link token, and
  -- api_claim_quote_bookings (7c) fills the column in later if they ever do sign up.
  v_owner := quote_owner_for_email(v_quote.customer_email);

  -- DEPOSIT SIZING. The deposit is total_minor * deposit_bps / 10000 (basis points; 1000 = 10.00%),
  -- rounded to the minor unit. total_minor AND operator_payout_minor stay the FULL quoted price — they
  -- feed the VAT invoice and the operator payout, and it is only the FIRST payments row (sized to this
  -- deposit in create_payment) that the guest is charged now. deposit_bps = 10000 makes the deposit the
  -- whole total — the UNCHANGED pay-in-full path. deposit_bps carries a `between 1 and 10000` CHECK, so
  -- the deposit is always a positive fraction of the total.
  v_deposit_minor := round(v_quote.total_minor * v_quote.deposit_bps / 10000.0);

  -- balance_due_minor is INITIALISED to the full total: nothing is settled at conversion, so the
  -- "amount still owed" is the whole order, exactly as append_payment_event's projection would compute
  -- it (total_minor - sum of settled money, which is 0 here). It is NOT total - deposit — that would
  -- read as if the deposit were already paid the moment the booking is minted, before the guest has
  -- been charged a cent, and would disagree with the projection that recomputes this column downward
  -- as the deposit and then the balance settle (→ total - deposit → 0). The deposit is a CHARGE size
  -- (deposit_minor / the first payments row), not a payment; only settling it reduces what is owed.
  insert into bookings (
    user_id, customer_name, customer_email, customer_phone, status, source,
    currency, total_minor, operator_payout_minor, payment_state, locale,
    deposit_minor, balance_due_minor
  )
  values (
    v_owner, v_quote.customer_name, v_quote.customer_email, v_quote.customer_phone, 'payment_pending',
    'quote', v_quote.currency, v_quote.total_minor, v_quote.total_minor, 'pending', v_quote.locale,
    v_deposit_minor, v_quote.total_minor
  )
  returning * into v_booking;

  -- The `kind <> 'catalogue'` filter is what keeps this statement and the hold path below from both
  -- claiming the same line: booking_custom_items carries `check (kind <> 'catalogue')`, and a
  -- catalogue line belongs in booking_items, where it can be counted against a departure.
  insert into booking_custom_items (
    booking_id, position, kind, description, starts_at, ends_at,
    rental_vehicle_slug, quantity, unit_amount_minor, subtotal_minor
  )
  select v_booking.id, qi.position, qi.kind, qi.description, qi.starts_at, qi.ends_at,
         qi.rental_vehicle_slug, qi.quantity, qi.unit_amount_minor, qi.subtotal_minor
    from quote_items qi
   where qi.quote_id = v_quote.id
     and qi.kind <> 'catalogue';

  -- ── THE CATALOGUE LINES TAKE THEIR SEATS, HERE, IN THIS TRANSACTION ─────────────────────────
  --
  -- A catalogue line names a session_occurrence, so unlike a custom line it is a place on a real
  -- departure. It is only actually reserved if it is reserved the way every other booking reserves
  -- one: create_hold — the universal gate, which api_create_hold and api_book both delegate their
  -- hold INSERT to — takes `select … for update` on the occurrence, re-reads used_capacity() under
  -- that lock and refuses an oversell; and the booking_items row is what used_capacity() counts once
  -- the booking confirms, what append_payment_event's oversell re-check reads before it confirms
  -- anything, and what puts the guest on the day sheet. Re-deriving either here would be a second,
  -- quieter definition of "a seat exists" on the money path.
  --
  -- WHY IT IS IN THIS FUNCTION AND NOT IN THE PAY ROUTE (which is where the plan first put it): a
  -- route does it in a SECOND transaction, so a hold that fails leaves a converted quote and a
  -- payable booking with no seat behind it — the guest pays for a place nobody reserved, which is
  -- the precise state the placeholder guard this replaces existed to prevent, now reached by a
  -- different road. In here, a refusal takes the booking, its custom lines and `converted_at` back
  -- with it, and the guest sees a refusal instead of a charge.
  --
  -- UNITS, NOT PEOPLE. used_capacity() sums booking_holds.quantity and booking_items.quantity, and
  -- append_payment_event re-checks this booking's own booking_items sum against the occurrence's
  -- capacity — so the hold's quantity must equal the quantities of the lines it covers, or the seat
  -- count drifts the moment the payment lands. Lines that share an occurrence are aggregated into
  -- ONE hold for exactly that reason (two 'Adult' and 'Child' lines on one boat are three seats on
  -- one trip, not two reservations).
  --
  -- The idempotency key is scoped to THIS booking, so a re-arm (a fresh booking for the same quote)
  -- takes fresh holds rather than being handed create_hold's idempotent replay of a released one.
  --
  -- WHAT IS DELIBERATELY *NOT* RE-USED FROM THE CHECKOUT: create_booking's per-booking guests-per-trip
  -- cap (20260908000000). That cap exists because a self-serve guest cannot know the day's pool is
  -- several departures — "the boat only seats so many, however big the day's pool is" — and it is
  -- enforced per BOOKING, so one quote line could never express "twenty guests, two boats" with it in
  -- the way. The operator drafting this quote chose the departure and the party size, and the POOL is
  -- still enforced by create_hold, so no other guest can be oversold; what a big party costs is two
  -- boats' worth of units out of the day, which is what it consumes. Revisit this the day quotes are
  -- drafted by anyone but staff.
  for v_seats in
    select qi.session_occurrence_id as occurrence_id, sum(qi.quantity)::int as units
      from quote_items qi
     where qi.quote_id = v_quote.id and qi.kind = 'catalogue'
     group by qi.session_occurrence_id
  loop
    begin
      v_hold := create_hold(
        v_seats.occurrence_id, v_seats.units,
        'quote:' || v_booking.id::text || ':' || v_seats.occurrence_id::text
      );
    exception when raise_exception then
      -- create_hold refuses in the CHECKOUT's vocabulary — insufficient_capacity,
      -- occurrence_not_bookable, occurrence_in_past, occurrence_too_soon — and mapDbError turns those
      -- into "Not enough availability for this selection" or the bare "Invalid booking request",
      -- neither of which tells a quote guest anything they can act on: they cannot pick another date,
      -- because the date was arranged for them. One token for all of them, carrying the real reason in
      -- DETAIL for error_logs, and mapped to a sold-out 409 that says to message us.
      raise exception 'quote_seats_unavailable'
        using detail = format('occurrence %s x%s: %s', v_seats.occurrence_id, v_seats.units, sqlerrm);
    end;

    -- ATTACH THE HOLD TO THE BOOKING. Not tidiness: append_payment_event's oversell re-check counts
    -- every active hold that is NOT this booking's own against it, so a detached hold is the guest's
    -- own reservation blocking their own confirmation and routing a good payment to refund_pending.
    -- It is also what makes the confirmation mark it 'consumed' rather than leaving it to lapse.
    update booking_holds set booking_id = v_booking.id where id = v_hold.id;
  end loop;

  -- One row per LINE (the hold above is one row per occurrence): the tiers are what the voucher, the
  -- day sheet and the VAT invoice itemise. Prices are the quote's own — the negotiated figure the
  -- guest saw and `quote_total_mismatch` has just re-checked — never re-derived from the catalogue
  -- here; the pay route compares them against the live price list and refuses on drift before this
  -- function is ever called. `price_label` is NOT NULL on booking_items, so a line that carries no
  -- tier name falls back to its description rather than failing at the constraint.
  insert into booking_items (
    booking_id, session_occurrence_id, activity_option_id, price_label,
    quantity, unit_amount_minor, subtotal_minor
  )
  select v_booking.id, qi.session_occurrence_id, qi.activity_option_id,
         coalesce(nullif(btrim(qi.price_label), ''), nullif(btrim(qi.description), ''), 'Quoted place'),
         qi.quantity, qi.unit_amount_minor, qi.subtotal_minor
    from quote_items qi
   where qi.quote_id = v_quote.id
     and qi.kind = 'catalogue'
   order by qi.position;

  -- Overwrites booking_id on a re-arm, which releases the dead booking from the UNIQUE.
  update quotes
     set booking_id = v_booking.id,
         converted_at = now(),
         status = 'accepted',
         updated_at = now()
   where id = v_quote.id;

  return booking_json(v_booking.id);
end;
$$;
revoke execute on function api_convert_quote(jsonb) from public, anon, authenticated;
grant execute on function api_convert_quote(jsonb) to service_role;

create or replace function create_payment(p jsonb, p_enforce_caller_identity boolean default true)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking bookings;
  v_payment payments;
  v_rate numeric;
  v_src text;
  v_at timestamptz;
  v_charged bigint;
  v_purpose text := coalesce(nullif(p ->> 'purpose', ''), 'booking');
  v_req booking_pickup_requests;
begin
  if v_purpose not in ('booking', 'pickup_addon', 'balance') then
    raise exception 'invalid_payment_purpose' using detail = v_purpose;
  end if;

  -- FOR UPDATE: every concurrent create-payment call for one booking serialises on this row for the
  -- rest of the transaction. That closes two races at once: two callers both inserting a payments row
  -- below, and — via the checkout lease — two callers both getting a green light to mint a Peach
  -- session. Peach's nonce is unique per REQUEST (it never dedupes), so without this lease two tabs
  -- or a retry could create two independently payable sessions for the same booking.
  -- (It also makes the charge pin race-free: one caller pins, the loser re-reads the pinned row.)
  --
  -- It is also what serialises the two ENTRY POINTS against each other: a staff member opening the
  -- checkout for a quote booking through api_create_payment and the guest clicking Pay through
  -- api_create_quote_payment reach this same lock, this same payments row and this same lease.
  select * into v_booking from bookings where ref = p ->> 'bookingRef' for update;
  if not found then
    raise exception 'booking_not_found';
  end if;
  if v_purpose = 'booking' then
    if v_booking.status in ('confirmed', 'completed', 'cancelled', 'expired', 'refund_pending', 'refunded', 'failed')
       or v_booking.payment_state in ('paid', 'partially_refunded', 'refunded') then
      raise exception 'booking_not_payable' using detail = v_booking.status::text;
    end if;
  elsif v_purpose = 'balance' then
    -- THE BALANCE'S OWN PAYABILITY. The deposit has already CONFIRMED the booking, so a 'booking' row
    -- here would trip the guard above (booking_not_payable) — which is exactly why the balance is a
    -- separate purpose, the same reason the pickup add-on is. What is left to collect is the booking's
    -- balance_due_minor, the projection append_payment_event maintains (add-on-immune, the true amount
    -- still owed). Payable only on a confirmed booking that still owes something; a fully-paid booking
    -- (balance_due_minor = 0) has nothing to charge, so it is refused with a readable code of its own —
    -- distinct from booking_not_payable, which the balance row could never itself provoke.
    if v_booking.status <> 'confirmed' then
      raise exception 'booking_not_payable' using detail = 'balance:' || v_booking.status::text;
    end if;
    if coalesce(v_booking.balance_due_minor, 0) <= 0 then
      raise exception 'balance_already_paid';
    end if;
  else
    -- The add-on's own payability: an open request must exist, and the trip must not have left.
    select * into v_req from booking_pickup_requests
     where booking_id = v_booking.id and applied_at is null and payment_id is not null;
    if not found then
      raise exception 'pickup_request_not_found';
    end if;
    -- …and it must not ALREADY hold the guest's money. A request refused at settlement (the departure
    -- was called off) stays open behind a payments row that is already 'paid'. If the trip is then
    -- rescheduled onto a live date the eligibility ladder goes green again, and without this guard
    -- the booking page's "Complete payment" button minted a SECOND Peach session on that same row —
    -- charging the card twice for one supplement, invisibly: the apply trigger cannot fire again
    -- (its WHEN clause needs old.status distinct from 'paid'), so no second alert is raised either.
    if exists (
      select 1 from payments pay
       where pay.id = v_req.payment_id and pay.paid_minor >= pay.amount_minor and pay.amount_minor > 0
    ) then
      raise exception 'pickup_already_paid';
    end if;
    if not coalesce((pickup_addon_quote(v_booking.id, v_req.pickup_lat, v_req.pickup_lng) ->> 'eligible')::boolean, false) then
      raise exception 'booking_not_payable' using detail = 'pickup_addon';
    end if;
  end if;
  -- THE CALLER-IDENTITY CHECK — unchanged, and still what api_create_payment enforces. It is skipped
  -- ONLY for a caller that has already proved a stronger, non-session credential: see the header, and
  -- api_create_quote_payment, which is the only function in the schema that passes `false`.
  if p_enforce_caller_identity
     and not (is_staff() or (auth.uid() is not null and v_booking.user_id = auth.uid())) then
    raise exception 'forbidden';
  end if;

  -- No `and status <> 'failed'`: that skipped the row a declined attempt had latched to 'failed' and
  -- minted a SECOND payments row, orphaning the checkout-reuse window and the single-flight lease
  -- (both columns on the skipped row) and leaving two independently payable Peach sessions.
  if v_purpose = 'booking' then
    select * into v_payment from payments
    where booking_id = v_booking.id and purpose = 'booking'
    order by created_at desc
    limit 1;

    if not found then
      -- Scoped to THIS booking: an unscoped key lookup let a caller echo another payment's key and
      -- receive that payment's id/amount back.
      select * into v_payment from payments
      where idempotency_key = p ->> 'idempotencyKey' and booking_id = v_booking.id and purpose = 'booking';
    end if;
  elsif v_purpose = 'balance' then
    -- The newest 'balance' row for this booking — never a 'booking' row (that is the deposit, a distinct
    -- purpose). Under the booking-row FOR UPDATE above this is the single-open-lease guard: a second mint
    -- finds the row the first minted and REUSES its checkout lease, so one balance is one payable session,
    -- not a fork. No `and status <> 'failed'`, exactly as the deposit path: a declined balance attempt's
    -- row (which carries the checkout-reuse window and the lease) is reused rather than orphaned by a
    -- second row.
    select * into v_payment from payments
    where booking_id = v_booking.id and purpose = 'balance'
    order by created_at desc
    limit 1;

    if not found then
      select * into v_payment from payments
      where idempotency_key = p ->> 'idempotencyKey' and booking_id = v_booking.id and purpose = 'balance';
    end if;
  else
    -- Exactly the row the open request points at — never "the newest add-on row", which after a
    -- superseded request could be a different, abandoned one.
    select * into v_payment from payments where id = v_req.payment_id and purpose = 'pickup_addon';
  end if;

  if not found then
    if v_purpose = 'pickup_addon' then
      -- api_request_pickup owns the add-on row (it is the only place that knows the fare). Never
      -- invent one here, or the amount would come from nowhere.
      raise exception 'pickup_request_not_found';
    elsif v_purpose = 'balance' then
      -- Mint the balance row. Its amount is the booking's CURRENT balance_due_minor — the SERVER's figure
      -- for what is still owed, read off the booking row (never caller input, exactly like the deposit
      -- and the FX pin) and snapshotted onto this row, so charging it drives balance_due_minor to 0. The
      -- balance-payability branch above has already proved it is > 0. From here everything is per-payment-
      -- row: this row takes its own FX pin, its own checkout lease and its own provider_checkout_id.
      insert into payments (booking_id, idempotency_key, amount_minor, purpose)
      values (v_booking.id, p ->> 'idempotencyKey', v_booking.balance_due_minor, 'balance')
      returning * into v_payment;
      insert into payment_events (payment_id, type, amount_minor)
      values (v_payment.id, 'intent', v_booking.balance_due_minor);
    else
      -- The first `booking` row is sized to the DEPOSIT when the booking carries one. A quote booking
      -- carries a positive deposit_minor (api_convert_quote sized it from deposit_bps), and a pay-in-full
      -- quote's is the whole total; an ordinary customer booking has none — deposit_minor DEFAULTS to 0,
      -- so nullif() falls the charge back to total_minor and the customer path is bit-for-bit what it was.
      -- Sized off the BOOKING ROW, never caller input, exactly like the FX pin below: what a card is
      -- charged is a server figure. append_payment_event then confirms the booking when THIS row is paid
      -- in full, so paying the deposit confirms it and reserves the seat with no change to that gate.
      insert into payments (booking_id, idempotency_key, amount_minor, purpose)
      values (v_booking.id, p ->> 'idempotencyKey',
              coalesce(nullif(v_booking.deposit_minor, 0), v_booking.total_minor), 'booking')
      returning * into v_payment;
      insert into payment_events (payment_id, type, amount_minor)
      values (v_payment.id, 'intent', coalesce(nullif(v_booking.deposit_minor, 0), v_booking.total_minor));
    end if;
  end if;

  -- ── Pin the charge (once per payment row) ────────────────────────────────────────────────────
  -- The EUR ledger total converted to WHOLE MUR RUPEES at the server-controlled rate. Derived here,
  -- in SQL, from fx_rates — NEVER from caller input (this function is granted to authenticated; a
  -- caller-supplied rate would let a booking owner pin their own MUR 0.05 charge). First-write-wins:
  -- every later call — every re-minted checkout session, the pay page, reconcile — reads THIS figure,
  -- so a moved FX rate between sessions can never make the charge and the expected settlement drift.
  if v_payment.charged_amount_minor is null and v_payment.amount_minor > 0 then
    select r.rate, r.source, r.fetched_at into v_rate, v_src, v_at
      from fx_rates r where r.base = 'EUR' and r.quote = 'MUR';
    -- Band-clamped on READ as well as write: an inverted or foreign payload that somehow reached the
    -- table (0.0185 would bill MUR 1.85 for a EUR 100 booking — and, because settled == charged,
    -- CONFIRM it) falls back to the floor instead of being trusted.
    if v_rate is null or v_rate < 40 or v_rate > 70 then
      v_rate := 53.00; -- cold-start floor; see the fx_rates seed comment (kept below mid on purpose)
      v_src := 'fallback';
      v_at := now();
    end if;
    -- Whole rupees: kills every sub-unit disagreement between what we send Peach and what Peach
    -- reports back. Costs at most MUR 0.50 (~EUR 0.01) per booking.
    v_charged := (round(v_payment.amount_minor * v_rate / 100.0) * 100)::bigint;
    update payments
       set charged_amount_minor = v_charged,
           charged_currency = 'MUR',
           charged_fx_rate = v_rate,
           charged_fx_source = v_src,
           charged_fx_at = v_at,
           updated_at = now()
     where id = v_payment.id and charged_amount_minor is null
     returning * into v_payment;
    if not found then
      -- Another transaction pinned first (or a legacy row already carried a charge): read the truth.
      select * into v_payment from payments where id = v_payment.id;
    end if;
  end if;

  -- Checkout lease (single-flight): exactly one caller may be out creating a Peach session at any
  -- moment. Order matters — reuse beats pending beats claim:
  --   1. a still-fresh recorded checkout        -> hand the SAME session back (reuse; no Peach call);
  --   2. someone else holds an unexpired lease  -> checkoutPending (caller retries shortly);
  --   3. otherwise                              -> stamp the lease and let THIS caller call Peach.
  -- api_record_payment_checkout clears the lease when the session id is recorded; a Peach failure
  -- releases it via api_release_checkout_claim, and the 90-second expiry is the crash backstop.
  --
  -- Freshness is measured from checkout_created_at (when the session was MINTED), never from
  -- updated_at: the reconcile sweep touches updated_at on every pass, which used to re-arm this
  -- window forever and trap the customer on a dead session. The caller still verifies liveness with
  -- the provider before actually reusing what this returns.
  if v_payment.provider_checkout_id is not null
     and coalesce(v_payment.checkout_created_at, v_payment.updated_at) > now() - interval '25 minutes' then
    return jsonb_build_object(
      'paymentId', v_payment.id, 'amountMinor', v_payment.amount_minor,
      'bookingRef', v_booking.ref, 'customerEmail', v_booking.customer_email,
      'existingCheckoutId', v_payment.provider_checkout_id,
      'chargedAmountMinor', v_payment.charged_amount_minor,
      'chargedCurrency', v_payment.charged_currency,
      'chargedFxRate', v_payment.charged_fx_rate
    );
  end if;

  if v_payment.checkout_claimed_until is not null and v_payment.checkout_claimed_until > now() then
    return jsonb_build_object(
      'paymentId', v_payment.id, 'amountMinor', v_payment.amount_minor,
      'bookingRef', v_booking.ref, 'customerEmail', v_booking.customer_email,
      'existingCheckoutId', null,
      'checkoutPending', true,
      'chargedAmountMinor', v_payment.charged_amount_minor,
      'chargedCurrency', v_payment.charged_currency,
      'chargedFxRate', v_payment.charged_fx_rate
    );
  end if;

  update payments set checkout_claimed_until = now() + interval '90 seconds'
  where id = v_payment.id;

  return jsonb_build_object(
    'paymentId', v_payment.id, 'amountMinor', v_payment.amount_minor,
    'bookingRef', v_booking.ref, 'customerEmail', v_booking.customer_email,
    'existingCheckoutId', null,
    'chargedAmountMinor', v_payment.charged_amount_minor,
    'chargedCurrency', v_payment.charged_currency,
    'chargedFxRate', v_payment.charged_fx_rate
  );
end;
$$;

revoke execute on function create_payment(jsonb, boolean) from public, anon, authenticated;
grant execute on function create_payment(jsonb, boolean) to service_role;

comment on function create_payment(jsonb, boolean) is
  'Shared body behind api_create_payment (identity check ON) and api_create_quote_payment (OFF). '
  'Holds the single-flight checkout lease, the reuse window and the first-write-wins FX pin, so the '
  'two entry points cannot drift into two payable sessions for one booking. Internal: service_role '
  'only — the boolean argument is the authorization decision itself.';



-- ---------------------------------------------------------------------------------------------------
-- Task 3 — append_payment_event maintains balance_due_minor.
--
-- The deposit is the first `booking` payments row SIZED to it (Task 2), so the confirm-on-paid gate is
-- UNCHANGED: a deposit-sized row reaching its own amount_minor still flips draft/held/payment_pending
-- to confirmed and consumes the hold. What this migration adds is one statement — "how much is still
-- owed", recomputed after every event as a PROJECTION over the payment rows, never latched from the
-- single row this event touched (the sticky-failed landmine, [[gytm-sticky-failed-payment-state]]):
--
--   balance_due_minor = greatest(0, total_minor - sum(paid_minor - refunded_minor) over the payment rows
--                                    that actually REACHED total_minor)
--
-- total_minor is the running order total: the FULL quoted price, which GROWS by an applied late-pickup
-- fee (apply_pickup_request in 20260910000000, an AFTER-UPDATE-of-status trigger on payments that fires
-- from INSIDE the `update payments` a few lines up in this very function). A row counts on the summed
-- side exactly to the extent its money reached that total: the deposit ('booking') and the balance
-- ('balance') ARE the total, and an APPLIED 'pickup_addon' (a booking_pickup_requests row with
-- applied_at set and fee_minor > 0) grew it, so its capture must count to net that growth back out.
-- A pickup captured but NOT applied never reached total_minor — the zero-fee revision cuts its
-- payment_id loose, a called-off departure returns before growing total, and both ORPHAN the capture —
-- so summing its gross paid_minor in (the first, all-purposes shape) silently REDUCED the amount owed by
-- money that never paid down the order: a permanent under-collection on a booking that still owes its
-- balance. Netting refunds (paid_minor - refunded_minor) stops a later refund of a counted row still
-- reading as settled. balance_due_minor stays OUT of the payment_state enum, so the booking-level
-- roll-up (and everything that reads it, incl. the sticky-failed protection) is byte-for-byte what it was.
--
-- ONE MORE TIME, THE WHOLE BODY, VERBATIM. This is the most dangerous function in the repo: re-
-- declaring it from a stale copy silently reverts an earlier fix ([[gytm-migration-revert-drift]]).
-- The body below is the WINNING one — 20260910000000 (the LATER of the two prior definitions, so the
-- one a fully-migrated database actually resolves to), which is itself 20260902000000 plus (a) the
-- owner_overpayment alert and (b) the refunded-branch guard `coalesce(v_booking_state, v_state) =
-- 'refunded'` that stops a single refunded child row (e.g. a refunded pickup supplement) from stamping
-- a still-paid booking 'refunded'. BOTH are carried forward here unchanged; the oversold/called-off/
-- refund branches are re-applied verbatim. The ONLY change is the balance_due_minor statement, added
-- after the payment_state roll-up. resolved-function-bodies.test.ts pins that statement against
-- pg_proc so a future re-definition cannot drop it and keep the comment.
-- ---------------------------------------------------------------------------------------------------

create or replace function append_payment_event(
  p_payment_id uuid,
  p_type text,
  p_provider_event_id text,
  p_amount_minor bigint,
  p_occurred_at timestamptz,
  p_payload jsonb
)
returns payments
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payment payments;
  v_paid bigint;
  v_refunded bigint;
  v_failed boolean;
  v_state payment_state;
  v_booking_state payment_state;
  v_booking_status booking_status;
  v_occ_id uuid;
  v_needed bigint;
  v_cap bigint;
  v_used_conf bigint;
  v_used_hold bigint;
  v_oversold boolean := false;
  v_called_off boolean := false;
begin
  select * into v_payment from payments where id = p_payment_id for update;
  if not found then
    raise exception 'payment_not_found';
  end if;

  insert into payment_events (payment_id, type, provider_event_id, amount_minor, occurred_at, payload)
  values (
    p_payment_id, p_type, p_provider_event_id, coalesce(p_amount_minor, 0),
    coalesce(p_occurred_at, now()), coalesce(p_payload, '{}'::jsonb)
  )
  on conflict (payment_id, provider_event_id, type) do nothing;

  select
    coalesce(sum(amount_minor) filter (where type in ('paid', 'captured')), 0),
    coalesce(sum(amount_minor) filter (where type = 'refunded'), 0),
    bool_or(type = 'failed')
  into v_paid, v_refunded, v_failed
  from payment_events
  where payment_id = p_payment_id;

  if v_paid > 0 and v_refunded >= v_paid then
    v_state := 'refunded';
  elsif v_paid > 0 and v_refunded > 0 then
    v_state := 'partially_refunded';
  -- amount_minor > 0: a zero-amount payment must never read as fully paid (0 >= 0) -- the 'failed'
  -- branch below has to win for it.
  elsif v_payment.amount_minor > 0 and v_paid >= v_payment.amount_minor then
    v_state := 'paid';
  elsif v_paid > 0 then
    v_state := 'pending'; -- underpaid: do not confirm
  elsif coalesce(v_failed, false) then
    v_state := 'failed';
  else
    v_state := 'pending';
  end if;

  update payments
  set status = v_state, paid_minor = v_paid, refunded_minor = v_refunded, updated_at = now()
  where id = p_payment_id
  returning * into v_payment;

  -- MORE money than we asked for, on one payments row. Nothing else in this system can see that: the
  -- reducer's own branches all read `>= amount_minor`, so a second capture on an already-paid row is
  -- indistinguishable from the first, and the late-pickup apply trigger cannot re-fire on it. It
  -- should be impossible — but "impossible" is what the double-charge guards keep discovering it is
  -- not, and the only honest response to money we did not ask for is to tell someone who can return it.
  if v_payment.amount_minor > 0 and v_paid > v_payment.amount_minor then
    insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
    select 'email', 'owner', 'owner_overpayment',
           jsonb_build_object(
             'ref', b.ref,
             'customerName', b.customer_name,
             'expectedEur', v_payment.amount_minor::float / 100,
             'paidEur', v_paid::float / 100,
             'purpose', v_payment.purpose
           ),
           b.id,
           'overpaid:' || v_payment.id::text
      from bookings b where b.id = v_payment.booking_id
    on conflict (idempotency_key) do nothing;
  end if;

  -- BOOKING-level projection, rolled up across every payment row of this booking -- best row wins,
  -- and 'failed' only when EVERY row failed. Written from the single touched row it was a latch: one
  -- declined attempt stamped the booking 'failed' forever (nothing else writes this column), which
  -- silently removed it from api_pending_payment_checkouts and run_booking_maintenance. Ranking
  -- rather than re-summing the ledger keeps this a pure widening: a booking with one payment row --
  -- every booking that never hit the fork -- projects exactly what it projected before.
  -- Ordered paid > partially_refunded > refunded > pending > failed: with two rows after a double
  -- charge, one refunded and one not, money is still held and 'paid' is the honest answer.
  select case min(
           case pay.status
             when 'paid' then 1
             when 'partially_refunded' then 2
             when 'refunded' then 3
             when 'pending' then 4
             when 'failed' then 5
           end
         )
         when 1 then 'paid'
         when 2 then 'partially_refunded'
         when 3 then 'refunded'
         when 5 then 'failed'
         else 'pending'
         end::payment_state
    into v_booking_state
    from payments pay
   where pay.booking_id = v_payment.booking_id;

  update bookings set payment_state = coalesce(v_booking_state, v_state), updated_at = now()
  where id = v_payment.booking_id;

  -- AMOUNT STILL OWED, maintained here as a projection over the payment ROWS — never latched from the
  -- single row this event touched (that is precisely the sticky-failed class of bug: a booking-level
  -- figure derived from one child row). total_minor is the running order total — the FULL quoted price,
  -- GROWN by an applied late-pickup fee (apply_pickup_request, the AFTER-UPDATE-of-status trigger that
  -- fires from inside the `update payments` above) — so "owed" is that total minus everything settled.
  -- A row counts only to the extent its money actually REACHED total_minor:
  --   * the deposit ('booking') and the balance ('balance'), which ARE the total; and
  --   * a 'pickup_addon' ONLY once its request was APPLIED (a booking_pickup_requests row with
  --     applied_at set and fee_minor > 0 points at it) — an applied add-on grew total_minor, so its
  --     capture must count here to net that growth back out.
  -- A pickup captured but NOT applied never reached total_minor, so it must NOT count: the zero-fee
  -- revision cuts its payment_id loose (api_request_pickup) and a called-off departure returns before
  -- growing total (apply_pickup_request), and both leave the capture ORPHANED (notify_pickup_orphan_
  -- payment). Summing that gross capture in — the original all-purposes shape — silently REDUCED the
  -- amount owed by money that never paid down the order: a real, permanent under-collection on a booking
  -- that still owes its balance. (paid_minor - refunded_minor) so a later refund of a counted row stops
  -- it counting; greatest(0, …) so an overpayment, a refund event, or an unapplied pickup can never
  -- drive balance_due_minor negative. A legacy/customer booking whose single 'booking' row covers
  -- total_minor still recomputes to 0 unchanged.
  update bookings b
     set balance_due_minor = greatest(
           0,
           b.total_minor - coalesce((
             select sum(pay.paid_minor - pay.refunded_minor)
               from payments pay
              where pay.booking_id = b.id
                and (
                  pay.purpose in ('booking', 'balance')
                  or exists (
                    select 1
                      from booking_pickup_requests r
                     where r.payment_id = pay.id
                       and r.applied_at is not null
                       and r.fee_minor > 0
                  )
                )
           ), 0)
         ),
         updated_at = now()
   where b.id = v_payment.booking_id;

  -- Confirmation stays driven by THIS row reaching 'paid' (v_state), never by the roll-up: a row
  -- that just captured the full amount is what licenses confirming, and reusing the roll-up here
  -- would re-run the capacity re-check on every later event of an already-paid booking.
  if v_state = 'paid' then
    select status into v_booking_status from bookings where id = v_payment.booking_id;

    if v_booking_status in ('draft', 'held', 'payment_pending') then
      -- Re-validate capacity per occurrence, excluding this booking's own items/holds.
      for v_occ_id in
        select distinct session_occurrence_id from booking_items where booking_id = v_payment.booking_id
      loop
        perform 1 from session_occurrences where id = v_occ_id for update;
        select coalesce(sum(quantity), 0) into v_needed
        from booking_items where booking_id = v_payment.booking_id and session_occurrence_id = v_occ_id;
        select capacity into v_cap from session_occurrences where id = v_occ_id;
        select coalesce(sum(bi.quantity), 0) into v_used_conf
        from booking_items bi join bookings b on b.id = bi.booking_id
        where bi.session_occurrence_id = v_occ_id
          and b.status in ('confirmed', 'completed')
          and b.id <> v_payment.booking_id;
        select coalesce(sum(h.quantity), 0) into v_used_hold
        from booking_holds h
        where h.session_occurrence_id = v_occ_id
          and h.status = 'active' and h.expires_at > now()
          and (h.booking_id is null or h.booking_id <> v_payment.booking_id);
        if v_needed > v_cap - v_used_conf - v_used_hold then
          v_oversold := true;
        end if;
      end loop;

      -- Was the departure called off while this payment was in flight?
      --
      -- Confirming here would tell the guest they are booked onto a trip that is not running. Worse,
      -- they could never be put right afterwards: api_weather_cancel_occurrence stamps only bookings
      -- that were ALREADY confirmed+paid when it ran, and it refuses to re-run on an occurrence it
      -- has already cancelled — so this booking would never receive a `disruption` stamp, and that
      -- stamp is the ONLY thing that opens the 24h bypass in api_cancel_booking and
      -- api_reschedule_booking (via booking_awaiting_choice). Charged, told "confirmed", and locked
      -- out of both the refund and the free reschedule /refunds promises.
      --
      -- Route the money back instead — the same answer this function already gives when the seats
      -- turn out to be gone (oversold) or the booking is no longer live. refund_pending frees the
      -- capacity immediately and fires enqueue_booking_notification's refund_pending branch, so the
      -- owner gets a work item and the guest is told.
      select exists (
        select 1
          from booking_items bi
          join session_occurrences so on so.id = bi.session_occurrence_id
         where bi.booking_id = v_payment.booking_id
           and so.status = 'cancelled'
      ) into v_called_off;

      if v_oversold or v_called_off then
        update bookings set status = 'refund_pending', updated_at = now() where id = v_payment.booking_id;
      else
        update bookings set status = 'confirmed', updated_at = now() where id = v_payment.booking_id;
        update booking_holds set status = 'consumed'
        where booking_id = v_payment.booking_id and status = 'active';
      end if;
    elsif v_booking_status not in ('confirmed', 'completed') then
      -- Money captured on an expired/cancelled booking: must be refunded, not confirmed.
      update bookings set status = 'refund_pending', updated_at = now() where id = v_payment.booking_id;
    end if;
  elsif v_state = 'refunded' and coalesce(v_booking_state, v_state) = 'refunded' then
    update bookings set status = 'refunded', updated_at = now()
    where id = v_payment.booking_id and status <> 'cancelled';
    update booking_holds set status = 'released'
    where booking_id = v_payment.booking_id and status = 'active';
  end if;

  return v_payment;
end;
$$;

revoke execute on function append_payment_event(uuid, text, text, bigint, timestamptz, jsonb) from public, anon, authenticated;
grant execute on function append_payment_event(uuid, text, text, bigint, timestamptz, jsonb) to service_role;


-- Task 4 — the accountless quote guest's way into the BALANCE checkout (20260912000000).
-- create_payment (re-applied above) now carries a 'balance' branch; this re-applies
-- api_create_quote_payment as the winning body, widened so the same token-authorized guest who paid the
-- deposit can pay the balance the same way. Service-role only, narrowed to the quote path, still routes
-- to the shared create_payment body — everything that made the deposit entry sound, one purpose along.
create or replace function api_create_quote_payment(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_purpose text := coalesce(nullif(p ->> 'purpose', ''), 'booking');
begin
  if v_purpose not in ('booking', 'balance') then
    raise exception 'forbidden' using detail = 'quote_payment_purpose:' || v_purpose;
  end if;

  if not exists (
    select 1
      from bookings b
      join quotes q on q.booking_id = b.id
     where b.ref = p ->> 'bookingRef'
       and b.source = 'quote'
  ) then
    raise exception 'forbidden' using detail = 'not_a_quote_booking';
  end if;

  return create_payment(p, false);
end;
$$;

revoke execute on function api_create_quote_payment(jsonb) from public, anon, authenticated;
grant execute on function api_create_quote_payment(jsonb) to service_role;

comment on function api_create_quote_payment(jsonb) is
  'Opens a checkout for a QUOTE booking, which has no owner to check (the guest has no account). '
  'Authorization is the emailed link token, verified by resolveQuoteForToken before the route calls '
  'this; service_role only, and refuses any booking no quote points at. Admits the DEPOSIT (''booking'') '
  'and the BALANCE (''balance'') — the two the accountless guest pays through the link — and refuses the '
  'pickup add-on, which is the signed-in owner''s to pay. Shares api_create_payment''s body, so both '
  'take the same single-flight checkout lease.';



-- ---- 20260913000000_saved_cards.sql (saved cards / Peach tokenisation) ----
-- Saved cards — Peach card-on-file tokens for the signed-in customer (one-click reuse).
--
-- Card data NEVER touches our server (PCI SAQ A unchanged): the embedded Peach widget captures the PAN
-- client-side and returns only an opaque `registrationId` token, which we harvest server-side from the
-- checkout STATUS payload (never the webhook — it omits card.*) and store here with brand/last4/expiry.
--
-- Owner-scoped in BOTH RLS (defense in depth) and the api_* seam. Writes happen server-side only
-- (api_save_card is service_role-only, called from the confirm/harvest path); the customer-facing RPCs
-- list (metadata only — never the token) and delete their own cards. Idempotent DDL so catch-up.sql
-- can reuse this exact text.

create table if not exists saved_cards (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  provider text not null default 'peach',
  provider_registration_id text not null,
  brand text,
  last4 text,
  exp_month int,
  exp_year int,
  created_at timestamptz not null default now(),
  unique (user_id, provider_registration_id)
);
create index if not exists saved_cards_user_idx on saved_cards (user_id, created_at desc);

-- The blanket "grant on all tables to authenticated" ran in the original RLS migration, before this
-- table existed, so grant explicitly. No INSERT for authenticated — cards are only ever written by the
-- service-role harvest path (api_save_card). RLS still gates every row to its owner.
grant select, delete on saved_cards to authenticated;

alter table saved_cards enable row level security;
drop policy if exists saved_cards_select on saved_cards;
drop policy if exists saved_cards_delete on saved_cards;
drop policy if exists saved_cards_staff on saved_cards;
create policy saved_cards_select on saved_cards for select using (user_id = auth.uid());
create policy saved_cards_delete on saved_cards for delete using (user_id = auth.uid());
create policy saved_cards_staff on saved_cards for all using (is_staff()) with check (is_staff());

-- api_save_card — SERVER-ONLY harvest write. Called from the confirm/status path (service-role) when a
-- checkout came back with a registrationId (the customer ticked "save card" in the widget). Upserts on
-- (user, token) so re-paying with the same stored card refreshes its metadata rather than duplicating.
create or replace function api_save_card(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid   uuid := nullif(p ->> 'userId', '')::uuid;
  v_reg   text := nullif(p ->> 'registrationId', '');
  v_brand text := nullif(p ->> 'brand', '');
  v_last4 text := nullif(p ->> 'last4', '');
  v_em    int  := nullif(p ->> 'expMonth', '')::int;
  v_ey    int  := nullif(p ->> 'expYear', '')::int;
  v_row   saved_cards;
begin
  -- Grants are the primary gate (service_role only); this is defense in depth. A present-but-non-service
  -- JWT that somehow reaches here (staff excepted) is refused; a null claims context is the trusted
  -- server path (pg owner / service-role rpc).
  if nullif(current_setting('request.jwt.claims', true), '') is not null
     and coalesce(auth.role(), '') <> 'service_role'
     and not is_staff() then
    raise exception 'forbidden';
  end if;
  if v_uid is null or v_reg is null then
    raise exception 'invalid_request' using detail = 'save_card: userId and registrationId required';
  end if;
  insert into saved_cards (user_id, provider, provider_registration_id, brand, last4, exp_month, exp_year)
  values (v_uid, 'peach', v_reg, v_brand, v_last4, v_em, v_ey)
  on conflict (user_id, provider_registration_id) do update
    set brand = excluded.brand, last4 = excluded.last4,
        exp_month = excluded.exp_month, exp_year = excluded.exp_year
  returning * into v_row;
  return jsonb_build_object('id', v_row.id, 'saved', true);
end;
$$;

-- api_list_saved_cards — the caller's own cards for the account screen. METADATA ONLY: the opaque
-- provider_registration_id (the reusable token) is DELIBERATELY not returned to the browser — the reuse
-- flow reads it server-side. Owner-scoped DEFINER seam.
create or replace function api_list_saved_cards(p jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid   uuid := auth.uid();
  v_items jsonb;
begin
  if v_uid is null then
    raise exception 'unauthorized' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', c.id, 'brand', c.brand, 'last4', c.last4,
      'expMonth', c.exp_month, 'expYear', c.exp_year, 'createdAt', c.created_at
    ) order by c.created_at desc), '[]'::jsonb) into v_items
  from saved_cards c
  where c.user_id = v_uid;
  return v_items;
end;
$$;

-- api_delete_saved_card — remove one of the caller's own cards (idempotent). Deleting the local row does
-- NOT revoke the token at Peach; that's acceptable for a "forget this card" affordance.
create or replace function api_delete_saved_card(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_id  uuid := nullif(p ->> 'id', '')::uuid;
begin
  if v_uid is null then
    raise exception 'unauthorized' using errcode = '42501';
  end if;
  if v_id is null then
    raise exception 'invalid_request' using detail = 'delete_saved_card: id required';
  end if;
  delete from saved_cards where id = v_id and user_id = v_uid;
  return jsonb_build_object('id', v_id, 'deleted', true);
end;
$$;

-- api_list_card_tokens — the OPAQUE reusable tokens for one user, to hand the Peach widget as
-- `cardTokens` for one-click reuse. SERVER-ONLY (returns the tokens the browser must never see):
-- createPaymentLink calls it under the service-role port when building a checkout for a signed-in user.
create or replace function api_list_card_tokens(p jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid    uuid := nullif(p ->> 'userId', '')::uuid;
  v_tokens jsonb;
begin
  if nullif(current_setting('request.jwt.claims', true), '') is not null
     and coalesce(auth.role(), '') <> 'service_role'
     and not is_staff() then
    raise exception 'forbidden';
  end if;
  if v_uid is null then
    raise exception 'invalid_request' using detail = 'list_card_tokens: userId required';
  end if;
  select coalesce(jsonb_agg(c.provider_registration_id order by c.created_at desc), '[]'::jsonb)
    into v_tokens
  from saved_cards c
  where c.user_id = v_uid;
  return v_tokens;
end;
$$;

-- Lock down grants. Postgres implicitly grants EXECUTE to PUBLIC (and anon/authenticated are members),
-- so revoke from PUBLIC by name, then grant only the intended roles.
revoke execute on function api_save_card(jsonb)         from public, anon, authenticated;
revoke execute on function api_list_saved_cards(jsonb)  from public;
revoke execute on function api_delete_saved_card(jsonb) from public;
revoke execute on function api_list_card_tokens(jsonb)  from public, anon, authenticated;
grant  execute on function api_save_card(jsonb)         to service_role;
grant  execute on function api_list_saved_cards(jsonb)  to authenticated, service_role;
grant  execute on function api_delete_saved_card(jsonb) to authenticated, service_role;
grant  execute on function api_list_card_tokens(jsonb)  to service_role;

-- GDPR erasure. `api_erase_user` deletes the caller's `profiles` row in its GUARANTEED data-erasure
-- step; the `auth.users` removal is a SEPARATE, later step in the delete route that can fail (the row
-- is then banned but retained). So the auth.users ON DELETE CASCADE above is not enough on its own —
-- tie the token deletion to the profiles delete instead, which is the erase signal that always fires.
-- Deliberately NOT a redefine of the large api_erase_user (avoids the migration-revert-drift trap).
create or replace function erase_saved_cards_for_profile()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  delete from saved_cards where user_id = old.id;
  return old;
end;
$$;
drop trigger if exists saved_cards_erase_with_profile on profiles;
create trigger saved_cards_erase_with_profile
  before delete on profiles
  for each row execute function erase_saved_cards_for_profile();


-- ===================================================================================================
-- 20260915000000_quote_deposit_invoice — the RECEIPT-vs-INVOICE split. Re-applies the WINNING bodies
-- of enqueue_booking_notification / api_booking_receipt / api_mark_refunded (verbatim apart from the
-- deposit split) so catch-up carries the latest, and adds the notify_balance_paid trigger. Kept
-- byte-identical to the migration so catch-up-parity sees no body change.
-- ===================================================================================================
create or replace function enqueue_booking_notification()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.status = 'confirmed' and old.status is distinct from 'confirmed' then
    -- THE DEPOSIT SPLIT. A part-paid booking (a deposit settled, a balance still owed) gets a deposit
    -- RECEIPT; the full 'booking_confirmation' VAT invoice is fired later by notify_balance_paid when the
    -- balance clears. Everything with balance_due_minor = 0 at confirm — a pay-in-full quote, every
    -- ordinary catalogue booking — takes the else and is bit-for-bit the pre-deposit behaviour.
    if new.balance_due_minor > 0 then
      insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
      values (
        'email', new.customer_email, 'deposit_receipt',
        jsonb_build_object(
          'ref', new.ref, 'customerName', new.customer_name,
          'totalMinor', new.total_minor, 'depositMinor', new.deposit_minor,
          'balanceDueMinor', new.balance_due_minor, 'currency', new.currency
        ),
        new.id, 'deposit_receipt:' || new.id
      )
      on conflict (idempotency_key) do nothing;
    else
      insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
      values (
        'email', new.customer_email, 'booking_confirmation',
        jsonb_build_object(
          'ref', new.ref, 'customerName', new.customer_name,
          'totalMinor', new.total_minor, 'currency', new.currency
        ),
        new.id, 'booking_confirmation:' || new.id
      )
      on conflict (idempotency_key) do nothing;
    end if;
    insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
    values (
      'email', 'owner', 'owner_new_booking',
      jsonb_build_object(
        'ref', new.ref, 'customerName', new.customer_name,
        'totalMinor', new.total_minor, 'currency', new.currency
      ),
      new.id, 'owner_new_booking:' || new.id
    )
    on conflict (idempotency_key) do nothing;
    insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
    values (
      'telegram', 'owner', 'owner_new_booking',
      jsonb_build_object(
        'ref', new.ref, 'customerName', new.customer_name,
        'totalMinor', new.total_minor, 'currency', new.currency
      ),
      new.id, 'owner_new_booking_tg:' || new.id
    )
    on conflict (idempotency_key) do nothing;
    insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
    values (
      'whatsapp', 'owner', 'owner_new_booking',
      jsonb_build_object(
        'ref', new.ref, 'customerName', new.customer_name,
        'totalMinor', new.total_minor, 'currency', new.currency
      ),
      new.id, 'owner_new_booking_wa:' || new.id
    )
    on conflict (idempotency_key) do nothing;
    insert into notifications (user_id, type, title, body, data)
    select p.id, 'admin_new_booking', 'New booking',
           coalesce(nullif(new.customer_name, ''), 'A guest') || ' booked ' || new.ref
             || ' — €' || to_char(new.total_minor / 100.0, 'FM999990.00'),
           jsonb_build_object('ref', new.ref, 'bookingId', new.id)
    from profiles p
    where p.role in ('staff', 'admin')
      and not exists (
        select 1 from notifications n
        where n.user_id = p.id and n.type = 'admin_new_booking'
          and n.data ->> 'bookingId' = new.id::text
      );
    if new.user_id is not null then
      insert into notifications (user_id, type, title, body, data)
      select new.user_id, 'booking_confirmed', 'Booking confirmed',
             'Your booking ' || new.ref || ' is confirmed.',
             jsonb_build_object('ref', new.ref, 'bookingId', new.id)
      where not exists (
        select 1 from notifications n
        where n.user_id = new.user_id and n.type = 'booking_confirmed'
          and n.data ->> 'bookingId' = new.id::text
      );
    end if;
  elsif new.status = 'cancelled' and old.status is distinct from 'cancelled' then
    if new.user_id is not null then
      insert into notifications (user_id, type, title, body, data)
      select new.user_id, 'booking_cancelled', 'Booking cancelled',
             'Your booking ' || new.ref || ' has been cancelled.',
             jsonb_build_object('ref', new.ref, 'bookingId', new.id)
      where not exists (
        select 1 from notifications n
        where n.user_id = new.user_id and n.type = 'booking_cancelled'
          and n.data ->> 'bookingId' = new.id::text
      );
    end if;
  elsif new.status = 'refunded' and old.status is distinct from 'refunded' then
    insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
    values (
      'email', new.customer_email, 'booking_refunded',
      jsonb_build_object('ref', new.ref, 'customerName', new.customer_name),
      new.id, 'booking_refunded:' || new.id
    )
    on conflict (idempotency_key) do nothing;
    if new.user_id is not null then
      insert into notifications (user_id, type, title, body, data)
      select new.user_id, 'booking_refunded', 'Refund issued',
             'Your booking ' || new.ref || ' has been refunded.',
             jsonb_build_object('ref', new.ref, 'bookingId', new.id)
      where not exists (
        select 1 from notifications n
        where n.user_id = new.user_id and n.type = 'booking_refunded'
          and n.data ->> 'bookingId' = new.id::text
      );
    end if;
  elsif new.status = 'refund_pending' and old.status is distinct from 'refund_pending' then
    if not exists (
      select 1 from notification_outbox
      where booking_id = new.id and template = 'booking_cancellation'
    ) then
      insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
      values (
        'email', new.customer_email, 'booking_refund_pending',
        jsonb_build_object(
          'ref', new.ref, 'customerName', new.customer_name,
          'totalMinor', new.total_minor, 'currency', new.currency
        ),
        new.id, 'booking_refund_pending:' || new.id
      )
      on conflict (idempotency_key) do nothing;
      insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
      values (
        'email', 'owner', 'owner_refund_pending',
        jsonb_build_object(
          'ref', new.ref, 'customerName', new.customer_name,
          'totalMinor', new.total_minor, 'currency', new.currency
        ),
        new.id, 'owner_refund_pending:' || new.id
      )
      on conflict (idempotency_key) do nothing;
      insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
      values (
        'telegram', 'owner', 'owner_refund_pending',
        jsonb_build_object(
          'ref', new.ref, 'customerName', new.customer_name,
          'totalMinor', new.total_minor, 'currency', new.currency
        ),
        new.id, 'owner_refund_pending_tg:' || new.id
      )
      on conflict (idempotency_key) do nothing;
      insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
      values (
        'whatsapp', 'owner', 'owner_refund_pending',
        jsonb_build_object(
          'ref', new.ref, 'customerName', new.customer_name,
          'totalMinor', new.total_minor, 'currency', new.currency
        ),
        new.id, 'owner_refund_pending_wa:' || new.id
      )
      on conflict (idempotency_key) do nothing;
      insert into notifications (user_id, type, title, body, data)
      select p.id, 'admin_refund_pending', 'Refund needed',
             coalesce(nullif(new.customer_name, ''), 'A guest') || ' -- booking ' || new.ref
               || ' needs a refund in Peach.',
             jsonb_build_object('ref', new.ref, 'bookingId', new.id)
      from profiles p
      where p.role in ('staff', 'admin')
        and not exists (
          select 1 from notifications n
          where n.user_id = p.id and n.type = 'admin_refund_pending'
            and n.data ->> 'bookingId' = new.id::text
        );
    end if;
  elsif new.status = 'expired' and old.status = 'payment_pending' then
    insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
    values (
      'email', new.customer_email, 'booking_expired',
      jsonb_build_object('ref', new.ref, 'customerName', new.customer_name),
      new.id, 'booking_expired:' || new.id
    )
    on conflict (idempotency_key) do nothing;
  end if;
  return new;
end;
$$;
revoke execute on function enqueue_booking_notification() from public, anon, authenticated;
grant execute on function enqueue_booking_notification() to service_role;

create or replace function notify_balance_paid(p_payment_id uuid)
returns void
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_payment payments;
  v_booking bookings;
begin
  select * into v_payment from payments where id = p_payment_id;
  if not found then
    return;
  end if;
  select * into v_booking from bookings where id = v_payment.booking_id;
  if not found then
    return;
  end if;

  -- Only a LIVE booking gets the settled-in-full invoice (see migration 20260915000000).
  if v_booking.status not in ('confirmed', 'completed') then
    return;
  end if;

  if v_booking.customer_email is not null then
    insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
    values (
      'email', v_booking.customer_email, 'booking_confirmation',
      jsonb_build_object(
        'ref', v_booking.ref, 'customerName', v_booking.customer_name,
        'totalMinor', v_booking.total_minor, 'currency', v_booking.currency
      ),
      v_booking.id, 'booking_confirmation:' || v_booking.id
    )
    on conflict (idempotency_key) do nothing;
  end if;

  insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
  values (
    'email', 'owner', 'owner_balance_paid',
    jsonb_build_object(
      'ref', v_booking.ref, 'customerName', v_booking.customer_name,
      'totalMinor', v_booking.total_minor, 'currency', v_booking.currency
    ),
    v_booking.id, 'owner_balance_paid:' || v_booking.id
  )
  on conflict (idempotency_key) do nothing;
end;
$$;
revoke execute on function notify_balance_paid(uuid) from public, anon, authenticated;
grant execute on function notify_balance_paid(uuid) to service_role;

create or replace function trg_notify_balance_paid()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform notify_balance_paid(new.id);
  return new;
end;
$$;
revoke execute on function trg_notify_balance_paid() from public, anon, authenticated;
grant execute on function trg_notify_balance_paid() to service_role;

drop trigger if exists payments_notify_balance_paid on payments;
create trigger payments_notify_balance_paid
after update of status on payments
for each row
when (new.purpose = 'balance' and new.status = 'paid' and old.status is distinct from 'paid')
execute function trg_notify_balance_paid();

create or replace function api_booking_receipt(p jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_booking_id uuid := nullif(p ->> 'bookingId', '')::uuid;
  v_base jsonb;
  v_title text;
  v_when timestamptz;
  v_payment jsonb;
  v_phone text;
  v_locale text;
  v_bal bigint;
  v_addon_charged bigint := 0;
  v_custom jsonb;
begin
  if v_booking_id is null then
    raise exception 'invalid_request' using detail = 'booking_receipt: bookingId required';
  end if;

  v_base := booking_json(v_booking_id);
  if v_base is null then
    return null;
  end if;

  select a.title, o.starts_at
    into v_title, v_when
    from booking_items bi
    join session_occurrences o on o.id = bi.session_occurrence_id
    join activity_options ao on ao.id = bi.activity_option_id
    join activities a on a.id = ao.activity_id
   where bi.booking_id = v_booking_id
   order by o.starts_at asc, bi.created_at asc
   limit 1;

  -- SETTLED SO FAR, summed across the deposit ('booking') and the balance ('balance') rows; ordinary
  -- bookings have one 'booking' row so this equals the old limit-1. Only settled rows contribute.
  select case
           when count(*) filter (where pay.paid_minor > 0) = 0 then null
           else jsonb_build_object(
             'chargedAmountMinor',
               coalesce(sum(coalesce(pay.charged_amount_minor, pay.amount_minor))
                        filter (where pay.paid_minor > 0), 0),
             'chargedCurrency',
               coalesce(max(coalesce(pay.charged_currency, pay.currency))
                        filter (where pay.paid_minor > 0), max(pay.currency)),
             'paidAt', max(paid.occurred_at) filter (where pay.paid_minor > 0),
             'providerRef', (array_agg(paid.provider_event_id order by paid.occurred_at desc nulls last)
                             filter (where pay.paid_minor > 0 and paid.provider_event_id is not null))[1]
           )
         end
    into v_payment
    from payments pay
    left join lateral (
      select pe.occurred_at, pe.provider_event_id
        from payment_events pe
       where pe.payment_id = pay.id and pe.type in ('paid', 'captured')
       order by pe.occurred_at asc
       limit 1
    ) paid on true
   where pay.booking_id = v_booking_id
     and pay.purpose in ('booking', 'balance');

  if v_payment is not null then
    select coalesce(sum(coalesce(pay.charged_amount_minor, pay.amount_minor)), 0)
      into v_addon_charged
      from payments pay
     where pay.booking_id = v_booking_id
       and pay.purpose = 'pickup_addon'
       and pay.paid_minor > 0
       and exists (
         select 1 from booking_pickup_requests r
          where r.payment_id = pay.id and r.applied_at is not null
       )
       and coalesce(pay.charged_currency, pay.currency)
             is not distinct from (v_payment ->> 'chargedCurrency');
    if v_addon_charged > 0 then
      v_payment := v_payment || jsonb_build_object(
        'chargedAmountMinor', (v_payment ->> 'chargedAmountMinor')::bigint + v_addon_charged
      );
    end if;
  end if;

  select b.customer_phone, b.locale::text, b.balance_due_minor
    into v_phone, v_locale, v_bal
    from bookings b where b.id = v_booking_id;

  select coalesce(jsonb_agg(jsonb_build_object(
           'priceLabel', ci.description,
           'quantity', ci.quantity,
           'pax', null::int,
           'unitAmountEur', ci.unit_amount_minor::float / 100,
           'subtotalEur', ci.subtotal_minor::float / 100
         ) order by ci.position), '[]'::jsonb)
    into v_custom
    from booking_custom_items ci
   where ci.booking_id = v_booking_id;

  return v_base
    || jsonb_build_object('items', coalesce(v_base -> 'items', '[]'::jsonb) || v_custom)
    || jsonb_build_object('activityTitle', v_title, 'when', v_when)
    || jsonb_build_object('payment', coalesce(v_payment, 'null'::jsonb))
    || jsonb_build_object('customerPhone', v_phone)
    || jsonb_build_object('balanceDueMinor', coalesce(v_bal, 0))
    || jsonb_build_object('locale', v_locale);
end;
$$;
revoke execute on function api_booking_receipt(jsonb) from public, anon, authenticated;
grant execute on function api_booking_receipt(jsonb) to service_role;


-- ===================================================================================================
-- 20260916000000_quote_deposit_forfeit — the quote DEPOSIT is NON-REFUNDABLE. Re-applies the WINNING
-- body of api_mark_refunded (20260910000000) verbatim apart from the forfeit change: a genuine partial
-- deposit (0 < deposit_minor < total_minor) is KEPT, the booking is driven to a terminal 'cancelled',
-- the durable balance link is cleared, and the guest gets a deposit_forfeited notice. Kept byte-identical
-- to the migration so catch-up-parity sees no body change.
-- ===================================================================================================
create or replace function api_mark_refunded(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking_id uuid := nullif(p ->> 'bookingId', '')::uuid;
  v_booking bookings;
  v_payment payments;
  v_amount bigint;
  v_reversed int := 0;
  v_reversed_minor bigint := 0;
  v_partial_deposit boolean;
begin
  if not is_staff() then
    raise exception 'forbidden';
  end if;
  if v_booking_id is null then
    raise exception 'invalid_request' using detail = 'mark_refunded: bookingId required';
  end if;

  select * into v_booking from bookings where id = v_booking_id;
  if not found then
    raise exception 'booking_not_found';
  end if;

  if not exists (select 1 from payments where booking_id = v_booking_id) then
    raise exception 'payment_not_found';
  end if;

  -- THE QUOTE DEPOSIT IS NON-REFUNDABLE. A genuine PARTIAL deposit (0 < deposit_minor < total_minor) is
  -- the first `booking` payments row sized to the deposit — money the guest agreed is forfeit. A
  -- pay-in-full quote (deposit_minor = total_minor) and every ordinary booking (deposit_minor = 0) are
  -- NOT partial, so this is false and every branch below stays byte-for-byte the pre-forfeit behaviour.
  v_partial_deposit := v_booking.deposit_minor > 0 and v_booking.deposit_minor < v_booking.total_minor;

  -- Already handled -> no-op (idempotent: a repeat click must not error, re-reverse or re-email). For an
  -- ordinary booking that is "no row still holds money" (every row reversed, status rolled to
  -- 'refunded'). For a PARTIAL-DEPOSIT booking the forfeit deposit row holds money FOREVER by design, so
  -- that test is never true and the function would re-run on every click; its handled signal is instead
  -- the terminal 'cancelled' this function drives it to below.
  if v_partial_deposit then
    if v_booking.status = 'cancelled' then
      return jsonb_build_object('ok', true, 'alreadyRefunded', true);
    end if;
  elsif not exists (
    select 1 from payments
     where booking_id = v_booking_id
       and (status in ('paid', 'partially_refunded') or paid_minor > refunded_minor)
  ) then
    return jsonb_build_object('ok', true, 'alreadyRefunded', true);
  end if;

  -- Only a booking whose money is actually held may be refunded: the cancel path lands it in
  -- refund_pending (payment_state stays paid), or staff refund a confirmed/completed paid booking
  -- directly. Anything else (unpaid, draft, already cancelled with no money) is rejected. The payment
  -- half of the gate is the `not exists` above - a pending sibling row must not veto the refund.
  if v_booking.status not in ('refund_pending', 'confirmed', 'completed') then
    raise exception 'not_refundable'
      using detail = format('booking %s', v_booking.status);
  end if;

  -- Reverse the full outstanding (paid - already-refunded) amount of EVERY row that still holds money,
  -- oldest first, so the booking-level roll-up inside append_payment_event only reaches 'refunded' on
  -- the last one. append_payment_event derives the refunded state from the SUM of refund events.
  --
  -- EXCEPT the non-refundable deposit. A partial-deposit booking's deposit is its single `booking` row
  -- (the balance is a distinct 'balance' purpose, a pickup supplement a distinct 'pickup_addon'), so
  -- `not (v_partial_deposit and purpose = 'booking')` keeps the deposit while still reversing the
  -- balance and any supplement. For a non-partial booking the flag is false and the WHERE is unchanged.
  for v_payment in
    select * from payments
     where booking_id = v_booking_id
       and (status in ('paid', 'partially_refunded') or paid_minor > refunded_minor)
       and not (v_partial_deposit and purpose = 'booking')
     order by created_at
  loop
    v_amount := greatest(v_payment.paid_minor - v_payment.refunded_minor, 0);
    if v_amount > 0 then
      -- Record through the SAME path the webhook uses. The synthesised provider_event_id makes it
      -- idempotent at the ledger: a second call with the same id hits the
      -- (payment_id, provider_event_id, type) conflict and is a no-op, so the booking_refunded enqueue
      -- (which also guards old.status is distinct from 'refunded') never double-fires.
      perform append_payment_event(
        v_payment.id,
        'refunded',
        'manual:refund:' || v_payment.id::text,
        v_amount,
        now(),
        jsonb_build_object('source', 'admin_mark_refunded', 'bookingId', v_booking_id)
      );
      v_reversed := v_reversed + 1;
      v_reversed_minor := v_reversed_minor + v_amount;
    end if;
  end loop;

  -- FORFEIT FINALISATION (partial deposit only). append_payment_event cannot drive this booking terminal
  -- — the kept deposit row keeps the roll-up at 'paid', so status would sit in refund_pending forever.
  -- Drive it to the honest terminal state, kill the durable balance link, and send the forfeit notice.
  if v_partial_deposit then
    -- 'cancelled', NOT 'refunded': the trip is off and the deposit is KEPT, so "refunded" would be a
    -- false claim and would fire booking_refunded. 'cancelled' also fails resolveBalanceForToken's
    -- status='confirmed' gate, so the durable balance link is dead even though refunding the balance
    -- rebounds balance_due_minor 0 -> balance. (Guarded on status so a re-run is a clean no-op; the
    -- alreadyRefunded return above already short-circuits before here, this is belt-and-braces.)
    update bookings set status = 'cancelled', updated_at = now()
     where id = v_booking_id and status <> 'cancelled';

    -- Clear the balance link's CREDENTIAL too, so it is dead at the token, not only via the status gate.
    -- ONLY balance_token_hash — never token_hash, which is the guest's original quote/deposit link and
    -- their route to their own booking record.
    update quotes set balance_token_hash = null, updated_at = now()
     where booking_id = v_booking_id and balance_token_hash is not null;

    -- The guest's FORFEIT notice — the ONE email they get (the 'cancelled' transition mails no guest).
    -- refundedMinor tells the copy whether any balance was returned (both-paid) or not (deposit-only).
    -- Keyed on the booking id + the alreadyRefunded guard above, so a repeat click cannot double-send.
    if v_booking.customer_email is not null then
      insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
      values (
        'email', v_booking.customer_email, 'deposit_forfeited',
        jsonb_build_object(
          'ref', v_booking.ref, 'customerName', v_booking.customer_name,
          'depositMinor', v_booking.deposit_minor, 'refundedMinor', v_reversed_minor,
          'currency', v_booking.currency
        ),
        v_booking_id, 'deposit_forfeited:' || v_booking_id
      )
      on conflict (idempotency_key) do nothing;
    end if;
  end if;

  return jsonb_build_object('ok', true, 'paymentsReversed', v_reversed);
end;
$$;

revoke execute on function api_mark_refunded(jsonb) from public;
grant execute on function api_mark_refunded(jsonb) to authenticated, service_role;


-- ---------------------------------------------------------------------------
-- 20260917000000_booking_json_quote_lines.sql
-- ---------------------------------------------------------------------------
-- The guest's own booking page could not describe a booking made from a quote.
--
-- api_convert_quote sends every non-occurrence line — custom, rental and the transport add-on — to
-- booking_custom_items, because booking_items' NOT NULL occurrence + option are load-bearing for
-- capacity, the day sheet and the voucher. booking_json only ever aggregated booking_items, so a
-- quote booking arrived at /bookings/{ref} as a bare "Total EUR 616.00" with NOTHING itemising it —
-- and, because payment_state flips to 'paid' the moment the DEPOSIT clears, no mention that a
-- balance was still owed at all. Observed on BMT2D0A9EF6FF61C: 0 booking_items, 1 custom item, and
-- EUR 0.90 of EUR 1.00 outstanding and invisible.
--
-- This widens the shared DTO with four ADDITIVE keys: customItems, depositEur, balanceDueEur and
-- firstActivityAt. Additive on purpose — every other reader of booking_json (api_book, the receipt,
-- the confirmation email) keeps the exact keys it already had, and a Zod schema that does not know
-- the new ones ignores them.
--
-- The body below is the verbatim 20260910000000 definition plus those keys; nothing else is
-- touched. Mirror into supabase/catch-up.sql per the DB-sync convention (and `npm run setup:sql`).

create or replace function booking_json(p_booking_id uuid)
returns jsonb
language sql
stable
security invoker
set search_path = public
as $$
  select jsonb_build_object(
    'id', b.id, 'ref', b.ref, 'status', b.status, 'paymentState', b.payment_state,
    'customerName', b.customer_name, 'customerEmail', b.customer_email,
    'totalEur', b.total_minor::float / 100, 'currency', b.currency, 'source', b.source,
    'createdAt', b.created_at,
    'customItinerary', b.custom_itinerary,
    'pickupLocation', b.pickup_location,
    'dropoffLocation', b.dropoff_location,
    'pickupPending', b.pickup_pending,
    'pickupHotelSlug', b.pickup_hotel_slug,
    'childSeats', b.child_seats,
    'transportEur', b.transport_minor::float / 100,
    'supplements', coalesce((
      select jsonb_agg(jsonb_build_object(
        'name', bs.name, 'qty', bs.qty,
        'unitEur', bs.unit_minor::float / 100, 'totalEur', bs.total_minor::float / 100
      ) order by bs.position, bs.name)
      from booking_supplements bs where bs.booking_id = b.id
    ), '[]'::jsonb),
    'pendingPickup', (
      select jsonb_build_object(
        'pickupLocation', r.pickup_location,
        'dropoffLocation', r.dropoff_location,
        'feeEur', r.fee_minor::float / 100,
        'paymentId', r.payment_id,
        'createdAt', r.created_at
      )
      from booking_pickup_requests r
      where r.booking_id = b.id and r.applied_at is null and r.fee_minor > 0
      order by r.created_at desc
      limit 1
    ),
    'pickupRegion', b.pickup_region,
    'tripType', b.trip_type,
    'tripDirection', b.trip_direction,
    'flightNumber', b.flight_number,
    'arrivalTime', b.arrival_time,
    'returnDate', b.return_date,
    'returnTime', b.return_time,
    'departureFlightNumber', b.departure_flight_number,
    'roomOrCabin', b.room_or_cabin,
    'luggageDetails', b.luggage_details,
    'childSeatAge', b.child_seat_age,
    'travellerGender', b.traveller_gender,
    'travellerCompany', b.traveller_company,
    'travellerCountry', b.traveller_country,
    'specialNotes', b.special_notes,
    'disruption', b.disruption,
    'partySize', coalesce((
      select sum(coalesce(bi.pax, bi.quantity))
        from booking_items bi where bi.booking_id = b.id
    ), 0),
    -- The BOOKING-UNIT count, the unit seatsLeft is denominated in. For a per-person option it equals
    -- partySize; for a vehicle/private one it is 1 (one van / one trip, any group size). The date
    -- picker must filter on THIS, not partySize, or a 6-guest transfer is offered nothing.
    'unitsNeeded', coalesce((
      select sum(bi.quantity)
        from booking_items bi where bi.booking_id = b.id
    ), 0),
    'activityOptionId', (
      select bi.activity_option_id
        from booking_items bi where bi.booking_id = b.id order by bi.id limit 1
    ),
    'activitySlug', (
      select a.slug
        from booking_items bi
        join activity_options ao on ao.id = bi.activity_option_id
        join activities a on a.id = ao.activity_id
       where bi.booking_id = b.id
       order by bi.id limit 1
    ),
    'cancellable', (
      b.status = 'confirmed' and b.payment_state = 'paid'
      and (
        booking_awaiting_choice(b.disruption)
        or coalesce((
          select min(so.starts_at)
            from booking_items bi
            join session_occurrences so on so.id = bi.session_occurrence_id
           where bi.booking_id = b.id
        ), 'epoch'::timestamptz) > now() + interval '24 hours'
      )
    ),
    'reschedulable', (
      b.status = 'confirmed' and b.payment_state = 'paid'
      and (
        booking_awaiting_choice(b.disruption)
        or coalesce((
          select min(so.starts_at)
            from booking_items bi
            join session_occurrences so on so.id = bi.session_occurrence_id
           where bi.booking_id = b.id
        ), 'epoch'::timestamptz) > now() + interval '24 hours'
      )
    ),
    'serviceDate', (
      select min(so.starts_at)
        from booking_items bi
        join session_occurrences so on so.id = bi.session_occurrence_id
       where bi.booking_id = b.id
    ),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'priceLabel', bi.price_label, 'quantity', bi.quantity, 'pax', bi.pax,
        'unitAmountEur', bi.unit_amount_minor::float / 100, 'subtotalEur', bi.subtotal_minor::float / 100,
        'occurrenceId', bi.session_occurrence_id
      ))
      from booking_items bi where bi.booking_id = b.id
    ), '[]'::jsonb),
    -- ── A QUOTE BOOKING'S OWN LINES ─────────────────────────────────────────────────────────────
    -- api_convert_quote writes every non-occurrence line (custom, rental, transport) to
    -- booking_custom_items, so a booking minted from a quote has NO booking_items at all and the
    -- 'items' array above is empty. The guest's own page then showed a bare total with nothing
    -- explaining it. Ordered by `position` — the order the guest read the offer in.
    'customItems', coalesce((
      select jsonb_agg(jsonb_build_object(
        'description', ci.description,
        'quantity', ci.quantity,
        'unitAmountEur', ci.unit_amount_minor::float / 100,
        'subtotalEur', ci.subtotal_minor::float / 100,
        'startsAt', ci.starts_at
      ) order by ci.position)
      from booking_custom_items ci where ci.booking_id = b.id
    ), '[]'::jsonb),
    -- What was taken up front and what is still owed. payment_state reads 'paid' the moment the
    -- DEPOSIT clears, so without these the page calls a 10%-paid booking settled.
    'depositEur', b.deposit_minor::float / 100,
    'balanceDueEur', b.balance_due_minor::float / 100,
    -- The earliest thing the guest is booked on, across BOTH line tables — the balance falls due 24h
    -- before it. `serviceDate` above sees only session occurrences and is left alone (receipts read
    -- it); this is the quote-aware one. Null when no line carries a date, and the page then shows no
    -- deadline rather than inventing one.
    'firstActivityAt', least(
      (select min(so.starts_at) from booking_items bi
         join session_occurrences so on so.id = bi.session_occurrence_id
        where bi.booking_id = b.id),
      (select min(ci.starts_at) from booking_custom_items ci where ci.booking_id = b.id)
    )
  )
  from bookings b where b.id = p_booking_id;
$$;

-- ---- migration 20260918000000_release_pending_booking (remove an Awaiting-payment cart line) ----
-- Let a customer REMOVE an "Awaiting payment" line from their cart.
--
-- The gap this closes: a `payment_pending` booking is a real row holding real seats, and nothing the
-- customer could reach would clear it. api_cancel_booking refuses anything that is not
-- `confirmed` + `paid` ('not_cancellable'), so the only exits were the 30-minute hold timer and
-- run_booking_maintenance's grace sweep. The cart rendered the line with a "Complete payment" button
-- and no way out, so a checkout that could not proceed — the widget refusing to open, an upstream
-- payment error, or simply a change of mind — left the customer staring at a dead row and their own
-- seats locked away from them for the rest of the window.
--
-- This is DELIBERATELY NOT a second cancel path. It is the manual trigger for the sweep that already
-- exists, carrying the same money guards, and it can only ever produce the state that sweep would
-- have produced a few minutes later:
--
--   * 'expired', not 'cancelled' — 'expired' is what run_booking_maintenance writes for exactly this
--     row, and enqueue_booking_notification already has a payment_pending -> expired branch. Reusing
--     it means no new notification shape, and the admin queues keep reading the same states.
--   * THE MONEY GUARD IS THE POINT. A booking whose payment settled after the customer opened the
--     cart — the Peach webhook is asynchronous, so `payment_pending` on screen can be `paid` in the
--     database — must never be expirable by a click, or a guest would release the seats they have
--     just been charged for. The `not exists (… paid / paid_minor > 0 / settlement_review_at …)`
--     predicate below is copied from run_booking_maintenance for that reason, and it is checked
--     under a row lock taken FIRST, so a webhook settling concurrently either lands before the lock
--     (and we refuse) or after the flip (and append_payment_event's own oversold/called-off handling
--     routes it to refund_pending, which is the pre-existing late-settlement path — see
--     [[gytm-payment-late-settlement]]).
--   * NO GRACE PERIOD. The sweep waits `graceMinutes` because it acts on the customer's behalf
--     without being asked; this one IS the asking, so a freshly-created booking is releasable at
--     once. That is the only substantive difference from the sweep.
--
-- Ownership is checked IN the function (definer bypasses RLS), matching api_cancel_booking: the
-- booking's own user, or staff. `authenticated` gets the grant because the caller identity is
-- auth.uid() — an anonymous quote booking has a null user_id and matches neither branch, which is
-- correct: those are paid through a link, never held in anybody's cart.


create or replace function api_release_pending_booking(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ref text := nullif(p ->> 'ref', '');
  v_uid uuid := auth.uid();
  v_booking bookings;
  v_settled boolean;
begin
  if v_ref is null then
    raise exception 'invalid_request' using detail = 'release: ref required';
  end if;

  -- FOR UPDATE before anything is read off the row: a Peach webhook settling this same booking has to
  -- serialise against us, not interleave between the money check and the status flip.
  select * into v_booking from bookings where ref = v_ref for update;
  if not found then
    raise exception 'booking_not_found';
  end if;

  -- Ownership: the booking's own customer, or staff. (A definer function bypasses RLS -- check here.)
  if not (is_staff() or (v_uid is not null and v_booking.user_id = v_uid)) then
    raise exception 'forbidden';
  end if;

  -- Idempotent: already gone (the sweep beat us, or a double-click) -> report the current state
  -- rather than raising, so the cart's optimistic removal is never contradicted by an error toast.
  if v_booking.status in ('expired', 'cancelled', 'refunded', 'refund_pending') then
    return jsonb_build_object(
      'ok', true, 'ref', v_booking.ref, 'status', v_booking.status, 'alreadyReleased', true
    );
  end if;

  -- Only an unpaid, not-yet-confirmed booking. A confirmed one belongs to api_cancel_booking (which
  -- owes the guest a refund and the owner an alert); this path owes nobody anything.
  if not (v_booking.status in ('draft', 'held', 'payment_pending')
          and v_booking.payment_state in ('pending', 'failed')) then
    raise exception 'not_releasable'
      using detail = format('booking %s / payment %s', v_booking.status, v_booking.payment_state);
  end if;

  -- The money guard, verbatim from run_booking_maintenance. `payment_state` alone is not enough: it
  -- is a projection that a lost webhook can leave stale, so the payments rows are the authority.
  select exists (
    select 1 from payments pay
     where pay.booking_id = v_booking.id
       and (pay.status in ('paid', 'partially_refunded', 'refunded')
            or pay.paid_minor > 0
            or pay.settlement_review_at is not null)
  ) into v_settled;
  if v_settled then
    raise exception 'payment_settled'
      using detail = 'a payment on this booking has money against it; it cannot be released';
  end if;

  update bookings
     set status = 'expired', updated_at = now()
   where id = v_booking.id;

  -- Free the seats immediately -- the whole point of the button is that the customer gets their
  -- capacity back now rather than in twenty-eight minutes.
  update booking_holds
     set status = 'released'
   where booking_id = v_booking.id and status = 'active';

  -- Distinguishable from the sweep's 'auto_expire_booking' in the audit trail: one is us acting on a
  -- silent customer, the other is the customer acting for themselves.
  insert into audit_logs (actor_id, actor_role, action, entity_type, entity_id, summary)
  values (
    v_uid,
    case when is_staff() then 'staff' else 'customer' end,
    'release_pending_booking', 'booking', v_booking.id,
    'removed from cart before payment'
  );

  return jsonb_build_object('ok', true, 'ref', v_booking.ref, 'status', 'expired');
end;
$$;

-- Caller identity IS auth.uid() inside the function, so the grant goes to `authenticated` (never
-- anon) and the in-function ownership check does the authorization -- same shape as
-- api_cancel_booking. Both member roles are named in the revoke: Supabase's default grants survive a
-- bare `revoke from public` ([[gytm-definer-grant-leak]]).
revoke execute on function api_release_pending_booking(jsonb) from public, anon;
grant execute on function api_release_pending_booking(jsonb) to authenticated, service_role;


-- ---- migration 20260919000000_booking_custom_items_owner_read (guest reads their own quote lines) ----
-- A guest can read their OWN booking's custom lines.
--
-- 20260917000000 put `customItems` on the booking DTO and the confirmation page renders them, but the
-- guest still saw a bare total. The DTO was never the problem: `booking_json` is `security invoker`,
-- so its subquery over `booking_custom_items` runs under the CALLER's RLS — and that table has
-- carried exactly one policy since 20260909000000 introduced it:
--
--     create policy booking_custom_items_staff ... using (is_staff())
--
-- `booking_items` got an owner-or-staff SELECT policy in the original RLS migration
-- (20260615120800); its sibling never did. So for the person who paid, the subquery matched zero
-- rows and `customItems` came back `[]`.
--
-- WHY NOTHING FAILED LOUDLY. The `grant select ... to authenticated` is present, so this is not a
-- permission error — RLS filters rows, it does not raise. An empty array is indistinguishable from
-- "this booking has no custom lines", which is the normal case for every ordinary booking. Staff saw
-- the lines (the admin drawer, 20260917000000's own tests, and any check run as the table owner all
-- pass), so the gap was only ever visible to the guest. Verified against production on
-- BMTFE8B468EC8961: `booking_json` as owner returns the line; the booking's owner is `customer`, and
-- the staff-only policy is the sole policy on the table.
--
-- Mirrors booking_items_select verbatim, deliberately: the two tables hold the same thing (the lines
-- of one booking) and differ only in whether the line names an occurrence, so they must be readable
-- by the same people. An OWNERLESS quote booking (`user_id is null` — the guest paid from the emailed
-- link with no account) matches neither branch and stays invisible to anon and authenticated alike;
-- that path is read server-side under the link token, and api_claim_quote_bookings is what later
-- fills `user_id` in and brings the booking under this policy.


drop policy if exists booking_custom_items_select on booking_custom_items;
create policy booking_custom_items_select on booking_custom_items for select using (
  exists (select 1 from bookings b where b.id = booking_id and (b.user_id = auth.uid() or is_staff()))
);

-- ---- migration 20260920000000_pending_offer_valid_until (quote cart row shows the offer deadline) ----
-- A quote booking's cart row shows the OFFER's deadline instead of a countdown that never ran.
--
-- The cart's "Awaiting payment" row renders a mm:ss countdown off `holdExpiresAt`. That is the right
-- deadline for a web booking — the 30-minute hold on its seats — but a QUOTE booking has no hold at
-- all: api_convert_quote mints it straight from the quote's lines and never calls create_hold,
-- because a custom line reserves no capacity ("Holds nothing — a free-text line reserves no
-- capacity"). Measured in production: all 24 `web` bookings have a hold row, all 3 `quote` bookings
-- have none.
--
-- So `holdExpiresAt` came back null, the client's `Number.isFinite(NaN)` fallback floored the
-- remaining seconds at 0, and the guest was told "Pay within 00:00" on an offer with three weeks
-- left to run. Nothing was expiring; there was simply no deadline of that kind to show.
--
-- A quote does have a real deadline — `quotes.valid_until`, the date already printed on the offer
-- email and the quote page — so this returns it and the row states that instead.
--
-- DRIFT RULE (see 20260915000000 / 20260916000000, [[gytm-migration-revert-drift]]): the body below
-- is 20260733000001's WINNING body re-applied VERBATIM apart from one join and one key. Re-applying
-- a stale body is how an earlier fix gets silently reverted.
--
-- WHAT IS DELIBERATELY NOT EXPOSED: only the date. `quotes` also holds the link token hash and the
-- guest's email, and this function is `security definer` (so the join bypasses RLS). It stays scoped
-- by `b.user_id = v_uid` exactly as before — the join adds a date to rows the caller could already
-- read, and nothing else.


create or replace function api_my_pending_bookings(p jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_rows jsonb;
begin
  if v_uid is null then
    raise exception 'unauthorized' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(t.row order by t.created_at desc), '[]'::jsonb) into v_rows
  from (
    select
      jsonb_build_object(
        'ref', b.ref,
        'status', b.status,
        'paymentState', b.payment_state,
        'totalMinor', b.total_minor,
        'currency', b.currency,
        'createdAt', b.created_at,
        'holdExpiresAt', h.expires_at,
        -- CHANGE 2 of 2: the offer's own deadline. Null for every non-quote booking, which is what
        -- tells the cart to keep showing the seat-hold countdown for those.
        'offerValidUntil', q.valid_until,
        'title', coalesce(a.title, 'Your booking'),
        'startsAt', occ.starts_at
      ) as row,
      b.created_at
    from bookings b
    left join lateral (
      select bh.expires_at from booking_holds bh
      where bh.booking_id = b.id and bh.status = 'active'
      order by bh.expires_at desc
      limit 1
    ) h on true
    -- CHANGE 1 of 2: the quote this booking was converted from, if any. `quotes.booking_id` is
    -- UNIQUE (it is the schema-level half of "one quote never mints two bookings"), so this can
    -- never fan a booking out into duplicate rows.
    left join quotes q on q.booking_id = b.id
    left join lateral (
      select bi.session_occurrence_id, bi.activity_option_id from booking_items bi
      where bi.booking_id = b.id
      order by bi.created_at
      limit 1
    ) item on true
    left join session_occurrences occ on occ.id = item.session_occurrence_id
    left join activity_options ao on ao.id = item.activity_option_id
    left join activities a on a.id = ao.activity_id
    where b.user_id = v_uid
      and b.status = 'payment_pending'
      and b.payment_state = 'pending'
  ) t;
  return v_rows;
end;
$$;

revoke execute on function api_my_pending_bookings(jsonb) from public;
grant execute on function api_my_pending_bookings(jsonb) to authenticated;


-- The customer's route stops being browser-only.
--
-- WHAT WENT WRONG. A Custom Road Trip (pricing_mode = 'vehicle_custom') is a full-day private
-- vehicle whose entire deliverable IS the list of places. That list travelled from the AI planner to
-- checkout through ONE channel: a sessionStorage key in the visitor's own tab, because the route is
-- too big for the URL. Nothing server-side ever saw it until api_book. On 9 Aug 2026 booking
-- BMTFF77DC5CDD471 confirmed and was paid (€100, 2 guests, 8 Oct) with custom_itinerary NULL — the
-- stash was gone by the time checkout read it, and the same absence shows in the hold record: that
-- booking's consumed hold was created in the SAME instant as the booking (api_book minted one
-- inline) instead of minutes earlier like every healthy one, because the hold id had vanished with
-- it. Two symptoms, one cause. The operator was left with a paid trip and no route, unrecoverable:
-- booking_holds had nowhere to keep one.
--
-- THE FIX, and why it is here rather than in the client. The route is now sent when the HOLD is
-- taken — the first moment the server hears about this booking at all — and stored on the hold. At
-- pay time the server prefers the client's copy (the customer may have edited the day after
-- holding) and falls back to the hold's. The browser stops being the sole custodian of the thing the
-- product is.
--
-- Deliberately NOT done here: api_book is untouched. It already accepts `itinerary`, so the fallback
-- is a resolution step in front of it (services/bookings.ts), and a 376-line money-path function
-- does not get rewritten for a field it already takes.

alter table booking_holds add column if not exists custom_itinerary jsonb;

comment on column booking_holds.custom_itinerary is
  'The customer-built route captured when the spot was held, so a browser that loses its copy before pay cannot lose the route. Read back by resolveCustomRoute at booking time; NULL for every activity that has no custom route.';

-- api_create_hold: unchanged except that it now records the route.
--
-- The store is idempotent-replay-safe in the same shape as created_by directly below it: create_hold
-- returns the EXISTING hold for a repeated idempotency key, and a replay must not blank a route the
-- first call already stored. So it only ever fills a NULL — never overwrites, never clears.
create or replace function api_create_hold(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_occ uuid := (p ->> 'occurrenceId')::uuid;
  v_key text := p ->> 'idempotencyKey';
  v_expected_slug text := nullif(p ->> 'expectedSlug', '');
  v_people bigint := coalesce((p ->> 'people')::bigint, 0);
  v_route jsonb := case when jsonb_typeof(p -> 'itinerary') = 'array'
                          and jsonb_array_length(p -> 'itinerary') > 0
                        then p -> 'itinerary' end;
  v_mode text := 'per_person';
  v_is_private boolean := false;
  v_qty int;
  v_hold booking_holds;
  v_uid uuid;
begin
  if v_occ is null or v_key is null then
    raise exception 'invalid_request';
  end if;
  if v_people <= 0 or v_people > 1000000 then
    raise exception 'invalid_party';
  end if;
  if v_expected_slug is not null and not exists (
    select 1 from session_occurrences so
    join activity_options o on o.id = so.activity_option_id
    join activities a on a.id = o.activity_id
    where so.id = v_occ and a.slug = v_expected_slug
  ) then
    raise exception 'occurrence_activity_mismatch';
  end if;

  select a.pricing_mode, (o.private_base_minor is not null)
    into v_mode, v_is_private
  from session_occurrences so
  join activity_options o on o.id = so.activity_option_id
  join activities a on a.id = o.activity_id
  where so.id = v_occ;
  v_qty := case when coalesce(v_mode, 'per_person') in ('vehicle', 'vehicle_custom')
                  or coalesce(v_is_private, false) then 1 else v_people::int end;

  v_hold := create_hold(v_occ, v_qty, v_key);

  -- Stamp ownership for the server-mediated path (see the function comment). Prefer a real JWT
  -- identity when one exists; only ever fill a NULL created_by (idempotent replays keep the original).
  v_uid := coalesce(auth.uid(), nullif(p ->> 'userId', '')::uuid);
  if v_uid is not null and v_hold.created_by is null then
    update booking_holds set created_by = v_uid where id = v_hold.id and created_by is null;
    select * into v_hold from booking_holds where id = v_hold.id;
  end if;

  if v_route is not null and v_hold.custom_itinerary is null then
    update booking_holds set custom_itinerary = v_route
    where id = v_hold.id and custom_itinerary is null;
  end if;

  return jsonb_build_object('holdId', v_hold.id, 'quantity', v_hold.quantity, 'expiresAt', v_hold.expires_at);
end;
$$;

-- `create or replace` preserves the existing ACL, so this is belt-and-braces — but it is restated in
-- full because the lockdown (20260807000000) is what keeps a bot from squatting a hot occurrence's
-- seats by calling this directly with an anon key, and a future replace that forgets it would reopen
-- that quietly. Same three roles as the lockdown named.
revoke execute on function api_create_hold(jsonb) from public, anon, authenticated;
grant execute on function api_create_hold(jsonb) to service_role;

-- What the server needs at pay time to decide whether a route is required and where to get it.
--
-- Returns the occurrence's pricing mode plus any route the hold kept, in ONE round trip. The mode is
-- read from the occurrence rather than trusted from the caller for the usual reason: it decides
-- whether a missing route is fatal, so a client that could assert it could opt out of the check.
create or replace function api_hold_route(p jsonb)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'pricingMode', (
      select a.pricing_mode
      from session_occurrences so
      join activity_options o on o.id = so.activity_option_id
      join activities a on a.id = o.activity_id
      where so.id = (p ->> 'occurrenceId')::uuid
    ),
    'itinerary', (
      select h.custom_itinerary
      from booking_holds h
      where h.id = nullif(p ->> 'holdId', '')::uuid
    )
  );
$$;

-- New function, so its grants DO matter: a fresh function is executable by public by default, and
-- this one reads a hold's route. Service-role only, like every other api_* on the booking path.
revoke execute on function api_hold_route(jsonb) from public, anon, authenticated;
grant execute on function api_hold_route(jsonb) to service_role;


-- ---- 20260922000000_business_settings -------------------------------------
-- 20260922000000_business_settings
--
-- The customer-facing "Chat on WhatsApp" number, editable from the admin Dashboard.
--
-- Every wa.me deep link on the site (the ContactFloat bubble, the footer, booking cards, rental,
-- transfers, the disruption banner, ...) is built by whatsappUrl() in src/lib/seo/site.ts, which
-- until now derived the number from the compile-time constant SITE.phone -- so changing the WhatsApp
-- number meant a code edit + a redeploy. This table lets the owner change it from /admin without a
-- deploy. It is DELIBERATELY only the wa.me number: the displayed phone, the tel: links, the invoice
-- footer and the schema.org business data all stay on SITE.phone, so the WhatsApp number is free to
-- differ from the call number.
--
-- Singleton: `id boolean primary key default true check (id)` -- the primary key plus the check that
-- id is always true means at most one row can ever exist, so a reader does `select ... limit 1` and a
-- writer `update`s without needing to know a key.
--
-- Public read (the number is rendered into every visitor's page), staff write -- the guest_reviews
-- (20260822000000) pattern. A blank/absent number is the app's cue to fall back to SITE.phone, so the
-- wa.me links are never broken; getWhatsAppNumber() (src/lib/settings/whatsapp-number.ts) does that.
--
-- Idempotent throughout (this file is appended verbatim to supabase/catch-up.sql).

create table if not exists business_settings (
  id boolean primary key default true check (id),
  -- Stored free-form as typed ("+230 5772 9919"); whatsappUrl() strips it to digits at link time. The
  -- check bounds the DIGIT count to the wa.me/E.164 range (8..15) so a malformed number can never
  -- reach the link builder -- a belt to the admin card's own validation. NULL means "no override, use
  -- the SITE.phone fallback".
  whatsapp_number text
    check (whatsapp_number is null
           or length(regexp_replace(whatsapp_number, '\D', '', 'g')) between 8 and 15),
  updated_at timestamptz not null default now(),
  -- The staff member who last changed it; set null rather than block if that account is later deleted.
  updated_by uuid references profiles (id) on delete set null
);

-- Exactly one row, created idempotently. `on conflict do nothing` so re-running this file (it lives in
-- catch-up.sql) never disturbs a number the owner has already set.
insert into business_settings (id) values (true) on conflict (id) do nothing;

alter table business_settings enable row level security;

-- Public read: the number is shown to every visitor, so anon must be able to select it.
drop policy if exists business_settings_public_read on business_settings;
create policy business_settings_public_read on business_settings for select using (true);

-- Staff write: the same boundary as every other admin mutation. Only UPDATE -- the singleton row
-- already exists and must never be removed or duplicated, so insert/delete stay closed.
drop policy if exists business_settings_staff on business_settings;
create policy business_settings_staff on business_settings for update using (is_staff()) with check (is_staff());

grant select on business_settings to anon, authenticated, service_role;
grant update on business_settings to authenticated;


-- ===================================================================================================
-- 20260923000000_receipt_per_line_activity_title — the VAT invoice/receipt printed every line under ONE
-- tour's name. api_booking_receipt returned a single booking-wide activityTitle and buildInvoice
-- prefixed it onto every line; a converted quote that mixes several tours + transfers + a rental then
-- read "Catamaran Cruise – Ile Aux Cerfs — Nissan March …". This re-applies the WINNING body verbatim
-- apart from moving the title ONTO EACH LINE: a catalogue line carries its own activity's title, a
-- custom line carries title = null. Preserves `from booking_custom_items` and the `balanceDueMinor`
-- projection (both pinned by resolved-function-bodies.test.ts). Last definition wins, so this sits at
-- the end of catch-up.sql and matches the migration's newest body (catch-up-parity.test.ts).
-- ===================================================================================================
create or replace function api_booking_receipt(p jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_booking_id uuid := nullif(p ->> 'bookingId', '')::uuid;
  v_base jsonb;
  v_title text;
  v_when timestamptz;
  v_payment jsonb;
  v_phone text;
  v_locale text;
  v_bal bigint;
  v_addon_charged bigint := 0;
  v_items jsonb;
  v_custom jsonb;
begin
  if v_booking_id is null then
    raise exception 'invalid_request' using detail = 'booking_receipt: bookingId required';
  end if;

  v_base := booking_json(v_booking_id);
  if v_base is null then
    return null;
  end if;

  -- The booking-wide "headline" activity title (the FIRST tour) + earliest trip date, for the header.
  select a.title, o.starts_at
    into v_title, v_when
    from booking_items bi
    join session_occurrences o on o.id = bi.session_occurrence_id
    join activity_options ao on ao.id = bi.activity_option_id
    join activities a on a.id = ao.activity_id
   where bi.booking_id = v_booking_id
   order by o.starts_at asc, bi.created_at asc
   limit 1;

  select case
           when count(*) filter (where pay.paid_minor > 0) = 0 then null
           else jsonb_build_object(
             'chargedAmountMinor',
               coalesce(sum(coalesce(pay.charged_amount_minor, pay.amount_minor))
                        filter (where pay.paid_minor > 0), 0),
             'chargedCurrency',
               coalesce(max(coalesce(pay.charged_currency, pay.currency))
                        filter (where pay.paid_minor > 0), max(pay.currency)),
             'paidAt', max(paid.occurred_at) filter (where pay.paid_minor > 0),
             'providerRef', (array_agg(paid.provider_event_id order by paid.occurred_at desc nulls last)
                             filter (where pay.paid_minor > 0 and paid.provider_event_id is not null))[1]
           )
         end
    into v_payment
    from payments pay
    left join lateral (
      select pe.occurred_at, pe.provider_event_id
        from payment_events pe
       where pe.payment_id = pay.id and pe.type in ('paid', 'captured')
       order by pe.occurred_at asc
       limit 1
    ) paid on true
   where pay.booking_id = v_booking_id
     and pay.purpose in ('booking', 'balance');

  if v_payment is not null then
    select coalesce(sum(coalesce(pay.charged_amount_minor, pay.amount_minor)), 0)
      into v_addon_charged
      from payments pay
     where pay.booking_id = v_booking_id
       and pay.purpose = 'pickup_addon'
       and pay.paid_minor > 0
       and exists (
         select 1 from booking_pickup_requests r
          where r.payment_id = pay.id and r.applied_at is not null
       )
       and coalesce(pay.charged_currency, pay.currency)
             is not distinct from (v_payment ->> 'chargedCurrency');
    if v_addon_charged > 0 then
      v_payment := v_payment || jsonb_build_object(
        'chargedAmountMinor', (v_payment ->> 'chargedAmountMinor')::bigint + v_addon_charged
      );
    end if;
  end if;

  select b.customer_phone, b.locale::text, b.balance_due_minor
    into v_phone, v_locale, v_bal
    from bookings b where b.id = v_booking_id;

  -- Catalogue lines, EACH with its own activity title. Same FROM/WHERE as booking_json's items and NO
  -- order by — so item order is byte-identical to before (the owner-alert party mix and voucher lines[0]
  -- read it positionally); the title is the ONLY addition, via a correlated subquery. A JOIN/order by
  -- here reordered the age bands and broke the owner alert — do not reintroduce either.
  select coalesce(jsonb_agg(jsonb_build_object(
           'title', (select a.title
                       from activity_options ao
                       join activities a on a.id = ao.activity_id
                      where ao.id = bi.activity_option_id),
           'when', (select o.starts_at from session_occurrences o where o.id = bi.session_occurrence_id),
           'priceLabel', bi.price_label,
           'quantity', bi.quantity,
           'pax', bi.pax,
           'unitAmountEur', bi.unit_amount_minor::float / 100,
           'subtotalEur', bi.subtotal_minor::float / 100,
           'occurrenceId', bi.session_occurrence_id
         )), '[]'::jsonb)
    into v_items
    from booking_items bi
   where bi.booking_id = v_booking_id;

  -- The priced lines that have no session_occurrence (a converted quote's custom/transfer lines, and
  -- rentals). title = null so buildInvoice adds no prefix — the description already names the line.
  select coalesce(jsonb_agg(jsonb_build_object(
           'title', null::text,
           'when', ci.starts_at,
           'priceLabel', ci.description,
           'quantity', ci.quantity,
           'pax', null::int,
           'unitAmountEur', ci.unit_amount_minor::float / 100,
           'subtotalEur', ci.subtotal_minor::float / 100
         ) order by ci.position), '[]'::jsonb)
    into v_custom
    from booking_custom_items ci
   where ci.booking_id = v_booking_id;

  return v_base
    || jsonb_build_object('items', v_items || v_custom)
    || jsonb_build_object('activityTitle', v_title, 'when', v_when)
    || jsonb_build_object('payment', coalesce(v_payment, 'null'::jsonb))
    || jsonb_build_object('customerPhone', v_phone)
    || jsonb_build_object('balanceDueMinor', coalesce(v_bal, 0))
    || jsonb_build_object('locale', v_locale);
end;
$$;

revoke execute on function api_booking_receipt(jsonb) from public, anon, authenticated;
grant execute on function api_booking_receipt(jsonb) to service_role;


-- ===================================================================================================
-- 20260924000000_line_transport_addon — a round-trip transfer attached to a tour/custom line as three
-- nullable columns, not a separate line, so it travels with the activity on the calendar and reads as one
-- line + add-on on the receipt. Purely additive; null on every existing row. Idempotent for re-runs.
-- ===================================================================================================
alter table quote_items
  add column if not exists transport_pickup_label text,
  add column if not exists transport_dropoff_label text,
  add column if not exists transport_fare_minor bigint
    check (transport_fare_minor is null or transport_fare_minor >= 0);

alter table booking_items
  add column if not exists transport_pickup_label text,
  add column if not exists transport_dropoff_label text,
  add column if not exists transport_fare_minor bigint
    check (transport_fare_minor is null or transport_fare_minor >= 0);

alter table booking_custom_items
  add column if not exists transport_pickup_label text,
  add column if not exists transport_dropoff_label text,
  add column if not exists transport_fare_minor bigint
    check (transport_fare_minor is null or transport_fare_minor >= 0);


-- ===================================================================================================
-- 20260925000000_convert_quote_transport — api_convert_quote includes Σ transport_fare_minor in the
-- total check and copies the three transport_* columns onto booking_items + booking_custom_items.
-- Winning body; last def wins. Contracts (quote_owner_for_email, deposit sizing) preserved.
-- ===================================================================================================
create or replace function api_convert_quote(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_quote quotes;
  v_prior bookings;
  v_booking bookings;
  v_reusable boolean := false;
  v_lines_minor bigint;
  v_owner uuid;
  v_deposit_minor bigint;
  v_seats record;
  v_hold booking_holds;
begin
  select * into v_quote
    from quotes
   where id = nullif(p ->> 'quoteId', '')::uuid
   for update;

  if v_quote.id is null then
    raise exception 'quote_not_found';
  end if;

  -- Convert-once, read off converted_at, and meaning "one PAYABLE booking at a time" (see above).
  if v_quote.converted_at is not null then
    -- LOCK THE MONEY BEFORE JUDGING IT. append_payment_event locks the payments row, writes paid_minor
    -- and status onto it, and only THEN rolls the projection onto bookings — so an unlocked read of
    -- either table can catch a settlement mid-flight, conclude "this booking never took a cent", mint
    -- booking B, commit, and let the settlement land on A afterwards. Taking the payments locks in the
    -- same order that function does serialises the two instead of racing them.
    --
    -- `bookings` is deliberately NOT locked here as well: api_create_payment locks bookings and then
    -- payments, so adding payments -> bookings on this side would close a deadlock cycle on the money
    -- path. It is also unnecessary — read committed gives every later statement in this function a
    -- fresh snapshot, so once the payments locks are held the reads below see post-settlement state.
    -- A booking with no payments row locks nothing, which is safe: api_create_payment refuses a dead
    -- booking ('booking_not_payable'), so no first payment can appear on one.
    perform 1 from payments where booking_id = v_quote.booking_id for update;

    -- booking_id is null here when an erasure hard-deleted the booking; the select finds nothing and
    -- v_reusable stays false, which is the section-4 invariant.
    select * into v_prior from bookings where id = v_quote.booking_id;
    v_reusable := found
      and v_prior.status in ('expired', 'cancelled', 'failed')
      and v_prior.payment_state in ('pending', 'failed')
      -- Money already HELD, including the shapes the booking-level projection above cannot see: an
      -- underpayment (append_payment_event sets 'pending' when v_paid > 0 but below amount_minor, so
      -- paid_minor is positive while payment_state is not) and a wrong-currency settlement quarantine
      -- (settlement_review_at, 20260830000000), which is stamped precisely so the projection is left
      -- alone. Both hold a capture on a booking that still reads clean.
      and not exists (
        select 1 from payments pay
         where pay.booking_id = v_prior.id
           and (pay.paid_minor > 0
                or pay.refunded_minor > 0
                or pay.status in ('paid', 'partially_refunded', 'refunded')
                or pay.settlement_review_at is not null)
      )
      -- Money that can still be TAKEN. A dead booking is not a dead checkout: run_booking_maintenance
      -- expires a booking 30 minutes after it was CREATED, while a Peach session stays completable
      -- ~30 minutes after it was MINTED (api_pending_payment_checkouts says exactly that in its own
      -- comment). A guest who converts at T0, clicks Pay at T0+26 and wanders off has an expired
      -- booking at T0+30 and a live session until roughly T0+56; re-arming in that gap leaves TWO
      -- payable sessions for one quote — the double charge api_create_payment's reuse guard refuses
      -- to create one level down ("Minting a replacement while the original is still live would leave
      -- TWO payable sessions for one booking") and the one 20260902000000 removed. It is also
      -- unreconcilable: api_pending_payment_checkouts only re-queries bookings still in
      -- 'payment_pending', so once the booking is expired a lost webhook on that capture is never
      -- swept — money taken, no ledger row, no link back to the quote.
      --
      -- 30 minutes, not api_create_payment's 25: 25 is the REUSE window, deliberately short of the
      -- session's life so a session handed back cannot die under the guest. The hazard here lasts as
      -- long as the session can be COMPLETED, so this window has to be the wider of the two.
      --
      -- The claimed-lease arm covers the ~90 seconds where a caller is out at Peach and the session
      -- id has not been recorded yet: provider_checkout_id is still null, so freshness alone sees
      -- nothing and would re-arm into the same double charge moments before the session appears.
      --
      -- The refusal is a wait, not a wall: mapDbError already reads quote_already_converted as "has
      -- already been paid for or is being paid", and the quote converts again once the session dies.
      and not exists (
        select 1 from payments pay
         where pay.booking_id = v_prior.id
           and ((pay.provider_checkout_id is not null
                 and coalesce(pay.checkout_created_at, pay.updated_at) > now() - interval '30 minutes')
                or (pay.checkout_claimed_until is not null and pay.checkout_claimed_until > now()))
      );
    if not v_reusable then
      raise exception 'quote_already_converted'
        using detail = coalesce(v_prior.status::text, 'linked booking no longer exists');
    end if;

    -- THE DEAD BOOKING'S SEATS GO BACK BEFORE THIS CONVERSION TAKES FRESH ONES.
    --
    -- Re-arming mints a SECOND booking, which takes its own holds below — so unless the first
    -- booking's holds are released here, one quote reserves two sets of seats for the rest of their
    -- 30-minute life. Nothing else does it: run_booking_maintenance releases holds only for the
    -- bookings IT expired, so a hand-cancelled booking (or one already swept while its hold ran on)
    -- keeps them. On a nearly-full departure that is the guest's own abandoned attempt selling the
    -- trip out from under them — create_hold would raise `insufficient_capacity` and the quote would
    -- read as sold out to the only person entitled to those seats.
    --
    -- Safe because of what the branch above has already established: this booking is dead
    -- (expired/cancelled/failed), never took a cent, and cannot take one.
    update booking_holds set status = 'released'
     where booking_id = v_prior.id and status = 'active';
  end if;

  -- Status: an explicit WHITELIST, the shape api_create_payment uses next door. A blacklist of one
  -- let a 'draft' (a half-built offer the owner has not sent, whose total may be mid-edit) and an
  -- 'expired' quote — a terminal state of the very enum this migration created — both convert.
  -- 'accepted' is in the list because that is what a converted quote's status already is, and the
  -- re-arm branch above has to be able to get past here.
  if v_quote.status = 'cancelled' then
    raise exception 'quote_cancelled';
  end if;
  if v_quote.status = 'expired' or v_quote.valid_until < current_date then
    raise exception 'quote_expired';
  end if;
  if v_quote.status not in ('sent', 'accepted') then
    raise exception 'quote_not_convertible' using detail = v_quote.status::text;
  end if;

  -- A zero-total quote mints a booking that can NEVER confirm: api_create_payment skips the FX pin
  -- for a zero amount, and append_payment_event carries an explicit guard whose own comment says "a
  -- zero-amount payment must never read as fully paid (0 >= 0)". The booking would sit in
  -- payment_pending until the sweep expired it. quotes.total_minor DEFAULTS to 0, so an empty or
  -- never-priced draft reaches this state by default rather than by accident.
  if coalesce(v_quote.total_minor, 0) <= 0 then
    raise exception 'quote_not_convertible' using detail = 'zero total';
  end if;

  -- THE TWO CATALOGUE LINES THIS FUNCTION WILL NOT PRICE INTO A SEAT. Both fail closed here, before
  -- anything is minted, because both are shapes whose capacity meaning cannot be read off the line.
  --
  -- 1. AN OPTION THAT IS NOT COUNTED IN PEOPLE. For a private or vehicle option one BOOKING is one
  --    unit of the pool — the pool counts trips, not heads (20260908000000), and create_booking
  --    records the real party size in booking_items.pax while writing quantity 1. A quote line for
  --    six guests would therefore reserve SIX DEPARTURES if it were held like a per-person line, and
  --    reserve one while charging for six if it were not. Neither is a guess worth making on the
  --    money path: there is no editor that can draft such a line yet, and the pay route's re-price
  --    gate refuses it one step earlier anyway (a private option has no activity_option_prices row
  --    to re-price against). The day the editor learns to quote a private charter, this is the
  --    branch that teaches the conversion the trips-vs-heads mapping — deliberately, with a test.
  --
  -- 2. AN OPTION THAT IS NOT THE OCCURRENCE'S OWN. `quote_item_shape` makes a catalogue line name
  --    both, and nothing checks they agree; a mismatch would write a booking_items row whose option
  --    contradicts its occurrence, i.e. a voucher and a day sheet naming a trip the guest is not on.
  --
  -- Both reuse `quote_not_convertible` rather than minting a token of their own: mapDbError already
  -- reads it as "This quote is not ready to pay yet — please message us", which is exactly true, and
  -- an unfinished offer is the operator's to fix.
  if exists (
    select 1
      from quote_items qi
      join activity_options o on o.id = qi.activity_option_id
      join activities a on a.id = o.activity_id
     where qi.quote_id = v_quote.id
       and qi.kind = 'catalogue'
       and (o.private_base_minor is not null
            or coalesce(a.pricing_mode::text, 'per_person') in ('vehicle', 'vehicle_custom'))
  ) then
    raise exception 'quote_not_convertible' using detail = 'private/vehicle catalogue line';
  end if;
  if exists (
    select 1
      from quote_items qi
      join session_occurrences so on so.id = qi.session_occurrence_id
     where qi.quote_id = v_quote.id
       and qi.kind = 'catalogue'
       and qi.activity_option_id is distinct from so.activity_option_id
  ) then
    raise exception 'quote_not_convertible' using detail = 'catalogue line option is not its occurrence''s';
  end if;

  -- THE CHARGE AND THE ITEMISATION MUST AGREE, or nothing is minted.
  --
  -- The amount charged is copied from quotes.total_minor while the lines are copied by the separate
  -- statement below, and nothing else ties the two together: total_minor carries no CHECK against its
  -- lines and no trigger recomputing it, and the editor writes the total in a different statement from
  -- the lines. src/lib/quotes/totals.ts states in its own header that there is no Zod layer above it
  -- yet and that its guards "ARE the only validation between a browser-supplied line and
  -- quotes.total_minor" — so this function is the last gate before a card is charged, and failing OPEN
  -- on the drift charges the guest a figure the itemisation does not support and renders a VAT
  -- invoice whose lines do not sum to the charge.
  --
  -- The sum is over ALL lines, of every kind, AND their transport add-ons: the line price
  -- (subtotal_minor) plus its optional round-trip transfer (transport_fare_minor) — the same
  -- Σ subtotal + Σ transport the browser's quoteTotalMinor summed into quotes.total_minor. Omitting
  -- the fares would refuse every quote that attaches a transfer ("total 61600 vs lines 52000").
  --
  -- It subsumes the zero-lines case too — a hand-set total with no itemisation at all would otherwise
  -- mint a booking with no lines and a booking_json carrying no items: charged for something with no
  -- record of what it was.
  select coalesce(sum(qi.subtotal_minor), 0) + coalesce(sum(qi.transport_fare_minor), 0)
    into v_lines_minor
    from quote_items qi
   where qi.quote_id = v_quote.id;
  if v_quote.total_minor <> v_lines_minor then
    raise exception 'quote_total_mismatch'
      using detail = format('total %s vs lines %s', v_quote.total_minor, v_lines_minor);
  end if;

  -- WHO WILL BE ABLE TO SEE THIS BOOKING. `user_id` is what the bookings RLS policy reads
  -- (`user_id = auth.uid() or is_staff()`), so a booking minted with a null one is invisible to every
  -- customer — including the guest about to pay for it, whose confirmation email links to
  -- /bookings/{ref}. quote_owner_for_email (section 6d) answers with the single CONFIRMED account
  -- holding the quoted address, or null; see its header for why that rule is exactly this narrow.
  --
  -- NULL IS A SUPPORTED ANSWER, NOT A FAILURE. Most quote guests never open an account, and nothing
  -- downstream requires an owner: api_create_quote_payment (20260911000000) exists precisely because a
  -- quote booking has none, the guest's own record stays reachable through the link token, and
  -- api_claim_quote_bookings (7c) fills the column in later if they ever do sign up.
  v_owner := quote_owner_for_email(v_quote.customer_email);

  -- DEPOSIT SIZING. The deposit is total_minor * deposit_bps / 10000 (basis points; 1000 = 10.00%),
  -- rounded to the minor unit. total_minor AND operator_payout_minor stay the FULL quoted price — they
  -- feed the VAT invoice and the operator payout, and it is only the FIRST payments row (sized to this
  -- deposit in create_payment) that the guest is charged now. deposit_bps = 10000 makes the deposit the
  -- whole total — the UNCHANGED pay-in-full path. deposit_bps carries a `between 1 and 10000` CHECK, so
  -- the deposit is always a positive fraction of the total.
  v_deposit_minor := round(v_quote.total_minor * v_quote.deposit_bps / 10000.0);

  -- balance_due_minor is INITIALISED to the full total: nothing is settled at conversion, so the
  -- "amount still owed" is the whole order, exactly as append_payment_event's projection would compute
  -- it (total_minor - sum of settled money, which is 0 here). It is NOT total - deposit — that would
  -- read as if the deposit were already paid the moment the booking is minted, before the guest has
  -- been charged a cent, and would disagree with the projection that recomputes this column downward
  -- as the deposit and then the balance settle (→ total - deposit → 0). The deposit is a CHARGE size
  -- (deposit_minor / the first payments row), not a payment; only settling it reduces what is owed.
  insert into bookings (
    user_id, customer_name, customer_email, customer_phone, status, source,
    currency, total_minor, operator_payout_minor, payment_state, locale,
    deposit_minor, balance_due_minor
  )
  values (
    v_owner, v_quote.customer_name, v_quote.customer_email, v_quote.customer_phone, 'payment_pending',
    'quote', v_quote.currency, v_quote.total_minor, v_quote.total_minor, 'pending', v_quote.locale,
    v_deposit_minor, v_quote.total_minor
  )
  returning * into v_booking;

  -- The `kind <> 'catalogue'` filter is what keeps this statement and the hold path below from both
  -- claiming the same line: booking_custom_items carries `check (kind <> 'catalogue')`, and a
  -- catalogue line belongs in booking_items, where it can be counted against a departure. The three
  -- transport_* columns ride across so a custom line's attached transfer reaches the day sheet + receipt.
  insert into booking_custom_items (
    booking_id, position, kind, description, starts_at, ends_at,
    rental_vehicle_slug, quantity, unit_amount_minor, subtotal_minor,
    transport_pickup_label, transport_dropoff_label, transport_fare_minor
  )
  select v_booking.id, qi.position, qi.kind, qi.description, qi.starts_at, qi.ends_at,
         qi.rental_vehicle_slug, qi.quantity, qi.unit_amount_minor, qi.subtotal_minor,
         qi.transport_pickup_label, qi.transport_dropoff_label, qi.transport_fare_minor
    from quote_items qi
   where qi.quote_id = v_quote.id
     and qi.kind <> 'catalogue';

  -- ── THE CATALOGUE LINES TAKE THEIR SEATS, HERE, IN THIS TRANSACTION ─────────────────────────
  --
  -- A catalogue line names a session_occurrence, so unlike a custom line it is a place on a real
  -- departure. It is only actually reserved if it is reserved the way every other booking reserves
  -- one: create_hold — the universal gate, which api_create_hold and api_book both delegate their
  -- hold INSERT to — takes `select … for update` on the occurrence, re-reads used_capacity() under
  -- that lock and refuses an oversell; and the booking_items row is what used_capacity() counts once
  -- the booking confirms, what append_payment_event's oversell re-check reads before it confirms
  -- anything, and what puts the guest on the day sheet. Re-deriving either here would be a second,
  -- quieter definition of "a seat exists" on the money path.
  --
  -- WHY IT IS IN THIS FUNCTION AND NOT IN THE PAY ROUTE (which is where the plan first put it): a
  -- route does it in a SECOND transaction, so a hold that fails leaves a converted quote and a
  -- payable booking with no seat behind it — the guest pays for a place nobody reserved, which is
  -- the precise state the placeholder guard this replaces existed to prevent, now reached by a
  -- different road. In here, a refusal takes the booking, its custom lines and `converted_at` back
  -- with it, and the guest sees a refusal instead of a charge.
  --
  -- UNITS, NOT PEOPLE. used_capacity() sums booking_holds.quantity and booking_items.quantity, and
  -- append_payment_event re-checks this booking's own booking_items sum against the occurrence's
  -- capacity — so the hold's quantity must equal the quantities of the lines it covers, or the seat
  -- count drifts the moment the payment lands. Lines that share an occurrence are aggregated into
  -- ONE hold for exactly that reason (two 'Adult' and 'Child' lines on one boat are three seats on
  -- one trip, not two reservations).
  --
  -- The idempotency key is scoped to THIS booking, so a re-arm (a fresh booking for the same quote)
  -- takes fresh holds rather than being handed create_hold's idempotent replay of a released one.
  --
  -- WHAT IS DELIBERATELY *NOT* RE-USED FROM THE CHECKOUT: create_booking's per-booking guests-per-trip
  -- cap (20260908000000). That cap exists because a self-serve guest cannot know the day's pool is
  -- several departures — "the boat only seats so many, however big the day's pool is" — and it is
  -- enforced per BOOKING, so one quote line could never express "twenty guests, two boats" with it in
  -- the way. The operator drafting this quote chose the departure and the party size, and the POOL is
  -- still enforced by create_hold, so no other guest can be oversold; what a big party costs is two
  -- boats' worth of units out of the day, which is what it consumes. Revisit this the day quotes are
  -- drafted by anyone but staff.
  for v_seats in
    select qi.session_occurrence_id as occurrence_id, sum(qi.quantity)::int as units
      from quote_items qi
     where qi.quote_id = v_quote.id and qi.kind = 'catalogue'
     group by qi.session_occurrence_id
  loop
    begin
      v_hold := create_hold(
        v_seats.occurrence_id, v_seats.units,
        'quote:' || v_booking.id::text || ':' || v_seats.occurrence_id::text
      );
    exception when raise_exception then
      -- create_hold refuses in the CHECKOUT's vocabulary — insufficient_capacity,
      -- occurrence_not_bookable, occurrence_in_past, occurrence_too_soon — and mapDbError turns those
      -- into "Not enough availability for this selection" or the bare "Invalid booking request",
      -- neither of which tells a quote guest anything they can act on: they cannot pick another date,
      -- because the date was arranged for them. One token for all of them, carrying the real reason in
      -- DETAIL for error_logs, and mapped to a sold-out 409 that says to message us.
      raise exception 'quote_seats_unavailable'
        using detail = format('occurrence %s x%s: %s', v_seats.occurrence_id, v_seats.units, sqlerrm);
    end;

    -- ATTACH THE HOLD TO THE BOOKING. Not tidiness: append_payment_event's oversell re-check counts
    -- every active hold that is NOT this booking's own against it, so a detached hold is the guest's
    -- own reservation blocking their own confirmation and routing a good payment to refund_pending.
    -- It is also what makes the confirmation mark it 'consumed' rather than leaving it to lapse.
    update booking_holds set booking_id = v_booking.id where id = v_hold.id;
  end loop;

  -- One row per LINE (the hold above is one row per occurrence): the tiers are what the voucher, the
  -- day sheet and the VAT invoice itemise. Prices are the quote's own — the negotiated figure the
  -- guest saw and `quote_total_mismatch` has just re-checked — never re-derived from the catalogue
  -- here; the pay route compares them against the live price list and refuses on drift before this
  -- function is ever called. `price_label` is NOT NULL on booking_items, so a line that carries no
  -- tier name falls back to its description rather than failing at the constraint. The transport_*
  -- columns ride across so a tour's attached transfer reaches the day sheet + receipt.
  insert into booking_items (
    booking_id, session_occurrence_id, activity_option_id, price_label,
    quantity, unit_amount_minor, subtotal_minor,
    transport_pickup_label, transport_dropoff_label, transport_fare_minor
  )
  select v_booking.id, qi.session_occurrence_id, qi.activity_option_id,
         coalesce(nullif(btrim(qi.price_label), ''), nullif(btrim(qi.description), ''), 'Quoted place'),
         qi.quantity, qi.unit_amount_minor, qi.subtotal_minor,
         qi.transport_pickup_label, qi.transport_dropoff_label, qi.transport_fare_minor
    from quote_items qi
   where qi.quote_id = v_quote.id
     and qi.kind = 'catalogue'
   order by qi.position;

  -- Overwrites booking_id on a re-arm, which releases the dead booking from the UNIQUE.
  update quotes
     set booking_id = v_booking.id,
         converted_at = now(),
         status = 'accepted',
         updated_at = now()
   where id = v_quote.id;

  return booking_json(v_booking.id);
end;
$$;
revoke execute on function api_convert_quote(jsonb) from public, anon, authenticated;
grant execute on function api_convert_quote(jsonb) to service_role;


-- ===================================================================================================
-- 20260926000000_receipt_transport — api_booking_receipt carries each line's transport add-on
-- (transportFareMinor + transportPickupLabel), so buildInvoice can itemise the attached transfer.
-- Winning body; last def wins. Contracts (from booking_custom_items, balanceDueMinor) preserved.
-- ===================================================================================================
create or replace function api_booking_receipt(p jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_booking_id uuid := nullif(p ->> 'bookingId', '')::uuid;
  v_base jsonb;
  v_title text;
  v_when timestamptz;
  v_payment jsonb;
  v_phone text;
  v_locale text;
  v_bal bigint;
  v_addon_charged bigint := 0;
  v_items jsonb;
  v_custom jsonb;
begin
  if v_booking_id is null then
    raise exception 'invalid_request' using detail = 'booking_receipt: bookingId required';
  end if;

  v_base := booking_json(v_booking_id);
  if v_base is null then
    return null;
  end if;

  -- The booking-wide "headline" activity title (the FIRST tour) + earliest trip date, for the header.
  select a.title, o.starts_at
    into v_title, v_when
    from booking_items bi
    join session_occurrences o on o.id = bi.session_occurrence_id
    join activity_options ao on ao.id = bi.activity_option_id
    join activities a on a.id = ao.activity_id
   where bi.booking_id = v_booking_id
   order by o.starts_at asc, bi.created_at asc
   limit 1;

  select case
           when count(*) filter (where pay.paid_minor > 0) = 0 then null
           else jsonb_build_object(
             'chargedAmountMinor',
               coalesce(sum(coalesce(pay.charged_amount_minor, pay.amount_minor))
                        filter (where pay.paid_minor > 0), 0),
             'chargedCurrency',
               coalesce(max(coalesce(pay.charged_currency, pay.currency))
                        filter (where pay.paid_minor > 0), max(pay.currency)),
             'paidAt', max(paid.occurred_at) filter (where pay.paid_minor > 0),
             'providerRef', (array_agg(paid.provider_event_id order by paid.occurred_at desc nulls last)
                             filter (where pay.paid_minor > 0 and paid.provider_event_id is not null))[1]
           )
         end
    into v_payment
    from payments pay
    left join lateral (
      select pe.occurred_at, pe.provider_event_id
        from payment_events pe
       where pe.payment_id = pay.id and pe.type in ('paid', 'captured')
       order by pe.occurred_at asc
       limit 1
    ) paid on true
   where pay.booking_id = v_booking_id
     and pay.purpose in ('booking', 'balance');

  if v_payment is not null then
    select coalesce(sum(coalesce(pay.charged_amount_minor, pay.amount_minor)), 0)
      into v_addon_charged
      from payments pay
     where pay.booking_id = v_booking_id
       and pay.purpose = 'pickup_addon'
       and pay.paid_minor > 0
       and exists (
         select 1 from booking_pickup_requests r
          where r.payment_id = pay.id and r.applied_at is not null
       )
       and coalesce(pay.charged_currency, pay.currency)
             is not distinct from (v_payment ->> 'chargedCurrency');
    if v_addon_charged > 0 then
      v_payment := v_payment || jsonb_build_object(
        'chargedAmountMinor', (v_payment ->> 'chargedAmountMinor')::bigint + v_addon_charged
      );
    end if;
  end if;

  select b.customer_phone, b.locale::text, b.balance_due_minor
    into v_phone, v_locale, v_bal
    from bookings b where b.id = v_booking_id;

  -- Catalogue lines, each with its OWN activity title, per-line date, AND its attached transport add-on.
  -- Same FROM/WHERE as booking_json's items and NO order by, so item order stays byte-identical (the
  -- owner-alert party mix + voucher lines[0] read it positionally). `transportFareMinor`/
  -- `transportPickupLabel` are the attached round-trip transfer; buildInvoice renders a nested line from
  -- them. A JOIN/order by here reordered the age bands and broke the owner alert — do not reintroduce.
  select coalesce(jsonb_agg(jsonb_build_object(
           'title', (select a.title
                       from activity_options ao
                       join activities a on a.id = ao.activity_id
                      where ao.id = bi.activity_option_id),
           'when', (select o.starts_at from session_occurrences o where o.id = bi.session_occurrence_id),
           'priceLabel', bi.price_label,
           'quantity', bi.quantity,
           'pax', bi.pax,
           'unitAmountEur', bi.unit_amount_minor::float / 100,
           'subtotalEur', bi.subtotal_minor::float / 100,
           'occurrenceId', bi.session_occurrence_id,
           'transportFareMinor', bi.transport_fare_minor,
           'transportPickupLabel', bi.transport_pickup_label
         )), '[]'::jsonb)
    into v_items
    from booking_items bi
   where bi.booking_id = v_booking_id;

  -- The priced lines that have no session_occurrence (a converted quote's custom/transfer lines, and
  -- rentals). title = null so buildInvoice adds no prefix — the description already names the line. The
  -- transport add-on rides along exactly as it does for a catalogue line.
  select coalesce(jsonb_agg(jsonb_build_object(
           'title', null::text,
           'when', ci.starts_at,
           'priceLabel', ci.description,
           'quantity', ci.quantity,
           'pax', null::int,
           'unitAmountEur', ci.unit_amount_minor::float / 100,
           'subtotalEur', ci.subtotal_minor::float / 100,
           'transportFareMinor', ci.transport_fare_minor,
           'transportPickupLabel', ci.transport_pickup_label
         ) order by ci.position), '[]'::jsonb)
    into v_custom
    from booking_custom_items ci
   where ci.booking_id = v_booking_id;

  -- Catalogue lines FIRST (voucher-pdf.ts reads lines[0]), custom lines after by position.
  return v_base
    || jsonb_build_object('items', v_items || v_custom)
    || jsonb_build_object('activityTitle', v_title, 'when', v_when)
    || jsonb_build_object('payment', coalesce(v_payment, 'null'::jsonb))
    || jsonb_build_object('customerPhone', v_phone)
    || jsonb_build_object('balanceDueMinor', coalesce(v_bal, 0))
    || jsonb_build_object('locale', v_locale);
end;
$$;

revoke execute on function api_booking_receipt(jsonb) from public, anon, authenticated;
grant execute on function api_booking_receipt(jsonb) to service_role;


-- =================================================================================================
-- 20260927000000_documents_module — Documents module (mirror of the migration; full commentary in the
-- migration file). Two staff-RLS tables + numbering counter + four SECURITY DEFINER helpers. Idempotent.
-- =================================================================================================
-- 20260927000000_documents_module
--
-- The DOCUMENTS module: standalone quotes / invoices / proformas / receipts for any client, in
-- MUR / EUR / USD, paid offline or unpaid. A self-contained ISLAND — it never reads or writes
-- bookings, payments or the Peach ledger, so it cannot destabilise the money path. It exists to bill
-- the parties that never go through the online booking flow (the GLOBALAND case, which had to be run
-- from a throwaway script). Full design: docs/superpowers/specs/2026-08-12-documents-module-design.md.
--
-- Two staff-only tables + a per-type/per-year numbering counter, and four small SECURITY DEFINER
-- helpers for the transitions that must be atomic (gapless numbering) or cross-cutting
-- (issue / convert / void). Staff read and write the tables directly through the browser client under
-- the *_staff RLS policies, exactly as the quotes module does (20260909000000); only the numbered and
-- linked transitions go through an RPC.
--
-- Money is in integer MINOR units (all three currencies are ISO exponent-2). Idempotent throughout
-- (this file is mirrored into supabase/catch-up.sql and bundled into supabase/setup.sql).

-- ---------------------------------------------------------------------------
-- 1) document_clients — the self-building bill-to list. The operator free-types a client on a
--    document and may tick "remember", which upserts a reusable row here. PII, so staff-only.
-- ---------------------------------------------------------------------------
create table if not exists document_clients (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  email text,
  phone text,
  street text,
  locality text,
  region text,
  country text,
  brn text,
  vat text,
  -- `set null`, like quotes.created_by: a document outlives its author, so removing a departed
  -- colleague's auth user must forget who saved the client, never be blocked by it.
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table document_clients enable row level security;
drop policy if exists document_clients_staff_all on document_clients;
create policy document_clients_staff_all on document_clients
  for all using (is_staff()) with check (is_staff());

-- ---------------------------------------------------------------------------
-- 2) documents — one row = one document. Once ISSUED it is an immutable snapshot: client_snapshot and
--    issuer_snapshot freeze the bill-to and our own identity, so a reprint is stable even if the
--    client record or the business address later changes (the same discipline booking supplements use).
--    The stored *_minor totals are for the list + sorting; the renderer recomputes from `lines`, so a
--    drifted stored total can never produce a wrong PDF.
-- ---------------------------------------------------------------------------
create table if not exists documents (
  id uuid primary key default gen_random_uuid(),
  type text not null check (type in ('quote', 'invoice', 'proforma', 'receipt')),
  -- Null until issued: a draft is unnumbered, so an abandoned draft never burns a number.
  number text,
  status text not null default 'draft'
    check (status in ('draft', 'issued', 'accepted', 'declined', 'expired', 'paid', 'part_paid', 'void', 'converted')),
  currency text not null check (currency in ('MUR', 'EUR', 'USD')),
  client_id uuid references document_clients (id) on delete set null,
  client_snapshot jsonb not null default '{}'::jsonb,
  issuer_snapshot jsonb not null default '{}'::jsonb,
  -- [{ description, quantity, unitMinor }] — the itemisation, snapshotted on the document.
  lines jsonb not null default '[]'::jsonb,
  vat_mode text not null default 'inclusive' check (vat_mode in ('inclusive', 'exclusive', 'none')),
  vat_rate_pct int not null default 15,
  -- bigint like every money column on the repo's money path: a full-boat charter overflows int4 cents.
  subtotal_net_minor bigint not null default 0 check (subtotal_net_minor >= 0),
  vat_minor bigint not null default 0 check (vat_minor >= 0),
  total_minor bigint not null default 0 check (total_minor >= 0),
  -- Manual settlement — NOT the Peach ledger. Drives the PAID stamp / Amount Due on the document.
  amount_paid_minor bigint not null default 0 check (amount_paid_minor >= 0),
  payment_method text,
  payment_ref text,
  paid_at timestamptz,
  issue_date date,
  due_date date,
  valid_until date,
  -- Client-facing covering note (rendered) and staff-only note (never rendered).
  notes text,
  internal_notes text,
  -- The quote this invoice was converted from (convert_document), for provenance.
  source_document_id uuid references documents (id) on delete set null,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists documents_type_status_idx on documents (type, status);
create index if not exists documents_created_idx on documents (created_at desc);
create index if not exists documents_number_idx on documents (number);

alter table documents enable row level security;
drop policy if exists documents_staff_all on documents;
create policy documents_staff_all on documents
  for all using (is_staff()) with check (is_staff());

-- ---------------------------------------------------------------------------
-- 3) document_counters — the per-type, per-year sequence behind gapless numbering. No RLS policy:
--    only allocate_document_number (SECURITY DEFINER) ever touches it, so no role reaches it directly.
-- ---------------------------------------------------------------------------
create table if not exists document_counters (
  doc_type text not null,
  year int not null,
  next_val int not null default 0,
  primary key (doc_type, year)
);
alter table document_counters enable row level security;

-- Table privileges. The one-time `grant ... on all tables in schema public` (20260615120800) only
-- covered the tables that existed then, so a table added later must state its own grants. RLS (above)
-- is what gates the ROWS to staff; these grants are the table-level privilege that both the browser
-- client (direct staff reads/writes) and the definer helpers' `returns documents` composite require.
-- anon gets nothing — the whole module is staff-only. document_counters is reached ONLY through
-- allocate_document_number (definer), so it is never granted to authenticated.
grant select, insert, update, delete on document_clients to authenticated;
grant select, insert, update, delete on documents to authenticated;
grant all on document_clients, documents, document_counters to service_role;

-- ---------------------------------------------------------------------------
-- 4) allocate_document_number — atomically claim the next number for a (type, year). The upsert's
--    ON CONFLICT DO UPDATE increments under the row lock, so two staff issuing at the same instant
--    serialise here rather than both reading the same next_val. Format PREFIX-YYYY-#### (4-digit).
-- ---------------------------------------------------------------------------
create or replace function allocate_document_number(p_type text, p_year int)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_next int;
  v_prefix text;
begin
  if not is_staff() then
    raise exception 'forbidden';
  end if;

  v_prefix := case p_type
    when 'quote' then 'QUO'
    when 'invoice' then 'INV'
    when 'proforma' then 'PRO'
    when 'receipt' then 'RCT'
    else null
  end;
  if v_prefix is null then
    raise exception 'invalid_document_type' using detail = coalesce(p_type, 'null');
  end if;

  insert into document_counters as c (doc_type, year, next_val)
    values (p_type, p_year, 1)
  on conflict (doc_type, year)
    do update set next_val = c.next_val + 1
  returning next_val into v_next;

  return v_prefix || '-' || p_year::text || '-' || lpad(v_next::text, 4, '0');
end;
$$;
-- `from public, anon`, never just PUBLIC: Supabase grants EXECUTE to anon AND authenticated explicitly
-- at creation (not via PUBLIC), so a revoke naming only PUBLIC leaves anon holding it — the one-word
-- omission that has shipped a live leak from this repo more than once. is_staff() guards the body too.
revoke execute on function allocate_document_number(text, int) from public, anon;
grant execute on function allocate_document_number(text, int) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 5) issue_document — allocate the number, freeze the issuer snapshot, move off draft, all atomically
--    under a row lock so a double-click cannot issue the same document twice or burn two numbers.
--    Refuses anything already issued (a numbered document is voided, never re-issued).
-- ---------------------------------------------------------------------------
create or replace function issue_document(p_id uuid, p_issuer jsonb)
returns documents
language plpgsql
security definer
set search_path = public
as $$
declare
  v_doc documents;
  v_year int;
  v_number text;
begin
  if not is_staff() then
    raise exception 'forbidden';
  end if;

  select * into v_doc from documents where id = p_id for update;
  if v_doc.id is null then
    raise exception 'document_not_found';
  end if;
  if v_doc.status <> 'draft' then
    raise exception 'document_already_issued' using detail = v_doc.status;
  end if;

  v_year := extract(year from coalesce(v_doc.issue_date, current_date))::int;
  v_number := allocate_document_number(v_doc.type, v_year);

  update documents
     set number = v_number,
         issuer_snapshot = coalesce(p_issuer, issuer_snapshot),
         status = 'issued',
         issue_date = coalesce(issue_date, current_date),
         updated_at = now()
   where id = p_id
   returning * into v_doc;

  return v_doc;
end;
$$;
revoke execute on function issue_document(uuid, jsonb) from public, anon;
grant execute on function issue_document(uuid, jsonb) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 6) convert_document — clone a QUOTE into a fresh invoice DRAFT and mark the quote converted, in one
--    transaction. The new invoice is a draft (unnumbered) so the operator can adjust it before issuing.
-- ---------------------------------------------------------------------------
create or replace function convert_document(p_id uuid)
returns documents
language plpgsql
security definer
set search_path = public
as $$
declare
  v_src documents;
  v_new documents;
begin
  if not is_staff() then
    raise exception 'forbidden';
  end if;

  select * into v_src from documents where id = p_id for update;
  if v_src.id is null then
    raise exception 'document_not_found';
  end if;
  if v_src.type <> 'quote' then
    raise exception 'not_a_quote' using detail = v_src.type;
  end if;

  insert into documents (
    type, status, currency, client_id, client_snapshot, lines,
    vat_mode, vat_rate_pct, subtotal_net_minor, vat_minor, total_minor,
    notes, source_document_id, created_by
  )
  values (
    'invoice', 'draft', v_src.currency, v_src.client_id, v_src.client_snapshot, v_src.lines,
    v_src.vat_mode, v_src.vat_rate_pct, v_src.subtotal_net_minor, v_src.vat_minor, v_src.total_minor,
    v_src.notes, v_src.id, auth.uid()
  )
  returning * into v_new;

  update documents set status = 'converted', updated_at = now() where id = v_src.id;

  return v_new;
end;
$$;
revoke execute on function convert_document(uuid) from public, anon;
grant execute on function convert_document(uuid) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 7) void_document — a numbered document is VOIDED, never deleted, so the sequence stays gapless and
--    audit-clean. A draft has no number and is deleted outright by the client, so voiding one is refused.
-- ---------------------------------------------------------------------------
create or replace function void_document(p_id uuid)
returns documents
language plpgsql
security definer
set search_path = public
as $$
declare
  v_doc documents;
begin
  if not is_staff() then
    raise exception 'forbidden';
  end if;

  select * into v_doc from documents where id = p_id for update;
  if v_doc.id is null then
    raise exception 'document_not_found';
  end if;
  if v_doc.status = 'draft' then
    raise exception 'draft_not_voidable';
  end if;

  update documents set status = 'void', updated_at = now() where id = p_id returning * into v_doc;
  return v_doc;
end;
$$;
revoke execute on function void_document(uuid) from public, anon;
grant execute on function void_document(uuid) to authenticated, service_role;


-- ===================================================================================================
-- 20260928000000_custom_line_runsheet — custom lines gain guests + pickup_label, quotes gain
-- room_or_cabin; api_convert_quote copies them onto the booking. Winning body; last def wins.
-- Contracts (quote_owner_for_email owner resolve, deposit sizing round(...)) preserved verbatim.
-- ===================================================================================================
-- 20260928000000_custom_line_runsheet
--
-- A custom/private-tour line carries no headcount and no pickup of its own, so the operations calendar
-- can show a bespoke tour's date and price but not "collect 2 guests from <hotel>, room 214". Three
-- additive, nullable columns fix that, on every table a custom line lives in so they survive quote ->
-- booking conversion and reach the day sheet:
--   * guests       — the party size for the run sheet (custom lines only; a catalogue line has its
--                    tier quantities, a rental counts vehicles). NOT a money field: PricedLine ignores
--                    it and quote_total_mismatch never sees it.
--   * pickup_label — where to collect the tour from (the guest's hotel), independent of the optional
--                    paid transport add-on (a private tour includes its transport, so it must not be
--                    forced through a €0 "round-trip transfer" line just to record a pickup).
--   * room_or_cabin on quotes — the guest's room for the driver's hotel gate pass, copied onto the
--                    booking (bookings.room_or_cabin already exists) at conversion.
--
-- Null everywhere today, so purely additive; it changes no existing figure. Then api_convert_quote is
-- re-applied VERBATIM from its winning body (20260925000000) apart from two copies: booking.room_or_cabin
-- from the quote, and guests/pickup_label onto booking_custom_items. The total check, the owner resolve
-- (quote_owner_for_email) and the deposit sizing (round(total_minor * deposit_bps / 10000.0)) are
-- byte-identical (resolved-function-bodies.test.ts pins the latter two).
--
-- Mirror into supabase/catch-up.sql and regenerate supabase/setup.sql (`npm run setup:sql`); add
-- ('20260928000000','custom_line_runsheet') to supabase/backfill-migration-ledger.sql.

alter table quote_items
  add column if not exists guests int check (guests is null or guests > 0),
  add column if not exists pickup_label text;

alter table booking_custom_items
  add column if not exists guests int check (guests is null or guests > 0),
  add column if not exists pickup_label text;

alter table quotes
  add column if not exists room_or_cabin text;

create or replace function api_convert_quote(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_quote quotes;
  v_prior bookings;
  v_booking bookings;
  v_reusable boolean := false;
  v_lines_minor bigint;
  v_owner uuid;
  v_deposit_minor bigint;
  v_seats record;
  v_hold booking_holds;
begin
  select * into v_quote
    from quotes
   where id = nullif(p ->> 'quoteId', '')::uuid
   for update;

  if v_quote.id is null then
    raise exception 'quote_not_found';
  end if;

  -- Convert-once, read off converted_at, and meaning "one PAYABLE booking at a time" (see above).
  if v_quote.converted_at is not null then
    -- LOCK THE MONEY BEFORE JUDGING IT. append_payment_event locks the payments row, writes paid_minor
    -- and status onto it, and only THEN rolls the projection onto bookings — so an unlocked read of
    -- either table can catch a settlement mid-flight, conclude "this booking never took a cent", mint
    -- booking B, commit, and let the settlement land on A afterwards. Taking the payments locks in the
    -- same order that function does serialises the two instead of racing them.
    --
    -- `bookings` is deliberately NOT locked here as well: api_create_payment locks bookings and then
    -- payments, so adding payments -> bookings on this side would close a deadlock cycle on the money
    -- path. It is also unnecessary — read committed gives every later statement in this function a
    -- fresh snapshot, so once the payments locks are held the reads below see post-settlement state.
    -- A booking with no payments row locks nothing, which is safe: api_create_payment refuses a dead
    -- booking ('booking_not_payable'), so no first payment can appear on one.
    perform 1 from payments where booking_id = v_quote.booking_id for update;

    -- booking_id is null here when an erasure hard-deleted the booking; the select finds nothing and
    -- v_reusable stays false, which is the section-4 invariant.
    select * into v_prior from bookings where id = v_quote.booking_id;
    v_reusable := found
      and v_prior.status in ('expired', 'cancelled', 'failed')
      and v_prior.payment_state in ('pending', 'failed')
      -- Money already HELD, including the shapes the booking-level projection above cannot see: an
      -- underpayment (append_payment_event sets 'pending' when v_paid > 0 but below amount_minor, so
      -- paid_minor is positive while payment_state is not) and a wrong-currency settlement quarantine
      -- (settlement_review_at, 20260830000000), which is stamped precisely so the projection is left
      -- alone. Both hold a capture on a booking that still reads clean.
      and not exists (
        select 1 from payments pay
         where pay.booking_id = v_prior.id
           and (pay.paid_minor > 0
                or pay.refunded_minor > 0
                or pay.status in ('paid', 'partially_refunded', 'refunded')
                or pay.settlement_review_at is not null)
      )
      -- Money that can still be TAKEN. A dead booking is not a dead checkout: run_booking_maintenance
      -- expires a booking 30 minutes after it was CREATED, while a Peach session stays completable
      -- ~30 minutes after it was MINTED (api_pending_payment_checkouts says exactly that in its own
      -- comment). A guest who converts at T0, clicks Pay at T0+26 and wanders off has an expired
      -- booking at T0+30 and a live session until roughly T0+56; re-arming in that gap leaves TWO
      -- payable sessions for one quote — the double charge api_create_payment's reuse guard refuses
      -- to create one level down ("Minting a replacement while the original is still live would leave
      -- TWO payable sessions for one booking") and the one 20260902000000 removed. It is also
      -- unreconcilable: api_pending_payment_checkouts only re-queries bookings still in
      -- 'payment_pending', so once the booking is expired a lost webhook on that capture is never
      -- swept — money taken, no ledger row, no link back to the quote.
      --
      -- 30 minutes, not api_create_payment's 25: 25 is the REUSE window, deliberately short of the
      -- session's life so a session handed back cannot die under the guest. The hazard here lasts as
      -- long as the session can be COMPLETED, so this window has to be the wider of the two.
      --
      -- The claimed-lease arm covers the ~90 seconds where a caller is out at Peach and the session
      -- id has not been recorded yet: provider_checkout_id is still null, so freshness alone sees
      -- nothing and would re-arm into the same double charge moments before the session appears.
      --
      -- The refusal is a wait, not a wall: mapDbError already reads quote_already_converted as "has
      -- already been paid for or is being paid", and the quote converts again once the session dies.
      and not exists (
        select 1 from payments pay
         where pay.booking_id = v_prior.id
           and ((pay.provider_checkout_id is not null
                 and coalesce(pay.checkout_created_at, pay.updated_at) > now() - interval '30 minutes')
                or (pay.checkout_claimed_until is not null and pay.checkout_claimed_until > now()))
      );
    if not v_reusable then
      raise exception 'quote_already_converted'
        using detail = coalesce(v_prior.status::text, 'linked booking no longer exists');
    end if;

    -- THE DEAD BOOKING'S SEATS GO BACK BEFORE THIS CONVERSION TAKES FRESH ONES.
    --
    -- Re-arming mints a SECOND booking, which takes its own holds below — so unless the first
    -- booking's holds are released here, one quote reserves two sets of seats for the rest of their
    -- 30-minute life. Nothing else does it: run_booking_maintenance releases holds only for the
    -- bookings IT expired, so a hand-cancelled booking (or one already swept while its hold ran on)
    -- keeps them. On a nearly-full departure that is the guest's own abandoned attempt selling the
    -- trip out from under them — create_hold would raise `insufficient_capacity` and the quote would
    -- read as sold out to the only person entitled to those seats.
    --
    -- Safe because of what the branch above has already established: this booking is dead
    -- (expired/cancelled/failed), never took a cent, and cannot take one.
    update booking_holds set status = 'released'
     where booking_id = v_prior.id and status = 'active';
  end if;

  -- Status: an explicit WHITELIST, the shape api_create_payment uses next door. A blacklist of one
  -- let a 'draft' (a half-built offer the owner has not sent, whose total may be mid-edit) and an
  -- 'expired' quote — a terminal state of the very enum this migration created — both convert.
  -- 'accepted' is in the list because that is what a converted quote's status already is, and the
  -- re-arm branch above has to be able to get past here.
  if v_quote.status = 'cancelled' then
    raise exception 'quote_cancelled';
  end if;
  if v_quote.status = 'expired' or v_quote.valid_until < current_date then
    raise exception 'quote_expired';
  end if;
  if v_quote.status not in ('sent', 'accepted') then
    raise exception 'quote_not_convertible' using detail = v_quote.status::text;
  end if;

  -- A zero-total quote mints a booking that can NEVER confirm: api_create_payment skips the FX pin
  -- for a zero amount, and append_payment_event carries an explicit guard whose own comment says "a
  -- zero-amount payment must never read as fully paid (0 >= 0)". The booking would sit in
  -- payment_pending until the sweep expired it. quotes.total_minor DEFAULTS to 0, so an empty or
  -- never-priced draft reaches this state by default rather than by accident.
  if coalesce(v_quote.total_minor, 0) <= 0 then
    raise exception 'quote_not_convertible' using detail = 'zero total';
  end if;

  -- THE TWO CATALOGUE LINES THIS FUNCTION WILL NOT PRICE INTO A SEAT. Both fail closed here, before
  -- anything is minted, because both are shapes whose capacity meaning cannot be read off the line.
  --
  -- 1. AN OPTION THAT IS NOT COUNTED IN PEOPLE. For a private or vehicle option one BOOKING is one
  --    unit of the pool — the pool counts trips, not heads (20260908000000), and create_booking
  --    records the real party size in booking_items.pax while writing quantity 1. A quote line for
  --    six guests would therefore reserve SIX DEPARTURES if it were held like a per-person line, and
  --    reserve one while charging for six if it were not. Neither is a guess worth making on the
  --    money path: there is no editor that can draft such a line yet, and the pay route's re-price
  --    gate refuses it one step earlier anyway (a private option has no activity_option_prices row
  --    to re-price against). The day the editor learns to quote a private charter, this is the
  --    branch that teaches the conversion the trips-vs-heads mapping — deliberately, with a test.
  --
  -- 2. AN OPTION THAT IS NOT THE OCCURRENCE'S OWN. `quote_item_shape` makes a catalogue line name
  --    both, and nothing checks they agree; a mismatch would write a booking_items row whose option
  --    contradicts its occurrence, i.e. a voucher and a day sheet naming a trip the guest is not on.
  --
  -- Both reuse `quote_not_convertible` rather than minting a token of their own: mapDbError already
  -- reads it as "This quote is not ready to pay yet — please message us", which is exactly true, and
  -- an unfinished offer is the operator's to fix.
  if exists (
    select 1
      from quote_items qi
      join activity_options o on o.id = qi.activity_option_id
      join activities a on a.id = o.activity_id
     where qi.quote_id = v_quote.id
       and qi.kind = 'catalogue'
       and (o.private_base_minor is not null
            or coalesce(a.pricing_mode::text, 'per_person') in ('vehicle', 'vehicle_custom'))
  ) then
    raise exception 'quote_not_convertible' using detail = 'private/vehicle catalogue line';
  end if;
  if exists (
    select 1
      from quote_items qi
      join session_occurrences so on so.id = qi.session_occurrence_id
     where qi.quote_id = v_quote.id
       and qi.kind = 'catalogue'
       and qi.activity_option_id is distinct from so.activity_option_id
  ) then
    raise exception 'quote_not_convertible' using detail = 'catalogue line option is not its occurrence''s';
  end if;

  -- THE CHARGE AND THE ITEMISATION MUST AGREE, or nothing is minted.
  --
  -- The amount charged is copied from quotes.total_minor while the lines are copied by the separate
  -- statement below, and nothing else ties the two together: total_minor carries no CHECK against its
  -- lines and no trigger recomputing it, and the editor writes the total in a different statement from
  -- the lines. src/lib/quotes/totals.ts states in its own header that there is no Zod layer above it
  -- yet and that its guards "ARE the only validation between a browser-supplied line and
  -- quotes.total_minor" — so this function is the last gate before a card is charged, and failing OPEN
  -- on the drift charges the guest a figure the itemisation does not support and renders a VAT
  -- invoice whose lines do not sum to the charge.
  --
  -- The sum is over ALL lines, of every kind, AND their transport add-ons: the line price
  -- (subtotal_minor) plus its optional round-trip transfer (transport_fare_minor) — the same
  -- Σ subtotal + Σ transport the browser's quoteTotalMinor summed into quotes.total_minor. Omitting
  -- the fares would refuse every quote that attaches a transfer ("total 61600 vs lines 52000").
  --
  -- It subsumes the zero-lines case too — a hand-set total with no itemisation at all would otherwise
  -- mint a booking with no lines and a booking_json carrying no items: charged for something with no
  -- record of what it was.
  select coalesce(sum(qi.subtotal_minor), 0) + coalesce(sum(qi.transport_fare_minor), 0)
    into v_lines_minor
    from quote_items qi
   where qi.quote_id = v_quote.id;
  if v_quote.total_minor <> v_lines_minor then
    raise exception 'quote_total_mismatch'
      using detail = format('total %s vs lines %s', v_quote.total_minor, v_lines_minor);
  end if;

  -- WHO WILL BE ABLE TO SEE THIS BOOKING. `user_id` is what the bookings RLS policy reads
  -- (`user_id = auth.uid() or is_staff()`), so a booking minted with a null one is invisible to every
  -- customer — including the guest about to pay for it, whose confirmation email links to
  -- /bookings/{ref}. quote_owner_for_email (section 6d) answers with the single CONFIRMED account
  -- holding the quoted address, or null; see its header for why that rule is exactly this narrow.
  --
  -- NULL IS A SUPPORTED ANSWER, NOT A FAILURE. Most quote guests never open an account, and nothing
  -- downstream requires an owner: api_create_quote_payment (20260911000000) exists precisely because a
  -- quote booking has none, the guest's own record stays reachable through the link token, and
  -- api_claim_quote_bookings (7c) fills the column in later if they ever do sign up.
  v_owner := quote_owner_for_email(v_quote.customer_email);

  -- DEPOSIT SIZING. The deposit is total_minor * deposit_bps / 10000 (basis points; 1000 = 10.00%),
  -- rounded to the minor unit. total_minor AND operator_payout_minor stay the FULL quoted price — they
  -- feed the VAT invoice and the operator payout, and it is only the FIRST payments row (sized to this
  -- deposit in create_payment) that the guest is charged now. deposit_bps = 10000 makes the deposit the
  -- whole total — the UNCHANGED pay-in-full path. deposit_bps carries a `between 1 and 10000` CHECK, so
  -- the deposit is always a positive fraction of the total.
  v_deposit_minor := round(v_quote.total_minor * v_quote.deposit_bps / 10000.0);

  -- balance_due_minor is INITIALISED to the full total: nothing is settled at conversion, so the
  -- "amount still owed" is the whole order, exactly as append_payment_event's projection would compute
  -- it (total_minor - sum of settled money, which is 0 here). It is NOT total - deposit — that would
  -- read as if the deposit were already paid the moment the booking is minted, before the guest has
  -- been charged a cent, and would disagree with the projection that recomputes this column downward
  -- as the deposit and then the balance settle (→ total - deposit → 0). The deposit is a CHARGE size
  -- (deposit_minor / the first payments row), not a payment; only settling it reduces what is owed.
  --
  -- room_or_cabin rides across from the quote (this migration): the guest's room for the driver's
  -- hotel gate pass. Null on every quote drafted before this column existed, so additive.
  insert into bookings (
    user_id, customer_name, customer_email, customer_phone, status, source,
    currency, total_minor, operator_payout_minor, payment_state, locale,
    deposit_minor, balance_due_minor, room_or_cabin
  )
  values (
    v_owner, v_quote.customer_name, v_quote.customer_email, v_quote.customer_phone, 'payment_pending',
    'quote', v_quote.currency, v_quote.total_minor, v_quote.total_minor, 'pending', v_quote.locale,
    v_deposit_minor, v_quote.total_minor, v_quote.room_or_cabin
  )
  returning * into v_booking;

  -- The `kind <> 'catalogue'` filter is what keeps this statement and the hold path below from both
  -- claiming the same line: booking_custom_items carries `check (kind <> 'catalogue')`, and a
  -- catalogue line belongs in booking_items, where it can be counted against a departure. The three
  -- transport_* columns ride across so a custom line's attached transfer reaches the day sheet + receipt;
  -- guests + pickup_label ride across (this migration) so a bespoke tour's headcount and pickup hotel
  -- reach the operations day sheet.
  insert into booking_custom_items (
    booking_id, position, kind, description, starts_at, ends_at,
    rental_vehicle_slug, quantity, unit_amount_minor, subtotal_minor,
    transport_pickup_label, transport_dropoff_label, transport_fare_minor,
    guests, pickup_label
  )
  select v_booking.id, qi.position, qi.kind, qi.description, qi.starts_at, qi.ends_at,
         qi.rental_vehicle_slug, qi.quantity, qi.unit_amount_minor, qi.subtotal_minor,
         qi.transport_pickup_label, qi.transport_dropoff_label, qi.transport_fare_minor,
         qi.guests, qi.pickup_label
    from quote_items qi
   where qi.quote_id = v_quote.id
     and qi.kind <> 'catalogue';

  -- ── THE CATALOGUE LINES TAKE THEIR SEATS, HERE, IN THIS TRANSACTION ─────────────────────────
  --
  -- A catalogue line names a session_occurrence, so unlike a custom line it is a place on a real
  -- departure. It is only actually reserved if it is reserved the way every other booking reserves
  -- one: create_hold — the universal gate, which api_create_hold and api_book both delegate their
  -- hold INSERT to — takes `select … for update` on the occurrence, re-reads used_capacity() under
  -- that lock and refuses an oversell; and the booking_items row is what used_capacity() counts once
  -- the booking confirms, what append_payment_event's oversell re-check reads before it confirms
  -- anything, and what puts the guest on the day sheet. Re-deriving either here would be a second,
  -- quieter definition of "a seat exists" on the money path.
  --
  -- WHY IT IS IN THIS FUNCTION AND NOT IN THE PAY ROUTE (which is where the plan first put it): a
  -- route does it in a SECOND transaction, so a hold that fails leaves a converted quote and a
  -- payable booking with no seat behind it — the guest pays for a place nobody reserved, which is
  -- the precise state the placeholder guard this replaces existed to prevent, now reached by a
  -- different road. In here, a refusal takes the booking, its custom lines and `converted_at` back
  -- with it, and the guest sees a refusal instead of a charge.
  --
  -- UNITS, NOT PEOPLE. used_capacity() sums booking_holds.quantity and booking_items.quantity, and
  -- append_payment_event re-checks this booking's own booking_items sum against the occurrence's
  -- capacity — so the hold's quantity must equal the quantities of the lines it covers, or the seat
  -- count drifts the moment the payment lands. Lines that share an occurrence are aggregated into
  -- ONE hold for exactly that reason (two 'Adult' and 'Child' lines on one boat are three seats on
  -- one trip, not two reservations).
  --
  -- The idempotency key is scoped to THIS booking, so a re-arm (a fresh booking for the same quote)
  -- takes fresh holds rather than being handed create_hold's idempotent replay of a released one.
  --
  -- WHAT IS DELIBERATELY *NOT* RE-USED FROM THE CHECKOUT: create_booking's per-booking guests-per-trip
  -- cap (20260908000000). That cap exists because a self-serve guest cannot know the day's pool is
  -- several departures — "the boat only seats so many, however big the day's pool is" — and it is
  -- enforced per BOOKING, so one quote line could never express "twenty guests, two boats" with it in
  -- the way. The operator drafting this quote chose the departure and the party size, and the POOL is
  -- still enforced by create_hold, so no other guest can be oversold; what a big party costs is two
  -- boats' worth of units out of the day, which is what it consumes. Revisit this the day quotes are
  -- drafted by anyone but staff.
  for v_seats in
    select qi.session_occurrence_id as occurrence_id, sum(qi.quantity)::int as units
      from quote_items qi
     where qi.quote_id = v_quote.id and qi.kind = 'catalogue'
     group by qi.session_occurrence_id
  loop
    begin
      v_hold := create_hold(
        v_seats.occurrence_id, v_seats.units,
        'quote:' || v_booking.id::text || ':' || v_seats.occurrence_id::text
      );
    exception when raise_exception then
      -- create_hold refuses in the CHECKOUT's vocabulary — insufficient_capacity,
      -- occurrence_not_bookable, occurrence_in_past, occurrence_too_soon — and mapDbError turns those
      -- into "Not enough availability for this selection" or the bare "Invalid booking request",
      -- neither of which tells a quote guest anything they can act on: they cannot pick another date,
      -- because the date was arranged for them. One token for all of them, carrying the real reason in
      -- DETAIL for error_logs, and mapped to a sold-out 409 that says to message us.
      raise exception 'quote_seats_unavailable'
        using detail = format('occurrence %s x%s: %s', v_seats.occurrence_id, v_seats.units, sqlerrm);
    end;

    -- ATTACH THE HOLD TO THE BOOKING. Not tidiness: append_payment_event's oversell re-check counts
    -- every active hold that is NOT this booking's own against it, so a detached hold is the guest's
    -- own reservation blocking their own confirmation and routing a good payment to refund_pending.
    -- It is also what makes the confirmation mark it 'consumed' rather than leaving it to lapse.
    update booking_holds set booking_id = v_booking.id where id = v_hold.id;
  end loop;

  -- One row per LINE (the hold above is one row per occurrence): the tiers are what the voucher, the
  -- day sheet and the VAT invoice itemise. Prices are the quote's own — the negotiated figure the
  -- guest saw and `quote_total_mismatch` has just re-checked — never re-derived from the catalogue
  -- here; the pay route compares them against the live price list and refuses on drift before this
  -- function is ever called. `price_label` is NOT NULL on booking_items, so a line that carries no
  -- tier name falls back to its description rather than failing at the constraint. The transport_*
  -- columns ride across so a tour's attached transfer reaches the day sheet + receipt.
  insert into booking_items (
    booking_id, session_occurrence_id, activity_option_id, price_label,
    quantity, unit_amount_minor, subtotal_minor,
    transport_pickup_label, transport_dropoff_label, transport_fare_minor
  )
  select v_booking.id, qi.session_occurrence_id, qi.activity_option_id,
         coalesce(nullif(btrim(qi.price_label), ''), nullif(btrim(qi.description), ''), 'Quoted place'),
         qi.quantity, qi.unit_amount_minor, qi.subtotal_minor,
         qi.transport_pickup_label, qi.transport_dropoff_label, qi.transport_fare_minor
    from quote_items qi
   where qi.quote_id = v_quote.id
     and qi.kind = 'catalogue'
   order by qi.position;

  -- Overwrites booking_id on a re-arm, which releases the dead booking from the UNIQUE.
  update quotes
     set booking_id = v_booking.id,
         converted_at = now(),
         status = 'accepted',
         updated_at = now()
   where id = v_quote.id;

  return booking_json(v_booking.id);
end;
$$;
revoke execute on function api_convert_quote(jsonb) from public, anon, authenticated;
grant execute on function api_convert_quote(jsonb) to service_role;

-- ==================== 20260929000000_align_transfer_vehicle_label ====================
-- Transfer lines carry the airport vocabulary (Standard car / Minibus …), not Sedan / Van, so the
-- option and price_label agree. Winning api_book body — mirrored so catch-up.sql re-runs to it too.
create or replace function api_book(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_occ uuid := (p ->> 'occurrenceId')::uuid;
  v_key text := p ->> 'idempotencyKey';
  v_expected_slug text := nullif(p ->> 'expectedSlug', '');
  v_total_qty bigint := 0;
  v_items jsonb := '[]'::jsonb;
  v_mode text := 'per_person';
  v_is_private boolean := false;
  v_suv boolean := coalesce((p ->> 'suv')::boolean, false);
  v_hold_id uuid := nullif(p ->> 'holdId', '')::uuid;
  v_want_qty int;
  v_reused boolean := false;
  v_child int;
  v_child_extra bigint;
  v_supp_total bigint := 0;
  v_activity_id uuid;
  v_hold booking_holds;
  v_booking bookings;
  r record;
  v_activity_region text;
  v_pickup_available boolean := false;
  v_pickup_lat double precision;
  v_pickup_lng double precision;
  v_pickup_region text;
  v_transport bigint;
  v_is_airport boolean := false;
  v_is_hotel boolean := false;
  v_dropoff_zone text;
  v_trip_type text;
  v_trip_direction text;
  v_ret_pct int;
  v_fare bigint;
  v_hotel_pickup_region text;
  v_hotel_dropoff_region text;
  v_band text;
  v_actor uuid;
begin
  if v_occ is null or v_key is null then
    raise exception 'invalid_request';
  end if;

  if v_expected_slug is not null and not exists (
    select 1 from session_occurrences so
    join activity_options o on o.id = so.activity_option_id
    join activities a on a.id = o.activity_id
    where so.id = v_occ and a.slug = v_expected_slug
  ) then
    raise exception 'occurrence_activity_mismatch';
  end if;

  for r in select key, (value::text)::bigint as q from jsonb_each(p -> 'party') loop
    if r.q < 0 or r.q > 1000000 then raise exception 'invalid_party'; end if;
    if r.q > 0 then
      v_total_qty := v_total_qty + r.q;
      v_items := v_items || jsonb_build_object('price_label', r.key, 'quantity', r.q);
    end if;
  end loop;
  if v_total_qty <= 0 or v_total_qty > 1000000 then raise exception 'invalid_party'; end if;

  select a.pricing_mode,
         coalesce(a.region, region_from_coords(a.lat, a.lng)),
         coalesce(a.pickup_available, false),
         coalesce(a.is_airport_transfer, false),
         coalesce(a.is_hotel_transfer, false),
         (o.private_base_minor is not null),
         a.id
    into v_mode, v_activity_region, v_pickup_available, v_is_airport, v_is_hotel, v_is_private,
         v_activity_id
  from session_occurrences so
  join activity_options o on o.id = so.activity_option_id
  join activities a on a.id = o.activity_id
  where so.id = v_occ;
  v_mode := coalesce(v_mode, 'per_person');
  v_want_qty := case when v_mode in ('vehicle', 'vehicle_custom')
                       or coalesce(v_is_private, false) then 1 else v_total_qty::int end;

  -- Actor identity, resolved BEFORE the hold-reuse gate so ownership can bind reuse. api_book is
  -- service-role-only, so auth.uid() is null; the JWKS-verified caller id arrives as p.actorUserId
  -- (trustworthy BECAUSE only the server can execute this function). auth.uid() stays first as
  -- belt-and-suspenders.
  v_actor := coalesce(auth.uid(), nullif(p ->> 'actorUserId', '')::uuid);

  if v_hold_id is not null then
    -- FOR UPDATE: two concurrent api_book calls quoting the same holdId must serialise here, or both
    -- read booking_id IS NULL and both proceed (create_booking's own lock cannot save the second one
    -- on its own — it re-checks under the lock, but only because of the guard added alongside this).
    -- Ownership: an OWNED hold (created_by set) is only reusable by its owner; an ownerless hold
    -- (guest checkout, or created before sign-in) stays reusable by whoever holds the unguessable id,
    -- which keeps the guest → sign-in-mid-checkout flow working.
    select * into v_hold from booking_holds
    where id = v_hold_id and status = 'active' and expires_at > now() and booking_id is null
      and session_occurrence_id = v_occ and quantity = v_want_qty
      and (created_by is null or created_by = v_actor)
    for update;
    if found then v_reused := true; end if;
  end if;
  -- A REPLAY whose booking already exists must not mint a hold.
  --
  -- create_booking's idempotency check runs before it ever looks at p_hold_id, so on a replay it
  -- returns the existing booking and never attaches whatever hold we passed. The original hold is by
  -- then consumed (booking_id set), so the reuse SELECT above cannot match it and v_reused is false --
  -- and create_hold would mint a fresh one that nothing ever claims. It then sits ACTIVE, counted by
  -- used_capacity, for its whole TTL. Worse, on a nearly-full departure create_hold raises
  -- insufficient_capacity, so a legitimate retry of a booking that ALREADY SUCCEEDED fails instead of
  -- returning it -- the caller is told the booking failed when it did not.
  -- (Only ever one orphan: a second replay finds it by idempotency key. One is enough to sell out a
  -- last vehicle.)
  if not v_reused and not exists (select 1 from bookings where idempotency_key = v_key) then
    v_hold := create_hold(v_occ, v_want_qty, v_key || ':book');
  end if;

  v_booking := create_booking(
    v_key, v_hold.id, p ->> 'customerName', p ->> 'customerEmail', p ->> 'customerPhone',
    coalesce((p ->> 'source')::booking_source, 'web'), v_items, v_suv
  );

  -- F23 (replay-disclosure guard): create_booking returns the existing row on an idempotency-key
  -- replay, and api_book runs SECURITY DEFINER, so RLS does not filter the returned DTO. Refuse to
  -- echo a booking the caller can't prove they own:
  --   * an authenticated user replaying someone else's OWNED booking -> forbidden;
  --   * ANY caller replaying an UNOWNED (guest) booking whose supplied email doesn't match -> forbidden.
  --     A stolen/guessed key alone (authenticated OR anonymous) would otherwise hand back the original
  --     guest's PII / let an authed caller adopt the row. A legitimate retry resends the same email and
  --     passes; a fresh create trivially passes (just inserted with this caller's email).
  if (v_booking.user_id is not null and v_booking.user_id is distinct from v_actor)
     or (v_booking.user_id is null
         and lower(coalesce(v_booking.customer_email, '')) <> lower(coalesce(p ->> 'customerEmail', '')))
  then
    raise exception 'forbidden';
  end if;
  if v_actor is not null then
    update bookings set user_id = v_actor where id = v_booking.id and user_id is null;
  end if;

  -- Ownership for the FALLBACK hold: when no reusable holdId was supplied, api_book mints its own
  -- hold above via create_hold, which runs under service_role here (server-only RPC) and so wrote
  -- created_by = auth.uid() = NULL. Stamp the actor onto it so the customer's owner-scoped hold
  -- status/release endpoints work. A REUSED hold already carries its owner (created_by not null),
  -- so the guard leaves it alone; a guest booking (v_actor null) leaves the hold ownerless as before.
  if v_actor is not null then
    update booking_holds set created_by = v_actor where id = v_hold.id and created_by is null;
  end if;

  -- The language the guest booked in. Email and PDFs render later, often from a cron worker with no
  -- request context, so the locale must be stored rather than inferred at send time. Unconditional: by
  -- this point the F23 guard above has already verified the caller may act on this booking, so re-
  -- asserting the same value on an idempotent replay is harmless. Absent/empty collapses to 'en' (never
  -- SQL NULL, never a failed enum cast), so an older client that sends no locale still books cleanly.
  update bookings
  set locale = coalesce(nullif(p ->> 'locale', ''), 'en')::content_locale
  where id = v_booking.id;

  if p ? 'itinerary'
     and jsonb_typeof(p -> 'itinerary') = 'array'
     and jsonb_array_length(p -> 'itinerary') > 0
     and jsonb_array_length(p -> 'itinerary') <= 30
  then
    update bookings set custom_itinerary = p -> 'itinerary'
    where id = v_booking.id and custom_itinerary is null;
  end if;

  if nullif(btrim(p ->> 'pickupLocation'), '') is not null then
    update bookings set pickup_location = left(btrim(p ->> 'pickupLocation'), 200)
    where id = v_booking.id and pickup_location is null;
  end if;

  -- Drop-off is its OWN field (never merged into pickup_location). pickup_pending records "pickup to be
  -- arranged" — distinct from "no pickup" — and is set on the just-created row only.
  if nullif(btrim(p ->> 'dropoffLocation'), '') is not null then
    update bookings set dropoff_location = left(btrim(p ->> 'dropoffLocation'), 200)
    where id = v_booking.id and dropoff_location is null;
  end if;

  if coalesce((p ->> 'pickupPending')::boolean, false) then
    update bookings set pickup_pending = true
    where id = v_booking.id and pickup_pending = false;
  end if;

  -- Airport transfer (server-authoritative, zero-trust): the destination ZONE comes from the hotel
  -- SLUG via airport_transfer_hotels — never a client-sent zone. When the guest's hotel isn't listed
  -- (no dropoffSlug), classify the zone from the supplied AREA instead (Zone 2 = the near-airport
  -- south-east areas), still never trusting a client price. The whole fare is the zone × vehicle matrix
  -- (vehicle derived from party size + the ≤4 SUV upgrade); a return trip is two legs minus the
  -- configured discount. We OVERRIDE the booking total + payout + the single line item so the receipt's
  -- item == total. Mirrors airportTransferQuoteMinor() in pricing.ts.
  if v_is_airport then
    v_trip_direction := case
      when (p ->> 'tripDirection') in ('arrival', 'departure', 'return') then p ->> 'tripDirection'
      when (p ->> 'tripType') = 'return' then 'return'
      else 'arrival'
    end;
    v_trip_type := case when v_trip_direction = 'return' then 'return' else 'one_way' end;
    if nullif(p ->> 'dropoffSlug', '') is not null then
      select zone into v_dropoff_zone from airport_transfer_hotels
        where slug = nullif(p ->> 'dropoffSlug', '');
    end if;
    if v_dropoff_zone is null then
      v_dropoff_zone := airport_transfer_area_zone(p ->> 'dropoffArea');
    end if;
    v_fare := airport_transfer_fare_minor(v_dropoff_zone, v_total_qty::int, v_suv);
    if v_trip_type = 'return' then
      select coalesce(return_discount_pct, 0) into v_ret_pct from airport_transfer_config limit 1;
      v_fare := round(v_fare::numeric * 2 * (100 - coalesce(v_ret_pct, 0)) / 100)::bigint;
    end if;
    -- Replay guard, matching the pattern every other post-create mutation in this function already
    -- uses (`and custom_itinerary is null`, `and pickup_location is null`, `and pickup_pending = false`).
    -- create_booking returns the EXISTING row on an idempotency-key replay, so unguarded this silently
    -- re-prices a booking that has already started paying -- moving total_minor out from under the MUR
    -- charge pinned on its payment row and a Peach session already minted for the old amount.
    if v_fare > 0 and not exists (select 1 from payments pay where pay.booking_id = v_booking.id) then
      update bookings
        set total_minor = v_fare, operator_payout_minor = v_fare
        where id = v_booking.id;
      update booking_items
        set unit_amount_minor = v_fare, subtotal_minor = v_fare,
            -- Align the line's vehicle name with the airport vocabulary the customer picked
            -- (airportVehicleLabel in pricing.ts) so the option and the price_label agree — the line
            -- otherwise read "Standard car (…) · 1 × Sedan". Sightseeing keeps its own Sedan/Van.
            price_label = case
              when v_total_qty <= 4 then case when v_suv then 'SUV' else 'Standard car' end
              when v_total_qty <= 6 then 'Family car'
              when v_total_qty <= 14 then 'Minibus'
              else 'Coaster'
            end
        where booking_id = v_booking.id;
    end if;
    update bookings set
        trip_type = v_trip_type,
        trip_direction = v_trip_direction,
        flight_number = left(nullif(btrim(p ->> 'flightNumber'), ''), 40),
        arrival_time = left(nullif(btrim(p ->> 'arrivalTime'), ''), 40),
        return_date = nullif(p ->> 'returnDate', '')::date,
        return_time = left(nullif(btrim(p ->> 'returnTime'), ''), 40),
        departure_flight_number = left(nullif(btrim(p ->> 'departureFlightNumber'), ''), 40),
        room_or_cabin = left(nullif(btrim(p ->> 'roomOrCabin'), ''), 60),
        luggage_details = left(nullif(btrim(p ->> 'luggageDetails'), ''), 300),
        child_seat_age = nullif(p ->> 'childSeatAge', '')::int,
        traveller_gender = left(nullif(btrim(p ->> 'travellerGender'), ''), 20),
        traveller_company = left(nullif(btrim(p ->> 'travellerCompany'), ''), 120),
        traveller_country = left(nullif(btrim(p ->> 'travellerCountry'), ''), 80),
        special_notes = left(nullif(btrim(p ->> 'specialNotes'), ''), 600)
      where id = v_booking.id;
  end if;

  -- Hotel-to-hotel transfer (server-authoritative, zero-trust): derive BOTH endpoints' regions from the
  -- hotel SLUGS via airport_transfer_hotels (or area_region() for a free-text end), reject a same-hotel
  -- trip, classify the distance band (region_distance_band), and price band × vehicle (× return discount).
  -- OVERRIDE the booking total + payout + line item. Mirrors hotelTransferQuoteMinor() in pricing.ts.
  if v_is_hotel then
    if nullif(p ->> 'pickupSlug', '') is not null
       and nullif(p ->> 'pickupSlug', '') = nullif(p ->> 'dropoffSlug', '') then
      raise exception 'same_hotel';
    end if;
    v_trip_type := case when (p ->> 'tripType') = 'return' then 'return' else 'one_way' end;
    v_hotel_pickup_region := hotel_end_region(
      p ->> 'pickupSlug',
      nullif(p ->> 'pickupLat', '')::double precision,
      nullif(p ->> 'pickupLng', '')::double precision,
      p ->> 'pickupArea');
    v_hotel_dropoff_region := hotel_end_region(
      p ->> 'dropoffSlug',
      nullif(p ->> 'dropoffLat', '')::double precision,
      nullif(p ->> 'dropoffLng', '')::double precision,
      p ->> 'dropoffArea');
    v_band := region_distance_band(v_hotel_pickup_region, v_hotel_dropoff_region);
    v_fare := hotel_transfer_fare_minor(v_band, v_total_qty::int, v_suv);
    if v_trip_type = 'return' then
      select coalesce(return_discount_pct, 0) into v_ret_pct from hotel_transfer_config limit 1;
      v_fare := round(v_fare::numeric * 2 * (100 - coalesce(v_ret_pct, 0)) / 100)::bigint;
    end if;
    -- Replay guard, matching the pattern every other post-create mutation in this function already
    -- uses (`and custom_itinerary is null`, `and pickup_location is null`, `and pickup_pending = false`).
    -- create_booking returns the EXISTING row on an idempotency-key replay, so unguarded this silently
    -- re-prices a booking that has already started paying -- moving total_minor out from under the MUR
    -- charge pinned on its payment row and a Peach session already minted for the old amount.
    if v_fare > 0 and not exists (select 1 from payments pay where pay.booking_id = v_booking.id) then
      update bookings
        set total_minor = v_fare, operator_payout_minor = v_fare
        where id = v_booking.id;
      update booking_items
        set unit_amount_minor = v_fare, subtotal_minor = v_fare,
            -- Align the line's vehicle name with the airport vocabulary the customer picked
            -- (airportVehicleLabel in pricing.ts) so the option and the price_label agree — the line
            -- otherwise read "Standard car (…) · 1 × Sedan". Sightseeing keeps its own Sedan/Van.
            price_label = case
              when v_total_qty <= 4 then case when v_suv then 'SUV' else 'Standard car' end
              when v_total_qty <= 6 then 'Family car'
              when v_total_qty <= 14 then 'Minibus'
              else 'Coaster'
            end
        where booking_id = v_booking.id;
    end if;
    update bookings set
        trip_type = v_trip_type,
        arrival_time = left(nullif(btrim(p ->> 'arrivalTime'), ''), 40),
        pickup_hotel_slug = left(nullif(btrim(p ->> 'pickupSlug'), ''), 120),
        pickup_region = v_hotel_pickup_region,
        return_date = nullif(p ->> 'returnDate', '')::date,
        return_time = left(nullif(btrim(p ->> 'returnTime'), ''), 40),
        room_or_cabin = left(nullif(btrim(p ->> 'roomOrCabin'), ''), 60),
        luggage_details = left(nullif(btrim(p ->> 'luggageDetails'), ''), 300),
        special_notes = left(nullif(btrim(p ->> 'specialNotes'), ''), 600)
      where id = v_booking.id;
  end if;

  v_child := least(greatest(coalesce(nullif(p ->> 'childSeats', '')::int, 0), 0), v_total_qty::int);
  if v_child > 0 then
    v_child_extra := greatest(0, v_child - 1) * 600;
    update bookings
    set child_seats = v_child,
        total_minor = total_minor + v_child_extra,
        operator_payout_minor = operator_payout_minor + v_child_extra
    where id = v_booking.id and child_seats = 0;
  end if;

  -- Per-activity supplements (e.g. the lobster lunch upgrade), MANY per activity since 20260908.
  -- Priced PER PERSON from each activity_supplements row, resolved by id AND scoped to the activity
  -- behind the occurrence — an unknown or foreign id simply doesn't join and charges nothing.
  -- Duplicate ids in the payload aggregate; every count clamps to the head count. Replay guards:
  -- rows already snapshot (the normal replay) or a payment already exists (a mutated replay must
  -- never re-price a booking mid-payment — [[gytm-drift-gate-double-charge]]). A configured-but-free
  -- supplement (price 0) still records the guest's request — the kitchen needs the head count.
  -- Sits after the transfer overrides for the same reason the child seats do: those OVERWRITE
  -- total_minor, so additive add-ons belong at the end.
  if p ? 'supplements'
     and jsonb_typeof(p -> 'supplements') = 'array'
     and jsonb_array_length(p -> 'supplements') between 1 and 20
     and not exists (select 1 from booking_supplements bs where bs.booking_id = v_booking.id)
     and not exists (select 1 from payments pay where pay.booking_id = v_booking.id)
  then
    for r in
      select s.id, s.name, s.price_minor, s.position,
             least(
               sum(least(greatest(coalesce(nullif(e ->> 'qty', '')::int, 0), 0), v_total_qty::int)),
               v_total_qty
             )::int as q
      from jsonb_array_elements(p -> 'supplements') e
      join activity_supplements s
        on s.id = nullif(e ->> 'id', '')::uuid
       and s.activity_id = v_activity_id
      group by s.id, s.name, s.price_minor, s.position
      order by s.position, s.id
    loop
      if r.q > 0 then
        insert into booking_supplements (booking_id, supplement_id, name, qty, unit_minor, total_minor, position)
        values (v_booking.id, r.id, r.name, r.q, r.price_minor, r.price_minor::bigint * r.q, r.position)
        on conflict (booking_id, supplement_id) where supplement_id is not null do nothing;
        v_supp_total := v_supp_total + r.price_minor::bigint * r.q;
      end if;
    end loop;
    if v_supp_total > 0 then
      update bookings
      set total_minor = total_minor + v_supp_total,
          operator_payout_minor = operator_payout_minor + v_supp_total
      where id = v_booking.id;
    end if;
  end if;

  -- Region-based transport add-on (per_person / per_group with pickup_available): a fee that scales with
  -- how far the pickup is from the activity's boarding region. The server RE-DERIVES the region from the
  -- pickup coordinates and looks up the fare here — it never trusts a client-sent price. Round-trip rule:
  -- drop-off doesn't change the fare, so it isn't read. Mirrors transportFare() in pricing.ts.
  if v_mode in ('per_person', 'per_group') and v_pickup_available
     and nullif(p ->> 'pickupLat', '') is not null
     and nullif(p ->> 'pickupLng', '') is not null
  then
    v_pickup_lat := (p ->> 'pickupLat')::double precision;
    v_pickup_lng := (p ->> 'pickupLng')::double precision;
    v_pickup_region := region_from_coords(v_pickup_lat, v_pickup_lng);
    if v_pickup_region is not null and v_activity_region is not null then
      v_transport := transport_fare_minor(v_pickup_region, v_activity_region, v_total_qty::int, v_suv);
      if v_transport > 0 then
        update bookings
        set transport_minor = v_transport,
            total_minor = total_minor + v_transport,
            operator_payout_minor = operator_payout_minor + v_transport,
            pickup_region = v_pickup_region,
            pickup_lat = v_pickup_lat,
            pickup_lng = v_pickup_lng
        where id = v_booking.id and transport_minor = 0;
      end if;
    end if;
  end if;

  return booking_json(v_booking.id);
end;
$$;

revoke execute on function api_book(jsonb) from public, anon, authenticated;
grant execute on function api_book(jsonb) to service_role;

-- ==================== 20260930000000_payment_schedule (mirrored) ====================
-- Idempotent mirror of the payment_schedule migration — last-wins for catch-up-parity.
-- Per-date payment schedule ("pay before each activity").
--
-- A quote can be sent in payment_mode = 'per_date' instead of 'deposit'. On conversion, the booking's
-- balance is split into a SCHEDULE of installments — one per activity DATE — each due before that day,
-- each with its own durable pay-link and an auto-reminder emailed a few days before. Nothing about the
-- ledger changes: installments ride on the existing `purpose='balance'` payments, so
-- append_payment_event's balance_due_minor projection (total − settled) is UNTOUCHED. An installment is
-- "covered" the moment cumulative settlement reaches its running total — a pure waterfall over the
-- balance already tracked. Installment 0 IS the deposit (the payment that secures the whole trip's
-- seats, exactly like today's deposit); 1..N are the dated balance links.
--
-- This file is the SCHEMA + the three redefined money-path functions (api_convert_quote, create_payment,
-- booking_json — each reproduced from its winning body with an ADDITIVE branch) + the reminder enqueuer.

-- ── Schema ──────────────────────────────────────────────────────────────────────────────────────

-- How a quote is to be paid. 'deposit' (default) = the existing deposit + one balance. 'per_date' =
-- a schedule of one installment per activity date, built by api_convert_quote from the line dates.
alter table quotes
  add column if not exists payment_mode text not null default 'deposit'
    check (payment_mode in ('deposit', 'per_date'));

-- Which installment a payment row belongs to (0 = the deposit row, 1..N = the dated balance rows).
-- NULL on every ordinary booking/balance/pickup payment, so the single-flight lease and the balance
-- projection are unchanged for them; it only scopes the per-installment checkout lease in create_payment.
alter table payments
  add column if not exists installment_seq int;

-- One row per scheduled payment. Amounts are the negotiated quote figures (Σ line subtotal + transport
-- for that date); `due_on` is the activity's Mauritius-local date (pay by that day, reminder a few days
-- before). The amounts are a projection of the booking's lines snapshot at conversion — a schedule NEVER
-- overrides what append_payment_event says is owed; it only groups it into dated buckets. The durable
-- pay-link needs no column here: its token is a deterministic HMAC(secret, booking_id:seq) recomputed at
-- send/resolve time (src/lib/quotes/installment-token.ts), so no raw bearer token is ever persisted —
-- the same rule the balance link follows (nothing raw in notification_outbox).
create table if not exists booking_installments (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references bookings (id) on delete cascade,
  seq int not null,
  due_on date not null,
  label text not null,
  amount_minor bigint not null check (amount_minor >= 0),
  created_at timestamptz not null default now(),
  unique (booking_id, seq)
);

create index if not exists booking_installments_booking_idx on booking_installments (booking_id);
create index if not exists booking_installments_due_idx on booking_installments (due_on);

-- New table needs its OWN grants (the blanket grant-on-all was a one-time backfill). Anon is granted
-- nothing: the durable-link path reads through SECURITY DEFINER functions (booking_json / the resolver),
-- which bypass RLS; only the owner's account page and staff read the table directly.
grant select on booking_installments to authenticated;
grant all on booking_installments to service_role;

alter table booking_installments enable row level security;

drop policy if exists booking_installments_owner_select on booking_installments;
create policy booking_installments_owner_select on booking_installments
  for select using (
    exists (
      select 1 from bookings b
      where b.id = booking_installments.booking_id
        and (b.user_id = auth.uid() or is_staff())
    )
  );

drop policy if exists booking_installments_staff_all on booking_installments;
create policy booking_installments_staff_all on booking_installments
  for all using (is_staff()) with check (is_staff());

-- ── api_convert_quote — winning body from 20260928000000, + a per_date schedule branch ────────
create or replace function api_convert_quote(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_quote quotes;
  v_prior bookings;
  v_booking bookings;
  v_reusable boolean := false;
  v_lines_minor bigint;
  v_owner uuid;
  v_deposit_minor bigint;
  v_seats record;
  v_hold booking_holds;
  v_per_date boolean := false;
  v_min_date date;
begin
  select * into v_quote
    from quotes
   where id = nullif(p ->> 'quoteId', '')::uuid
   for update;

  if v_quote.id is null then
    raise exception 'quote_not_found';
  end if;

  -- Convert-once, read off converted_at, and meaning "one PAYABLE booking at a time" (see above).
  if v_quote.converted_at is not null then
    -- LOCK THE MONEY BEFORE JUDGING IT. append_payment_event locks the payments row, writes paid_minor
    -- and status onto it, and only THEN rolls the projection onto bookings — so an unlocked read of
    -- either table can catch a settlement mid-flight, conclude "this booking never took a cent", mint
    -- booking B, commit, and let the settlement land on A afterwards. Taking the payments locks in the
    -- same order that function does serialises the two instead of racing them.
    --
    -- `bookings` is deliberately NOT locked here as well: api_create_payment locks bookings and then
    -- payments, so adding payments -> bookings on this side would close a deadlock cycle on the money
    -- path. It is also unnecessary — read committed gives every later statement in this function a
    -- fresh snapshot, so once the payments locks are held the reads below see post-settlement state.
    -- A booking with no payments row locks nothing, which is safe: api_create_payment refuses a dead
    -- booking ('booking_not_payable'), so no first payment can appear on one.
    perform 1 from payments where booking_id = v_quote.booking_id for update;

    -- booking_id is null here when an erasure hard-deleted the booking; the select finds nothing and
    -- v_reusable stays false, which is the section-4 invariant.
    select * into v_prior from bookings where id = v_quote.booking_id;
    v_reusable := found
      and v_prior.status in ('expired', 'cancelled', 'failed')
      and v_prior.payment_state in ('pending', 'failed')
      -- Money already HELD, including the shapes the booking-level projection above cannot see: an
      -- underpayment (append_payment_event sets 'pending' when v_paid > 0 but below amount_minor, so
      -- paid_minor is positive while payment_state is not) and a wrong-currency settlement quarantine
      -- (settlement_review_at, 20260830000000), which is stamped precisely so the projection is left
      -- alone. Both hold a capture on a booking that still reads clean.
      and not exists (
        select 1 from payments pay
         where pay.booking_id = v_prior.id
           and (pay.paid_minor > 0
                or pay.refunded_minor > 0
                or pay.status in ('paid', 'partially_refunded', 'refunded')
                or pay.settlement_review_at is not null)
      )
      -- Money that can still be TAKEN. A dead booking is not a dead checkout: run_booking_maintenance
      -- expires a booking 30 minutes after it was CREATED, while a Peach session stays completable
      -- ~30 minutes after it was MINTED (api_pending_payment_checkouts says exactly that in its own
      -- comment). A guest who converts at T0, clicks Pay at T0+26 and wanders off has an expired
      -- booking at T0+30 and a live session until roughly T0+56; re-arming in that gap leaves TWO
      -- payable sessions for one quote — the double charge api_create_payment's reuse guard refuses
      -- to create one level down ("Minting a replacement while the original is still live would leave
      -- TWO payable sessions for one booking") and the one 20260902000000 removed. It is also
      -- unreconcilable: api_pending_payment_checkouts only re-queries bookings still in
      -- 'payment_pending', so once the booking is expired a lost webhook on that capture is never
      -- swept — money taken, no ledger row, no link back to the quote.
      --
      -- 30 minutes, not api_create_payment's 25: 25 is the REUSE window, deliberately short of the
      -- session's life so a session handed back cannot die under the guest. The hazard here lasts as
      -- long as the session can be COMPLETED, so this window has to be the wider of the two.
      --
      -- The claimed-lease arm covers the ~90 seconds where a caller is out at Peach and the session
      -- id has not been recorded yet: provider_checkout_id is still null, so freshness alone sees
      -- nothing and would re-arm into the same double charge moments before the session appears.
      --
      -- The refusal is a wait, not a wall: mapDbError already reads quote_already_converted as "has
      -- already been paid for or is being paid", and the quote converts again once the session dies.
      and not exists (
        select 1 from payments pay
         where pay.booking_id = v_prior.id
           and ((pay.provider_checkout_id is not null
                 and coalesce(pay.checkout_created_at, pay.updated_at) > now() - interval '30 minutes')
                or (pay.checkout_claimed_until is not null and pay.checkout_claimed_until > now()))
      );
    if not v_reusable then
      raise exception 'quote_already_converted'
        using detail = coalesce(v_prior.status::text, 'linked booking no longer exists');
    end if;

    -- THE DEAD BOOKING'S SEATS GO BACK BEFORE THIS CONVERSION TAKES FRESH ONES.
    --
    -- Re-arming mints a SECOND booking, which takes its own holds below — so unless the first
    -- booking's holds are released here, one quote reserves two sets of seats for the rest of their
    -- 30-minute life. Nothing else does it: run_booking_maintenance releases holds only for the
    -- bookings IT expired, so a hand-cancelled booking (or one already swept while its hold ran on)
    -- keeps them. On a nearly-full departure that is the guest's own abandoned attempt selling the
    -- trip out from under them — create_hold would raise `insufficient_capacity` and the quote would
    -- read as sold out to the only person entitled to those seats.
    --
    -- Safe because of what the branch above has already established: this booking is dead
    -- (expired/cancelled/failed), never took a cent, and cannot take one.
    update booking_holds set status = 'released'
     where booking_id = v_prior.id and status = 'active';
  end if;

  -- Status: an explicit WHITELIST, the shape api_create_payment uses next door. A blacklist of one
  -- let a 'draft' (a half-built offer the owner has not sent, whose total may be mid-edit) and an
  -- 'expired' quote — a terminal state of the very enum this migration created — both convert.
  -- 'accepted' is in the list because that is what a converted quote's status already is, and the
  -- re-arm branch above has to be able to get past here.
  if v_quote.status = 'cancelled' then
    raise exception 'quote_cancelled';
  end if;
  if v_quote.status = 'expired' or v_quote.valid_until < current_date then
    raise exception 'quote_expired';
  end if;
  if v_quote.status not in ('sent', 'accepted') then
    raise exception 'quote_not_convertible' using detail = v_quote.status::text;
  end if;

  -- A zero-total quote mints a booking that can NEVER confirm: api_create_payment skips the FX pin
  -- for a zero amount, and append_payment_event carries an explicit guard whose own comment says "a
  -- zero-amount payment must never read as fully paid (0 >= 0)". The booking would sit in
  -- payment_pending until the sweep expired it. quotes.total_minor DEFAULTS to 0, so an empty or
  -- never-priced draft reaches this state by default rather than by accident.
  if coalesce(v_quote.total_minor, 0) <= 0 then
    raise exception 'quote_not_convertible' using detail = 'zero total';
  end if;

  -- THE TWO CATALOGUE LINES THIS FUNCTION WILL NOT PRICE INTO A SEAT. Both fail closed here, before
  -- anything is minted, because both are shapes whose capacity meaning cannot be read off the line.
  --
  -- 1. AN OPTION THAT IS NOT COUNTED IN PEOPLE. For a private or vehicle option one BOOKING is one
  --    unit of the pool — the pool counts trips, not heads (20260908000000), and create_booking
  --    records the real party size in booking_items.pax while writing quantity 1. A quote line for
  --    six guests would therefore reserve SIX DEPARTURES if it were held like a per-person line, and
  --    reserve one while charging for six if it were not. Neither is a guess worth making on the
  --    money path: there is no editor that can draft such a line yet, and the pay route's re-price
  --    gate refuses it one step earlier anyway (a private option has no activity_option_prices row
  --    to re-price against). The day the editor learns to quote a private charter, this is the
  --    branch that teaches the conversion the trips-vs-heads mapping — deliberately, with a test.
  --
  -- 2. AN OPTION THAT IS NOT THE OCCURRENCE'S OWN. `quote_item_shape` makes a catalogue line name
  --    both, and nothing checks they agree; a mismatch would write a booking_items row whose option
  --    contradicts its occurrence, i.e. a voucher and a day sheet naming a trip the guest is not on.
  --
  -- Both reuse `quote_not_convertible` rather than minting a token of their own: mapDbError already
  -- reads it as "This quote is not ready to pay yet — please message us", which is exactly true, and
  -- an unfinished offer is the operator's to fix.
  if exists (
    select 1
      from quote_items qi
      join activity_options o on o.id = qi.activity_option_id
      join activities a on a.id = o.activity_id
     where qi.quote_id = v_quote.id
       and qi.kind = 'catalogue'
       and (o.private_base_minor is not null
            or coalesce(a.pricing_mode::text, 'per_person') in ('vehicle', 'vehicle_custom'))
  ) then
    raise exception 'quote_not_convertible' using detail = 'private/vehicle catalogue line';
  end if;
  if exists (
    select 1
      from quote_items qi
      join session_occurrences so on so.id = qi.session_occurrence_id
     where qi.quote_id = v_quote.id
       and qi.kind = 'catalogue'
       and qi.activity_option_id is distinct from so.activity_option_id
  ) then
    raise exception 'quote_not_convertible' using detail = 'catalogue line option is not its occurrence''s';
  end if;

  -- THE CHARGE AND THE ITEMISATION MUST AGREE, or nothing is minted.
  --
  -- The amount charged is copied from quotes.total_minor while the lines are copied by the separate
  -- statement below, and nothing else ties the two together: total_minor carries no CHECK against its
  -- lines and no trigger recomputing it, and the editor writes the total in a different statement from
  -- the lines. src/lib/quotes/totals.ts states in its own header that there is no Zod layer above it
  -- yet and that its guards "ARE the only validation between a browser-supplied line and
  -- quotes.total_minor" — so this function is the last gate before a card is charged, and failing OPEN
  -- on the drift charges the guest a figure the itemisation does not support and renders a VAT
  -- invoice whose lines do not sum to the charge.
  --
  -- The sum is over ALL lines, of every kind, AND their transport add-ons: the line price
  -- (subtotal_minor) plus its optional round-trip transfer (transport_fare_minor) — the same
  -- Σ subtotal + Σ transport the browser's quoteTotalMinor summed into quotes.total_minor. Omitting
  -- the fares would refuse every quote that attaches a transfer ("total 61600 vs lines 52000").
  --
  -- It subsumes the zero-lines case too — a hand-set total with no itemisation at all would otherwise
  -- mint a booking with no lines and a booking_json carrying no items: charged for something with no
  -- record of what it was.
  select coalesce(sum(qi.subtotal_minor), 0) + coalesce(sum(qi.transport_fare_minor), 0)
    into v_lines_minor
    from quote_items qi
   where qi.quote_id = v_quote.id;
  if v_quote.total_minor <> v_lines_minor then
    raise exception 'quote_total_mismatch'
      using detail = format('total %s vs lines %s', v_quote.total_minor, v_lines_minor);
  end if;

  -- WHO WILL BE ABLE TO SEE THIS BOOKING. `user_id` is what the bookings RLS policy reads
  -- (`user_id = auth.uid() or is_staff()`), so a booking minted with a null one is invisible to every
  -- customer — including the guest about to pay for it, whose confirmation email links to
  -- /bookings/{ref}. quote_owner_for_email (section 6d) answers with the single CONFIRMED account
  -- holding the quoted address, or null; see its header for why that rule is exactly this narrow.
  --
  -- NULL IS A SUPPORTED ANSWER, NOT A FAILURE. Most quote guests never open an account, and nothing
  -- downstream requires an owner: api_create_quote_payment (20260911000000) exists precisely because a
  -- quote booking has none, the guest's own record stays reachable through the link token, and
  -- api_claim_quote_bookings (7c) fills the column in later if they ever do sign up.
  v_owner := quote_owner_for_email(v_quote.customer_email);

  -- DEPOSIT SIZING. The deposit is total_minor * deposit_bps / 10000 (basis points; 1000 = 10.00%),
  -- rounded to the minor unit. total_minor AND operator_payout_minor stay the FULL quoted price — they
  -- feed the VAT invoice and the operator payout, and it is only the FIRST payments row (sized to this
  -- deposit in create_payment) that the guest is charged now. deposit_bps = 10000 makes the deposit the
  -- whole total — the UNCHANGED pay-in-full path. deposit_bps carries a `between 1 and 10000` CHECK, so
  -- the deposit is always a positive fraction of the total.
  v_deposit_minor := round(v_quote.total_minor * v_quote.deposit_bps / 10000.0);

  -- PER-DATE SCHEDULE. When the quote is sent payment_mode='per_date', the balance is split into one
  -- installment per activity DATE (Mauritius-local; a null-dated line folds into the earliest date). The
  -- earliest PAYABLE date is installment 0 and IS the deposit — the payment that secures every seat,
  -- exactly like the % deposit above — so v_deposit_minor is overridden to that date's amount here, and
  -- the rest become dated balance links (built below, after the lines are copied). Falls back to the %
  -- deposit when the quote has no dated lines at all (nothing to schedule). This ONLY resizes the deposit
  -- CHARGE; the total, the balance projection and every downstream reader are untouched.
  --
  -- ZERO-AMOUNT DATES ARE EXCLUDED. A date whose lines sum to 0 (a complimentary activity) is not an
  -- installment — there is nothing to collect for it, and its seats are secured by the deposit like any
  -- other. Sizing the deposit to a zero earliest date would set deposit_minor = 0, which create_payment
  -- reads as the "no deposit" sentinel (coalesce(nullif(deposit_minor,0), total_minor)) and would then
  -- charge the WHOLE total at the deposit step — the guest shown "Pay 0.00" but billed everything. So the
  -- deposit is the first date with a POSITIVE amount, and the schedule below skips zero dates to match.
  v_min_date := (
    select min((qi.starts_at at time zone 'Indian/Mauritius')::date)
      from quote_items qi
     where qi.quote_id = v_quote.id and qi.starts_at is not null
  );
  v_per_date := (v_quote.payment_mode = 'per_date' and v_min_date is not null);
  if v_per_date then
    select g.amount_minor
      into v_deposit_minor
      from (
        select coalesce((qi.starts_at at time zone 'Indian/Mauritius')::date, v_min_date) as due_on,
               coalesce(sum(qi.subtotal_minor), 0) + coalesce(sum(qi.transport_fare_minor), 0) as amount_minor
          from quote_items qi
         where qi.quote_id = v_quote.id
         group by 1
        having coalesce(sum(qi.subtotal_minor), 0) + coalesce(sum(qi.transport_fare_minor), 0) > 0
         order by due_on
         limit 1
      ) g;
    -- Defensive: total_minor > 0 guarantees at least one positive date, so this cannot be null in
    -- practice. If it ever were, fall back to the % deposit rather than mint a zero-deposit booking.
    if v_deposit_minor is null or v_deposit_minor <= 0 then
      v_per_date := false;
      v_deposit_minor := round(v_quote.total_minor * v_quote.deposit_bps / 10000.0);
    end if;
  end if;

  -- balance_due_minor is INITIALISED to the full total: nothing is settled at conversion, so the
  -- "amount still owed" is the whole order, exactly as append_payment_event's projection would compute
  -- it (total_minor - sum of settled money, which is 0 here). It is NOT total - deposit — that would
  -- read as if the deposit were already paid the moment the booking is minted, before the guest has
  -- been charged a cent, and would disagree with the projection that recomputes this column downward
  -- as the deposit and then the balance settle (→ total - deposit → 0). The deposit is a CHARGE size
  -- (deposit_minor / the first payments row), not a payment; only settling it reduces what is owed.
  --
  -- room_or_cabin rides across from the quote (this migration): the guest's room for the driver's
  -- hotel gate pass. Null on every quote drafted before this column existed, so additive.
  insert into bookings (
    user_id, customer_name, customer_email, customer_phone, status, source,
    currency, total_minor, operator_payout_minor, payment_state, locale,
    deposit_minor, balance_due_minor, room_or_cabin
  )
  values (
    v_owner, v_quote.customer_name, v_quote.customer_email, v_quote.customer_phone, 'payment_pending',
    'quote', v_quote.currency, v_quote.total_minor, v_quote.total_minor, 'pending', v_quote.locale,
    v_deposit_minor, v_quote.total_minor, v_quote.room_or_cabin
  )
  returning * into v_booking;

  -- The `kind <> 'catalogue'` filter is what keeps this statement and the hold path below from both
  -- claiming the same line: booking_custom_items carries `check (kind <> 'catalogue')`, and a
  -- catalogue line belongs in booking_items, where it can be counted against a departure. The three
  -- transport_* columns ride across so a custom line's attached transfer reaches the day sheet + receipt;
  -- guests + pickup_label ride across (this migration) so a bespoke tour's headcount and pickup hotel
  -- reach the operations day sheet.
  insert into booking_custom_items (
    booking_id, position, kind, description, starts_at, ends_at,
    rental_vehicle_slug, quantity, unit_amount_minor, subtotal_minor,
    transport_pickup_label, transport_dropoff_label, transport_fare_minor,
    guests, pickup_label
  )
  select v_booking.id, qi.position, qi.kind, qi.description, qi.starts_at, qi.ends_at,
         qi.rental_vehicle_slug, qi.quantity, qi.unit_amount_minor, qi.subtotal_minor,
         qi.transport_pickup_label, qi.transport_dropoff_label, qi.transport_fare_minor,
         qi.guests, qi.pickup_label
    from quote_items qi
   where qi.quote_id = v_quote.id
     and qi.kind <> 'catalogue';

  -- ── THE CATALOGUE LINES TAKE THEIR SEATS, HERE, IN THIS TRANSACTION ─────────────────────────
  --
  -- A catalogue line names a session_occurrence, so unlike a custom line it is a place on a real
  -- departure. It is only actually reserved if it is reserved the way every other booking reserves
  -- one: create_hold — the universal gate, which api_create_hold and api_book both delegate their
  -- hold INSERT to — takes `select … for update` on the occurrence, re-reads used_capacity() under
  -- that lock and refuses an oversell; and the booking_items row is what used_capacity() counts once
  -- the booking confirms, what append_payment_event's oversell re-check reads before it confirms
  -- anything, and what puts the guest on the day sheet. Re-deriving either here would be a second,
  -- quieter definition of "a seat exists" on the money path.
  --
  -- WHY IT IS IN THIS FUNCTION AND NOT IN THE PAY ROUTE (which is where the plan first put it): a
  -- route does it in a SECOND transaction, so a hold that fails leaves a converted quote and a
  -- payable booking with no seat behind it — the guest pays for a place nobody reserved, which is
  -- the precise state the placeholder guard this replaces existed to prevent, now reached by a
  -- different road. In here, a refusal takes the booking, its custom lines and `converted_at` back
  -- with it, and the guest sees a refusal instead of a charge.
  --
  -- UNITS, NOT PEOPLE. used_capacity() sums booking_holds.quantity and booking_items.quantity, and
  -- append_payment_event re-checks this booking's own booking_items sum against the occurrence's
  -- capacity — so the hold's quantity must equal the quantities of the lines it covers, or the seat
  -- count drifts the moment the payment lands. Lines that share an occurrence are aggregated into
  -- ONE hold for exactly that reason (two 'Adult' and 'Child' lines on one boat are three seats on
  -- one trip, not two reservations).
  --
  -- The idempotency key is scoped to THIS booking, so a re-arm (a fresh booking for the same quote)
  -- takes fresh holds rather than being handed create_hold's idempotent replay of a released one.
  --
  -- WHAT IS DELIBERATELY *NOT* RE-USED FROM THE CHECKOUT: create_booking's per-booking guests-per-trip
  -- cap (20260908000000). That cap exists because a self-serve guest cannot know the day's pool is
  -- several departures — "the boat only seats so many, however big the day's pool is" — and it is
  -- enforced per BOOKING, so one quote line could never express "twenty guests, two boats" with it in
  -- the way. The operator drafting this quote chose the departure and the party size, and the POOL is
  -- still enforced by create_hold, so no other guest can be oversold; what a big party costs is two
  -- boats' worth of units out of the day, which is what it consumes. Revisit this the day quotes are
  -- drafted by anyone but staff.
  for v_seats in
    select qi.session_occurrence_id as occurrence_id, sum(qi.quantity)::int as units
      from quote_items qi
     where qi.quote_id = v_quote.id and qi.kind = 'catalogue'
     group by qi.session_occurrence_id
  loop
    begin
      v_hold := create_hold(
        v_seats.occurrence_id, v_seats.units,
        'quote:' || v_booking.id::text || ':' || v_seats.occurrence_id::text
      );
    exception when raise_exception then
      -- create_hold refuses in the CHECKOUT's vocabulary — insufficient_capacity,
      -- occurrence_not_bookable, occurrence_in_past, occurrence_too_soon — and mapDbError turns those
      -- into "Not enough availability for this selection" or the bare "Invalid booking request",
      -- neither of which tells a quote guest anything they can act on: they cannot pick another date,
      -- because the date was arranged for them. One token for all of them, carrying the real reason in
      -- DETAIL for error_logs, and mapped to a sold-out 409 that says to message us.
      raise exception 'quote_seats_unavailable'
        using detail = format('occurrence %s x%s: %s', v_seats.occurrence_id, v_seats.units, sqlerrm);
    end;

    -- ATTACH THE HOLD TO THE BOOKING. Not tidiness: append_payment_event's oversell re-check counts
    -- every active hold that is NOT this booking's own against it, so a detached hold is the guest's
    -- own reservation blocking their own confirmation and routing a good payment to refund_pending.
    -- It is also what makes the confirmation mark it 'consumed' rather than leaving it to lapse.
    update booking_holds set booking_id = v_booking.id where id = v_hold.id;
  end loop;

  -- One row per LINE (the hold above is one row per occurrence): the tiers are what the voucher, the
  -- day sheet and the VAT invoice itemise. Prices are the quote's own — the negotiated figure the
  -- guest saw and `quote_total_mismatch` has just re-checked — never re-derived from the catalogue
  -- here; the pay route compares them against the live price list and refuses on drift before this
  -- function is ever called. `price_label` is NOT NULL on booking_items, so a line that carries no
  -- tier name falls back to its description rather than failing at the constraint. The transport_*
  -- columns ride across so a tour's attached transfer reaches the day sheet + receipt.
  insert into booking_items (
    booking_id, session_occurrence_id, activity_option_id, price_label,
    quantity, unit_amount_minor, subtotal_minor,
    transport_pickup_label, transport_dropoff_label, transport_fare_minor
  )
  select v_booking.id, qi.session_occurrence_id, qi.activity_option_id,
         coalesce(nullif(btrim(qi.price_label), ''), nullif(btrim(qi.description), ''), 'Quoted place'),
         qi.quantity, qi.unit_amount_minor, qi.subtotal_minor,
         qi.transport_pickup_label, qi.transport_dropoff_label, qi.transport_fare_minor
    from quote_items qi
   where qi.quote_id = v_quote.id
     and qi.kind = 'catalogue'
   order by qi.position;

  -- THE PER-DATE SCHEDULE ROWS. One installment per activity date (Mauritius-local; null-dated lines fold
  -- into the earliest). seq 0 = the earliest date = the deposit just sized above; 1..N = the later dates,
  -- each a dated balance link. Amounts are the SAME Σ subtotal + Σ transport the quote total was just
  -- re-checked against (quote_total_mismatch), grouped by date — a projection over the balance, never a
  -- second source of truth for what is owed. On a re-arm this runs against the FRESH booking id.
  if v_per_date then
    insert into booking_installments (booking_id, seq, due_on, label, amount_minor)
    select v_booking.id,
           (row_number() over (order by g.due_on) - 1)::int,
           g.due_on,
           to_char(g.due_on, 'FMDD Mon YYYY'),
           g.amount_minor
      from (
        select coalesce((qi.starts_at at time zone 'Indian/Mauritius')::date, v_min_date) as due_on,
               coalesce(sum(qi.subtotal_minor), 0) + coalesce(sum(qi.transport_fare_minor), 0) as amount_minor
          from quote_items qi
         where qi.quote_id = v_quote.id
         group by 1
         -- Skip zero-amount dates: a complimentary date is not an installment (nothing to collect), and
         -- keeping it would make seq 0 a €0 row that disagrees with the positive-first deposit above.
        having coalesce(sum(qi.subtotal_minor), 0) + coalesce(sum(qi.transport_fare_minor), 0) > 0
      ) g;
  end if;

  -- Overwrites booking_id on a re-arm, which releases the dead booking from the UNIQUE.
  update quotes
     set booking_id = v_booking.id,
         converted_at = now(),
         status = 'accepted',
         updated_at = now()
   where id = v_quote.id;

  return booking_json(v_booking.id);
end;
$$;
revoke execute on function api_convert_quote(jsonb) from public, anon, authenticated;
grant execute on function api_convert_quote(jsonb) to service_role;

-- ── create_payment — winning body from 20260912000000, + installment sizing in the balance branch
create or replace function create_payment(p jsonb, p_enforce_caller_identity boolean default true)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking bookings;
  v_payment payments;
  v_rate numeric;
  v_src text;
  v_at timestamptz;
  v_charged bigint;
  v_purpose text := coalesce(nullif(p ->> 'purpose', ''), 'booking');
  v_req booking_pickup_requests;
  -- The installment a 'balance' link names (null = the plain whole-balance link, unchanged). Its charge
  -- brings settlement up to that installment's running total; scopes the checkout lease so each dated
  -- link is its own single-flight session, not a fork of the previous installment's.
  v_installment_seq int := nullif(p ->> 'installmentSeq', '')::int;
  v_charge bigint;
begin
  if v_purpose not in ('booking', 'pickup_addon', 'balance') then
    raise exception 'invalid_payment_purpose' using detail = v_purpose;
  end if;

  -- FOR UPDATE: every concurrent create-payment call for one booking serialises on this row for the
  -- rest of the transaction. That closes two races at once: two callers both inserting a payments row
  -- below, and — via the checkout lease — two callers both getting a green light to mint a Peach
  -- session. Peach's nonce is unique per REQUEST (it never dedupes), so without this lease two tabs
  -- or a retry could create two independently payable sessions for the same booking.
  -- (It also makes the charge pin race-free: one caller pins, the loser re-reads the pinned row.)
  --
  -- It is also what serialises the two ENTRY POINTS against each other: a staff member opening the
  -- checkout for a quote booking through api_create_payment and the guest clicking Pay through
  -- api_create_quote_payment reach this same lock, this same payments row and this same lease.
  select * into v_booking from bookings where ref = p ->> 'bookingRef' for update;
  if not found then
    raise exception 'booking_not_found';
  end if;
  if v_purpose = 'booking' then
    if v_booking.status in ('confirmed', 'completed', 'cancelled', 'expired', 'refund_pending', 'refunded', 'failed')
       or v_booking.payment_state in ('paid', 'partially_refunded', 'refunded') then
      raise exception 'booking_not_payable' using detail = v_booking.status::text;
    end if;
  elsif v_purpose = 'balance' then
    -- THE BALANCE'S OWN PAYABILITY. The deposit has already CONFIRMED the booking, so a 'booking' row
    -- here would trip the guard above (booking_not_payable) — which is exactly why the balance is a
    -- separate purpose, the same reason the pickup add-on is. What is left to collect is the booking's
    -- balance_due_minor, the projection append_payment_event maintains (add-on-immune, the true amount
    -- still owed). Payable only on a confirmed booking that still owes something; a fully-paid booking
    -- (balance_due_minor = 0) has nothing to charge, so it is refused with a readable code of its own —
    -- distinct from booking_not_payable, which the balance row could never itself provoke.
    if v_booking.status <> 'confirmed' then
      raise exception 'booking_not_payable' using detail = 'balance:' || v_booking.status::text;
    end if;
    if coalesce(v_booking.balance_due_minor, 0) <= 0 then
      raise exception 'balance_already_paid';
    end if;
    -- A DATED INSTALLMENT LINK. It charges the amount that brings this booking's settlement up to the
    -- installment's RUNNING total (Σ amounts of it and every earlier installment) — so paying a later
    -- date also clears any earlier unpaid one, which is correct because activities are chronological and
    -- an earlier date is already overdue by then. settled = total − balance_due (the projection). Nothing
    -- to charge means it, and everything before it, is already covered. All server-derived from the
    -- booking row + the schedule, never caller input — exactly like the deposit and the FX pin. The plain
    -- balance link (no installmentSeq) skips all of this and pays the whole balance, unchanged.
    if v_installment_seq is not null then
      if not exists (
        select 1 from booking_installments bi
         where bi.booking_id = v_booking.id and bi.seq = v_installment_seq
      ) then
        raise exception 'installment_not_found' using detail = v_installment_seq::text;
      end if;
      v_charge := greatest(0, least(
        v_booking.balance_due_minor,
        (select coalesce(sum(bi.amount_minor), 0)
           from booking_installments bi
          where bi.booking_id = v_booking.id and bi.seq <= v_installment_seq)
          - (v_booking.total_minor - v_booking.balance_due_minor)
      ));
      if v_charge <= 0 then
        raise exception 'installment_already_paid' using detail = v_installment_seq::text;
      end if;
    end if;
  else
    -- The add-on's own payability: an open request must exist, and the trip must not have left.
    select * into v_req from booking_pickup_requests
     where booking_id = v_booking.id and applied_at is null and payment_id is not null;
    if not found then
      raise exception 'pickup_request_not_found';
    end if;
    -- …and it must not ALREADY hold the guest's money. A request refused at settlement (the departure
    -- was called off) stays open behind a payments row that is already 'paid'. If the trip is then
    -- rescheduled onto a live date the eligibility ladder goes green again, and without this guard
    -- the booking page's "Complete payment" button minted a SECOND Peach session on that same row —
    -- charging the card twice for one supplement, invisibly: the apply trigger cannot fire again
    -- (its WHEN clause needs old.status distinct from 'paid'), so no second alert is raised either.
    if exists (
      select 1 from payments pay
       where pay.id = v_req.payment_id and pay.paid_minor >= pay.amount_minor and pay.amount_minor > 0
    ) then
      raise exception 'pickup_already_paid';
    end if;
    if not coalesce((pickup_addon_quote(v_booking.id, v_req.pickup_lat, v_req.pickup_lng) ->> 'eligible')::boolean, false) then
      raise exception 'booking_not_payable' using detail = 'pickup_addon';
    end if;
  end if;
  -- THE CALLER-IDENTITY CHECK — unchanged, and still what api_create_payment enforces. It is skipped
  -- ONLY for a caller that has already proved a stronger, non-session credential: see the header, and
  -- api_create_quote_payment, which is the only function in the schema that passes `false`.
  if p_enforce_caller_identity
     and not (is_staff() or (auth.uid() is not null and v_booking.user_id = auth.uid())) then
    raise exception 'forbidden';
  end if;

  -- No `and status <> 'failed'`: that skipped the row a declined attempt had latched to 'failed' and
  -- minted a SECOND payments row, orphaning the checkout-reuse window and the single-flight lease
  -- (both columns on the skipped row) and leaving two independently payable Peach sessions.
  if v_purpose = 'booking' then
    select * into v_payment from payments
    where booking_id = v_booking.id and purpose = 'booking'
    order by created_at desc
    limit 1;

    if not found then
      -- Scoped to THIS booking: an unscoped key lookup let a caller echo another payment's key and
      -- receive that payment's id/amount back.
      select * into v_payment from payments
      where idempotency_key = p ->> 'idempotencyKey' and booking_id = v_booking.id and purpose = 'booking';
    end if;
  elsif v_purpose = 'balance' then
    -- The newest STILL-OPEN 'balance' row for this booking — never a 'booking' row (that is the deposit,
    -- a distinct purpose). Under the booking-row FOR UPDATE above this is the single-open-session guard,
    -- and it is scoped to the BOOKING, NOT to installment_seq: a booking has at most ONE payable balance
    -- session at a time, whichever installment (or the plain whole-balance link) opened it. This is
    -- load-bearing because each installment charge is CUMULATIVE (seq k collects the running total up to
    -- it, minus what is settled) — so two installment links, or an installment link and the plain balance
    -- link, size to OVERLAPPING amounts. If each minted its own live Peach session (the per-seq scoping
    -- this replaces), completing both would settle the overlap twice and overcharge the guest. One open
    -- session per booking makes that unrepresentable: the second open reuses the first's row + checkout
    -- lease, and only once it settles (and balance_due drops) does the next open mint a fresh, correctly
    -- re-sized row.
    --
    -- "Still open" = paid_minor < amount_minor, so a DECLINED or PENDING row (paid_minor 0) is reused
    -- rather than orphaned by a second row — the original plain-balance behaviour, which for the plain
    -- link the balance_already_paid guard above already made equivalent (a fully-paid plain balance
    -- leaves balance_due = 0 and never reaches here). An installment booking DOES reach here with a
    -- fully-paid earlier row while balance_due is still > 0, and the filter is what lets seq k+1 mint its
    -- own session instead of re-minting on the settled seq k row. No `and status <> 'failed'`, exactly as
    -- the deposit path.
    select * into v_payment from payments
    where booking_id = v_booking.id and purpose = 'balance'
      and coalesce(paid_minor, 0) < amount_minor
    order by created_at desc
    limit 1;

    if not found then
      select * into v_payment from payments
      where idempotency_key = p ->> 'idempotencyKey' and booking_id = v_booking.id and purpose = 'balance';
    end if;
  else
    -- Exactly the row the open request points at — never "the newest add-on row", which after a
    -- superseded request could be a different, abandoned one.
    select * into v_payment from payments where id = v_req.payment_id and purpose = 'pickup_addon';
  end if;

  if not found then
    if v_purpose = 'pickup_addon' then
      -- api_request_pickup owns the add-on row (it is the only place that knows the fare). Never
      -- invent one here, or the amount would come from nowhere.
      raise exception 'pickup_request_not_found';
    elsif v_purpose = 'balance' then
      -- Mint the balance row. Its amount is the booking's CURRENT balance_due_minor — the SERVER's figure
      -- for what is still owed, read off the booking row (never caller input, exactly like the deposit
      -- and the FX pin) and snapshotted onto this row, so charging it drives balance_due_minor to 0. The
      -- balance-payability branch above has already proved it is > 0. From here everything is per-payment-
      -- row: this row takes its own FX pin, its own checkout lease and its own provider_checkout_id.
      -- Sized to the named installment's charge (v_charge, computed + proved > 0 above) when this is a
      -- dated link, else the WHOLE balance — the unchanged plain-balance path. installment_seq is RECORDED
      -- (which installment first opened this session), not used to scope the lease: the reuse lookup above
      -- is booking-wide, so this is the booking's one open balance session until it settles.
      insert into payments (booking_id, idempotency_key, amount_minor, purpose, installment_seq)
      values (v_booking.id, p ->> 'idempotencyKey',
              coalesce(v_charge, v_booking.balance_due_minor), 'balance', v_installment_seq)
      returning * into v_payment;
      insert into payment_events (payment_id, type, amount_minor)
      values (v_payment.id, 'intent', coalesce(v_charge, v_booking.balance_due_minor));
    else
      -- The first `booking` row is sized to the DEPOSIT when the booking carries one. A quote booking
      -- carries a positive deposit_minor (api_convert_quote sized it from deposit_bps), and a pay-in-full
      -- quote's is the whole total; an ordinary customer booking has none — deposit_minor DEFAULTS to 0,
      -- so nullif() falls the charge back to total_minor and the customer path is bit-for-bit what it was.
      -- Sized off the BOOKING ROW, never caller input, exactly like the FX pin below: what a card is
      -- charged is a server figure. append_payment_event then confirms the booking when THIS row is paid
      -- in full, so paying the deposit confirms it and reserves the seat with no change to that gate.
      -- installment_seq: 0 on a scheduled booking (the deposit IS installment 0), null otherwise — so the
      -- schedule's first row is settled by this payment, and an ordinary booking is bit-for-bit unchanged.
      -- The deposit SIZING (the pinned coalesce) is untouched.
      insert into payments (booking_id, idempotency_key, amount_minor, purpose, installment_seq)
      values (v_booking.id, p ->> 'idempotencyKey',
              coalesce(nullif(v_booking.deposit_minor, 0), v_booking.total_minor), 'booking',
              (select min(bi.seq) from booking_installments bi where bi.booking_id = v_booking.id))
      returning * into v_payment;
      insert into payment_events (payment_id, type, amount_minor)
      values (v_payment.id, 'intent', coalesce(nullif(v_booking.deposit_minor, 0), v_booking.total_minor));
    end if;
  end if;

  -- ── Pin the charge (once per payment row) ────────────────────────────────────────────────────
  -- The EUR ledger total converted to WHOLE MUR RUPEES at the server-controlled rate. Derived here,
  -- in SQL, from fx_rates — NEVER from caller input (this function is granted to authenticated; a
  -- caller-supplied rate would let a booking owner pin their own MUR 0.05 charge). First-write-wins:
  -- every later call — every re-minted checkout session, the pay page, reconcile — reads THIS figure,
  -- so a moved FX rate between sessions can never make the charge and the expected settlement drift.
  if v_payment.charged_amount_minor is null and v_payment.amount_minor > 0 then
    select r.rate, r.source, r.fetched_at into v_rate, v_src, v_at
      from fx_rates r where r.base = 'EUR' and r.quote = 'MUR';
    -- Band-clamped on READ as well as write: an inverted or foreign payload that somehow reached the
    -- table (0.0185 would bill MUR 1.85 for a EUR 100 booking — and, because settled == charged,
    -- CONFIRM it) falls back to the floor instead of being trusted.
    if v_rate is null or v_rate < 40 or v_rate > 70 then
      v_rate := 53.00; -- cold-start floor; see the fx_rates seed comment (kept below mid on purpose)
      v_src := 'fallback';
      v_at := now();
    end if;
    -- Whole rupees: kills every sub-unit disagreement between what we send Peach and what Peach
    -- reports back. Costs at most MUR 0.50 (~EUR 0.01) per booking.
    v_charged := (round(v_payment.amount_minor * v_rate / 100.0) * 100)::bigint;
    update payments
       set charged_amount_minor = v_charged,
           charged_currency = 'MUR',
           charged_fx_rate = v_rate,
           charged_fx_source = v_src,
           charged_fx_at = v_at,
           updated_at = now()
     where id = v_payment.id and charged_amount_minor is null
     returning * into v_payment;
    if not found then
      -- Another transaction pinned first (or a legacy row already carried a charge): read the truth.
      select * into v_payment from payments where id = v_payment.id;
    end if;
  end if;

  -- Checkout lease (single-flight): exactly one caller may be out creating a Peach session at any
  -- moment. Order matters — reuse beats pending beats claim:
  --   1. a still-fresh recorded checkout        -> hand the SAME session back (reuse; no Peach call);
  --   2. someone else holds an unexpired lease  -> checkoutPending (caller retries shortly);
  --   3. otherwise                              -> stamp the lease and let THIS caller call Peach.
  -- api_record_payment_checkout clears the lease when the session id is recorded; a Peach failure
  -- releases it via api_release_checkout_claim, and the 90-second expiry is the crash backstop.
  --
  -- Freshness is measured from checkout_created_at (when the session was MINTED), never from
  -- updated_at: the reconcile sweep touches updated_at on every pass, which used to re-arm this
  -- window forever and trap the customer on a dead session. The caller still verifies liveness with
  -- the provider before actually reusing what this returns.
  if v_payment.provider_checkout_id is not null
     and coalesce(v_payment.checkout_created_at, v_payment.updated_at) > now() - interval '25 minutes' then
    return jsonb_build_object(
      'paymentId', v_payment.id, 'amountMinor', v_payment.amount_minor,
      'bookingRef', v_booking.ref, 'customerEmail', v_booking.customer_email,
      'existingCheckoutId', v_payment.provider_checkout_id,
      'chargedAmountMinor', v_payment.charged_amount_minor,
      'chargedCurrency', v_payment.charged_currency,
      'chargedFxRate', v_payment.charged_fx_rate
    );
  end if;

  if v_payment.checkout_claimed_until is not null and v_payment.checkout_claimed_until > now() then
    return jsonb_build_object(
      'paymentId', v_payment.id, 'amountMinor', v_payment.amount_minor,
      'bookingRef', v_booking.ref, 'customerEmail', v_booking.customer_email,
      'existingCheckoutId', null,
      'checkoutPending', true,
      'chargedAmountMinor', v_payment.charged_amount_minor,
      'chargedCurrency', v_payment.charged_currency,
      'chargedFxRate', v_payment.charged_fx_rate
    );
  end if;

  update payments set checkout_claimed_until = now() + interval '90 seconds'
  where id = v_payment.id;

  return jsonb_build_object(
    'paymentId', v_payment.id, 'amountMinor', v_payment.amount_minor,
    'bookingRef', v_booking.ref, 'customerEmail', v_booking.customer_email,
    'existingCheckoutId', null,
    'chargedAmountMinor', v_payment.charged_amount_minor,
    'chargedCurrency', v_payment.charged_currency,
    'chargedFxRate', v_payment.charged_fx_rate
  );
end;
$$;

revoke execute on function create_payment(jsonb, boolean) from public, anon, authenticated;
grant execute on function create_payment(jsonb, boolean) to service_role;

-- ── booking_json — winning body from 20260917000000, + an installments[] array ────────────────
create or replace function booking_json(p_booking_id uuid)
returns jsonb
language sql
stable
security invoker
set search_path = public
as $$
  select jsonb_build_object(
    'id', b.id, 'ref', b.ref, 'status', b.status, 'paymentState', b.payment_state,
    'customerName', b.customer_name, 'customerEmail', b.customer_email,
    'totalEur', b.total_minor::float / 100, 'currency', b.currency, 'source', b.source,
    'createdAt', b.created_at,
    'customItinerary', b.custom_itinerary,
    'pickupLocation', b.pickup_location,
    'dropoffLocation', b.dropoff_location,
    'pickupPending', b.pickup_pending,
    'pickupHotelSlug', b.pickup_hotel_slug,
    'childSeats', b.child_seats,
    'transportEur', b.transport_minor::float / 100,
    'supplements', coalesce((
      select jsonb_agg(jsonb_build_object(
        'name', bs.name, 'qty', bs.qty,
        'unitEur', bs.unit_minor::float / 100, 'totalEur', bs.total_minor::float / 100
      ) order by bs.position, bs.name)
      from booking_supplements bs where bs.booking_id = b.id
    ), '[]'::jsonb),
    'pendingPickup', (
      select jsonb_build_object(
        'pickupLocation', r.pickup_location,
        'dropoffLocation', r.dropoff_location,
        'feeEur', r.fee_minor::float / 100,
        'paymentId', r.payment_id,
        'createdAt', r.created_at
      )
      from booking_pickup_requests r
      where r.booking_id = b.id and r.applied_at is null and r.fee_minor > 0
      order by r.created_at desc
      limit 1
    ),
    'pickupRegion', b.pickup_region,
    'tripType', b.trip_type,
    'tripDirection', b.trip_direction,
    'flightNumber', b.flight_number,
    'arrivalTime', b.arrival_time,
    'returnDate', b.return_date,
    'returnTime', b.return_time,
    'departureFlightNumber', b.departure_flight_number,
    'roomOrCabin', b.room_or_cabin,
    'luggageDetails', b.luggage_details,
    'childSeatAge', b.child_seat_age,
    'travellerGender', b.traveller_gender,
    'travellerCompany', b.traveller_company,
    'travellerCountry', b.traveller_country,
    'specialNotes', b.special_notes,
    'disruption', b.disruption,
    'partySize', coalesce((
      select sum(coalesce(bi.pax, bi.quantity))
        from booking_items bi where bi.booking_id = b.id
    ), 0),
    -- The BOOKING-UNIT count, the unit seatsLeft is denominated in. For a per-person option it equals
    -- partySize; for a vehicle/private one it is 1 (one van / one trip, any group size). The date
    -- picker must filter on THIS, not partySize, or a 6-guest transfer is offered nothing.
    'unitsNeeded', coalesce((
      select sum(bi.quantity)
        from booking_items bi where bi.booking_id = b.id
    ), 0),
    'activityOptionId', (
      select bi.activity_option_id
        from booking_items bi where bi.booking_id = b.id order by bi.id limit 1
    ),
    'activitySlug', (
      select a.slug
        from booking_items bi
        join activity_options ao on ao.id = bi.activity_option_id
        join activities a on a.id = ao.activity_id
       where bi.booking_id = b.id
       order by bi.id limit 1
    ),
    'cancellable', (
      b.status = 'confirmed' and b.payment_state = 'paid'
      and (
        booking_awaiting_choice(b.disruption)
        or coalesce((
          select min(so.starts_at)
            from booking_items bi
            join session_occurrences so on so.id = bi.session_occurrence_id
           where bi.booking_id = b.id
        ), 'epoch'::timestamptz) > now() + interval '24 hours'
      )
    ),
    'reschedulable', (
      b.status = 'confirmed' and b.payment_state = 'paid'
      and (
        booking_awaiting_choice(b.disruption)
        or coalesce((
          select min(so.starts_at)
            from booking_items bi
            join session_occurrences so on so.id = bi.session_occurrence_id
           where bi.booking_id = b.id
        ), 'epoch'::timestamptz) > now() + interval '24 hours'
      )
    ),
    'serviceDate', (
      select min(so.starts_at)
        from booking_items bi
        join session_occurrences so on so.id = bi.session_occurrence_id
       where bi.booking_id = b.id
    ),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'priceLabel', bi.price_label, 'quantity', bi.quantity, 'pax', bi.pax,
        'unitAmountEur', bi.unit_amount_minor::float / 100, 'subtotalEur', bi.subtotal_minor::float / 100,
        'occurrenceId', bi.session_occurrence_id
      ))
      from booking_items bi where bi.booking_id = b.id
    ), '[]'::jsonb),
    -- ── A QUOTE BOOKING'S OWN LINES ─────────────────────────────────────────────────────────────
    -- api_convert_quote writes every non-occurrence line (custom, rental, transport) to
    -- booking_custom_items, so a booking minted from a quote has NO booking_items at all and the
    -- 'items' array above is empty. The guest's own page then showed a bare total with nothing
    -- explaining it. Ordered by `position` — the order the guest read the offer in.
    'customItems', coalesce((
      select jsonb_agg(jsonb_build_object(
        'description', ci.description,
        'quantity', ci.quantity,
        'unitAmountEur', ci.unit_amount_minor::float / 100,
        'subtotalEur', ci.subtotal_minor::float / 100,
        'startsAt', ci.starts_at
      ) order by ci.position)
      from booking_custom_items ci where ci.booking_id = b.id
    ), '[]'::jsonb),
    -- What was taken up front and what is still owed. payment_state reads 'paid' the moment the
    -- DEPOSIT clears, so without these the page calls a 10%-paid booking settled.
    'depositEur', b.deposit_minor::float / 100,
    'balanceDueEur', b.balance_due_minor::float / 100,
    -- The earliest thing the guest is booked on, across BOTH line tables — the balance falls due 24h
    -- before it. `serviceDate` above sees only session occurrences and is left alone (receipts read
    -- it); this is the quote-aware one. Null when no line carries a date, and the page then shows no
    -- deadline rather than inventing one.
    'firstActivityAt', least(
      (select min(so.starts_at) from booking_items bi
         join session_occurrences so on so.id = bi.session_occurrence_id
        where bi.booking_id = b.id),
      (select min(ci.starts_at) from booking_custom_items ci where ci.booking_id = b.id)
    ),
    -- The per-date payment schedule (empty on an ordinary deposit booking). `coveredEur` is a pure
    -- WATERFALL over the balance append_payment_event already maintains: settlement (total − balanceDue)
    -- fills the installments in seq order, so an installment is fully covered when settlement has reached
    -- its running total. No second ledger — just a dated view of the one balance.
    'installments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'seq', bi.seq,
        'dueOn', bi.due_on,
        'label', bi.label,
        'amountEur', bi.amount_minor::float / 100,
        'coveredEur', greatest(0, least(
          bi.amount_minor,
          (b.total_minor - b.balance_due_minor)
            - coalesce((select sum(bi2.amount_minor) from booking_installments bi2
                         where bi2.booking_id = b.id and bi2.seq < bi.seq), 0)
        ))::float / 100
      ) order by bi.seq)
      from booking_installments bi where bi.booking_id = b.id
    ), '[]'::jsonb)
  )
  from bookings b where b.id = p_booking_id;
$$;

-- ── api_enqueue_installment_reminders — dated chase (guest) + overdue alert (owner) ───────────────
-- Modeled on api_enqueue_pickup_reminders: a service-role enqueuer the maintenance cron calls each tick.
-- For every UNCOVERED dated installment (seq > 0; seq 0 is the deposit, settled at confirmation): if it
-- is within `leadDays` (default 3) of its date, chase the guest; if its date has passed, alert the owner
-- that it is overdue (owner's call whether to run the activity — nothing auto-cancels). "Covered" and the
-- amount-still-due are the same waterfall over balance_due the pay-link uses, so a reminder never asks for
-- money already settled. Idempotency key is per installment, so each is chased at most once per bucket.
create or replace function api_enqueue_installment_reminders(p jsonb default '{}'::jsonb)
returns int
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_count int := 0;
  v_lead int := coalesce((p ->> 'leadDays')::int, 3);
  v_c record;
  v_due_minor bigint;
  -- Today in MAURITIUS local time, not the session's UTC current_date. due_on is a Mauritius-local date
  -- (grouped `at time zone 'Indian/Mauritius'`), so comparing it to a UTC "today" would slide the chase
  -- and overdue windows by the +4h offset at every day boundary — chasing a few hours early, flagging
  -- overdue a few hours late. Mauritius keeps a fixed UTC+4 offset, so this is exact year-round.
  v_today date := (now() at time zone 'Indian/Mauritius')::date;
begin
  if auth.role() <> 'service_role' then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  for v_c in (
    select b.id as booking_id, b.ref, q.ref as quote_ref,
           b.customer_email, b.customer_name, b.locale::text as locale,
           b.total_minor, b.balance_due_minor,
           bi.seq, bi.due_on, bi.label, bi.amount_minor,
           (select coalesce(sum(x.amount_minor), 0) from booking_installments x
             where x.booking_id = b.id and x.seq <= bi.seq) as cumulative_minor
      from booking_installments bi
      join bookings b on b.id = bi.booking_id
      -- The durable link + its HMAC token are keyed on the QUOTE ref + the booking id, so carry both.
      left join quotes q on q.booking_id = b.id
     where b.status = 'confirmed'
       and b.customer_email is not null
       and q.ref is not null
       and bi.seq > 0
       and coalesce(b.balance_due_minor, 0) > 0
  )
  loop
    -- settled = total − balance_due; covered once settlement reaches this installment's running total.
    if (v_c.total_minor - v_c.balance_due_minor) >= v_c.cumulative_minor then
      continue;
    end if;
    v_due_minor := greatest(0, least(
      v_c.balance_due_minor,
      v_c.cumulative_minor - (v_c.total_minor - v_c.balance_due_minor)
    ));

    if v_c.due_on >= v_today and v_c.due_on <= v_today + v_lead then
      insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
      values (
        'email', v_c.customer_email, 'installment_reminder',
        jsonb_build_object(
          'ref', v_c.ref, 'quoteRef', v_c.quote_ref, 'bookingId', v_c.booking_id,
          'customerName', v_c.customer_name, 'seq', v_c.seq,
          'dueOn', v_c.due_on, 'label', v_c.label, 'amountDueMinor', v_due_minor, 'locale', v_c.locale
        ),
        v_c.booking_id,
        'installment_reminder:' || v_c.booking_id::text || ':' || v_c.seq::text
      )
      on conflict (idempotency_key) do nothing;
      v_count := v_count + 1;
    elsif v_c.due_on < v_today then
      insert into notification_outbox (channel, recipient, template, payload, booking_id, idempotency_key)
      values (
        'email', 'owner', 'owner_installment_overdue',
        jsonb_build_object(
          'ref', v_c.ref, 'customerName', v_c.customer_name, 'seq', v_c.seq,
          'dueOn', v_c.due_on, 'label', v_c.label, 'amountDueMinor', v_due_minor
        ),
        v_c.booking_id,
        'installment_overdue:' || v_c.booking_id::text || ':' || v_c.seq::text
      )
      on conflict (idempotency_key) do nothing;
      v_count := v_count + 1;
    end if;
  end loop;

  return v_count;
end;
$$;

revoke execute on function api_enqueue_installment_reminders(jsonb) from public, anon, authenticated;
grant execute on function api_enqueue_installment_reminders(jsonb) to service_role;
